import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for fast access
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        neighbors = [set(lst) for lst in adj]

    # Helper: compute degree in induced subgraph of uncolored vertices
    def degree_in_uncolored(v, uncolored_set):
        return len(neighbors[v] & uncolored_set)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        deg = [len(neighbors[i]) for i in range(n)]
        while uncolored:
            # Find vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in uncolored:
                # Compute saturation degree: distinct colors in neighbors
                sat_set = set()
                for u in neighbors[v]:
                    if color[u] != -1:
                        sat_set.add(color[u])
                sat = len(sat_set)
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    d = degree_in_uncolored(v, uncolored)
                    if d > max_deg:
                        max_deg = d
                        best_v = v
                    elif d == max_deg and v < best_v:  # secondary tie-break by index
                        best_v = v
                v = best_v
            else:
                v = candidates[0]
            # Assign smallest available color
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: degree_in_uncolored(x, uncolored))
            S.add(v)
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if neighbors[u] & S:  # adjacent to S
                    U.remove(u)
                    W.add(u)
            # Step 4: while U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    deg_u = degree_in_uncolored(u, U)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_u
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        if deg_u < min_deg_in_U:
                            min_deg_in_U = deg_u
                            best_u = u
                        elif deg_u == min_deg_in_U and u < best_u:
                            best_u = u
                # Add best_u to S, move from U to W its neighbors in U
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for nb in list(neighbors[best_u] & U):
                    U.remove(nb)
                    W.add(nb)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # We'll simulate removal
        current_deg = deg[:]
        # Use buckets for efficiency (n <= 100)
        for _ in range(n):
            # Find vertex with min current_deg in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if current_deg[v] < min_deg:
                    min_deg = current_deg[v]
                    v_min = v
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for nb in neighbors[v_min]:
                if nb in remaining:
                    current_deg[nb] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate (should not happen), fallback to greedy on natural order
    if not candidates:
        col = greedy_color(list(range(n)))
        if is_valid(col):
            candidates.append(col)
        else:
            # Last resort: assign each vertex a unique color
            col = list(range(n))
            candidates.append(col)

    # Select the candidate with minimal number of colors
    best_coloring = min(candidates, key=num_colors)
    k = num_colors(best_coloring)

    # Kempe chain color reduction: try to eliminate color classes from highest downward
    def kempe_reduce(coloring):
        nonlocal n, neighbors
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find the highest color class that is non-empty
            # We'll try to reduce from the top
            max_color = max(col) if col else -1
            for target_color in range(max_color, -1, -1):
                # Get vertices with this color
                verts = [v for v in range(n) if col[v] == target_color]
                if not verts:
                    continue
                # Try to recolor each vertex in this class to a lower color
                for v in verts:
                    # Try direct reassignment to any lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if col[u] != -1:
                            neighbor_colors.add(col[u])
                    for c in range(target_color):  # only lower colors
                        if c not in neighbor_colors:
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        # After recoloring v, break to restart scan (as coloring changed)
                        break
                if changed:
                    break
            # If no direct reassignment worked, try Kempe chains for swapping
            if not changed:
                for target_color in range(max_color, -1, -1):
                    verts = [v for v in range(n) if col[v] == target_color]
                    if not verts:
                        continue
                    for v in verts:
                        neighbor_colors = set()
                        for u in neighbors[v]:
                            if col[u] != -1:
                                neighbor_colors.add(col[u])
                        # Try each lower color c
                        for c in range(target_color):
                            if c in neighbor_colors:
                                continue  # cannot use directly, but maybe via Kempe
                            # Check if v is in a Kempe chain of (target_color, c) that does not include any vertex of color c that is adjacent to v?
                            # Actually, we want to swap a component containing v in the subgraph of colors {target_color, c}
                            # such that after swap, v becomes c, and we don't introduce conflict.
                            # Standard: if there is no path from v to any vertex of color c using only colors {target_color, c},
                            # then we can swap the component containing v.
                            # But we can also swap if the component does not contain a neighbor of v that is color c? 
                            # Actually, the condition is: in the Kempe chain component of v in colors {a,b}, if we swap, 
                            # then v becomes b. We need that no neighbor of v is b after swap.
                            # Since we are only swapping within {a,b}, neighbors of v that are not in {a,b} remain same.
                            # So we need that no neighbor of v is currently color b (c) and is in the same Kempe component? 
                            # Actually, after swap, v becomes c. A neighbor u of v that is color c will become target_color if u is in the component, 
                            # or stay c if not. So if there is a neighbor u of v with color c that is in the same Kempe component as v, 
                            # then after swap u becomes target_color, so no conflict. 
                            # If the neighbor u of v with color c is NOT in the component, then after swap it remains c, and v becomes c -> conflict.
                            # Therefore, we can swap the component containing v if and only if no neighbor of v with color c is in the same Kempe component as v.
                            # Equivalent: the component of v in {target_color, c} does not contain any neighbor of v that has color c.
                            a, b = target_color, c
                            # BFS to get the Kempe component of v in colors {a,b}
                            from collections import deque
                            comp = set()
                            q = deque([v])
                            comp.add(v)
                            while q:
                                x = q.popleft()
                                for y in neighbors[x]:
                                    if col[y] == a or col[y] == b:
                                        if y not in comp:
                                            comp.add(y)
                                            q.append(y)
                            # Check if any neighbor of v with color b is in comp
                            conflict = False
                            for u in neighbors[v]:
                                if col[u] == b and u in comp:
                                    conflict = True
                                    break
                            if not conflict:
                                # Perform swap: a<->b in the component
                                for x in comp:
                                    if col[x] == a:
                                        col[x] = b
                                    elif col[x] == b:
                                        col[x] = a
                                changed = True
                                break
                        if changed:
                            break
                    if changed:
                        break
            if changed:
                break  # restart the while loop from the top
        return col

    # Apply Kempe reduction
    try:
        reduced = kempe_reduce(best_coloring)
        if is_valid(reduced):
            final_coloring = reduced
        else:
            final_coloring = best_coloring
    except Exception:
        final_coloring = best_coloring

    # Ensure colors are consecutive starting from 0
    # Map colors to 0..k-1
    unique_colors = sorted(set(final_coloring))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    final_coloring = [mapping[c] for c in final_coloring]

    # Final validation (should be valid)
    if not is_valid(final_coloring):
        # Fallback to greedy on natural order as last resort
        final_coloring = greedy_color(list(range(n)))
        unique_colors = sorted(set(final_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        final_coloring = [mapping[c] for c in final_coloring]

    return final_coloring

