import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix or adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(col):
        for u in range(n):
            for v in graph[u]:
                if col[u] == col[v]:
                    return False
        return True

    # Helper: count unique colors
    def num_colors(col):
        return max(col) + 1 if col else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(col):
        if not col:
            return col
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    # Heuristic 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Precompute degrees
        degrees = [len(graph[i]) for i in range(n)]
        # Saturation sets per vertex (as bitmask of colors used by neighbors)
        saturation = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = sum(1 for u in graph[v] if u in uncolored)
                elif sat == best_sat:
                    deg = sum(1 for u in graph[v] if u in uncolored)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            v = best_v
            # Compute available colors (MEX)
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in graph[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = {u for u in uncolored if u != v and not (bit_adj[v] & (1 << u))}
            W = {u for u in uncolored if u != v and (bit_adj[v] & (1 << u))}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    score = sum(1 for w in graph[u] if w in W)
                    deg_u = sum(1 for w in graph[u] if w in U)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_u = deg_u
                    elif score == best_score:
                        if deg_u < best_deg_u:
                            best_deg_u = deg_u
                            best_u = u
                        elif deg_u == best_deg_u and random.random() < 0.5:
                            best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in graph[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(graph[i]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find first non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for u in graph[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    # Move u to lower bucket
                    if d < len(buckets):
                        buckets[d].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]
        # Color in reverse order using First-Fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in graph[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = min(candidates, key=num_colors)
    best_color = compact_colors(best_color)

    # Kempe chain color reduction
    def eliminate_color_class(col, target_color):
        # Try to recolor all vertices of target_color
        vertices = [v for v in range(n) if col[v] == target_color]
        if not vertices:
            return col, True  # already empty
        # Try direct reassignment first
        new_col = col[:]
        for v in vertices:
            used = 0
            for u in graph[v]:
                if new_col[u] != -1:
                    used |= (1 << new_col[u])
            # Find smallest available color
            c = 0
            while used & (1 << c):
                c += 1
            if c < target_color:
                new_col[v] = c
        # Check if target_color is eliminated
        if all(new_col[v] != target_color for v in vertices):
            return compact_colors(new_col), True
        # Try Kempe chains for each vertex
        for v in vertices:
            if new_col[v] != target_color:
                continue  # already recolored
            for c in range(target_color):
                # Direct move check
                used = 0
                for u in graph[v]:
                    if new_col[u] != -1:
                        used |= (1 << new_col[u])
                if not (used & (1 << c)):
                    new_col[v] = c
                    break
                # Kempe chain (v, target_color) <-> (v, c)
                # Find component of v in subgraph of colors {target_color, c}
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                while queue:
                    node = queue.popleft()
                    component.append(node)
                    for u in graph[node]:
                        if not visited[u] and (new_col[u] == target_color or new_col[u] == c):
                            visited[u] = True
                            queue.append(u)
                # Check if swapping frees color c for v
                # After swap, v would get color c if it was target_color
                # We need to ensure no neighbor of v has color c after swap
                # Actually, in the component, target_color <-> c are swapped
                # So if any neighbor of v has color c and is in the component, after swap it becomes target_color -> conflict
                # But we are moving v away from target_color, so we need that after swap, v gets c and no neighbor has c
                # However, if a neighbor has c and is in the component, after swap it becomes target_color, so no longer c -> safe
                # If a neighbor has c and is not in the component, it stays c -> conflict
                safe = True
                for u in graph[v]:
                    if new_col[u] == c and not visited[u]:
                        safe = False
                        break
                if safe:
                    # Perform swap
                    for node in component:
                        if new_col[node] == target_color:
                            new_col[node] = c
                        elif new_col[node] == c:
                            new_col[node] = target_color
                    break
            else:
                continue  # only executed if inner loop did NOT break
            break  # break outer loop if inner broke
        # Compact and check if target_color eliminated
        new_col = compact_colors(new_col)
        if target_color >= len(new_col) or all(new_col[v] != target_color for v in range(n)):
            return new_col, True
        return col, False

    # Iteratively try to reduce colors
    k = num_colors(best_color)
    improved = True
    while improved and k > 0:
        improved = False
        # Try to eliminate color k-1
        new_col, success = eliminate_color_class(best_color, k - 1)
        if success:
            best_color = new_col
            k = num_colors(best_color)
            improved = True

    # Final validation and compact
    assert is_valid(best_color), "Invalid coloring produced"
    best_color = compact_colors(best_color)
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bit masks
    adj_list = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: count colors
    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    best_colors = None
    best_k = float('inf')

    # DSATUR
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Precompute neighbor masks for saturation
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturated[u]
                if sat_u > max_sat:
                    max_sat = sat_u
                    max_deg = sum(1 for w in adj_list[u] if w in uncolored)
                    v = u
                elif sat_u == max_sat:
                    deg_u = sum(1 for w in adj_list[u] if w in uncolored)
                    if deg_u > max_deg:
                        max_deg = deg_u
                        v = u
                    elif deg_u == max_deg:
                        if random.random() < 0.5:
                            v = u
            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Recompute saturation: number of distinct colors in neighbors
                    neighbor_colors = set()
                    for w in adj_list[u]:
                        if colors[w] != -1:
                            neighbor_colors.add(colors[w])
                    saturated[u] = len(neighbor_colors)
        return colors

    # RLF
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build maximal independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg_u = sum(1 for w in adj_list[u] if w in uncolored)
                if deg_u > max_deg:
                    max_deg = deg_u
                    v = u
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in S:
                    if u in adj_list[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty, add vertex with max neighbors in W
            while U:
                u_best = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_U = sum(1 for w in adj_list[u] if w in U)
                        u_best = u
                    elif w_neighbors == max_w_neighbors:
                        deg_u = sum(1 for w in adj_list[u] if w in U)
                        if deg_u < min_deg_U:
                            min_deg_U = deg_u
                            u_best = u
                S.add(u_best)
                U.remove(u_best)
                # Move neighbors of u_best from U to W
                for w in adj_list[u_best]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for u in S:
                colors[u] = color_idx
                uncolored.remove(u)
            color_idx += 1
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # Get vertex from bucket
            while buckets[ptr] and (buckets[ptr][-1] not in remaining):
                buckets[ptr].pop()
            if not buckets[ptr]:
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    degree[u] -= 1
                    if degree[u] < len(buckets):
                        buckets[degree[u]].append(u)
                    else:
                        # Extend buckets if needed (should not happen)
                        while len(buckets) <= degree[u]:
                            buckets.append([])
                        buckets[degree[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Welsh-Powell: sort by degree descending
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    candidates.append(welsh_powell())

    # Also try random restarts of DSATUR for diversification
    for _ in range(5):
        random.seed()  # Use system time
        candidates.append(dsatur())

    # Evaluate candidates
    for cols in candidates:
        k = count_colors(cols)
        if k < best_k:
            best_k = k
            best_colors = cols

    # Kempe chain color reduction
    def kempe_reduction(colors):
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            # Vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            made_progress = True
            while made_progress and verts:
                made_progress = False
                v = verts.pop()
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    c = colors[u]
                    if c != -1:
                        neighbor_colors.add(c)
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # Build (target_color, c)-Kempe chain containing v
                    # We want to swap colors in the component of v in the subgraph induced by colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in adj_list[u]:
                            if not visited[w] and colors[w] in (target_color, c):
                                visited[w] = True
                                queue.append(w)
                    # Check if swapping is safe: no neighbor of component has color c (would cause conflict)
                    # Actually, after swap, vertices in component that were target_color become c, and vice versa.
                    # Conflict occurs if a vertex in component that becomes c has a neighbor outside component with color c.
                    safe = True
                    for u in component:
                        new_color = c if colors[u] == target_color else target_color
                        for w in adj_list[u]:
                            if colors[w] == new_color and w not in component:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for u in component:
                            if colors[u] == target_color:
                                colors[u] = c
                            else:
                                colors[u] = target_color
                        made_progress = True
                        break
                if made_progress:
                    # Rebuild verts list for this target_color (some may have been recolored)
                    verts = [v for v in range(n) if colors[v] == target_color]
            # If no verts left with target_color, we eliminated the color
            if not any(colors[v] == target_color for v in range(n)):
                # Reindex colors: shift down all colors > target_color
                for v in range(n):
                    if colors[v] > target_color:
                        colors[v] -= 1
                break  # Restart from highest color as k reduced
        return colors

    # Apply Kempe reduction
    best_colors = kempe_reduction(best_colors)

    # Validate and compact colors
    # Verify proper coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_colors[u] == best_colors[v]:
                # Fallback: greedy on random order if invalid (should not happen)
                order = list(range(n))
                random.shuffle(order)
                best_colors = greedy_color(order)
                break
        else:
            continue
        break

    # Compact to 0..k-1
    color_map = {}
    next_color = 0
    for i in range(n):
        c = best_colors[i]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best_colors[i] = color_map[c]

    return best_colors

import math
