    # Helper: count distinct colors
    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: convert to 0-indexed consecutive colors
    def normalize_colors(colors):
        mapping = {}
        next_color = 0
        for i in range(n):
            c = colors[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            colors[i] = mapping[c]
        return colors

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
