                        best_v = v
                    elif deg_uncolored == max_deg and v < best_v:
                        best_v = v
                v = best_v
            else:
                v = candidates[0]
            # Assign smallest available color
            used = [False] * (n + 1)  # n+1 is safe upper bound
            for u in neighbors[v]:
                if colored[u]:
                    c = colors[u]
