                        break
                if adj_to_S:
                    W.add(v)
                else:
                    U.add(v)
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_neighbors += 1
                    # Tie-break: min degree in G[U]
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
