                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_U
                        best_u = u
                if best_u is None:
                    break  # safety
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color idx to all in S
            for v in S:
                colors[v] = color_idx
            # Remove S from uncolored
            uncolored -= S
            color_idx += 1
        return colors

    # Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # Compute degeneracy ordering via smallest-last
        remaining = set(range(n))
        order = []  # will be peeled order (smallest last)
        deg = [len(neighbors[i]) for i in range(n)]
        # We'll maintain current degrees in the remaining graph
        curr_deg = deg[:]
        # Bucket sort for efficiency: since n <= 100, we can use list of sets
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = curr_deg[v]
            if d <= max_deg:
                buckets[d].add(v)
        # Pointer to current min non-empty bucket
        min_bucket = 0
        while remaining:
            # Find first non-empty bucket from min_bucket
            while min_bucket <= max_deg and not buckets[min_bucket]:
                min_bucket += 1
            if min_bucket > max_deg:
                break  # no vertices left?
            # Pick a vertex from this bucket
            v = buckets[min_bucket].pop()
            remaining.remove(v)
            order.append(v)
