                    if old_deg <= max_deg:
                        if u in buckets[old_deg]:
                            buckets[old_deg].remove(u)
                    if new_deg <= max_deg:
                        buckets[new_deg].add(u)
                    # Update min_bucket if needed
                    if new_deg < min_bucket:
                        min_bucket = new_deg
        # Now color in reverse order (largest last first)
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if colors[u] != -1:
                    c = colors[u]
                    if c < n + 1:
                        used[c] = True
            for c in range(n + 1):
                if not used[c]:
                    colors[v] = c
                    break
        return colors

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, -1, -1):
            # Build list of vertices with this color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                continue
            made_progress = True
            while made_progress and target_vertices:
                made_progress = False
                # Try to recolor each vertex in target_vertices
                for v in target_vertices[:]:  # iterate over copy
                    c_v = colors[v]
                    # Try direct reassignment to a lower color
                    for c in range(target_color):  # only colors < target_color
                        conflict = False
                        for u in neighbors[v]:
                            if colors[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            # Recolor v to c
                            colors[v] = c
                            made_progress = True
                            # Remove v from target_vertices
                            if v in target_vertices:
                                target_vertices.remove(v)
                            break
                    if made_progress:
                        break  # restart while loop after change
                if made_progress:
                    continue  # restart while loop
                # Try Kempe chain swaps for each target vertex
                for v in target_vertices[:]:
                    c_v = colors[v]
                    for c in range(target_color):  # try each lower color
                        # Find the Kempe chain component of (c_v, c) containing v
                        # BFS/DFS over vertices with color c_v or c
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if colors[node] == c_v or colors[node] == c:
                                component.add(node)
                                for u in neighbors[node]:
                                    if colors[u] == c_v or colors[u] == c:
                                        if u not in visited:
                                            stack.append(u)
                        # Check if any neighbor of v has color c (would cause conflict if we swap)
                        has_c_neighbor = False
                        for u in neighbors[v]:
                            if colors[u] == c:
                                has_c_neighbor = True
                                break
                        if not has_c_neighbor:
                            # Swap colors c_v and c in the component
                            for node in component:
                                if colors[node] == c_v:
                                    colors[node] = c
                                elif colors[node] == c:
                                    colors[node] = c_v
                            made_progress = True
                            # Update target_vertices: if v changed color, remove it
                            if colors[v] != target_color:
                                if v in target_vertices:
                                    target_vertices.remove(v)
                            break  # break color loop
                    if made_progress:
                        break  # break vertex loop
                if made_progress:
                    break  # break while loop
            # After trying to eliminate target_color, if no vertices left with that color, we can compact
            if not any(colors[v] == target_color for v in range(n)):
                # Compact colors: map all colors > target_color down by 1
                color_map = {}
                next_c = 0
                for orig_c in range(k):
                    if orig_c == target_color:
                        continue
                    color_map[orig_c] = next_c
                    next_c += 1
                for v in range(n):
                    if colors[v] in color_map:
                        colors[v] = color_map[colors[v]]
                # Update k and restart reduction from new highest color
                k = count_colors(colors)
                break  # break target_color loop to restart from new highest
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if not is_valid_coloring(cols):
                continue
            cols = normalize_colors(cols)
            k = count_colors(cols)
            if k < best_k:
                best_k = k
                best_colors = cols[:]
        except Exception:
            continue

    # Fallback: if all heuristics failed, use greedy random order
    if best_colors is None:
        order = list(range(n))
        random.shuffle(order)
        colors = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if colors[u] != -1:
                    c = colors[u]
                    if c < n + 1:
                        used[c] = True
            for c in range(n + 1):
                if not used[c]:
                    colors[v] = c
                    break
        if is_valid_coloring(colors):
            colors = normalize_colors(colors)
            best_colors = colors
            best_k = count_colors(colors)
        else:
            # Last resort: assign each vertex a unique color
            best_colors = list(range(n))
            best_k = n

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best_colors[:])
        if is_valid_coloring(improved):
            improved = normalize_colors(improved)
            k_improved = count_colors(improved)
            if k_improved < best_k:
                best_colors = improved
                best_k = k_improved
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_colors):
        # Should not happen, but fallback
        best_colors = list(range(n))
    best_colors = normalize_colors(best_colors)
    return best_colors

