def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if entries are binary (0 or 1)
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor bitmasks and adjacency list
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    # Ensure symmetry for undirected graph (if not already)
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].append(i)
                bit_adj[j] |= (1 << i)

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            cu = colors[u]
            for v in neighbors[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: convert to consecutive colors starting from 0
    def normalize(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(neighbors[i]) for i in range(n)]
        colored = [False] * n
        # Neighbor color sets as bitmasks for fast saturation
        neighbor_colors = [0] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # saturation = number of distinct colors in neighbors
                sat = neighbor_colors[u].bit_count()
                if sat > max_sat or (sat == max_sat and degrees[u] > max_deg):
                    max_sat = sat
                    max_deg = degrees[u]
                    v = u
            if v == -1:  # should not happen
                break
            # Find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update neighbor colors for all neighbors of v
            for u in neighbors[v]:
                if not colored[u]:
                    neighbor_colors[u] |= (1 << c)
        return normalize(colors)

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color = 0
        # Precompute degrees in the full graph for initial selection
        degrees = [len(neighbors[i]) for i in range(n)]
        while not all(colored):
            # Step 1: pick uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # degree in uncolored subgraph: count uncolored neighbors
                deg = 0
                for w in neighbors[u]:
                    if not colored[w]:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:  # no uncolored vertex
                break
            # Start independent set S with v
            S = [v]
            colored[v] = True
            # U: uncolored vertices not adjacent to any in S (eligible)
            # W: uncolored vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if colored[u]:
                    continue
                # check if u is adjacent to any in S
                adjacent = False
                for s in S:
                    if u in neighbors[s]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_nw = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    nw = 0
                    for w in neighbors[u]:
                        if w in W:
                            nw += 1
                    # tie-break: min degree in G[U]
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_U += 1
                    if nw > max_nw or (nw == max_nw and deg_U < min_deg_U):
                        max_nw = nw
                        min_deg_U = deg_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                # add best_u to S
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for u in S:
                colors[u] = color
            color += 1
        return normalize(colors)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering via smallest-last removal
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll maintain a list of vertices by current degree for efficiency
        # Since n <= 100, we can do simple scan
        while remaining:
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda u: degree[u])
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    degree[u] -= 1
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors_in):
        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(colors)
            if k <= 1:
                break
            # Try to eliminate color k-1
            target_color = k - 1
            # vertices with target color
            target_vertices = [i for i in range(n) if colors[i] == target_color]
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    cu = colors[u]
                    if cu < target_color:
                        used_by_neighbors |= (1 << cu)
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart while loop after any change
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has a neighbor with color c, swapping might not help directly
                    # but we still check the component
                    # Find the Kempe chain component of v in colors {c, target_color}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (colors[y] == c or colors[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if any vertex in component has a neighbor with color c (outside component) that would cause conflict if we swap?
                    # Actually, swapping colors in a Kempe chain preserves validity.
                    # We want to know if after swapping, v would not have color target_color.
                    # After swap, v will have color c if it was target_color, or target_color if it was c.
                    # Since v is target_color, after swap it becomes c.
                    # We need to ensure that no neighbor of v has color c after swap.
                    # Neighbors of v that are in the component: if they were c, they become target_color; if they were target_color, they become c.
                    # Neighbors of v not in the component: their color stays same.
                    # So after swap, v will have color c. We need that no neighbor of v has color c after swap.
                    # Let's check:
                    conflict = False
                    for y in neighbors[v]:
                        col_y = colors[y]
                        if y in component:
                            # if y was c, after swap becomes target_color; if y was target_color, after swap becomes c.
                            if col_y == c:
                                # after swap becomes target_color, which is not c (unless c==target_color, but c<target_color)
                                pass
                            elif col_y == target_color:
                                # after swap becomes c -> conflict!
                                conflict = True
                                break
                        else:
                            # not in component, color unchanged
                            if col_y == c:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap on component
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target_color
                            elif colors[x] == target_color:
                                colors[x] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # normalize colors to fill gaps
                colors = normalize(colors)
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')
    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if not is_valid(cols):
                continue
            k = num_colors(cols)
            if k < best_k:
                best_k = k
                best_colors = cols
        except Exception:
            continue
    # Fallback: greedy by node order
    if best_colors is None:
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = normalize(colors)
    # Apply Kempe reduction
    best_colors = kempe_reduce(best_colors)
    # Final validation and normalization
    if not is_valid(best_colors):
        # last resort: greedy
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = normalize(colors)
    return best_colors

