    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        deg = [len(neighbors[i]) for i in range(n)]
        while uncolored:
            # Find vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in uncolored:
                # Compute saturation degree: distinct colors in neighbors
                sat_set = set()
                for u in neighbors[v]:
                    if color[u] != -1:
                        sat_set.add(color[u])
