def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Saturation degree: bitmask of colors used by colored neighbors
        sat = [0] * n
        uncolored = set(range(n))
        # Initial selection: max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << 0)
        while uncolored:
            # Select vertex with max saturation degree (by bit count), tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x].bit_count(), len([u for u in adj_list[x] if u in uncolored]), x))
            # Find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: len([u for u in adj_list[x] if u in uncolored]))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: len([w for w in adj_list[x] if w in W]))
                # Tie-break: min degree in G[U]
                u = min((x for x in U if len([w for w in adj_list[x] if w in W]) == len([w for w in adj_list[u] if w in W])),
                        key=lambda x: len([w for w in adj_list[x] if w in U]))
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col[:]

    # If no valid candidate (should not happen), fallback to greedy
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduction(color):
        # Make color classes
        classes = [[] for _ in range(best_k)]
        for v in range(n):
            classes[color[v]].append(v)
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and best_k > 0:
            changed = False
            # Target smallest color class (highest index)
            target = best_k - 1
            if not classes[target]:
                # Already empty, compact
                for c in range(target, best_k - 1):
                    classes[c] = classes[c + 1]
                classes.pop()
                best_k -= 1
                # Update color mapping
                new_color = [-1] * n
                for v in range(n):
                    if color[v] > target:
                        new_color[v] = color[v] - 1
                    else:
                        new_color[v] = color[v]
                color = new_color
                classes = [[] for _ in range(best_k)]
                for v in range(n):
                    classes[color[v]].append(v)
                changed = True
                continue
            # Try to recolor each vertex in target class
            for v in classes[target][:]:
                # Try direct reassignment to a lower color
                moved = False
                for c in range(target):
                    # Check if color c is available (no neighbor has color c)
                    conflict = False
                    for u in adj_list[v]:
                        if color[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Move v to color c
                        color[v] = c
                        classes[target].remove(v)
                        classes[c].append(v)
                        moved = True
                        changed = True
                        break
                if moved:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(target):
                    # Find Kempe chain (c, target) containing v
                    # BFS to get component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (color[y] == c or color[y] == target):
                                visited[y] = True
                                queue.append(y)
                    # Check if swapping this component frees color c for v
                    # After swap, v would have color c; need to ensure no neighbor has color c
                    # Actually, we need to check that no neighbor of v has color c after swap
                    # But since we are swapping only within (c,target), neighbors of v that are not in component keep their color
                    # So we need: for all neighbors u of v, if u not in component, color[u] != c
                    # And for u in component, after swap they become target if they were c, or c if they were target
                    # So condition: no neighbor u of v has color c and is not in the component
                    safe = True
                    for u in adj_list[v]:
                        if color[u] == c and u not in component:
                            safe = False
                            break
                    if safe:
                        # Perform swap
                        for x in component:
                            if color[x] == c:
                                color[x] = target
                            else:  # must be target
                                color[x] = c
                        # Update classes
                        classes[target].remove(v)
                        classes[c].append(v)
                        # Actually, need to rebuild classes for simplicity
                        changed = True
                        break
                if changed:
                    break
            # If we made changes, rebuild classes and continue
            if changed:
                classes = [[] for _ in range(best_k)]
                for v in range(n):
                    classes[color[v]].append(v)
        return color

    # Apply Kempe reduction
    try:
        best_color = kempe_reduction(best_color)
    except:
        # If anything goes wrong, keep the current best
        pass

    # Final validation and compacting
    # Ensure colors are consecutive
    used_colors = set()
    for c in best_color:
        used_colors.add(c)
    if used_colors:
        mapping = {}
        sorted_colors = sorted(used_colors)
        for i, col in enumerate(sorted_colors):
            mapping[col] = i
        best_color = [mapping[c] for c in best_color]

    return best_color

