    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

