            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                if sat > best_sat or (sat == best_sat and (
                    degrees[v] > best_deg or (degrees[v] == best_deg and v < best_v)
                )):
                    best_sat = sat
                    best_deg = degrees[v]
                    best_v = v
            v = best_v
            # Find smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return colors

    # RLF: Recursive Largest First
    def rlf():
