        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            # Compute degrees in uncolored subgraph
            deg_in_uncolored = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_in_uncolored[v] += 1
            # Find vertex with max degree in uncolored
            start = max(uncolored, key=lambda v: (deg_in_uncolored[v], v))
            independent_set = {start}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {start}
            W = set()
            for u in adj_list[start]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # While U not empty, add vertex with max neighbors in W
            while U:
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = -1
