        return greedy_color(order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(colors):
        # Make sure colors are compact
        def compact(cols):
            mapping = {}
            next_color = 0
            for c in cols:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in cols]

        colors = compact(colors)
        k = max(colors) + 1 if n > 0 else 0
        # Try to reduce colors from k-1 down
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                k -= 1
                colors = compact(colors)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if colors[u] < target_color:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Direct move possible
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swaps
                for c in range(target_color):
                    # Check if v can be swapped with color c via Kempe chain
                    # We'll try to find a Kempe chain (target_color, c) starting from v
                    # that does not include any other target_color vertex (to avoid pulling them in)
                    # Actually, we allow the chain to include other target_color vertices, but we want to free color c for v
                    # Standard Kempe: swap colors in the component of v in the subgraph induced by colors {target_color, c}
                    # After swap, v will have color c, and we need to ensure no conflict
                    # Since we only swap within the component, it remains valid.
                    # However, if the component contains another vertex w of target_color, after swap w becomes c,
                    # which might cause conflict if w has a neighbor of color c outside the component.
                    # But the swap is still valid globally because we only swap within the component.
                    # The issue is that we might not reduce the number of target_color vertices.
                    # To reduce the count, we need the component to contain exactly one target_color vertex (v).
                    # So we check if the Kempe chain component of v in colors {target_color, c} contains any other target_color vertex.
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    is_safe = True  # True if no other target_color in component
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        if colors[x] == target_color and x != v:
                            is_safe = False  # Found another target_color in component
                        for y in adj_list[x]:
                            if not visited[y] and (colors[y] == target_color or colors[y] == c):
                                visited[y] = True
                                queue.append(y)
                    if is_safe:
                        # Swap colors in component
                        for x in component:
                            if colors[x] == target_color:
                                colors[x] = c
                            else:  # must be c
                                colors[x] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                k = max(colors) + 1
                colors = compact(colors)
            else:
                # Cannot reduce further
                break
        return colors

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        valid, _ = validate_and_count(c1)
        if valid:
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        valid, _ = validate_and_count(c2)
        if valid:
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        valid, _ = validate_and_count(c3)
        if valid:
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy by index
    if not candidates:
        colors = greedy_color(list(range(n)))
        candidates.append(colors)

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        _, k = validate_and_count(col)
        if k < best_k:
            best_k = k
            best = col

    # Apply Kempe reduction to best candidate
    best = kempe_reduce(best)
    # Final validation and compaction
    valid, _ = validate_and_count(best)
    if not valid:
        # Last resort: greedy by index
        best = greedy_color(list(range(n)))
    best = kempe_reduce(best)  # Try again
    # Ensure compact
    def compact_final(cols):
        mapping = {}
        next_color = 0
        for c in cols:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in cols]
    best = compact_final(best)
    return best

