                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = [list(neighbors) for neighbors in adj]
    # Precompute neighbor bitmasks
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        used_masks = [0] * n  # bitmask of colors used by neighbors
        for v in order:
            cmask = used_masks[v]
            c = 0
            while cmask & (1 << c):
                c += 1
            color[v] = c
            for u in graph[v]:
                used_masks[u] |= 1 << c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    best_coloring = None
    best_k = float('inf')

    # DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors in neighborhood
        sat_mask = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(graph[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = sat_mask[u].bit_count()
                deg = uncolored_deg[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and random.random() < 0.5):
                    max_sat = sat
                    max_deg = deg
                    v = u
            # assign smallest available color
            cmask = sat_mask[v]
            c = 0
            while cmask & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in uncolored:
                    sat_mask[u] |= 1 << c
                    uncolored_deg[u] -= 1
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in induced subgraph of uncolored
            deg = {}
            for u in uncolored:
                cnt = 0
                for v in graph[u]:
                    if v in uncolored:
                        cnt += 1
                deg[u] = cnt
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and all(w not in graph[u] for w in S)}
            # W: vertices adjacent to at least one in S
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = sum(1 for w in graph[u] if w in W)
                    # deg in U
                    degU = sum(1 for w in graph[u] if w in U)
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and random.random() < 0.5):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in graph[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # buckets by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = deg[v]
        # process
        for _ in range(n):
            # find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in remaining:
                    du = pos[u]
                    # remove u from bucket du
                    if u in buckets[du]:
                        buckets[du].remove(u)
                    pos[u] -= 1
                    buckets[pos[u]].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    for func in (dsatur, rlf, smallest_last):
        try:
            col = func()
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col
        except Exception:
            continue

    # If no candidate, fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # color classes
        classes = [[] for _ in range(k)]
        for v, c in enumerate(coloring):
            classes[c].append(v)
        # try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target = k - 1
            if not classes[target]:
                # should not happen, but compact
                for c in range(target, k-1):
                    classes[c] = classes[c+1]
                classes.pop()
                k -= 1
                # rebuild coloring
                new_coloring = [-1] * n
                for c, lst in enumerate(classes):
                    for v in lst:
                        new_coloring[v] = c
                coloring = new_coloring
                changed = True
                continue
            # try to recolor each vertex in target class
            for v in classes[target][:]:
                # try direct reassignment to lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if coloring[u] < target:
                        neighbor_colors.add(coloring[u])
                for c in range(target):
                    if c not in neighbor_colors:
                        # move v to color c
                        coloring[v] = c
                        classes[target].remove(v)
                        classes[c].append(v)
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                if changed:
                    break
                for c in range(target):
                    # BFS to get Kempe chain of colors c and target containing v
                    from collections import deque
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    while stack:
                        x = stack.pop()
                        for y in graph[x]:
                            if y not in visited and (coloring[y] == c or coloring[y] == target):
                                visited.add(y)
                                stack.append(y)
                    # check if swapping colors c and target in this component is safe
                    # i.e., no neighbor of any vertex in component has color c or target outside component
                    safe = True
                    for x in visited:
                        for y in graph[x]:
                            if y not in visited and (coloring[y] == c or coloring[y] == target):
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for x in visited:
                            if coloring[x] == c:
                                coloring[x] = target
                            else:
                                coloring[x] = c
                        # update classes
                        classes[c].clear()
                        classes[target].clear()
                        for idx, col_val in enumerate(coloring):
                            classes[col_val].append(idx)
                        changed = True
                        break
            if not changed:
                # cannot eliminate this color class, break
                break
        # compact colors
        # map colors to 0..k'-1
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = coloring[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[v] = unique_colors[c]
        return coloring

    best_coloring = kempe_reduce(best_coloring)
    # Final validation (optional, but ensure correctness)
    # for u in range(n):
    #     for v in graph[u]:
    #         if best_coloring[u] == best_coloring[v]:
    #             # fallback to greedy if invalid (should not happen)
    #             return greedy_color(list(range(n)))
    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    # ---------- Input handling ----------
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = (len(adj[0]) == n and 
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build neighbor sets and bit adjacency
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    for u in range(n):
        if is_matrix:
            row = adj[u]
            for v in range(n):
                if row[v]:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
        else:
            for v in adj[u]:
                if v != u:  # ignore self-loops
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)

    # Ensure symmetry (undirected graph)
    for u in range(n):
        for v in neighbors[u]:
            if u not in neighbors[v]:
                neighbors[v].add(u)
                bit_adj[v] |= (1 << u)

    # ---------- Helper functions ----------
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    def normalize_colors(coloring):
        # Map colors to 0..k-1 consecutively
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
        return coloring

    def count_colors(coloring):
        return max(coloring) + 1 if n > 0 else 0

    # ---------- DSATUR ----------
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighborhood
        saturation = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n

        # initial vertex: highest degree
        degrees = [len(neighbors[i]) for i in range(n)]
        vertex = max(range(n), key=lambda i: (degrees[i], i))
        coloring[vertex] = 0
        # update neighbors of vertex
        for v in neighbors[vertex]:
            neighbor_color_mask[v] |= (1 << 0)
            saturation[v] = 1  # only color 0 so far

        for _ in range(1, n):
            # select uncolored vertex with max saturation, tie-break by degree
            candidate = -1
            max_sat = -1
            max_deg = -1
            for v in range(n):
                if coloring[v] == -1:
                    sat = saturation[v]
                    deg = len(neighbors[v])
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or \
                       (sat == max_sat and deg == max_deg and v > candidate):
                        max_sat = sat
                        max_deg = deg
                        candidate = v
            v = candidate

            # find smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update neighbors
            for u in neighbors[v]:
                if not (neighbor_color_mask[u] & (1 << c)):
                    neighbor_color_mask[u] |= (1 << c)
                    saturation[u] += 1

        return normalize_colors(coloring)

    # ---------- RLF ----------
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            def degree_in_uncolored(v):
                return sum(1 for u in neighbors[v] if u in uncolored)

            v = max(uncolored, key=lambda x: (degree_in_uncolored(x), x))
            independent_set = {v}
            to_check = set(uncolored) - {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            W = set()
            for u in to_check:
                if any(w in neighbors[u] for w in independent_set):
                    W.add(u)
            U = to_check - W

            while U:
                # select u in U with max |N(u) ∩ W|
                def weight(u):
                    return sum(1 for w in neighbors[u] if w in W)
                # tie-break: min degree in G[U]
                def deg_in_U(u):
                    return sum(1 for w in neighbors[u] if w in U)
                u = max(U, key=lambda x: (weight(x), -deg_in_U(x), x))
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # assign color to independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize_colors(coloring)

    # ---------- Smallest-Last (Degeneracy ordering) ----------
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].add(v)

        for _ in range(n):
            # find first non-empty bucket
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from current bucket
                    buckets[degree[u]].remove(u)
                    degree[u] -= 1
                    if degree[u] >= 0:
                        buckets[degree[u]].add(u)
            remaining.remove(v)

        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize_colors(coloring)

    # ---------- Kempe chain color reduction ----------
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # make a copy to work on
        current = coloring[:]
        improved = True
        while improved:
            improved = False
            k = count_colors(current)
            if k <= 1:
                break
            # target smallest color class (highest index)
            target_color = k - 1
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # should not happen, but compact anyway
                return normalize_colors(current)

            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    cu = current[u]
                    if cu < target_color:  # only consider colors we might reassign to
                        used_by_neighbors |= (1 << cu)
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # can recolor v to c
                        current[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart scan after change

                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c after direct reassignment attempt, skip
                    if current[v] == c:
                        continue
                    # find the (c, target_color) Kempe chain containing v
                    # BFS/DFS over vertices colored c or target_color
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        cn = current[node]
                        if cn == c or cn == target_color:
                            component.add(node)
                            for w in neighbors[node]:
                                if w not in visited:
                                    stack.append(w)
                    # check if any neighbor of v in the component has color c
                    # actually, we need to see if we can swap: after swap, v would become c
                    # and we must ensure no neighbor of v becomes target_color (which would conflict if they are adjacent to v?)
                    # But note: after swap, neighbors of v that are in the component and had color c become target_color.
                    # If any such neighbor is adjacent to v, then after swap it would be target_color and adjacent to v (which is now c) -> ok.
                    # The only issue is if there is a neighbor of v not in the component that is color c? 
                    # Actually, the swap is safe if and only if no neighbor of v is colored c and not in the component? 
                    # Standard condition: we can swap the component if it does not contain a neighbor of v that is colored c? 
                    # Let's think: we want to recolor v to c. Currently v is target_color.
                    # After swapping the component, v becomes c (if v in component, which it is).
                    # A neighbor u of v:
                    #   - If u not in component: its color unchanged.
                    #   - If u in component: 
                    #         if it was c -> becomes target_color
                    #         if it was target_color -> becomes c
                    # For the coloring to remain valid:
                    #   - If u not in component: we need current[u] != c (since v becomes c)
                    #   - If u in component and was c: after swap becomes target_color, need target_color != current[u] (which was c) -> true, and also need target_color != current[v] (which becomes c) -> true as long as c != target_color.
                    #   - If u in component and was target_color: after swap becomes c, then we need c != current[u] (which becomes c) -> conflict! 
                    # Actually, wait: after swap, v becomes c, and if a neighbor u in component was target_color and becomes c, then both v and u are c -> conflict.
                    # Therefore, we can only perform the swap if the component does NOT contain any neighbor of v that is colored target_color.
                    # Equivalent: in the component, v is the only vertex colored target_color? 
                    # More precisely, we require that no neighbor of v in the component has color target_color (because after swap they would become c and conflict with v's new color c).
                    # But note: v itself is in the component and is target_color, but we don't consider v as its own neighbor.
                    has_target_color_neighbor = False
                    for u in component:
                        if u != v and current[u] == target_color and u in neighbors[v]:
                            has_target_color_neighbor = True
                            break
                    if not has_target_color_neighbor:
                        # perform swap
                        for node in component:
                            if current[node] == c:
                                current[node] = target_color
                            else:  # must be target_color
                                current[node] = c
                        improved = True
                        break
                if improved:
                    break
            # if we made a change, we might have emptied the target color class; compact colors
            if improved:
                current = normalize_colors(current)
        return current

    # ---------- Main heuristic selection ----------
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # List of heuristics to try
    heuristics = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last)
    ]

    for name, heuristic in heuristics:
        if time.time() - start_time > 0.04:  # leave time for Kempe
            break
        coloring = heuristic()
        if not is_valid_coloring(coloring):
            continue
        k = count_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]

    # If no heuristic produced a valid coloring (should not happen), fallback to greedy
    if best_coloring is None:
        # simple greedy ordering by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize_colors(coloring)

    # Apply Kempe chain reduction if time permits
    if time.time() - start_time < 0.045:
        best_coloring = kempe_reduce(best_coloring)
        # final validation and normalization
        if not is_valid_coloring(best_coloring):
            # fallback should not happen, but just in case
            best_coloring = [0] * n
        else:
            best_coloring = normalize_colors(best_coloring)

    return best_coloring

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
