                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        normalized = [0] * n
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            normalized[i] = unique_colors[c]
        return normalized

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return [0] * n
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph (initially full degree)
        degree_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree_uncolored
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    if saturation[u] > max_sat or (saturation[u] == max_sat and degree_uncolored[u] > max_deg):
                        max_sat = saturation[u]
                        max_deg = degree_uncolored[u]
                        v = u
                    elif saturation[u] == max_sat and degree_uncolored[u] == max_deg:
                        # Tie-break by vertex index (lower index preferred for determinism, but random is also ok)
                        if v == -1 or u < v:
                            v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color for v
            neighbor_colors = 0
            for w in adj_list[v]:
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and degree_uncolored for neighbors
            for w in adj_list[v]:
                if coloring[w] == -1:
                    # Update saturation: if color c is new in w's neighbors
                    # We can't easily track distinct colors without a set, but we can approximate by checking if this is the first time color c appears?
                    # Instead, we maintain for each uncolored neighbor w, we add color c to its neighbor colors set.
                    # Since we don't store sets, we do: if we haven't seen color c in w's neighbors before, increment saturation[w].
                    # To do that, we need to know if any other neighbor of w has color c? We don't track that.
                    # Alternative: we can recompute saturation from scratch? Too expensive.
