                    mapping = {}
                    new_c = 0
                    for old_c in range(k):
                        if used[old_c]:
                            mapping[old_c] = new_c
                            new_c += 1
                    # apply mapping
                    new_color = [mapping[c] for c in color_copy]
                    # validate again
                    valid2 = True
                    for u in range(n):
                        for v in adj_list[u]:
                            if new_color[u] == new_color[v]:
                                valid2 = False
                                break
                        if not valid2:
                            break
                    if valid2:
                        best = new_color
                        k = new_c
                        improved = True
        # end while improved

    # Final validation and compacting
    # Ensure colors are consecutive starting from 0
    used = [False] * (n + 1)
    for c in best:
        if c < len(used):
            used[c] = True
    # remap
    mapping = {}
    new_c = 0
    for old_c in range(len(used)):
        if used[old_c]:
            mapping[old_c] = new_c
            new_c += 1
    best = [mapping[c] for c in best]

    return best

