from collections import deque

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: normalize colors to 0..k-1
    def normalize_colors(colors):
        if not colors:
            return colors
        unique = {}
        next_color = 0
        for c in colors:
            if c not in unique:
                unique[c] = next_color
                next_color += 1
        return [unique[c] for c in colors]

    # DSATUR with bitmask optimization
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_count = saturation[v].bit_count()
                if sat_count > best_sat or (sat_count == best_sat and (
                    uncolored_deg[v] > best_deg or 
                    (uncolored_deg[v] == best_deg and random.random() < 0.5)
                )):
                    best_sat = sat_count
                    best_deg = uncolored_deg[v]
                    best_v = v
            v = best_v

            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)

            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
                S.append(v)
                uncolored.remove(v)

            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            W = set()
            for u in S:
                for w in adj_list[u]:
                    if w in uncolored:
                        W.add(w)
            U = uncolored - W

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for y in adj_list[u] if y in W)
                    u_deg = sum(1 for y in adj_list[u] if y in U)
                    if w_neighbors > best_w_neighbors or (
                        w_neighbors == best_w_neighbors and u_deg < best_u_deg
                    ):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                S.append(u)
                uncolored.remove(u)
                # Update U and W: remove u from U, add its neighbors in U to W
                U.remove(u)
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Compute core numbers and removal order
        deg = [len(adj_list[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            bins[deg[i]].append(i)
        # Track position in bins
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, v in enumerate(bins[d]):
                pos[v] = i

        order = []
        current_deg = deg[:]
        # Find min degree vertex iteratively
        for _ in range(n):
            # Find first non-empty bin
            d = 0
            while d <= max_deg and not bins[d]:
                d += 1
            if d > max_deg:
                break
            v = bins[d].pop()
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if current_deg[u] > d:  # u not yet removed
                    # Remove u from its current bin
                    d_u = current_deg[u]
                    idx = pos[u]
                    bins[d_u][idx] = bins[d_u][-1]
                    pos[bins[d_u][idx]] = idx
                    bins[d_u].pop()
                    # Add to bin d_u-1
                    current_deg[u] -= 1
                    d_new = current_deg[u]
                    bins[d_new].append(u)
                    pos[u] = len(bins[d_new]) - 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [i for i in range(n) if colors[i] == target_color]
            if not target_vertices:
                # Already empty, compact colors
                mapping = {}
                next_c = 0
                for c in range(k):
                    if any(colors[i] == c for i in range(n)):
                        mapping[c] = next_c
                        next_c += 1
                colors = [mapping[colors[i]] for i in range(n)]
                k = num_colors(colors)
                continue

            # Try to recolor each target vertex
            for v in target_vertices[:]:  # copy as we may modify
                # Try direct reassignment to lower color
                for c in range(target_color):
                    conflict = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    break

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find (target_color, c)-Kempe chain containing v
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in adj_list[node]:
                            if not visited[u] and (colors[u] == target_color or colors[u] == c):
                                visited[u] = True
                                stack.append(u)

                    # Check if we can swap: no neighbor of component has color c outside component
                    can_swap = True
                    for node in component:
                        for u in adj_list[node]:
                            if colors[u] == c and not visited[u]:
                                can_swap = False
                                break
                        if not can_swap:
                            break

                    if can_swap:
                        # Swap colors in component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:
                                colors[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                # Recompute k and continue
                k = num_colors(colors)
            else:
                # Could not eliminate target color, break
                break

        return colors

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(normalize_colors(c1))
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(normalize_colors(c2))
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(normalize_colors(c3))
    except:
        pass

    # Fallback: greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        if is_valid_coloring(colors):
            candidates.append(normalize_colors(colors))
    except:
        pass

    # Select best candidate (fewest colors)
    if not candidates:
        # Ultimate fallback: assign distinct colors
        return list(range(n))

    best = min(candidates, key=num_colors)
    best = kempe_reduce(best)

    # Final validation and normalization
    if not is_valid_coloring(best):
        # Should not happen, but fallback
        return list(range(n))

    return normalize_colors(best)

