                S.add(best_u)
                U.remove(best_u)
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color idx to all in S
            for u in S:
                colors[u] = color_idx
                uncolored.remove(u)
            color_idx += 1
        return compact_colors(colors)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # compute smallest-last ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # we will update degrees as we remove vertices
        deg_copy = degrees[:]
        for _ in range(n):
            # find vertex with min degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg_copy[u] < min_deg:
                    min_deg = deg_copy[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    deg_copy[u] -= 1
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Spectral-inspired clustering via random walk (for fallback/clustering idea)
    def spectral_clustering_coloring():
        # We'll use a simple random walk to get a vector, then cluster by sign (like spectral)
        # but since we cannot do eigenvectors, we do a few steps of random walk and use the visit frequency.
        # This is a heuristic to get a partitioning.
        if n == 0:
            return []
        # stationary distribution of random walk approximated by degree (for regular-ish graphs)
        # we use a random walk of length 32 to get a mixing vector
        visits = [0.0] * n
        # start from random vertex
        current = random.randrange(n)
        steps = 1000
        for _ in range(steps):
            visits[current] += 1.0
            neighbors = adj_list[current]
            if not neighbors:
                break
            current = random.choice(neighbors)
        # normalize
        total = sum(visits)
        if total > 0:
            visits = [v / total for v in visits]
        else:
            visits = [1.0 / n] * n
        # Now we try to split by median of visits
        sorted_visits = sorted(enumerate(visits), key=lambda x: x[1])
        # take first half as one cluster, second half as another
        half = n // 2
        cluster1 = set([v for v, _ in sorted_visits[:half]])
        cluster2 = set([v for v, _ in sorted_visits[half:]])
        # Now we try to color each cluster independently with DSATUR (since they might be disconnected)
        # but we must account for edges between clusters.
        # Instead, we use the clustering to order vertices: cluster1 first, then cluster2.
        ordered = list(cluster1) + list(cluster2)
        # greedy coloring in that order
        colors = [-1] * n
        for v in ordered:
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduction(colors_in):
        colors = colors_in[:]
        changed = True
        # We'll try to reduce from the highest color downwards
        while changed:
            changed = False
            k = num_colors(colors)
            if k <= 1:
                break
            # target the last color class (k-1)
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # should not happen, but safety
                break
            # Try to recolor each target vertex to a lower color
            for v in target_vertices:
                # Try direct reassignment to any color < target_color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    # after changing one, we break to restart the scan (since color classes changed)
                    break
                # If direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (c, target_color)
                    # We need to see if v is in a component of the (c, target_color) subgraph
                    # that does not contain any vertex of color c that is adjacent to v? 
                    # Actually, we can swap if the component of v in (c, target_color) does not 
                    # contain a neighbor of v that has color c (because swapping would then cause conflict).
                    # Standard: we can swap the component containing v if it does not contain any 
                    # vertex colored c that is adjacent to v? Actually, we swap the entire component.
                    # After swap, v becomes c, and we must check that no neighbor of v is c (after swap).
                    # But if we swap the component, then neighbors of v that are in the component and had color c become target_color, 
                    # and neighbors that were target_color become c. So we need that no neighbor of v 
                    # that is NOT in the component has color c (because after swap, they remain c and v becomes c -> conflict).
                    # Equivalent: in the (c, target_color) subgraph, the component of v must not be adjacent to any vertex of color c outside the component.
                    # However, a simpler condition: if there is no path from v to any vertex of color c that is adjacent to v? 
                    # Actually, we can do: let A be the set of vertices with color c that are adjacent to v.
                    # If v is not in the same connected component (in the subgraph induced by colors c and target_color) as any vertex in A, then we can swap the component of v.
                    from collections import deque
                    # BFS/DFS to get component of v in (c, target_color) subgraph
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    while q:
                        x = q.popleft()
                        for y in adj_list[x]:
                            if colors[y] == c or colors[y] == target_color:
                                if y not in comp:
                                    comp.add(y)
                                    q.append(y)
                    # Now, check if any neighbor of v that has color c is in this component?
                    conflict = False
                    for u in adj_list[v]:
                        if colors[u] == c and u in comp:
                            conflict = True
                            break
                    if not conflict:
                        # we can swap the component: c <-> target_color in comp
                        for x in comp:
                            if colors[x] == c:
                                colors[x] = target_color
                            elif colors[x] == target_color:
                                colors[x] = c
                        changed = True
                        break
                if changed:
                    break
            # After attempting to recolor all target vertices, if we changed something, we continue
            # Otherwise, we break
            if not changed:
                break
            # Compact colors after changes
            colors = compact_colors(colors)
        return colors

    # Run all heuristics with time budget
    start_time = time.time()
    best_colors = None
    best_k = float('inf')

    # Helper to try a heuristic and update best
    def try_heuristic(name, func):
        nonlocal best_colors, best_k
        if time.time() - start_time > 0.04:  # leave some margin
            return
        try:
            colors = func()
            if time.time() - start_time > 0.04:
                return
            if not is_valid_coloring(colors):
                return
            k = num_colors(colors)
            if k < best_k:
                best_k = k
                best_colors = colors[:]
        except Exception:
            pass

    # Order of heuristics: DSATUR, RLF, Smallest-Last, Spectral (as fallback)
    try_heuristic("DSATUR", dsatur)
    try_heuristic("RLF", rlf)
    try_heuristic("Smallest-Last", smallest_last)
    try_heuristic("Spectral", spectral_clustering_coloring)

    # If none worked (should not happen), fallback to greedy
    if best_colors is None:
        # simple greedy by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe reduction to try to improve
    if time.time() - start_time < 0.045:
        improved = kempe_reduction(best_colors)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_colors = improved
                best_k = k_improved

    # Final validation and compact
    if best_colors is None:
        best_colors = [0] * n
    best_colors = compact_colors(best_colors)
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    return best_colors

