def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list and compute degrees
    if len(adj) > 0 and len(adj[0]) == n and all(x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = adj

    degrees = [len(adj_list[i]) for i in range(n)]

    # Find articulation points using DFS (Tarjan's algorithm)
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    ap = [False] * n
    time = [0]

    def dfs_ap(u):
        children = 0
        disc[u] = low[u] = time[0]
        time[0] += 1
        for v in adj_list[u]:
            if disc[v] == -1:
                parent[v] = u
                children += 1
                dfs_ap(v)
                low[u] = min(low[u], low[v])
                if parent[u] == -1 and children > 1:
                    ap[u] = True
                if parent[u] != -1 and low[v] >= disc[u]:
                    ap[u] = True
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    for i in range(n):
        if disc[i] == -1:
            dfs_ap(i)

    # Find bridges using DFS
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    bridges = []
    time = [0]

    def dfs_bridge(u):
        disc[u] = low[u] = time[0]
        time[0] += 1
        for v in adj_list[u]:
            if disc[v] == -1:
                parent[v] = u
                dfs_bridge(v)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    for i in range(n):
        if disc[i] == -1:
            dfs_bridge(i)

    # Identify critical vertices: articulation points or incident to bridges
    critical = [False] * n
    for i in range(n):
        if ap[i]:
            critical[i] = True
    for u, v in bridges:
        critical[u] = True
        critical[v] = True

    # Order vertices: critical first (by degree descending), then others (by degree descending)
    vertices = list(range(n))
    critical_vertices = [v for v in vertices if critical[v]]
    non_critical_vertices = [v for v in vertices if not critical[v]]
    critical_vertices.sort(key=lambda x: degrees[x], reverse=True)
    non_critical_vertices.sort(key=lambda x: degrees[x], reverse=True)
    order = critical_vertices + non_critical_vertices

    # Greedy coloring in the determined order
    color = [-1] * n
    for u in order:
        used = [False] * (n + 1)
        for v in adj_list[u]:
            if color[v] != -1:
                used[color[v]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[u] = c

    # Compact color indices
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

