    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
