        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if coloring[u] == coloring[v]:
                        return False
        return True

    # Strategy 1: Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
    best_color = greedy_color(order_wp)
    best_k = count_colors(best_color)

    # Strategy 2: Smallest-Last ordering
    degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
    remaining = set(range(n))
