def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or list
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[j for j, val in enumerate(row) if val == 1] for row in adj]
    else:
        # Adjacency list
        adj_list = adj

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: Jaccard similarity for non-adjacent vertices
    def jaccard_similarity(u, v):
        if (bit_adj[u] >> v) & 1:  # adjacent
            return -1
        common = bit_adj[u] & bit_adj[v]
        union = bit_adj[u] | bit_adj[v]
        if union == 0:
            return 0.0
        return common.bit_count() / union.bit_count()

    # Precompute Jaccard similarities for non-adjacent pairs
    jaccard = [[0.0] * n for _ in range(n)]
    for u in range(n):
        for v in range(u + 1, n):
            sim = jaccard_similarity(u, v)
            jaccard[u][v] = jaccard[v][u] = sim

    # Greedy coloring with Jaccard-based ordering
    color = [-1] * n
    # Order vertices by descending sum of Jaccard similarities (high overlap first)
    order = sorted(range(n), key=lambda u: sum(jaccard[u]), reverse=True)

    for u in order:
        used = [False] * n
        for v in adj_list[u]:
            if color[v] != -1:
                used[color[v]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color[u] = c

    # Kempe chain-based color reduction
    def kempe_reduce(colors):
        n_local = len(colors)
        max_color = max(colors) if n_local > 0 else -1
        if max_color < 0:
            return colors

        # Try to eliminate color classes from highest to lowest
        for target_color in range(max_color, -1, -1):
            vertices = [i for i in range(n_local) if colors[i] == target_color]
            if not vertices:
                continue

            # Try to recolor each vertex in this class
            changed = True
            while changed and vertices:
                changed = False
                v = vertices.pop()
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if all(colors[u] != c for u in adj_list[v]):
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    continue

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the (c, target_color)-Kempe chain containing v
                    visited = [False] * n_local
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == c or colors[nb] == target_color):
                                visited[nb] = True
                                stack.append(nb)
                    # Check if inverting this component would not cause conflict
                    valid = True
                    for node in component:
                        for nb in adj_list[node]:
                            if not visited[nb] and colors[nb] == (target_color if colors[node] == c else c):
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        # Perform the swap
                        for node in component:
                            colors[node] = c if colors[node] == target_color else target_color
                        changed = True
                        break
                if changed:
                    vertices = [i for i in range(n_local) if colors[i] == target_color]
            # If we couldn't recolor any vertex, this color class is essential
            if vertices:
                break  # Cannot reduce further

        # Compact color indices
        unique_colors = {}
        next_color = 0
        for i in range(n_local):
            if colors[i] not in unique_colors:
                unique_colors[colors[i]] = next_color
                next_color += 1
            colors[i] = unique_colors[colors[i]]
        return colors

    color = kempe_reduce(color)
    return color

