            # Partition: U = vertices not adjacent to any in independent_set, W = adjacent
            W = set()
            for nb in adj_list[v]:
                if nb in uncolored and nb not in independent_set:
                    W.add(nb)
            U = uncolored - independent_set - W
            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and len([nb for nb in adj_list[u] if nb in U]) < len([nb for nb in adj_list[best_u] if nb in U]) if best_u != -1 else True):
                        max_w_neighbors = w_neighbors
                        best_u = u
                if best_u == -1:
                    break
                independent_set.add(best_u)
                to_remove.add(best_u)
                # Update W and U: move best_u from U, and its neighbors in U to W
                U.remove(best_u)
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to independent_set
            for v in independent_set:
                colors[v] = color_idx
            uncolored -= to_remove
            color_idx += 1
        return compact_colors(colors)

    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        degrees = [len(adj_list[i]) for i in range(n)]
        # Use buckets for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        pos = [0] * n
        for i in range(n):
            d = degrees[i]
            buckets[d].append(i)
            pos[i] = len(buckets[d]) - 1  # position in bucket
        # current degree and deleted flag
        curr_deg = degrees[:]
        deleted = [False] * n
        order = []
        for _ in range(n):
            # Find non-empty bucket with smallest degree
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            pos[v] = -1  # mark as removed from bucket
            deleted[v] = True
            order.append(v)
            # Update neighbors
            for nb in adj_list[v]:
                if not deleted[nb]:
                    d_nb = curr_deg[nb]
                    # remove nb from bucket d_nb
                    if pos[nb] < len(buckets[d_nb]):
                        buckets[d_nb][pos[nb]] = buckets[d_nb][-1]
                        if buckets[d_nb]:
                            pos[buckets[d_nb][-1]] = pos[nb]
                    curr_deg[nb] -= 1
                    d_nb_new = curr_deg[nb]
                    buckets[d_nb_new].append(nb)
                    pos[nb] = len(buckets[d_nb_new]) - 1
        # Color in reverse order
        return greedy_first_fit(order[::-1])

    # Run all heuristics
    best_coloring = None
    best_colors = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        if time.time() - start_time > 0.04:  # leave some margin
            break
        coloring = func()
        if is_proper(coloring):
            num_colors = len(set(coloring))
            if num_colors < best_colors:
                best_colors = num_colors
                best_coloring = coloring
        # If we already have a 1-coloring (edgeless), we can't do better
        if best_colors == 1:
            break

    # Fallback: if no heuristic produced a valid coloring (shouldn't happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_first_fit(list(range(n)))
        best_colors = len(set(best_coloring))

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        if time.time() - start_time > 0.045:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        improved = True
        while improved and time.time() - start_time < 0.048:
            improved = False
            # Find smallest color class (by index, assuming compact)
            color_classes = {}
            for v, c in enumerate(current):
                color_classes.setdefault(c, []).append(v)
            if not color_classes:
                break
            max_color = max(color_classes.keys())
            # Try to eliminate color classes from highest down, but we target the smallest color class for removal
            # Actually, we try to reduce the total number of colors by eliminating the highest color if possible
            # But literature often targets the largest color index (last color)
            # We'll try to see if we can recolor any vertex of color max_color to a lower color
            target_color = max_color
            if target_color == 0:
                break  # cannot reduce further
            target_vertices = color_classes.get(target_color, [])
            # Try to recolor each vertex in target_color to a lower color if possible
            for v in target_vertices:
                if time.time() - start_time > 0.048:
                    break
                used = 0
                for nb in adj_list[v]:
                    if current[nb] != -1:
                        used |= (1 << current[nb])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Check if moving v to c is valid (should be, by construction)
                        current[v] = c
                        if is_proper(current):
                            improved = True
                            break
                        else:
                            current[v] = target_color  # revert
                if improved:
                    break
                # If direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    if time.time() - start_time > 0.048:
                        break
                    # Check if v is connected to color c via a Kempe chain that we can swap
                    # We want to see if there is a Kempe chain (target_color, c) starting from v
                    # that does NOT include any vertex of color c that is adjacent to v? Actually, standard:
                    # In the subgraph induced by colors {target_color, c}, find the component containing v.
                    # If in that component, there is no vertex of color c adjacent to v? Actually, we can swap
                    # the colors in the component. After swap, v will become color c.
                    # This is valid if after swap, no adjacent vertices have same color.
                    # Since we only swap two colors, it remains proper.
                    # However, we must ensure that we don't create a conflict: but Kempe swap preserves validity.
                    # So we can always swap the component of v in (target_color, c) and it will be valid.
                    # But we want to free the target_color? Actually, after swap, v becomes c, and some vertices
                    # in the component become target_color. So the number of vertices of target_color may change.
                    # We want to eliminate the color target_color entirely, so we need to recolor all vertices
                    # of target_color. But we are doing it one by one.
                    # Instead, we attempt to recolor v to c via Kempe chain swap, which will change the color
                    # of v to c and possibly others in the component.
                    # This operation is valid and may reduce the number of vertices in target_color.
                    # We'll perform the swap and see if it reduces the count of target_color.
                    # Find the Kempe chain component of v in colors {target_color, c}
                    from collections import deque
                    comp = []
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    while queue:
                        x = queue.popleft()
                        comp.append(x)
                        for nb in adj_list[x]:
                            if nb not in visited and (current[nb] == target_color or current[nb] == c):
                                visited.add(nb)
                                queue.append(nb)
                    # Swap colors in the component
                    for x in comp:
                        if current[x] == target_color:
                            current[x] = c
                        elif current[x] == c:
                            current[x] = target_color
                    # Check if still proper (should be)
                    if is_proper(current):
                        improved = True
                        break
                    else:
                        # revert swap
                        for x in comp:
                            if current[x] == target_color:
                                current[x] = c
                            elif current[x] == c:
                                current[x] = target_color
            # After attempting to recolor vertices of target_color, compact colors
            current = compact_colors(current)
        return current

    # Apply Kempe reduction if time permits
    if time.time() - start_time < 0.045:
        best_coloring = kempe_reduction(best_coloring)

    # Final validation and compact
    if not is_proper(best_coloring):
        # Last resort: greedy on natural order
        best_coloring = greedy_first_fit(list(range(n)))
    best_coloring = compact_colors(best_coloring)

    return best_coloring

import math
