def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute bitmasks
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            neighbors[i] = adj[i][:]
            mask = 0
            for v in adj[i]:
                mask |= (1 << v)
            bit_adj[i] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to compact 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmask for fast saturation update
        neighbor_colors = [0] * n
        # degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]
        colored = [False] * n

        # Select first vertex: max degree
        v = max(range(n), key=lambda x: degrees[x])
        coloring[v] = 0
        colored[v] = True
        # Update neighbors of v
        for u in neighbors[v]:
            if not colored[u]:
                neighbor_colors[u] |= (1 << 0)
                saturation[u] = neighbor_colors[u].bit_count()

        for _ in range(1, n):
            # Select uncolored vertex with max saturation, tie-break by degree, then index
            candidates = []
            max_sat = -1
            for u in range(n):
                if not colored[u]:
                    sat = saturation[u]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [u]
                    elif sat == max_sat:
                        candidates.append(u)
            if max_sat == -1:
                break  # should not happen
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                # degree in uncolored subgraph: number of uncolored neighbors
                cand_deg = []
                for u in candidates:
                    deg = 0
                    for v in neighbors[u]:
                        if not colored[v]:
                            deg += 1
                    cand_deg.append(deg)
                max_deg = max(cand_deg)
                candidates = [candidates[i] for i in range(len(candidates)) if cand_deg[i] == max_deg]
            v = random.choice(candidates) if len(candidates) > 1 else candidates[0]

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True
            # Update neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] = neighbor_colors[u].bit_count()
        return coloring

    # RLF
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0
        # Precompute degree in full graph for initial selection
        degrees = [len(neighbors[i]) for i in range(n)]

        while not all(colored):
            # R: uncolored vertices
            R = [i for i in range(n) if not colored[i]]
            if not R:
                break
            # S: independent set for this color
            S = []
            # Step 2: choose v1 in R with max degree in G[R]
            # Compute degree in induced subgraph G[R]
            deg_in_R = [0] * n
            for u in R:
                for v in neighbors[u]:
                    if not colored[v]:
                        deg_in_R[u] += 1
            v1 = max(R, key=lambda x: deg_in_R[x])
            S.append(v1)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            in_S = [False] * n
            for u in S:
                in_S[u] = True
            U = []
            W = []
            for u in R:
                if u == v1:
                    continue
                adjacent_to_S = False
                for v in neighbors[u]:
                    if in_S[v]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.append(u)
                else:
                    U.append(u)
            # While U not empty
            while U:
                # Select u* in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                # Precompute W set for fast lookup
                W_set = set(W)
                for u in U:
                    score = 0
                    for v in neighbors[u]:
                        if v in W_set:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        deg_best = 0
                        for v in neighbors[u]:
                            if not colored[v]:
                                deg_u += 1
                        for v in neighbors[best_u]:
                            if not colored[v]:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break  # should not happen
                u_star = best_u
                S.append(u_star)
                in_S[u_star] = True
                # Remove u_star from U
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for v in neighbors[u_star]:
                    if v in U:
                        U.remove(v)
                        W.append(v)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
                colored[u] = True
            color += 1
        return coloring

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        # We'll compute the ordering and then color in reverse
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        # current degree in the remaining graph
        curr_degree = degree[:]
        ordering = []  # will be removal order (first removed first)
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # find vertex with minimum curr_degree in remaining
            min_deg = n
            v = -1
            for u in remaining:
                if curr_degree[u] < min_deg:
                    min_deg = curr_degree[u]
                    v = u
            if v == -1:
                break
            ordering.append(v)
            remaining.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    curr_degree[u] -= 1
        # Now color in reverse order
        coloring = [-1] * n
        # color vertices in reverse removal order
        for v in reversed(ordering):
            # find smallest color not used by colored neighbors
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to simple greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for v in neighbors[i]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = compact_colors(best)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        # We'll try to reduce colors until no improvement
        while changed:
            changed = False
            k = num_colors(col)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Vertices with target color
            target_vertices = [i for i in range(n) if col[i] == target_color]
            if not target_vertices:
                # Already compacted?
                col = compact_colors(col)
                continue
            # Try to recolor each target vertex
            # We'll attempt to move each to a lower color if possible
            # First, try direct reassignment
            for v in target_vertices:
                used = 0
                for u in neighbors[v]:
                    if col[u] != target_color:  # only consider neighbors not in target color (they might be recolored later, but we check current state)
                        used |= (1 << col[u])
                # Find smallest color not in used
                c = 0
                while used & (1 << c):
                    c += 1
                if c < target_color:
                    # Recolor v to c
                    col[v] = c
                    changed = True
                    # After recoloring, we may have vacated target color, but we continue to check others
            # Recompute target vertices after direct moves
            target_vertices = [i for i in range(n) if col[i] == target_color]
            if not target_vertices:
                changed = True  # we removed the color, will compact and retry
                continue
            # Try Kempe chains for remaining target vertices
            # For each target vertex, try to swap with a lower color via Kempe chain
            for v in target_vertices:
                cv = col[v]  # should be target_color
                # Try each lower color
                for c in range(target_color):
                    # Check if color c is available in neighbors? Not needed for Kempe
                    # We consider the (c, cv) Kempe chain containing v
                    # Build the component of vertices colored c or cv reachable from v
                    # We'll do BFS
                    from collections import deque
                    comp = []
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    while q:
                        u = q.popleft()
                        comp.append(u)
                        for w in neighbors[u]:
                            if not visited[w] and (col[w] == c or col[w] == cv):
                                visited[w] = True
                                q.append(w)
                    # In this component, check if there is any neighbor of v that has color c?
                    # Actually, we want to know if after swapping c<->cv in the component, 
                    # the vertex v would not conflict.
                    # After swap, v would become color c.
                    # It conflicts if any neighbor has color c after swap.
                    # Neighbors of v: if neighbor u is in the component and had color c, after swap it becomes cv.
                    # If neighbor u is not in the component and has color c, it stays c.
                    # So v conflicts after swap iff there exists a neighbor u of v with color c and u not in the component.
                    conflict = False
                    for u in neighbors[v]:
                        if col[u] == c and not visited[u]:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: c <-> cv in the component
                        for u in comp:
                            if col[u] == c:
                                col[u] = cv
                            else:  # col[u] == cv
                                col[u] = c
                        changed = True
                        break  # break from color loop, go to next target vertex
                if changed:
