        return col

    # Apply Kempe reduction
    try:
        best = kempe_reduction(best)
        best = compact_colors(best)
    except:
        pass  # if something goes wrong, keep the coloring we have

    # Final validation and compact
    if not is_valid(best):
        # Should not happen, but fallback to DSATUR
        best = dsatur()
        best = compact_colors(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    # Build neighbor list and bitmask representation
    if is_matrix:
        neighbors = [[j for j in range(n) if adj[i][j]] for i in range(n)]
    else:
        neighbors = [list(lst) for lst in adj]
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= 1 << j
        bit_adj[i] = mask

    # DSATUR heuristic
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Choose vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for nb in neighbors[x] if nb in uncolored)))
            # Determine available colors
            used = 0
            for nb in neighbors[v]:
                c = color[nb]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if nb in uncolored:
                    sat[nb] += 1
        return color

    # RLF heuristic
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            indep = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in neighbors[x] if nb in uncolored))
            indep.add(v)
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            U = uncolored - {v}
            W = set()
            for nb in neighbors[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            # Greedily add vertices from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (sum(1 for nb in neighbors[x] if nb in W), -sum(1 for nb in neighbors[x] if nb in U)))
                indep.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to independent set
            for v in indep:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering via repeated removal of min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Use buckets for efficiency (max degree <= n-1)
        max_deg = n - 1
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            for nb in neighbors[v]:
                if not removed[nb]:
                    d = deg[nb]
