                        deg[nb] -= 1
                        buckets[d].remove(nb)
                        buckets[d-1].append(nb)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in neighbors[v]:
                c = color[nb]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
