        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col[:]
    if best_color is None:
        # Fallback: greedy by vertex index
        best_color = [0] * n
        for i in range(n):
            used = 0
            for nb in neighbors[i]:
                c = best_color[nb]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            best_color[i] = c
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduction(color):
        nonlocal n, neighbors, bit_adj
        # Helper: get vertices of a color
        def color_class(c):
            return [i for i in range(n) if color[i] == c]
