        # Helper: perform Kempe swap on component of v with colors c1 and c2
        def kempe_swap(v, c1, c2):
            if color[v] not in (c1, c2):
                return False
            stack = [v]
            visited = set()
            comp = []
            while stack:
                u = stack.pop()
                if u in visited:
                    continue
                visited.add(u)
                if color[u] in (c1, c2):
                    comp.append(u)
                    for nb in neighbors[u]:
                        if nb not in visited and color[nb] in (c1, c2):
                            stack.append(nb)
            # Invert colors in component
            for u in comp:
                color[u] = c1 if color[u] == c2 else c2
            return True

        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 0:
            improved = False
            # Target smallest color class (k-1)
            target = k - 1
            target_vertices = color_class(target)
            if not target_vertices:
                # Should not happen, but skip
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in target_vertices[:]:  # iterate over copy
                # Try direct reassignment to a lower color
                for c in range(target):
                    if can_move(v, c):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    # After moving v, check if target color class is empty
                    if not color_class(target):
                        k -= 1
                        improved = True
                        break
                    else:
                        # Reset for next iteration
                        improved = False
                else:
                    # Try Kempe chain swaps with each lower color
                    for c in range(target):
                        # Check if v is in a Kempe chain that can be swapped to free color c
                        # We need that in the component of v in colors {target, c}, there is no vertex of color c
                        # that would become target after swap and cause conflict? Actually, swap is safe.
                        # Perform swap and see if v can take color c
                        # Save current color
                        orig_color = color[v]
                        if kempe_swap(v, target, c):
                            # After swap, v now has color c (if it was target) or target (if it was c)
                            # We want v to be color c, so if it was target, it's now c; good.
                            # If it was c, it's now target, not what we want.
                            if color[v] == c:
                                improved = True
                                break
                            else:
                                # Swap didn't put v in c, revert
                                kempe_swap(v, target, c)  # revert
                        # else: swap not applicable (v not in {target,c}? but we checked)
                    if improved:
                        if not color_class(target):
                            k -= 1
                            improved = True
                            break
                        else:
                            improved = False
            # Compact colors if possible
            while k > 0 and not color_class(k-1):
                k -= 1
        # Ensure colors are consecutive
        remap = {}
        next_c = 0
        for i in range(n):
            c = color[i]
            if c not in remap:
                remap[c] = next_c
                next_c += 1
            color[i] = remap[c]
        return color

    best_color = kempe_reduction(best_color)
    return best_color

