def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list and compute bitmask adjacency
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Build bitmask adjacency: bit_adj[u] has bit v set if (u,v) is an edge
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring: list[int]) -> bool:
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring: list[int]) -> int:
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring: list[int]) -> list[int]:
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur() -> list[int]:
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # colored_neighbor_masks[v] = bitmask of colors used by neighbors
        colored_neighbor_masks = [0] * n
        # degree in uncolored subgraph (for tie-breaking)
        uncolored_degree = [len(adj_list[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = uncolored_degree[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Assign smallest available color (mex)
            neighbor_mask = colored_neighbor_masks[v]
            c = 0
            while neighbor_mask & (1 << c):
                c += 1
            coloring[v] = c

            # Update neighbors of v
            for u in adj_list[v]:
                if coloring[u] == -1:  # u is uncolored
                    # Add color c to u's neighbor color mask
                    colored_neighbor_masks[u] |= (1 << c)
                    # Recompute saturation: number of distinct colors in neighbor mask
                    saturation[u] = bit_count(colored_neighbor_masks[u])
                    # Decrease uncolored degree of u (since v is now colored)
                    uncolored_degree[u] -= 1
            uncolored_count -= 1

        return compact_colors(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf() -> list[int]:
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for current color
            independent_set = []
            # Candidates: uncolored vertices not adjacent to any in independent_set
            candidates = set(uncolored)
            # Vertices adjacent to independent_set (blocked)
            blocked = set()

            # Start with vertex of max degree in uncolored subgraph
            if candidates:
                v = max(candidates, key=lambda u: len([w for w in adj_list[u] if w in uncolored]))
                independent_set.append(v)
                candidates.remove(v)
                # Update blocked and candidates
                for w in adj_list[v]:
                    if w in uncolored:
                        if w in candidates:
                            candidates.remove(w)
                        blocked.add(w)

            # Greedily add to independent set
            while candidates:
                # Select u in candidates maximizing |N(u) ∩ blocked|
                best_u = -1
                max_w = -1
                for u in candidates:
                    w_count = 0
                    for w in adj_list[u]:
                        if w in blocked:
                            w_count += 1
                    if w_count > max_w or (w_count == max_w and len([x for x in adj_list[u] if x in candidates]) < len([x for x in adj_list[best_u] if x in candidates]) if best_u != -1 else True):
                        max_w = w_count
                        best_u = u
                if best_u == -1:
                    break
                u = best_u
                independent_set.append(u)
                candidates.remove(u)
                # Move neighbors of u from candidates to blocked
                for w in adj_list[u]:
                    if w in uncolored:
                        if w in candidates:
                            candidates.remove(w)
                        blocked.add(w)

            # Assign color to all in independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return compact_colors(coloring)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last() -> list[int]:
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # Use buckets for efficiency (since n <= 100, simple scan is fine)
        for _ in range(n):
            # Find unremoved vertex with min degree
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    degree[u] -= 1

        # Color in reverse order (last removed first)
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            neighbor_colors = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors.add(coloring[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            coloring[v] = c

        return compact_colors(coloring)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        candidates.append(compact_colors(coloring))

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)

    # Kempe chain color reduction
    def eliminate_color_class(coloring: list[int], target_color: int) -> list[int] | None:
        # Try to recolor all vertices of target_color to lower colors
        # Returns new coloring if successful, else None
        n_local = len(coloring)
        # Direct reassignment first
        new_coloring = coloring[:]
        changed = False
        for v in range(n_local):
            if new_coloring[v] == target_color:
                # Try to find a free color < target_color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if new_coloring[u] != -1:
                        neighbor_colors.add(new_coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        new_coloring[v] = c
                        changed = True
                        break
                if not changed:
                    # Revert if we changed and then couldn't assign? Actually we break per vertex
                    # But we want to try all vertices; if one fails, we may need Kempe
                    # For simplicity, we'll do direct only and then Kempe per vertex
                    pass
        # If we reassigned all, check validity
        if changed and is_valid_coloring(new_coloring):
            return compact_colors(new_coloring)

        # Kempe chain approach: for each v in target_color, try to swap with a lower color
        # We'll attempt to move one vertex at a time
        target_vertices = [v for v in range(n_local) if coloring[v] == target_color]
        for v in target_vertices:
            for c in range(target_color):
                # Check if (target_color, c) Kempe chain from v does not include any other target_color vertex?
                # Actually, we want to swap in the component containing v; if after swap, no vertex remains in target_color, we can remove the color.
                # But we do it stepwise: try to move v to c via Kempe swap if possible.
                # Build the Kempe chain for colors (target_color, c) containing v
                visited = set()
                stack = [v]
                visited.add(v)
                component = set()
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for u in adj_list[node]:
                        if u not in visited and (coloring[u] == target_color or coloring[u] == c):
                            visited.add(u)
                            stack.append(u)
                # Check if swapping colors in component is valid: it always is for Kempe
                # After swap, v will have color c
                # We need to ensure that no neighbor of v has color c after swap? Actually, Kempe swap preserves validity.
                # But we want to know if after swap, v is no longer target_color (it becomes c) and we don't introduce conflict? Kempe swap is safe.
                # However, we want to eliminate target_color: after swap, if no vertex in component was target_color except v? Not necessary.
                # We can perform the swap and see if we reduce the number of target_color vertices.
                # But we are iterating; we can try to move v out of target_color.
                # Perform swap in component: target_color <-> c
                new_coloring2 = coloring[:]
                for node in component:
                    if new_coloring2[node] == target_color:
                        new_coloring2[node] = c
                    elif new_coloring2[node] == c:
                        new_coloring2[node] = target_color
                # Now v has color c
                if is_valid_coloring(new_coloring2):
                    # Success: we moved v out of target_color
                    return compact_colors(new_coloring2)
        return None

    # Iteratively try to reduce colors
    current = best_coloring[:]
    improved = True
    while improved and num_colors(current) > 1:
        improved = False
        k = num_colors(current)
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            new_coloring = eliminate_color_class(current, target_color)
            if new_coloring is not None and num_colors(new_coloring) < k:
                current = new_coloring
                improved = True
                break  # restart from highest color after reduction
        # If no elimination, break
    return current

