def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor bitmasks and degree list
    bit_adj = [0] * n
    deg = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= 1 << v
                    deg[u] += 1
    else:
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= 1 << v
                deg[u] += 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used >> c & 1:
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = saturated[u].bit_count()
                if sat > max_sat or (sat == max_sat and deg[u] > max_deg):
                    max_sat = sat
                    max_deg = deg[u]
                    v = u
                elif sat == max_sat and deg[u] == max_deg and u < v:
                    v = u
            # Assign smallest available color
            used = saturated[v]
            c = 0
            while used >> c & 1:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in uncolored:
                    saturated[u] |= 1 << c
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in uncolored if (bit_adj[x] >> y) & 1))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any((bit_adj[s] >> u) & 1 for s in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_w_nei = -1
                min_deg_u = float('inf')
                for u in U:
                    w_nei = sum(1 for w in W if (bit_adj[u] >> w) & 1)
                    deg_u = sum(1 for y in U if (bit_adj[u] >> y) & 1)
                    if w_nei > max_w_nei or (w_nei == max_w_nei and deg_u < min_deg_u) or \
                       (w_nei == max_w_nei and deg_u == min_deg_u and u < u_star):
                        max_w_nei = w_nei
                        min_deg_u = deg_u
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for y in list(U):
                    if (bit_adj[u_star] >> y) & 1:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # 3. Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        order = []
        remaining = set(range(n))
        deg_copy = deg[:]  # current degree in remaining subgraph
        # Recompute degrees in induced subgraph
        for _ in range(n):
            v = min(remaining, key=lambda x: deg_copy[x])
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    deg_copy[u] -= 1
        order.reverse()  # color in reverse removal order
        return greedy_color(order)

    # 4. Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        return greedy_color(order)

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if all(color[u] != color[v] for u in range(n) for v in range(u+1, n) if (bit_adj[u] >> v) & 1):
                k = num_colors(col)
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except Exception:
            continue

    # Fallback: greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        n_local = n
        bit_adj_local = bit_adj
        changed = True
        while changed:
            changed = False
            # Build color classes
            classes = [[] for _ in range(best_k)]
            for v in range(n_local):
                classes[coloring[v]].append(v)
            # Find smallest non-empty color class (highest index)
            for c in range(best_k - 1, -1, -1):
                if not classes[c]:
                    continue
                # Try to eliminate color c
                eliminated = True
                for v in classes[c][:]:  # iterate over copy
                    # Try direct reassignment to lower color
                    moved = False
                    for target in range(c):
                        # Check if v can take target color without conflict
                        conflict = False
                        for u in classes[target]:
                            if (bit_adj_local[v] >> u) & 1:
                                conflict = True
                                break
                        if not conflict:
                            # Move v to target
                            coloring[v] = target
                            classes[target].append(v)
                            classes[c].remove(v)
                            moved = True
                            changed = True
                            break
                    if moved:
                        continue
                    # Try Kempe chain swap with each lower color
                    for target in range(c):
                        # BFS to find (c, target) Kempe chain containing v
                        from collections import deque
                        visited = [False] * n_local
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in range(n_local):
                                if not visited[y] and ((bit_adj_local[x] >> y) & 1):
                                    if coloring[y] == c or coloring[y] == target:
                                        visited[y] = True
                                        queue.append(y)
                        # Check if swapping this component frees target color for v
                        # After swap, v would get target; check if any neighbor in target color remains
                        safe = True
                        for x in component:
                            new_color = target if coloring[x] == c else c
                            for y in range(n_local):
                                if (bit_adj_local[x] >> y) & 1 and coloring[y] == new_color and y not in component:
                                    safe = False
                                    break
                            if not safe:
                                break
                        if safe:
                            # Perform swap
                            for x in component:
                                if coloring[x] == c:
                                    coloring[x] = target
                                else:
                                    coloring[x] = c
                            # Update classes
                            for x in component:
                                if coloring[x] == target:
                                    classes[target].append(x)
                                else:
                                    classes[c].append(x)
                            # Remove from original classes (will be rebuilt, but we adjust)
                            # Instead, we break and rebuild classes after any change
                            changed = True
                            break  # break target loop
                    if changed:
                        break  # break vertex loop
                if changed:
                    break  # break color loop
            # Compact colors if highest color class is empty
            while best_k > 0 and not classes[best_k - 1]:
                best_k -= 1
            # Reindex colors to be 0..best_k-1
            if best_k < n_local:
                mapping = {}
                new_coloring = [-1] * n_local
                next_color = 0
                for c in range(best_k):
                    if classes[c]:
                        mapping[c] = next_color
                        next_color += 1
                for v in range(n_local):
                    if coloring[v] in mapping:
                        new_coloring[v] = mapping[coloring[v]]
                coloring = new_coloring
                # Rebuild classes
                classes = [[] for _ in range(best_k)]
                for v in range(n_local):
                    classes[coloring[v]].append(v)
        return coloring

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)
    # Final validation and compacting
    # Ensure valid
    for u in range(n):
        for v in range(u + 1, n):
            if (bit_adj[u] >> v) & 1 and best_coloring[u] == best_coloring[v]:
                # Should not happen, but fallback to greedy
                best_coloring = greedy_color(list(range(n)))
                break
    # Compact colors
    unique_colors = set(best_coloring)
    if unique_colors:
        mapping = {c: i for i, c in enumerate(sorted(unique_colors))]
        best_coloring = [mapping[c] for c in best_coloring]
    return best_coloring

