    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in adj_list[i]:
                mask |= 1 << j
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in adj_list[i]:
                mask |= 1 << j
            bit_adj[i] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

