            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturated[v]
                deg_v = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_v += 1
                if sat_v > best_sat or (sat_v == best_sat and deg_v > best_deg) or \
                   (sat_v == best_sat and deg_v == best_deg and v > best_v):
                    best_sat = sat_v
                    best_deg = deg_v
                    best_v = v

            v = best_v
            # Compute used colors by neighbors
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] += 1
            uncolored.remove(v)

        return compact_colors(colors)

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = {u for u in uncolored if u != v and not any(w in adj_list[u] for w in independent_set)}
            # W: vertices adjacent to at least one in independent_set
            W = {u for u in uncolored if u not in independent_set and u not in U}

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
            color_idx += 1
            uncolored -= independent_set

