    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Iterative Kempe chain color reduction
    def kempe_reduction(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue

            changed = True
            while changed and verts:
                changed = False
                # Try to recolor each vertex in this class
                new_verts = []
                for v in verts:
                    if colors[v] != target_color:  # might have been recolored
                        continue
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in adj_list[v]:
                        c = colors[u]
                        if c != -1:
                            used |= 1 << c
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            colors[v] = c
                            changed = True
                            break
                    if colors[v] == target_color:
                        new_verts.append(v)
                verts = new_verts

            # If still vertices in target_color, try Kempe chains
            if verts:
                for v in verts[:]:  # iterate over a copy
                    if colors[v] != target_color:
                        continue
                    # For each lower color, try Kempe chain swap
                    for c in range(target_color):
                        # Build the (target_color, c)-Kempe chain containing v
                        # Only if v is not already color c (it isn't, since it's target_color)
                        visited = set()
                        stack = [v]
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if colors[node] == target_color or colors[node] == c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if nb not in visited and (colors[nb] == target_color or colors[nb] == c):
                                        stack.append(nb)
