                        pass
                # Recollect verts after Kempe attempts
                verts = [v for v in range(n) if colors[v] == target_color]

        # Compact colors again
        return compact_colors(colors)

    # Apply Kempe reduction
    best = kempe_reduction(best)

    # Final validation and compact
    if not is_valid(best):
        # Should not happen, but fallback to greedy
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best = greedy_color(order)
    best = compact_colors(best)

    return best

