def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if i != j:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Helper: compute triangle count for each vertex
    def compute_triangle_counts():
        tri_count = [0] * n
        for u in range(n):
            for v in neighbors[u]:
                if v > u:
                    common = neighbors[u] & neighbors[v]
                    tri_count[u] += len(common)
                    tri_count[v] += len(common)
        return tri_count

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        saturation = [0] * n
        # Precompute degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    sat_u = saturation[u]
                    deg_u = degrees[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            neighbor_colors = 0
            for u in neighbors[v]:
                if colored[u]:
                    c = colors[u]
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u] += 1

        return compact_colors(colors)

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda u: len(neighbors[u] & uncolored))
            S = {v}
            # U: vertices not adjacent to any in S
            U = uncolored - {v} - neighbors[v]
            # W: vertices adjacent to S
            W = (uncolored - {v}) & neighbors[v]

            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = max(U, key=lambda u: len(neighbors[u] & W))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                nbrs_in_U = neighbors[u_star] & U
                U -= nbrs_in_U
                W |= nbrs_in_U

            # Assign color to all in S
            for u in S:
                colors[u] = color
            color += 1
            uncolored -= S

        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # Current degrees in remaining subgraph
        curr_deg = degrees[:]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = curr_deg[v]
            if d < len(buckets):
                buckets[d].add(v)
            else:
                # extend buckets if needed
                while len(buckets) <= d:
                    buckets.append(set())
                buckets[d].add(v)

        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_d = curr_deg[u]
                    curr_deg[u] -= 1
                    if old_d < len(buckets):
                        buckets[old_d].discard(u)
                    new_d = curr_deg[u]
                    if new_d >= len(buckets):
                        while len(buckets) <= new_d:
                            buckets.append(set())
                    buckets[new_d].add(u)

        # Color in reverse order using greedy
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Target the smallest color class (by size)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[colors[v]].append(v)
            # Find smallest non-empty class
            target_color = -1
            min_size = n + 1
            for c in range(k):
                if color_classes[c] and len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1:
                break

            # Try to recolor each vertex in target class
            for v in color_classes[target_color][:]:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors[v]:
                    if colors[u] != -1:
                        neighbor_colors |= (1 << colors[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    # Rebuild color classes and restart
                    k = num_colors(colors)
                    color_classes = [[] for _ in range(k)]
                    for u in range(n):
                        if colors[u] < k:
                            color_classes[colors[u]].append(u)
                    # Recompute target color
                    target_color = -1
                    min_size = n + 1
                    for c in range(k):
                        if color_classes[c] and len(color_classes[c]) < min_size:
                            min_size = len(color_classes[c])
                            target_color = c
                    if target_color == -1 or not color_classes[target_color]:
                        break
                    # Restart with first vertex in new target class
                    v = color_classes[target_color][0]
                    continue

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build (c, target_color) Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if colors[node] == c or colors[node] == target_color:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (colors[u] == c or colors[u] == target_color):
                                    stack.append(u)
                    # Check if swapping is safe: no neighbor of v in component has color c
                    safe = True
                    for node in component:
                        for u in neighbors[node]:
                            if u not in component and colors[u] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for node in component:
                            if colors[node] == c:
                                colors[node] = target_color
                            else:
                                colors[node] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                k = num_colors(colors)
        return compact_colors(colors)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        colors = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid_coloring(best):
        # Last resort: greedy
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        colors = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        best = compact_colors(colors)
    else:
        best = compact_colors(best)

    return best

