    def jaccard_heuristic():
        # Precompute Jaccard similarity for non-adjacent pairs
        # Only consider pairs with non-zero potential similarity
        pairs = []
        for i in range(n):
            for j in range(i+1, n):
                if j not in adj_list[i]:  # non-adjacent
                    # Compute Jaccard similarity: |N(i) ∩ N(j)| / |N(i) ∪ N(j)|
                    set_i = set(adj_list[i])
                    set_j = set(adj_list[j])
                    intersection = len(set_i & set_j)
                    union = len(set_i | set_j)
                    if union > 0:
                        similarity = intersection / union
                        if similarity > 0:  # only consider useful pairs
                            pairs.append((similarity, i, j))

        # Sort by similarity descending
        pairs.sort(key=lambda x: x[0], reverse=True)

