                coloring[j] = c
            elif coloring[i] == -1 and coloring[j] != -1:
                # Only i uncolored, try to give it j's color if possible
                c = coloring[j]
                # Check if i can take color c (i.e., no neighbor has color c)
                conflict = False
                for nb in adj_list[i]:
                    if coloring[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    coloring[i] = c
            elif coloring[i] != -1 and coloring[j] == -1:
                # Only j uncolored, try to give it i's color if possible
                c = coloring[i]
                conflict = False
                for nb in adj_list[j]:
                    if coloring[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    coloring[j] = c

        # Color remaining uncolored vertices with first-fit
        for v in range(n):
            if coloring[v] == -1:
                used = [False] * (n + 1)
                for nb in adj_list[v]:
                    if coloring[nb] != -1:
                        used[coloring[nb]] = True
                c = 0
                while used[c]:
                    c += 1
                coloring[v] = c

        return normalize(coloring)

    # Run all strategies and collect results
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Jaccard", jaccard_heuristic)
    ]

    best_coloring = None
    best_num_colors = float('inf')

    for name, strategy in strategies:
        try:
            coloring = strategy()
            # Validate coloring
            if is_valid_coloring(coloring):
                num = num_colors(coloring)
                if num < best_num_colors:
                    best_num_colors = num
                    best_coloring = coloring[:]
            else:
                # Invalid coloring, skip
                pass
        except Exception:
            # In case of error, skip this strategy
            pass

    # Fallback: if all strategies failed, use simple greedy
    if best_coloring is None:
        coloring = [-1] * n
        for v in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))

    return best_coloring

