def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = adj
    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= 1 << v
        bit_adj[u] = mask
    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color[v]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color
    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0
    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break by degree in uncolored subgraph
                v = max(candidates, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Start new color class
            # Pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not (bit_adj[v] >> u) & 1}
            W = {u for u in uncolored if (bit_adj[v] >> u) & 1}
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in U
                        deg_u = sum(1 for y in adj_list[u] if y in U)
                        deg_best = sum(1 for y in adj_list[best_u] if y in U) if best_u is not None else math.inf
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break  # Should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
        return color
    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[v]) for v in range(n)]
        order = []
        # Use buckets for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # Find next min degree vertex in remaining
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            # Find a vertex in bucket[min_deg] that is still in remaining
            v = None
            while buckets[min_deg]:
                candidate = buckets[min_deg].pop()
                if candidate in remaining:
                    v = candidate
                    break
            if v is None:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < min_deg:
                        min_deg = d-1
        # Color in reverse order
        return greedy_color(list(reversed(order)))
    # Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Ensure coloring uses consecutive colors
        def renormalize(col):
            mapping = {}
            next_color = 0
            for c in col:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in col]
        coloring = renormalize(coloring)
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        improved = True
        # Try to eliminate color classes from highest down
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            # Try to recolor each target vertex
            for v in target_vertices:
                used = 0
                for u in adj_list[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= 1 << c
                # Find smallest available color < target_color
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Direct move possible
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    # After moving one vertex, we may have emptied target color; break to renormalize
                    break
                # Try Kempe chains with each color c < target_color
                for c in range(target_color):
                    # If v already has color c (should not happen), skip
                    if coloring[v] == c:
                        continue
                    # Build Kempe chain for colors (target_color, c) starting from v
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == target_color or coloring[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if swapping colors in component would cause conflict
                    # For each vertex in component, after swap, check neighbors
                    valid = True
                    for x in component:
                        orig_c = coloring[x]
                        new_c = c if orig_c == target_color else target_color
                        for y in adj_list[x]:
                            if coloring[y] == new_c:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        # Perform swap
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:
                                coloring[x] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Renormalize colors to be consecutive
                coloring = renormalize(coloring)
                k = num_colors(coloring)
            else:
                # Could not reduce further
                break
        return coloring
    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    candidates.append(welsh_powell())
    # Select best (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction
    best = kempe_reduce(best)
    # Final validation (optional, but ensure correctness)
    # Verify no adjacent same color
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best[u] == best[v]:
                # Fallback: if invalid, use greedy on random order (should not happen)
                for _ in range(10):
                    order = list(range(n))
                    random.shuffle(order)
                    trial = greedy_color(order)
                    if all(trial[u] != trial[v] for u in range(n) for v in adj_list[u] if u < v):
                        best = trial
                        break
                else:
                    # Last resort: use DSATUR again
                    best = dsatur()
                break
    # Ensure colors are consecutive starting from 0
    def final_renormalize(col):
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]
    return final_renormalize(best)

