        # We'll maintain a list of uncolored vertices
        # For efficiency, we use a list and mark colored
        uncolored = [True] * n
        current_color = 0

        # Precompute adjacency as sets for fast lookup
        adj_set = [set(neigh) for neigh in graph]

        while any(uncolored):
            # Build maximal independent set for current_color
            # Step 1: choose vertex with max degree in the uncolored subgraph
            # We'll compute degree in the uncolored subgraph on the fly
            max_deg = -1
            v1 = -1
            for u in range(n):
                if uncolored[u]:
                    # count uncolored neighbors
                    deg = 0
                    for v in graph[u]:
                        if uncolored[v]:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v1 = u
            if v1 == -1:  # should not happen
                break
            # Start independent set with v1
            independent_set = [v1]
            uncolored[v1] = False
            # Partition remaining uncolored into U and W
            # U: not adjacent to any in independent_set
            # W: adjacent to at least one in independent_set
            U = set()
            W = set()
            for u in range(n):
                if uncolored[u]:
                    # check if adjacent to any in independent_set
                    adjacent = False
                    for v in independent_set:
