        color = [-1] * n
        for u in reversed(order):
            used = [False] * (n + 1)
            for v in graph[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            color[u] = c
        return renumber_colors(color)

    # Run all strategies and pick the best (fewest colors)
    strategies = [
        ("bipartite_plus_greedy", bipartite_plus_greedy),
        ("dsatur", dsatur),
        ("rlf", rlf),
        ("smallest_last", smallest_last)
    ]

    best_coloring = None
    best_num_colors = float('inf')

    for name, strategy in strategies:
        try:
