            # Validate
            if is_valid_coloring(coloring):
                num = num_colors(coloring)
                if num < best_num_colors:
                    best_num_colors = num
                    best_coloring = coloring
            else:
                # If invalid, try to fix by greedy? but we assume our strategies are valid
                pass
        except Exception:
            # In case of error, skip
            continue

    # Fallback: if all failed, use greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        color = [-1] * n
        for u in order:
