    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = [False] * n
            for v in graph[u]:
                if coloring[v] != -1:
                    used[coloring[v]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[u] = c
        return coloring

    # Strategy 1: DSATUR
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree
        colored_neighbors = [set() for _ in range(n)]  # track distinct neighbor colors
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            candidates = []
            max_sat = -1
            for v in uncolored:
                if saturated[v] > max_sat:
                    max_sat = saturated[v]
                    candidates = [v]
                elif saturated[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:  # all saturated 0, pick max degree in uncolored
                max_deg = -1
                for v in uncolored:
                    deg = sum(1 for u in graph[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        candidates = [v]
                    elif deg == max_deg:
                        candidates.append(v)
            v = random.choice(candidates) if candidates else next(iter(uncolored))
            # assign smallest available color
            used = [False] * n
            for u in graph[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in graph[v]:
                if u in uncolored and c not in colored_neighbors[u]:
                    colored_neighbors[u].add(c)
                    saturated[u] += 1
        return coloring

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # pick vertex with max degree in uncolored subgraph
            if not uncolored:
                break
            max_deg = -1
            candidates = []
            for v in uncolored:
                deg = sum(1 for u in graph[v] if u in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    candidates = [v]
                elif deg == max_deg:
                    candidates.append(v)
            v1 = random.choice(candidates) if candidates else next(iter(uncolored))
            S.add(v1)
            # U: vertices not adjacent to S, W: adjacent to S
            U = uncolored - {v1}
            W = set()
            for u in U:
                if any(w in graph[u] for w in S):
                    W.add(u)
            U -= W
            # grow independent set
            while U:
                # select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in graph[u] if w in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = sum(1 for x in graph[u] if x in U)
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = sum(1 for x in graph[u] if x in U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                if best_u is None:
                    break
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for nb in graph[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(graph[v]) for v in range(n)]
        order = []
        bucket = [[] for _ in range(n)]  # degree buckets
        pos = [0] * n
        for v in range(n):
            d = degree[v]
            if d < n:
                bucket[d].append(v)
                pos[v] = len(bucket[d]) - 1
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr < n and not bucket[ptr]:
                ptr += 1
            if ptr >= n:
                break
            v = bucket[ptr].pop()
            pos[v] = -1  # removed
            order.append(v)
            # update neighbors
            for u in graph[v]:
                if pos[u] >= 0:  # still in remaining
                    d = degree[u]
                    # remove u from bucket[d]
                    idx = pos[u]
                    last = bucket[d][-1]
                    bucket[d][idx] = last
                    pos[last] = idx
                    bucket[d].pop()
                    degree[u] -= 1
                    dnew = degree[u]
                    if dnew < n:
                        bucket[dnew].append(u)
                        pos[u] = len(bucket[dnew]) - 1
            # update ptr if needed
            if ptr > degree[v]:
                ptr = degree[v]
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * n
            for u in graph[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # Strategy 4: Spectral-inspired clustering via random walk (approximate)
    def spectral_cluster():
        if n == 0:
            return []
        # stationary distribution approximation via random walk
        # use heat kernel: p(t) = exp(-t * L) * 1, approximate with few steps
        t = min(10, max(1, n // 10))  # diffusion steps
        # initialize vector
        p = [1.0] * n
        for _ in range(t):
            p_new = [0.0] * n
            for u in range(n):
                if graph[u]:
                    prob = p[u] / len(graph[u])
                    for v in graph[u]:
                        p_new[v] += prob
                else:
                    p_new[u] += p[u]  # isolated vertex retains mass
            p = p_new
        # use p as feature, sort vertices by p value
        order = sorted(range(n), key=lambda x: p[x])
        # greedy coloring in that order
        return greedy_color(order)

    # Run all strategies
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Spectral", spectral_cluster)
    ]
    best_coloring = None
    best_k = float('inf')
    for name, func in strategies:
        try:
            coloring = func()
            if is_valid(coloring):
                k = count_colors(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        best_coloring = greedy_color(order)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        if not is_valid(coloring):
            return coloring
        # map color to list of vertices
        color_classes = {}
        for v, c in enumerate(coloring):
            color_classes.setdefault(c, []).append(v)
        colors = sorted(color_classes.keys())
        # try to eliminate highest color classes
        changed = True
        while changed and len(color_classes) > 1:
            changed = False
            max_color = max(color_classes.keys())
            if max_color == 0:
                break
            # try to recolor each vertex in max_color class
            for v in color_classes[max_color][:]:
                # try direct reassignment to lower color
                used = set()
                for u in graph[v]:
                    if coloring[u] != -1:
                        used.add(coloring[u])
                for c in range(max_color):
                    if c not in used:
                        # move v to color c
                        coloring[v] = c
                        color_classes[c].append(v)
                        color_classes[max_color].remove(v)
                        if not color_classes[max_color]:
                            del color_classes[max_color]
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(max_color):
                    if c in used:
                        continue
                    # find (c, max_color) Kempe chain containing v
                    # BFS over vertices colored c or max_color
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in graph[x]:
                            if coloring[y] in (c, max_color) and y not in visited:
                                visited.add(y)
                                queue.append(y)
                    # check if swapping c and max_color in component is valid
                    # it always preserves validity, but we want to see if it removes v from max_color
                    # after swap, v will have color c if it was max_color
                    # we can always swap, but we want to free the max_color class if possible
                    # actually, swapping will move v to color c, so we can do it
                    # perform swap
                    for x in component:
                        if coloring[x] == max_color:
                            coloring[x] = c
                        elif coloring[x] == c:
                            coloring[x] = max_color
                    # update color classes
                    for x in component:
                        if coloring[x] == max_color:
                            color_classes[max_color].append(x)
                        elif coloring[x] == c:
                            color_classes[c].append(x)
                    # rebuild color_classes from scratch to be safe
                    color_classes = {}
                    for idx, col in enumerate(coloring):
                        color_classes.setdefault(col, []).append(idx)
                    if not color_classes.get(max_color, []):
                        changed = True
                        break
            if changed:
                # compact colors if possible
                # remap colors to 0..k-1
                unique_colors = sorted(set(coloring))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                coloring = [mapping[c] for c in coloring]
        return coloring

    best_coloring = kempe_reduction(best_coloring)
    # final validation and compacting
    if not is_valid(best_coloring):
        # last resort: greedy
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        best_coloring = greedy_color(order)
    # compact colors
    unique_colors = sorted(set(best_coloring))
    if unique_colors != list(range(len(unique_colors))):
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]
    return best_coloring

