                # Already normalized, should not happen
                break

            # Try to recolor each target vertex
            for v in targets:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if col[u] != -1:
                        used_by_neighbors |= (1 << col[u])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor v to c
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart while loop after change

                # Try Kempe chain swaps for each lower color
                for c in range(target_color):
                    # Check if v can be recolored to c via Kempe chain (target_color, c)
                    # We'll do BFS/DFS for the Kempe chain starting from v
                    # Only consider vertices colored target_color or c
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    # We'll also check if we can swap: after swap, v would be c, and we need to ensure
                    # that no neighbor of v becomes c (which would cause conflict)
                    # Actually, in Kempe swap, we swap colors in the component: target_color <-> c
                    # After swap, v becomes c. We need to check that no neighbor of v is c after swap.
                    # But note: neighbors of v that are in the component and colored c will become target_color.
                    # So we need to check: for any neighbor u of v, if u is in the component and colored c, 
                    # after swap it becomes target_color -> safe because v becomes c (different).
                    # If u is in the component and colored target_color, after swap becomes c -> conflict if v becomes c? 
                    # Actually, if u is neighbor of v and in component and colored target_color, after swap u becomes c and v becomes c -> conflict.
                    # Therefore, we can only perform the swap if there is no neighbor of v in the component that is colored target_color.
                    # But wait: v is in the component and colored target_color. Its neighbors in the component that are colored target_color would become c -> conflict with v becoming c.
                    # So we must avoid having any neighbor of v in the component that is colored target_color (except v itself? but v is not neighbor of itself).
                    # Actually, we can rephrase: after swap, the color of v becomes c. We need that for every neighbor u of v, col[u] != c after swap.
                    # After swap:
                    #   if u in component: 
                    #       if original col[u] == target_color -> becomes c
                    #       if original col[u] == c -> becomes target_color
                    #   else: remains col[u]
                    # So we require: for every neighbor u of v:
                    #   if u in component: then original col[u] != target_color (because if it were, it becomes c and conflicts with v's new color c)
                    #   if u not in component: then original col[u] != c
                    #
                    # Alternatively, we can simulate: 
                    #   Let's collect the component and then check the condition.
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (col[y] == target_color or col[y] == c):
                                visited[y] = True
                                queue.append(y)

                    # Now check if we can swap: 
                    # Condition: for every neighbor u of v, 
                    #   if u in component: then col[u] must not be target_color (because after swap it becomes c, and v becomes c -> conflict)
                    #   if u not in component: then col[u] must not be c
                    valid_swap = True
                    for u in adj_list[v]:
                        if u in component:
                            if col[u] == target_color:
                                valid_swap = False
                                break
                        else:
                            if col[u] == c:
                                valid_swap = False
                                break
                    if valid_swap:
                        # Perform swap: in the component, swap target_color and c
                        for x in component:
                            if col[x] == target_color:
                                col[x] = c
                            elif col[x] == c:
                                col[x] = target_color
                        changed = True
                        break  # break from c loop
                if changed:
                    break  # break from targets loop
            # If we changed, we break and restart the while loop to possibly reduce further
            if changed:
                # Normalize after change? We'll do at the end of while loop
                pass
        return normalize(col)

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), use greedy
    if not candidates:
        # Simple greedy: order by index
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        candidates.append(normalize(colors))

    # Select candidate with fewest colors
    best = min(candidates, key=lambda x: num_colors(x))

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best)
        if is_valid(improved) and num_colors(improved) <= num_colors(best):
            best = improved
    except:
        pass

    # Final normalization and validation
    best = normalize(best)
    # Double-check validity (should be, but ensure)
    if not is_valid(best):
        # Fallback to greedy
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best = normalize(colors)

    return best

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count number of colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and deg_uncolored[u] > max_deg) or \
                   (s == max_sat and deg_uncolored[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = s
                    max_deg = deg_uncolored[u]
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # start with vertex of max degree in uncolored subgraph
            deg_uncolored = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - set(neighbors[v])
            W = set(neighbors[v]) & uncolored
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    deg_u = sum(1 for w in neighbors[u] if w in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or \
                       (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        # bin vertices by degree
        max_deg = max(deg) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            bins[deg[v]].append(v)
        # pointer to current bin
        pos = [0] * (max_deg + 1)
        # current degree of each vertex
        cur_deg = deg[:]
        # ordering stack
        order = []
        for _ in range(n):
            # find vertex with minimum degree
            d = 0
            while d <= max_deg and (pos[d] >= len(bins[d]) or cur_deg[bins[d][pos[d]]] != d):
                d += 1
            if d > max_deg:
                break  # should not happen
            v = bins[d][pos[d]]
            pos[d] += 1
            order.append(v)
            # decrease degree of neighbors
            for u in neighbors[v]:
                if cur_deg[u] > d:
                    # move u from bin cur_deg[u] to cur_deg[u]-1
                    old_deg = cur_deg[u]
                    cur_deg[u] -= 1
                    bins[old_deg].remove(v)  # inefficient but n <= 100
                    bins[cur_deg[u]].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate initial candidates
    candidates = []
    start_time = time.time()
    # DSATUR
    if time.time() - start_time < 0.04:  # leave time for others
        col = dsatur()
        if is_valid(col):
            candidates.append(col)
    # RLF
    if time.time() - start_time < 0.04:
        col = rlf()
        if is_valid(col):
            candidates.append(col)
    # Smallest-Last
    if time.time() - start_time < 0.04:
        col = smallest_last()
        if is_valid(col):
            candidates.append(col)
    # Fallback: simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)

    # Select best initial candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors) if candidates else [0]*n
    best_k = count_colors(best_coloring)

    # If already optimal (lower bound: max clique size, but we use degeneracy + 1 as bound)
    # Compute degeneracy for lower bound
    def degeneracy():
        deg = [len(neighbors[i]) for i in range(n)]
        max_deg = max(deg) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            bins[deg[v]].append(v)
        pos = [0] * (max_deg + 1)
        cur_deg = deg[:]
        d_max = 0
        for _ in range(n):
            d = 0
            while d <= max_deg and (pos[d] >= len(bins[d]) or cur_deg[bins[d][pos[d]]] != d):
                d += 1
            if d > max_deg:
                break
            v = bins[d][pos[d]]
            pos[d] += 1
            if d > d_max:
                d_max = d
            for u in neighbors[v]:
                if cur_deg[u] > d:
                    old_deg = cur_deg[u]
                    cur_deg[u] -= 1
                    bins[old_deg].remove(v)
                    bins[cur_deg[u]].append(u)
        return d_max
    lb = degeneracy() + 1
    if best_k == lb:
        # compact colors
        mapping = {}
        next_color = 0
        for c in best_coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in best_coloring]

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        changed = True
        while changed and count_colors(coloring) > lb:
            changed = False
            k = count_colors(coloring)
            # target smallest color class (color k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                # should not happen, but compact anyway
                mapping = {}
                next_color = 0
                for c in coloring:
                    if c not in mapping:
                        mapping[c] = next_color
                        next_color += 1
                return [mapping[c] for c in coloring]
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has color c due to previous swap, skip
                    if coloring[v] == c:
                        changed = True
                        break
                    # Build (c, target_color) Kempe chain containing v
                    # BFS to get component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if swapping colors in component frees color c for v
                    # After swap, v would have color c (since it was target_color)
                    # We need to ensure no neighbor of v has color c after swap
                    conflict = False
                    for x in component:
                        for y in neighbors[x]:
                            if y not in component and coloring[y] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            else:
                                coloring[x] = c
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                # cannot reduce further
                break
        return coloring

    # Apply Kempe reduction with time limit
    if time.time() - start_time < 0.045:
        improved = kempe_reduce(best_coloring[:])
        if is_valid(improved):
            improved_k = count_colors(improved)
            if improved_k < best_k:
                best_coloring = improved
                best_k = improved_k

    # Final compacting
    mapping = {}
    next_color = 0
    for c in best_coloring:
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
    final_coloring = [mapping[c] for c in best_coloring]

    # Ensure validity (should be, but double-check)
    if not is_valid(final_coloring):
        # last resort: greedy by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        final_coloring = greedy_color(order)
        mapping = {}
        next_color = 0
        for c in final_coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        final_coloring = [mapping[c] for c in final_coloring]

    return final_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Convert adjacency representation to bitmask list
    bit_adj = [0] * n
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1 and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Helper: 1-opt local improvement
    def local_improve(coloring):
        improved = True
        while improved:
            improved = False
            for u in range(n):
                used = 0
                for v in range(n):
                    if (bit_adj[u] >> v) & 1 and coloring[v] != -1:
                        used |= (1 << coloring[v])
                # Try to find a better color for u
                for c in range(num_colors(coloring) + 1):
                    if not (used & (1 << c)):
                        if c < coloring[u]:
                            coloring[u] = c
                            improved = True
                        break
        return coloring

    # Multiple randomized greedy passes
    best_coloring = None
    best_k = float('inf')
    vertices = list(range(n))

    # Run 10 fast passes with random ordering and local improvement
    for _ in range(10):
        random.shuffle(vertices)
        coloring = greedy_color(vertices)
        coloring = local_improve(coloring)
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]

    # Fallback: if no valid coloring found (should not happen), use greedy on natural order
    if best_coloring is None or not is_valid(best_coloring):
        coloring = greedy_color(list(range(n)))
        coloring = local_improve(coloring)
        best_coloring = coloring

    # Ensure colors are compact (0..k-1)
    if best_coloring:
        # Relabel colors to be consecutive
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [list(lst) for lst in adj]  # copy to avoid mutation

    # Convert to bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with bitmask
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree as bitmask of used neighbor colors
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << 0)
        while uncolored:
            # Select vertex with max saturation degree (number of colors in sat[v])
            v = max(uncolored, key=lambda x: (sat[x].bit_count(), len(neighbors[x]), -x))
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent = [v]
            uncolored.remove(v)
            # Partition: U = not adjacent to any in independent, W = adjacent to at least one
            U = {u for u in uncolored if all((bit_adj[u] & (1 << w)) == 0 for w in independent)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: sum(1 for y in neighbors[x] if y in W), default=None)
                if u is None:
                    break
                # Tie-break: min degree in U subgraph
                candidates = [x for x in U if sum(1 for y in neighbors[x] if y in W) == sum(1 for y in neighbors[u] if y in W)]
                u = min(candidates, key=lambda x: sum(1 for y in neighbors[x] if y in U))
                independent.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to independent set
            for v in independent:
                color[v] = c
            c += 1
            uncolored = W  # next round
        return color

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering via peeling min degree
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[v]) for v in range(n)]
        # Current degree in remaining subgraph
        curr_deg = degrees[:]
        while remaining:
            # Find vertex of minimum current degree
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # Color in reverse order
