            # Find vertex with minimum curr_degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if curr_degree[v] < min_deg:
                    min_deg = curr_degree[v]
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update neighbors' degrees
            for u in adj_list[v_min]:
                if u in remaining:
                    curr_degree[u] -= 1

        # Color in reverse order (last removed first)
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color

