    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        # We'll try to reduce colors until no improvement
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # Already normalized, should not happen
                break

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if current[u] != -1:
                        neighbor_colors.add(current[u])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if c not in neighbor_colors:
                        # Direct move possible
                        current[v] = c
                        changed = True
                        break
                if changed:
                    # After moving v, we might have emptied target_color, but we'll check later
                    continue

