                for c in range(target_color):
                    # We consider swapping colors target_color and c in the component containing v
                    # Only if v is not already c (it isn't, since we tried direct)
                    # Build the Kempe chain: connected component of v in subgraph induced by colors {c, target_color}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for u in adj_list[node]:
                            if not visited[u] and (current[u] == c or current[u] == target_color):
                                visited[u] = True
                                queue.append(u)

                    # Check if swapping is safe: no neighbor of any node in component has color c (if we swap target->c) 
                    # or target_color (if we swap c->target) that would cause conflict?
                    # Actually, swapping colors in a Kempe chain preserves validity.
                    # But we want to know if after swap, v becomes c and we free target_color?
                    # After swap: 
                    #   nodes in component that were c become target_color
                    #   nodes in component that were target_color become c
                    # So v (which was target_color) becomes c.
                    # We need to ensure that no neighbor of v is colored c after swap? 
                    # But if a neighbor of v is colored c and is in the component, then after swap it becomes target_color -> no conflict.
                    # If a neighbor of v is colored c and is NOT in the component, then after swap it remains c -> conflict if v becomes c.
                    # So we must check: for all neighbors u of v, if current[u] == c, then u must be in the component.
                    # Similarly, we don't care about target_color neighbors because they become c? 
