                # For now, we break and will normalize after the loop.
                # Actually, we can continue to try to reduce further.
                # But note: we might have introduced gaps. We'll normalize at the end of kempe_reduce.
                # For efficiency, we break and let the outer loop continue (which will recompute k)
                pass

        # Normalize the coloring to 0..k-1
        return normalize_colors(current)

    # Run all heuristics and keep the best (minimum colors)
    best_coloring = None
    best_num_colors = float('inf')

    # List of heuristic functions
    heuristics = [dsatur, rlf, smallest_last]

    for heuristic in heuristics:
        try:
            coloring = heuristic()
            if not is_valid_coloring(coloring):
                # If invalid, skip (should not happen if implemented correctly)
                continue
            num = num_colors(coloring)
            if num < best_num_colors:
                best_num_colors = num
                best_coloring = coloring
        except Exception:
            # In case of error, skip this heuristic
            continue

    # If no heuristic produced a valid coloring, fall back to trivial greedy
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors.add(coloring[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            coloring[v] = c
        best_coloring = normalize_colors(coloring)

    # Apply Kempe chain reduction to try to improve
    best_coloring = kempe_reduce(best_coloring)

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # As a last resort, use greedy with random order
        for _ in range(10):
