def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            if len(row) != len(adj):
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask adjacency
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring: list[int]) -> bool:
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring: list[int]) -> int:
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1 consecutive
    def normalize(coloring: list[int]) -> list[int]:
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        coloring = [-1] * n
        colored = [False] * n
        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in range(n):
                if colored[v]:
                    continue
                # Compute saturation degree: distinct colors in neighbors
                neighbor_colors = 0
                for u in adj_list[v]:
                    if colored[u]:
                        neighbor_colors |= (1 << coloring[u])
                sat = bit_count(neighbor_colors)
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    # Count uncolored neighbors
                    deg_uncolored = 0
                    for u in adj_list[v]:
                        if not colored[u]:
                            deg_uncolored += 1
                    if deg_uncolored > max_deg:
                        max_deg = deg_uncolored
                        best_v = v
                    elif deg_uncolored == max_deg and v < best_v:
                        best_v = v
                v = best_v
            else:
                v = candidates[0]

            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if colored[u]:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True
        return coloring

    # RLF (Recursive Largest First)
    def rlf() -> list[int]:
        coloring = [-1] * n
        uncolored_set = set(range(n))
        color = 0
        while uncolored_set:
            # Step 1: pick vertex with max degree in G[R]
            max_deg = -1
            v1 = None
            for v in uncolored_set:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored_set:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v1 = v
                elif deg == max_deg and v1 is not None and v < v1:
                    v1 = v
            if v1 is None:
                break  # should not happen
            S = {v1}
            # Partition R \ {v1} into U and W
            U = set()
            W = set()
            for v in uncolored_set:
                if v == v1:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.add(v)
            # Step 4: while U not empty
            while U:
                # Select u* in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for x in adj_list[u]:
                            if x in U:
                                deg_u += 1
                        deg_best = 0
                        for x in adj_list[best_u]:
                            if x in U:
                                deg_best += 1
                        if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                            best_u = u
                # Add best_u to S, move from U to S, and update W
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u in U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            # Next color, set R = W
            uncolored_set = W
            color += 1
        return coloring

    # Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last() -> list[int]:
        # Build core order by repeatedly removing min degree vertex
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll simulate removal
        current_degree = degree[:]
        removed = [False] * n
        for _ in range(n):
            # Find vertex with min current degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if current_degree[v] < min_deg:
                    min_deg = current_degree[v]
                    v_min = v
                elif current_degree[v] == min_deg and v < v_min:
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            removed[v_min] = True
            remaining.remove(v_min)
            # Update degrees of neighbors
            for nb in adj_list[v_min]:
                if not removed[nb]:
                    current_degree[nb] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain elimination to reduce colors
    def kempe_reduce(coloring: list[int]) -> list[int]:
        if not coloring:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        # We'll try to reduce colors as much as possible
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            target_color = k - 1
            # Try to eliminate target_color
            # First, try direct reassignment for each vertex with target_color
            vertices_target = [v for v in range(n) if current[v] == target_color]
            # Try to reassign each to a lower color if possible
            made_progress = False
            for v in vertices_target:
                used = 0
                for nb in adj_list[v]:
                    if current[nb] != -1:
                        used |= (1 << current[nb])
                # Try colors from 0 to target_color-1
                for c in range(target_color):
                    if not (used & (1 << c)):
                        current[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
            if made_progress:
                changed = True
                continue
            # If direct reassignment fails, try Kempe chains
            for v in vertices_target:
                # For each lower color c, try to swap in Kempe chain (target_color, c)
                for c in range(target_color):
                    # Check if v is adjacent to any vertex of color c -> if yes, swapping might not free c for v
                    has_adjacent_c = False
                    for nb in adj_list[v]:
                        if current[nb] == c:
                            has_adjacent_c = True
                            break
                    if has_adjacent_c:
                        continue  # swapping would put c on a neighbor of v, not useful
                    # Build the Kempe chain component containing v for colors (target_color, c)
                    # We'll do BFS/DFS over vertices with color target_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if current[node] == target_color or current[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if current[nb] == target_color or current[nb] == c:
                                    if nb not in visited:
                                        stack.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we already know v has no neighbor of color c.
                    # But we need to ensure that swapping does not cause conflict: after swap, neighbors of v should not have color c (which becomes target_color)
                    # Since v had no neighbor of color c, after swap v becomes c, and its neighbors that were target_color become c? Wait:
                    # In the component, we swap target_color <-> c.
                    # For a neighbor u of v:
                    #   If u is in component and had color target_color -> becomes c -> conflict with v (which becomes c) -> bad.
                    #   If u is in component and had color c -> becomes target_color -> no conflict (v becomes c).
                    #   If u not in component: color unchanged.
                    # So we need that no neighbor of v in the component has color target_color (because they would become c and conflict with v's new color c).
                    # Actually, if neighbor u is in component and had color target_color, after swap it becomes c, same as v's new color -> conflict.
                    # Therefore, we can only perform the swap if v has no neighbor in the component that is colored target_color.
                    safe = True
                    for nb in adj_list[v]:
                        if nb in component and current[nb] == target_color:
                            safe = False
                            break
                    if not safe:
                        continue
                    # Perform swap: for all nodes in component, swap target_color and c
                    for node in component:
                        if current[node] == target_color:
                            current[node] = c
                        elif current[node] == c:
                            current[node] = target_color
                    made_progress = True
                    break
                if made_progress:
                    break
            if made_progress:
                changed = True
        # Normalize colors to be consecutive
        return normalize(current)

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        greedy = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if greedy[nb] != -1:
                    used |= (1 << greedy[nb])
            c = 0
            while used & (1 << c):
                c += 1
            greedy[i] = c
        candidates.append(greedy)

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and normalization
    if not is_valid(best):
        # Should not happen, but fallback to greedy
        greedy = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if greedy[nb] != -1:
                    used |= (1 << greedy[nb])
            c = 0
            while used & (1 << c):
                c += 1
            greedy[i] = c
        best = greedy
    best = normalize(best)
    return best

