            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any(w in S for w in neighbors[u])}
            W = {u for u in uncolored if u not in S and u not in U}
            while U and time.time() - start_time < 0.04:
