                        U.remove(w)
                        W.add(w)
            # Assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # --- Heuristic 3: Smallest-Last (Degeneracy Ordering) ---
    if time.time() - start_time < 0.04:
        # Compute smallest-last ordering via core decomposition
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Peeling
        for _ in range(n):
            # Find non-empty bucket with smallest degree
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # Remove u from current bucket
                    if degree[u] < len(buckets):
                        buckets[degree[u]].remove(u)
                    degree[u] -= 1
                    if degree[u] < len(buckets):
                        buckets[degree[u]].append(u)
        # Color in reverse order
        color = greedy_color(order[::-1])
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # Fallback: if no heuristic succeeded, use simple greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best_coloring = greedy_color(order)
        best_k = num_colors(best_coloring)

    # --- Kempe Chain Color Reduction ---
    def kempe_reduce(coloring):
        nonlocal best_k, best_coloring
        # Try to eliminate color classes from highest downward
        changed = True
        while changed and time.time() - start_time < 0.04:
            changed = False
            # Find smallest non-empty color class (highest color index that is used)
            used_colors = set(coloring)
            if not used_colors:
                break
            max_color = max(used_colors)
            # Try to eliminate each color class from max_color down to 1
            for target_color in range(max_color, 0, -1):
                if time.time() - start_time > 0.04:
                    break
                # Get vertices with this color
                target_vertices = [v for v in range(n) if coloring[v] == target_color]
                if not target_vertices:
                    continue
                # Try to recolor each target vertex
                eliminated = True
                new_coloring = coloring[:]  # work on a copy
                for v in target_vertices:
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        if new_coloring[u] != -1:
                            used |= (1 << new_coloring[u])
                    # Find smallest available color < target_color
                    found = False
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            new_coloring[v] = c
                            found = True
                            break
                    if found:
                        continue
                    # Try Kempe chain swap with each lower color
                    swapped = False
                    for c in range(target_color):
                        # Build Kempe chain for colors c and target_color containing v
                        # Only consider vertices with color c or target_color
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if new_coloring[node] == c or new_coloring[node] == target_color:
                                component.add(node)
                                for u in neighbors[node]:
                                    if new_coloring[u] == c or new_coloring[u] == target_color:
                                        if u not in visited:
                                            stack.append(u)
                        # Check if swapping this component frees color c for v
                        # After swap, v would get color c if it was target_color
                        # We need to ensure no neighbor of v has color c after swap
                        conflict = False
                        for u in neighbors[v]:
                            col_u = new_coloring[u]
                            if col_u == c and u not in component:
                                conflict = True
                                break
                            if col_u == target_color and u in component:
                                # After swap, u becomes c
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap: flip colors in component
                            for node in component:
                                if new_coloring[node] == c:
                                    new_coloring[node] = target_color
                                elif new_coloring[node] == target_color:
                                    new_coloring[node] = c
                            swapped = True
                            break
                    if not swapped:
                        eliminated = False
                        break
                if eliminated and is_valid(new_coloring):
                    # Successfully eliminated target_color
                    # Compact colors: remap to 0..k-2
                    mapping = {}
                    next_color = 0
                    for col in sorted(set(new_coloring)):
                        mapping[col] = next_color
                        next_color += 1
                    compacted = [mapping[new_coloring[v]] for v in range(n)]
                    if is_valid(compacted):
                        coloring[:] = compacted
                        changed = True
                        break  # restart from highest color
            # If we tried all and none eliminated, break
        return coloring

    # Apply Kempe reduction if time permits
    if time.time() - start_time < 0.04:
        best_coloring = kempe_reduce(best_coloring)
        best_k = num_colors(best_coloring)

    # Final validation and cleanup
    if not is_valid(best_coloring):
        # Last resort: greedy by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best_coloring = greedy_color(order)
    # Ensure colors are consecutive starting from 0
    used = set(best_coloring)
    if used:
        mapping = {color: i for i, color in enumerate(sorted(used))]
        best_coloring = [mapping[c] for c in best_coloring]
    else:
        best_coloring = []
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix or list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # adjacency matrix
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in range(n):
                if adj[u][v]:
                    mask |= 1 << v
            bit_adj[u] = mask
    else:
        # adjacency list
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in adj[u]:
                if 0 <= v < n:
                    mask |= 1 << v
            bit_adj[u] = mask

    # Helper to get neighbors as list
    def neighbors(u: int):
        mask = bit_adj[u]
        while mask:
            v = (mask & -mask).bit_length() - 1
            yield v
            mask &= mask - 1

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets for saturation update
        neigh_colors = [set() for _ in range(n)]
        uncolored = set(range(n))
        # initial degrees for tie-breaking
        deg = [bit_adj[u].bit_count() for u in range(n)]
        while uncolored:
            # select vertex with max saturation, then max degree, then random
            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # find smallest available color
            used = [False] * (n + 1)
            for nb in neighbors(v):
                c = color[nb]
                if c != -1:
                    used[c] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for nb in neighbors(v):
                if nb in uncolored:
                    if c not in neigh_colors[nb]:
                        neigh_colors[nb].add(c)
                        sat[nb] += 1
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            S = set()
            # vertex with max degree in uncolored subgraph
            def deg_in_uncolored(u):
                return sum(1 for v in neighbors(u) if v in uncolored)
            v = max(uncolored, key=deg_in_uncolored)
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for nb in neighbors(v):
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                def score(u):
                    w_neigh = sum(1 for nb in neighbors(u) if nb in W)
                    u_deg = sum(1 for nb in neighbors(u) if nb in U)
                    return (w_neigh, -u_deg, random.random())
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in neighbors(u):
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering via min-degree removal
        deg = [bit_adj[u].bit_count() for u in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].add(u)
        # pointer to current min degree
        d = 0
        while remaining:
            # find non-empty bucket
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for nb in neighbors(v):
                if nb in remaining:
                    old_deg = deg[nb]
                    deg[nb] -= 1
                    buckets[old_deg].discard(nb)
                    buckets[deg[nb]].add(nb)
                    if deg[nb] < d:
                        d = deg[nb]
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for nb in neighbors(v):
                c = color[nb]
                if c != -1:
                    used[c] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return color

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(color, a, b, v):
        # returns new color list after swapping a<->b in the component of v
        if color[v] not in (a, b):
            return color
        stack = [v]
        visited = set()
        comp_color_a = []  # vertices with color a in component
        comp_color_b = []  # vertices with color b in component
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            cu = color[u]
            if cu == a:
                comp_color_a.append(u)
            elif cu == b:
                comp_color_b.append(u)
            for nb in neighbors(u):
                if nb not in visited and color[nb] in (a, b):
                    stack.append(nb)
        # swap colors in component
        new_color = color[:]
        for u in comp_color_a:
            new_color[u] = b
        for u in comp_color_b:
            new_color[u] = a
        return new_color

    # Try to eliminate a color via Kempe chains or reassignment
    def reduce_colors(color):
        # map color to list of vertices
        color_classes = {}
        for v, c in enumerate(color):
            color_classes.setdefault(c, []).append(v)
        if not color_classes:
            return color
        max_color = max(color_classes.keys())
        # try to eliminate colors from highest down
        for target in range(max_color, -1, -1):
            if target not in color_classes:
                continue
            verts = color_classes[target][:]
            # try to recolor each vertex in this class
            for v in verts:
                if color[v] != target:  # might have been recolored already
                    continue
                # neighbor colors
                neigh_cols = set()
                for nb in neighbors(v):
                    cnb = color[nb]
                    if cnb != -1:
                        neigh_cols.add(cnb)
                # try direct reassignment to a lower color
                for c in range(target):
                    if c not in neigh_cols:
                        color[v] = c
                        break
                else:
                    # try Kempe chains with each lower color
                    for c in range(target):
                        if c in neigh_cols:
                            continue
                        # check if v is connected to a vertex of color c via Kempe chain (target, c)
                        # if not, we can swap the component to free color c
                        # Actually, we want to see if swapping can move v to color c
                        # We check if in the Kempe chain of (target, c) containing v, there is no vertex of color c adjacent to v? 
                        # Standard: if v is not adjacent to any vertex of color c in its Kempe chain component, swapping moves v to c.
                        # We'll attempt swap and see if v gets color c.
                        new_color = kempe_swap(color, target, c, v)
                        if new_color[v] == c:
                            color = new_color
                            break
                    else:
                        continue
                    break
                else:
                    # failed to recolor v, cannot eliminate this color yet
                    break
            else:
                # all vertices of target color recolored successfully
                # rebuild color classes
                color_classes = {}
                for v, c in enumerate(color):
                    color_classes.setdefault(c, []).append(v)
                # reindex colors to be consecutive
                unique_colors = sorted(color_classes.keys())
                mapping = {old: new for new, old in enumerate(unique_colors)}
                color = [mapping[c] for c in color]
                # try to reduce further
                return reduce_colors(color)
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        # validate
        ok = True
        for u in range(n):
            for v in neighbors(u):
                if u < v and col[u] == col[v]:
                    ok = False
                    break
            if not ok:
                break
        if not ok:
            continue
        k = len(set(col))
        if k < best_k:
            best_k = k
            best = col
    if best is None:
        best = candidates[0]  # fallback

    # Apply Kempe chain reduction to try to improve
    best = reduce_colors(best)

    # Final validation and consecution
    # Ensure colors are 0..k-1
    unique = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique)}
    best = [mapping[c] for c in best]

    # Double-check validity
    for u in range(n):
        for v in neighbors(u):
            if u < v and best[u] == best[v]:
                # Should not happen, but if so, try a greedy fix
                pass

    return best

import math
