def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build bit adjacency and degree list
    bit_adj = [0] * n
    deg = [0] * n
    if is_matrix:
        for u in range(n):
            mask = 0
            for v in range(n):
                if adj[u][v] == 1:
                    mask |= (1 << v)
                    deg[u] += 1
            bit_adj[u] = mask
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                mask |= (1 << v)
                deg[u] += 1
            bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            nbrs = bit_adj[u]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                c = color[v]
                if c != -1:
                    used |= (1 << c)
                nbrs &= nbrs - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count distinct colors
    def count_colors(color):
        return max(color) + 1 if color else 0

    # Helper: validate coloring
    def is_valid(color):
        for u in range(n):
            c_u = color[u]
            nbrs = bit_adj[u]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                if color[v] == c_u:
                    return False
                nbrs &= nbrs - 1
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(color):
        mapping = {}
        next_color = 0
        for c in color:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in color]

    # DSATUR
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        sat = [0] * n  # saturation degree
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > max_deg):
                    max_sat = sat[u]
                    max_deg = deg[u]
                    v = u
                elif sat[u] == max_sat and deg[u] == max_deg and u < v:
                    v = u
            # Assign smallest available color
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                w = (nbrs & -nbrs).bit_length() - 1
                c = color[w]
                if c != -1:
                    used |= (1 << c)
                nbrs &= nbrs - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            nbrs = bit_adj[v]
            while nbrs:
                w = (nbrs & -nbrs).bit_length() - 1
                if w in uncolored:
                    sat[w] += 1
                nbrs &= nbrs - 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
