            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg[x])  # deg is static, but we need dynamic degree in uncolored
            # Recompute degree in uncolored subgraph for selection
            def uncolored_degree(u):
                return bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1')
            v = max(uncolored, key=uncolored_degree)
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v}
            nbrs_v = bit_adj[v]
            W = set()
            while nbrs_v:
                w = (nbrs_v & -nbrs_v).bit_length() - 1
                if w in U:
                    U.remove(w)
                    W.add(w)
                nbrs_v &= nbrs_v - 1
            # While U not empty, add vertex with max neighbors in W
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_u_deg = math.inf
                for u in U:
