                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and u_deg_U < min_u_deg):
                        max_w_neighbors = w_count
                        min_u_deg = u_deg_U
                        best_u = u
                    elif w_count == max_w_neighbors and u_deg_U == min_u_deg and u < best_u:
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = bit_adj[u]
                while nbrs_u:
                    w = (nbrs_u & -nbrs_u).bit_length() - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    nbrs_u &= nbrs_u - 1
            # Assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
