            remaining.remove(v)
            # Update degrees of neighbors
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if u in remaining:
                    degree[u] -= 1
                    if degree[u] < ptr:
                        ptr = degree[u]
                    buckets[degree[u]].append(u)
                nbrs &= nbrs - 1
