                        # Check if v and any u in color c are connected via Kempe chain (c, target_color)
                        # We only need to see if v is not connected to the color class c in the Kempe subgraph
                        # BFS/DFS over vertices colored c or target_color
                        from collections import deque
                        visited = [False] * n
