        remaining = set(range(n))
        order = []  # will store removal order

        while remaining:
            # find vertex with minimum degree in remaining subgraph
            min_deg = float('inf')
            v = -1
            for u in remaining:
                # compute degree in the subgraph induced by remaining
                deg = 0
                for w in adj_list[u]:
                    if w in remaining:
                        deg += 1
                if deg < min_deg or (deg == min_deg and u < v):
                    min_deg = deg
                    v = u
