            target_color = k - 1
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # should not happen if k is correct
                k -= 1
                continue

            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if current[u] != -1:
                        used_by_neighbors |= (1 << current[u])
                # find smallest color < target_color not used by neighbors
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # can move v to color c
                        current[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart the while loop after any change

                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c from direct reassignment above, skip
                    if current[v] == c:
                        continue
                    # find the Kempe chain component of v in colors {target_color, c}
                    # We'll do BFS to find the component containing v
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for neighbor in adj_list[node]:
                            if neighbor not in visited and (current[neighbor] == target_color or current[neighbor] == c):
                                visited.add(neighbor)
                                queue.append(neighbor)
                    # Check if any neighbor of v with color c is NOT in this component
                    # If so, we can swap the component and free color c for v
                    has_external = False
                    for u in adj_list[v]:
                        if current[u] == c and u not in component:
                            has_external = True
                            break
                    if has_external:
                        # swap colors in the component: target_color <-> c
                        for node in component:
                            if current[node] == target_color:
                                current[node] = c
                            else:  # must be c
                                current[node] = target_color
                        improved = True
                        break  # break from color loop
                if improved:
                    break  # break from vertex loop
            if improved:
                # compact colors and update k
                current = compact_colors(current)
                k = num_colors(current)

        return current

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_colors = c1
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_colors = c2
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_colors = c3
    except:
        pass

    # If none worked (shouldn't happen), fallback to greedy
    if best_colors is None:
        # simple greedy in order 0..n-1
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)

    # Apply Kempe chain reduction to improve
    try:
        improved = kempe_reduce(best_colors)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_colors = improved
    except:
        pass

    # Final validation and compacting
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)

    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
    else:
        for u in range(n):
            if isinstance(adj[u], list):
                neighbors[u] = set(adj[u])
            else:
                neighbors[u] = set()

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    def compact_colors(colors):
        if not colors:
            return colors
        unique = sorted(set(colors))
        mapping = {c: i for i, c in enumerate(unique)}
        return [mapping[c] for c in colors]

    # DSATUR
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        saturation = [0] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree then random
            max_sat = -1
            candidates = []
            for u in range(n):
                if not colored[u]:
                    sat = saturation[u]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [u]
                    elif sat == max_sat:
                        candidates.append(u)
            if not candidates:
                break  # should not happen
            # Tie-break by degree in uncolored subgraph
            max_deg = -1
            best_u = candidates[0]
            for u in candidates:
                deg = sum(1 for v in neighbors[u] if not colored[v])
                if deg > max_deg:
                    max_deg = deg
                    best_u = u
                elif deg == max_deg and u < best_u:
                    best_u = u
            u = best_u
            # Compute used colors by neighbors
            used = 0
            for v in neighbors[u]:
                if colored[v]:
                    used |= (1 << colors[v])
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
            colored[u] = True
            # Update saturation of uncolored neighbors
            for v in neighbors[u]:
                if not colored[v]:
                    saturation[v] += 1
        return compact_colors(colors)

    # RLF
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color_idx = 0
        while not all(colored):
            # Build uncolored set
            R = [u for u in range(n) if not colored[u]]
            if not R:
                break
            # Degree in induced subgraph G[R]
            deg_in_R = {u: 0 for u in R}
            for u in R:
                for v in neighbors[u]:
                    if not colored[v]:
                        deg_in_R[u] += 1
            # Start independent set S with max degree vertex in R
            S = set()
            u0 = max(R, key=lambda x: deg_in_R[x])
            S.add(u0)
            colored[u0] = True
            # Partition R \ {u0} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in R:
                if u == u0:
                    continue
                if any(v in neighbors[u] for v in S):
                    W.add(u)
                else:
                    U.add(u)
            # Grow S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = sum(1 for v in neighbors[u] if v in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break by min degree in G[U]
                        deg_u = sum(1 for v in neighbors[u] if v in U)
                        deg_best = sum(1 for v in neighbors[best_u] if v in U) if best_u is not None else float('inf')
                        if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                            best_u = u
                if best_u is None:
                    break
                S.add(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for v in neighbors[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to S
            for u in S:
                colors[u] = color_idx
            color_idx += 1
        return compact_colors(colors)

    # Smallest-Last ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees and adjacency for peeling
        rem_adj = [set(neighbors[u]) for u in range(n)]
        degree = [len(rem_adj[u]) for u in range(n)]
        removed = [False] * n
        order = []
        # Peel vertices of minimum degree
        for _ in range(n):
            # Find vertex with minimum degree among remaining
            min_deg = float('inf')
            v = -1
            for u in range(n):
                if not removed[u] and degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Update degrees of neighbors
            for u in rem_adj[v]:
                if not removed[u]:
                    degree[u] -= 1
                    rem_adj[u].discard(v)
            rem_adj[v].clear()
        # Color in reverse peeling order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if not colors:
            return colors
        # Make a copy to work on
        cur_colors = colors[:]
        k = max(cur_colors) + 1 if cur_colors else 0
        improved = True
        while improved and k > 0:
            improved = False
            # Find smallest color class (highest index)
            # We try to eliminate color k-1
            target_color = k - 1
            vertices = [v for v in range(n) if cur_colors[v] == target_color]
            if not vertices:
                k -= 1
                continue
            # Try to recolor each vertex in target color
            for v in vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if cur_colors[u] != -1:
                        used |= (1 << cur_colors[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        cur_colors[v] = c
                        improved = True
                        break
                if improved:
                    # After moving one vertex, break to restart scanning
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is connected to color c via Kempe chain (v, c)
                    # We'll do BFS to find the Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in neighbors[u]:
                            if not visited[w] and (cur_colors[w] == target_color or cur_colors[w] == c):
                                visited[w] = True
                                queue.append(w)
                    # Check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_conflict = False
                    for u in component:
                        for w in neighbors[u]:
                            if cur_colors[w] == c and w not in component:
                                has_conflict = True
                                break
                        if has_conflict:
                            break
                    if not has_conflict:
                        # Perform swap: target_color <-> c in component
                        for u in component:
                            if cur_colors[u] == target_color:
                                cur_colors[u] = c
                            else:
                                cur_colors[u] = target_color
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Could not eliminate target color, try next lower k? Actually we stop if can't reduce
                break
            # Compact colors after potential reduction
            cur_colors = compact_colors(cur_colors)
            k = max(cur_colors) + 1 if cur_colors else 0
        return cur_colors

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        colors = [-1] * n
        for u in range(n):
            used = 0
            for v in neighbors[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        candidates.append(compact_colors(colors))

    # Choose best candidate (fewest colors)
    best = min(candidates, key=lambda x: (max(x) + 1 if x else 0, len(x)))
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid_coloring(best):
        # Last resort: simple greedy
        colors = [-1] * n
        for u in range(n):
            used = 0
            for v in neighbors[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        best = compact_colors(colors)
    else:
        best = compact_colors(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor bitmasks and adjacency lists
    bit_adj = [0] * n
    neigh = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neigh[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue  # skip invalid indices
                bit_adj[i] |= (1 << j)
                neigh[i].append(j)

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: validate coloring
    def is_valid_coloring(colors: list[int]) -> bool:
        for u in range(n):
            for v in neigh[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors: list[int]) -> int:
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(colors: list[int]) -> list[int]:
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neigh[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = bit_count(sat[u])
                d = uncolored_deg[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and random.random() < 0.5):
                    max_sat = s
                    max_deg = d
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neigh[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # RLF (Recursive Largest First)
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neigh[x] if y in uncolored))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # grow independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_u_degree = float('inf')
                for u in U:
                    w_neighbors = sum(1 for y in neigh[u] if y in W)
                    u_degree = sum(1 for y in neigh[u] if y in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and u_degree < min_u_degree) or (w_neighbors == max_w_neighbors and u_degree == min_u_degree and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in neigh[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last() -> list[int]:
        # degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(neigh[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # we need to update degrees as we remove vertices
        # use bucket sort for efficiency (n <= 100)
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neigh[v]:
                if not removed[u]:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)  # O(n) but n small
                    if deg[u] >= 0:
                        buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neigh[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring: list[int]) -> list[int]:
        if not coloring:
            return coloring
        # make a copy to work on
        color = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest color index that is used)
            max_color = max(color) if color else -1
            if max_color < 0:
                break
            # try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
                # collect vertices with target_color
                targets = [i for i in range(n) if color[i] == target_color]
                if not targets:
                    continue
                # try to recolor each target vertex
                eliminated = True
                for v in targets:
                    # check if v can take any color < target_color
                    used_by_neighbors = 0
                    for u in neigh[v]:
                        c_u = color[u]
                        if c_u < target_color:
                            used_by_neighbors |= (1 << c_u)
                    # find smallest available color < target_color
                    free_color = -1
                    for c in range(target_color):
                        if not (used_by_neighbors & (1 << c)):
                            free_color = c
                            break
                    if free_color != -1:
                        color[v] = free_color
                        changed = True
                        continue  # v recolored, move to next target
                    # try Kempe chain swap with each color c < target_color
                    swapped = False
                    for c in range(target_color):
                        # if v has a neighbor of color c, then swapping might pull v back
                        has_c_neighbor = any(color[u] == c for u in neigh[v])
                        if has_c_neighbor:
                            continue
                        # build Kempe chain for colors (c, target_color) starting from v
                        # we want to swap in the component of v if it does NOT contain any vertex of color c
                        # Actually, we can swap any component; after swap, v will become color c if it was in the component
                        # So we need the component of v in the subgraph induced by colors c and target_color
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in neigh[x]:
                                if not visited[y] and (color[y] == c or color[y] == target_color):
                                    visited[y] = True
                                    queue.append(y)
                        # check if component contains any vertex of color c
                        has_c_in_component = any(color[x] == c for x in component)
                        if not has_c_in_component:
                            # safe to swap: no vertex of color c in component, so after swap, no vertex becomes target_color
                            for x in component:
                                if color[x] == c:
                                    color[x] = target_color
                                else:  # must be target_color
                                    color[x] = c
                            color[v] = c  # v was target_color, now becomes c
                            changed = True
                            swapped = True
                            break
                    if swapped:
                        break
                    # if we couldn't recolor v, then we cannot eliminate this color class yet
                    eliminated = False
                    break
                if eliminated and changed:
                    # we managed to recolor all vertices of target_color, so eliminate the color
                    # compact colors will be done later
                    break
                elif not eliminated:
                    # couldn't eliminate this color, try next lower
                    continue
        # compact colors to 0..k-1
        return compact_colors(color)

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if not is_valid_coloring(col):
                continue
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col
        except Exception:
            continue

    # Fallback: if no heuristic produced valid coloring, use greedy random order
    if best_coloring is None:
        order = list(range(n))
        random.shuffle(order)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neigh[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = color

    # Apply Kempe reduction to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_coloring = improved
    except Exception:
        pass

    # Final validation and compaction
    if not is_valid_coloring(best_coloring):
        # last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: len(neigh[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neigh[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = color

    return compact_colors(best_coloring)

