def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix or list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                v = max(uncolored, key=lambda x: bin(bit_adj[x]).count('1'))
            else:
                v = max(candidates, key=lambda x: bin(bit_adj[x] & sum((1 << u) for u in uncolored)).count('1'))
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] == -1:
                    sat[u] |= (1 << c)
        return color

    # Helper: RLF independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bin(bit_adj[x] & sum((1 << u) for u in uncolored)).count('1'))
            S = {v}
            U = uncolored - {v}
            W = set()
            # Initial W: neighbors of v in U
            for u in U:
                if (bit_adj[v] >> u) & 1:
                    W.add(u)
            U -= W
            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_u = bin(bit_adj[u] & sum((1 << uu) for uu in U)).count('1')
                        deg_best = bin(bit_adj[best_u] & sum((1 << uu) for uu in U)).count('1')
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u in U to W
                for uu in U:
                    if (bit_adj[best_u] >> uu) & 1:
                        W.add(uu)
                U -= {uu for uu in U if (bit_adj[best_u] >> uu) & 1}
            for vertex in S:
                color[vertex] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        order = []
        remaining = set(range(n))
        # We'll simulate removal by updating degrees
        curr_deg = degrees[:]
        for _ in range(n):
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    curr_deg[u] -= 1
        order.reverse()
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass

    # Fallback: Welsh-Powell
    try:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        candidates.append(greedy_color(order))
    except:
        pass

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if all(0 <= c < n for c in col):
            k = max(col) + 1 if col else 0
            if k < best_k:
                best_k = k
                best_color = col[:]

    if best_color is None:
        best_color = [0] * n

    # Kempe chain color reduction
    def is_valid(col):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1 and col[u] == col[v]:
                    return False
        return True

    def kempe_reduce(col):
        if not is_valid(col):
            return col
        while True:
            color_classes = {}
            for v in range(n):
                c = col[v]
                if c not in color_classes:
                    color_classes[c] = []
                color_classes[c].append(v)
            if not color_classes:
                break
            max_color = max(color_classes.keys())
            if max_color == 0:
                break
            smallest_class = color_classes[max_color]
            # Try to eliminate color max_color
            eliminated = False
            for v in smallest_class:
                neighbor_colors = set()
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        neighbor_colors.add(col[u])
                for c in range(max_color):
                    if c not in neighbor_colors:
                        col[v] = c
                        eliminated = True
                        break
                if eliminated:
                    break
                # Try Kempe chains
                for c in range(max_color):
                    if c in neighbor_colors:
                        continue
                    # Check if v can be recolored to c via Kempe chain (v, max_color) <-> (c)
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    component = set()
                    while stack:
                        node = stack.pop()
                        component.add(node)
                        for u in range(n):
                            if (bit_adj[node] >> u) & 1:
                                if col[u] == max_color or col[u] == c:
                                    if u not in visited:
                                        visited.add(u)
                                        stack.append(u)
                    # Check if any neighbor of v in component has color c -> swapping would cause conflict
                    conflict = False
                    for node in component:
                        for u in range(n):
                            if (bit_adj[node] >> u) & 1 and col[u] == c and u not in component:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors in component
                        for node in component:
                            if col[node] == max_color:
                                col[node] = c
                            elif col[node] == c:
                                col[node] = max_color
                        eliminated = True
                        break
            if not eliminated:
                break
            # Compact colors: remap to 0..k-1
            unique_colors = sorted(set(col))
            mapping = {old: new for new, old in enumerate(unique_colors)}
            col = [mapping[c] for c in col]
        return col

    best_color = kempe_reduce(best_color[:])
    # Final validation and compacting
    if not is_valid(best_color):
        # Last resort: greedy
        order = list(range(n))
        best_color = greedy_color(order)
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]
    return best_color

