            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u].bit_count()
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or (sat_u == max_sat and deg_u == max_deg and (v == -1 or u < v)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # assign smallest available color
            used = 0
            for w in neighbors[v]:
                cw = color[w]
                if cw != -1:
                    used |= (1 << cw)
            cv = 0
            while used & (1 << cv):
                cv += 1
            color[v] = cv
            uncolored.remove(v)
            # update saturation and uncolored degree of neighbors
            for w in neighbors[v]:
                if w in uncolored:
                    saturation[w] |= (1 << cv)
                    uncolored_deg[w] -= 1
