            # degree in induced subgraph of uncolored
            deg_uncolored = [0] * n
            for u in uncolored:
                cnt = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            # choose vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
