                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # tie-break by min degree in G[U]
                    deg_in_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_in_U += 1
                    if score > best_score or (score == best_score and deg_in_U < best_deg_U) or (score == best_score and deg_in_U == best_deg_U and (best_u == -1 or u < best_u)):
                        best_score = score
                        best_deg_U = deg_in_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        degree = [len(neighbors[i]) for i in range(n)]
        # bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].append(v)
        # pointer to current non-empty bin
        ptr = 0
        order = []
        # current degree array (will be updated)
        curr_deg = degree[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = bins[ptr].pop()
            while removed[v]:
                if not bins[ptr]:
                    while ptr <= max_deg and not bins[ptr]:
                        ptr += 1
                    if ptr > max_deg:
                        break
                    v = bins[ptr].pop()
                else:
                    break
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # update neighbors
            for w in neighbors[v]:
                if not removed[w]:
                    d = curr_deg[w]
                    if d > 0:
                        curr_deg[w] -= 1
                        bins[d].append(w)
                        if d - 1 < len(bins):
                            bins[d - 1].append(w)
