        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except Exception:
        pass

