    order_deg = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    candidates.append(greedy_color(order_deg))
    # greedy by degree ascending
    order_deg_asc = sorted(range(n), key=lambda x: len(neighbors[x]))
    candidates.append(greedy_color(order_deg_asc))

    # Evaluate candidates
    for coloring in candidates:
        k = count_colors(coloring)
