    # Compact colors: ensure colors are 0..k-1 consecutive
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
