    def validate_and_compact(coloring):
        # validate
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    # invalid, should not happen
                    pass
        # compact
        return compact_colors(coloring)

    best_coloring = validate_and_compact(best_coloring)
    return best_coloring

