    def bit_count(x):
        return x.bit_count()

    # Helper: get uncolored neighbor count
    def uncolored_degree(v, colored_mask):
        return bit_count(bit_adj[v] & ~colored_mask)

    # Helper: get saturation (distinct colors in neighbors)
    def saturation(v, color_of):
        mask = 0
        for u in neighbors[v]:
            c = color_of[u]
            if c != -1:
                mask |= (1 << c)
        return bit_count(mask)

    # DSATUR
    def dsatur():
        color_of = [-1] * n
        # Order by degree descending for initial tie-breaking
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        for v in order:
            if color_of[v] != -1:
                continue
