            used = 0
            for u in neighbors[v]:
                c = color_of[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color_of[v] = c
        return color_of

    # RLF (Recursive Largest First)
    def rlf():
        color_of = [-1] * n
        uncolored = set(range(n))
        color = 0
