            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: uncolored_degree(x, 0))  # 0 mask means all uncolored
            # Build independent set for this color
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            U = {u for u in uncolored if u != v and not (bit_adj[v] & (1 << u))}
            # W: vertices adjacent to S (ineligible)
            W = uncolored - S - U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = bit_count(bit_adj[u] & sum((1 << w) for w in W))
                    if score > best_score or (score == best_score and len(neighbors[u]) < len(neighbors[best_u]) if best_u is not None else False):
                        best_score = score
                        best_u = u
