                to_remove = set()
                temp = nbrs_in_U
                while temp:
                    lsb = temp & -temp
                    idx = (lsb.bit_length() - 1)
                    to_remove.add(idx)
                    temp -= lsb
                U -= to_remove
                W |= to_remove
