                                # swap in the visited set
                                for x in visited:
                                    if col[x] == c:
                                        col[x] = target_color
                                    elif col[x] == target_color:
                                        col[x] = c
                                changed = True
                                freed = True
                                # update classes: swap colors c and target_color in visited
                                # we will rebuild classes later, so just break
                                break
