    best_coloring = kempe_reduction(best_coloring)
    # final validation and compaction
    # compact colors
    unique = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique:
            unique[c] = next_color
            next_color += 1
        best_coloring[i] = unique[c]
    return best_coloring

