        for u in remaining:
            if degree[u] < min_deg:
                min_deg = degree[u]
                min_vertex = u
        # Remove min_vertex
        order.append(min_vertex)
        remaining.remove(min_vertex)
        # Update degrees of its neighbors still in remaining
        for v in adj_list[min_vertex]:
