            U = uncolored - W
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = sum(1 for v in adj_list[u] if v in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = sum(1 for v in adj_list[u] if v in U)
                        if best_u is None or deg_u < sum(1 for v in adj_list[best_u] if v in U):
                            best_u = u
                # Add best_u to S
                S.append(best_u)
                uncolored.remove(best_u)
                # Update W and U
                for v in adj_list[best_u]:
                    if v in uncolored:
                        W.add(v)
                        if v in U:
                            U.remove(v)
                U = uncolored - W
            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1
        return coloring

