        # Instead, we simulate peeling
        temp_adj = [set(adj_list[i]) for i in range(n)]
        remaining_set = set(range(n))
        while remaining_set:
            # Find vertex of minimum degree in remaining_set
            min_deg = float('inf')
            min_v = None
            for v in remaining_set:
                deg = sum(1 for u in temp_adj[v] if u in remaining_set)
                if deg < min_deg:
                    min_deg = deg
                    min_v = v
