        from collections import deque
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            u = queue.popleft()
            component.append(u)
            for w in adj_list[u]:
                if not visited[w] and (coloring[w] == a or coloring[w] == b):
                    visited[w] = True
                    queue.append(w)
        # Swap colors in component
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            elif new_coloring[u] == b:
                new_coloring[u] = a
