                        max_deg = deg
                        best_candidates = [v]
                    elif deg == max_deg:
                        best_candidates.append(v)
                candidates = best_candidates

            # Final tie-break: random
            v = random.choice(candidates) if candidates else 0

            # Assign smallest available color
            c = 0
            while neighbor_color_mask[v] & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True

            # Update neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    neighbor_color_mask[u] |= (1 << c)
                    uncolored_degree[u] -= 1

        return normalize_colors(coloring)

    # RLF heuristic (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                # Find vertex with max degree in induced subgraph
                max_deg = -1
                v_start = None
                for v in uncolored:
                    # Count neighbors in uncolored set
                    deg = 0
                    for u in adj_list[v]:
                        if u in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v_start = v
                if v_start is not None:
                    independent_set.append(v_start)
                    uncolored.remove(v_start)

            # Partition remaining uncolored into U (eligible) and W (ineligible)
            W = set()
            for v in independent_set:
                for u in adj_list[v]:
                    if u in uncolored:
                        W.add(u)
            U = uncolored - W

            # Greedily add vertices from U to independent set
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_u_deg = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # Tie-break: min degree in U
                    u_deg = 0
                    for w in adj_list[u]:
                        if w in U:
                            u_deg += 1
                    if (w_neighbors > max_w_neighbors or 
                        (w_neighbors == max_w_neighbors and u_deg < min_u_deg)):
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        best_u = u

                if best_u is None:
                    break  # Should not happen

                independent_set.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize_colors(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []

        # Repeatedly remove vertex of minimum degree
        for _ in range(n):
            # Find vertex with min degree in remaining graph
            min_deg = float('inf')
            v_min = None
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            if v_min is None:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for u in adj_list[v_min]:
                if u in remaining:
                    degree[u] -= 1

        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Kempe chain swap attempt
    def kempe_swap(coloring, v, c1, c2):
        # Try to swap colors c1 and c2 in the Kempe chain containing v
        # Only if v has color c1
        if coloring[v] != c1:
            return False

        # Find all vertices reachable from v via alternating c1-c2 paths
        visited = [False] * n
        stack = [v]
        visited[v] = True
        component = []

        while stack:
            u = stack.pop()
            component.append(u)
            for w in adj_list[u]:
                if not visited[w] and (coloring[w] == c1 or coloring[w] == c2):
                    visited[w] = True
                    stack.append(w)

        # Check if swapping is safe: no neighbor outside component has color c2
        # Actually, for Kempe chain swap to be valid, we need that after swap,
        # no adjacent vertices have same color. Since we only swap c1<->c2 in component,
        # it's valid if no vertex in component has a neighbor outside component with color c2
        # (because after swap, those would become c1 and conflict if neighbor has c2)
        # But standard Kempe chain swap is always valid for preserving proper coloring
        # because we only swap within the component and the component is maximal.
        # However, we want to free color c1 for v, so after swap v gets c2.
        # We need to ensure that v doesn't have any neighbor with color c2 outside the component.
        # Actually, by definition of the component, there is no edge from component to 
        # a vertex colored c2 outside the component (otherwise it would be in the component).
        # So the swap is always valid.

        # Perform the swap
        for u in component:
            if coloring[u] == c1:
                coloring[u] = c2
            else:  # must be c2
                coloring[u] = c1
        return True

    # Attempt to eliminate a color class using Kempe chains
    def eliminate_color(coloring, target_color):
        # Get vertices with target_color
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True  # Already eliminated

        # Try to recolor each vertex
        for v in vertices:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in adj_list[v]:
                c = coloring[u]
                if c < target_color:
                    neighbor_colors.add(c)
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Direct reassignment possible
                    coloring[v] = c
                    return True

            # Try Kempe chain swaps with each lower color
            for c in range(target_color):
                # Check if v has a neighbor with color c (necessary for Kempe chain to be useful)
                has_neighbor_c = False
                for u in adj_list[v]:
                    if coloring[u] == c:
                        has_neighbor_c = True
                        break
                if not has_neighbor_c:
                    continue

                # Try to swap colors c and target_color in the Kempe chain of v
                # Make a copy to test
                test_coloring = coloring[:]
                if kempe_swap(test_coloring, v, target_color, c):
                    # After swap, v should have color c
                    if test_coloring[v] == c:
                        # Verify the coloring is still valid
                        if is_valid_coloring(test_coloring):
                            coloring[:] = test_coloring
                            return True

        return False

    # Main algorithm: generate initial colorings and try to improve
    best_coloring = None
    best_num_colors = float('inf')

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Evaluate initial candidates
    for coloring in candidates:
        if is_valid_coloring(coloring):
            k = num_colors(coloring)
            if k < best_num_colors:
                best_num_colors = k
                best_coloring = coloring[:]

    # If no valid coloring found (shouldn't happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_num_colors = num_colors(best_coloring)
        best_coloring = normalize_colors(best_coloring)

    # Try to reduce colors by eliminating highest color classes
    current_coloring = best_coloring[:]
    k = best_num_colors

    # Iteratively try to eliminate color k-1, then k-2, etc.
    for target_color in range(k-1, -1, -1):
        # Make a copy to work on
        test_coloring = current_coloring[:]
        # Try to eliminate this color
        if eliminate_color(test_coloring, target_color):
            # Success: compact colors
            test_coloring = normalize_colors(test_coloring)
            new_k = num_colors(test_coloring)
            if new_k < k and is_valid_coloring(test_coloring):
                current_coloring = test_coloring
                k = new_k
                # Restart from the new highest color
                target_color = k  # will be decremented to k-1 in next iteration
            else:
                # No improvement, try next lower target color
                continue
        else:
            # Could not eliminate this color, try next lower
            continue

    # Final validation and normalization
    if not is_valid_coloring(current_coloring):
        # Fallback to DSATUR if something went wrong
        current_coloring = dsatur()

    current_coloring = normalize_colors(current_coloring)
    return current_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = coloring[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # Helper: 1-opt local improvement
    def local_improve(coloring, max_iter=1000):
        current = coloring[:]
        improved = True
        it = 0
        while improved and it < max_iter:
            improved = False
            it += 1
            v = random.randrange(n)
            used = 0
            for u in adj_list[v]:
                c = current[u]
                if c != -1:
                    used |= (1 << c)
            for c in range(n + 1):
                if not (used & (1 << c)):
                    if c != current[v]:
                        current[v] = c
                        improved = True
                    break
        return current

    best_coloring = None
    best_k = float('inf')

    # Try multiple random greedy passes
    for _ in range(20):
        order = list(range(n))
        random.shuffle(order)
        coloring = greedy_color(order)
        coloring = local_improve(coloring, max_iter=200)
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring
            if best_k == 1:  # optimal
                break

    # Fallback: try degree-sorted order
    if best_coloring is None or not is_valid(best_coloring):
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = greedy_color(order)
        coloring = local_improve(coloring, max_iter=200)
        if is_valid(coloring):
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring

    # Final validation and compaction
    if not is_valid(best_coloring):
        # As a last resort, use simple greedy with natural order
        best_coloring = greedy_color(list(range(n)))

    # Compact colors to 0..k-1
    color_map = {}
    next_color = 0
    compacted = []
    for c in best_coloring:
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        compacted.append(color_map[c])

    return compacted

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    for u in range(n):
        if is_matrix:
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
        else:
            for v in adj[u]:
                if v < n:  # safety check
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with bitmask optimization
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph (for tie-breaking)
        uncolored_deg = [len(adj_list[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by max uncolored degree
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_count = saturation[v].bit_count()
                if sat_count > best_sat or (sat_count == best_sat and uncolored_deg[v] > best_deg):
                    best_sat = sat_count
                    best_deg = uncolored_deg[v]
                    best_v = v
                elif sat_count == best_sat and uncolored_deg[v] == best_deg and v < best_v:
                    best_v = v

            v = best_v
            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    saturation[nb] |= (1 << c)
                    uncolored_deg[nb] -= 1
            uncolored.remove(v)

        return normalize(colors)

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Candidates: vertices not adjacent to any in independent_set
            candidates = set(uncolored)
            # Vertices adjacent to independent_set (blocked)
            blocked = set()

            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
                independent_set.append(v)
                candidates.remove(v)
                # Move neighbors to blocked
                for nb in adj_list[v]:
                    if nb in candidates:
                        candidates.remove(nb)
                        blocked.add(nb)

            # Greedily add vertices from candidates
            while candidates:
                # Select vertex with max neighbors in blocked
                best_v = -1
                best_blocked = -1
                best_deg_candidates = float('inf')
                for v in candidates:
                    blocked_neighbors = sum(1 for nb in adj_list[v] if nb in blocked)
                    deg_in_candidates = sum(1 for nb in adj_list[v] if nb in candidates)
                    if blocked_neighbors > best_blocked or \
                       (blocked_neighbors == best_blocked and deg_in_candidates < best_deg_candidates) or \
                       (blocked_neighbors == best_blocked and deg_in_candidates == best_deg_candidates and v < best_v):
                        best_blocked = blocked_neighbors
                        best_deg_candidates = deg_in_candidates
                        best_v = v

                v = best_v
                independent_set.append(v)
                candidates.remove(v)
                # Move neighbors of v from candidates to blocked
                for nb in adj_list[v]:
                    if nb in candidates:
                        candidates.remove(nb)
                        blocked.add(nb)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color
            # Remove from uncolored
            uncolored -= set(independent_set)
            color += 1

        return normalize(colors)

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []

        # Repeatedly remove vertex of minimum degree
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    degree[nb] -= 1

        # Color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if not colors:
            return colors
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                continue

            made_progress = True
            while made_progress and target_vertices:
                made_progress = False
                # Try to recolor each target vertex
                for v in target_vertices[:]:  # iterate over copy
                    current_color = colors[v]
                    # Try direct reassignment to lower colors
                    for c in range(target_color):
                        # Check if color c is available (no neighbor has color c)
                        conflict = False
                        for nb in adj_list[v]:
                            if colors[nb] == c:
                                conflict = True
                                break
                        if not conflict:
                            # Recolor v to c
                            colors[v] = c
                            target_vertices.remove(v)
                            made_progress = True
                            break
                    if made_progress:
                        break

                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        # Skip if v already has color c (shouldn't happen)
                        if colors[v] == c:
                            continue
                        # Find the Kempe chain component for colors (current_color, c) containing v
                        # We'll try to swap colors in the component if it doesn't contain any vertex
                        # that would cause a conflict when swapped
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        component = set()
                        valid_swap = True

                        while queue:
                            node = queue.popleft()
                            if node in visited:
                                continue
                            visited.add(node)
                            component.add(node)
                            # Check neighbors for conflicts if we swap
                            for nb in adj_list[node]:
                                if colors[nb] == c and nb not in component:
                                    # If neighbor has color c and is not in component, swapping would cause conflict
                                    valid_swap = False
                                    break
                                if colors[nb] == current_color and nb not in visited:
                                    queue.append(nb)
                            if not valid_swap:
                                break

                        if valid_swap:
                            # Perform swap: current_color <-> c in component
                            for node in component:
                                if colors[node] == current_color:
                                    colors[node] = c
                                elif colors[node] == c:
                                    colors[node] = current_color
                            # Update target_vertices if v was recolored
                            if colors[v] != target_color:
                                target_vertices.remove(v)
                                made_progress = True
                                break
                    if made_progress:
                        break

            # If we eliminated the target color, break and try again with new k
            if not any(v for v in range(n) if colors[v] == target_color):
                # Re-index colors to be consecutive
                return kempe_reduce(normalize(colors))

        return normalize(colors)

    # Generate candidate colorings
    start_time = time.time()
    candidates = []

    # Run DSATUR
    if time.time() - start_time < 0.04:  # 40ms budget for heuristics
        col = dsatur()
        if is_valid_coloring(col):
            candidates.append(col)

    # Run RLF
    if time.time() - start_time < 0.04:
        col = rlf()
        if is_valid_coloring(col):
            candidates.append(col)

    # Run Smallest-Last
    if time.time() - start_time < 0.04:
        col = smallest_last()
        if is_valid_coloring(col):
            candidates.append(col)

    # If no candidates (shouldn't happen), fallback to greedy
    if not candidates:
        # Simple greedy by vertex index
        colors = [-1] * n
        for v in range(n):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = normalize(best)

    # Apply Kempe chain reduction if time permits
    if time.time() - start_time < 0.045:  # Leave 5ms for Kempe
        reduced = kempe_reduce(best)
        if is_valid_coloring(reduced) and num_colors(reduced) < num_colors(best):
            best = reduced

    # Final validation and normalization
    best = normalize(best)
    if not is_valid_coloring(best):
        # Last resort: DSATUR again
        best = dsatur()
        best = normalize(best)

    return best

