def color_graph(adj: list[list[int]]) -> list[int]:
    # ----- Input handling and preprocessing -----
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    if is_matrix:
        # Convert adjacency matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Precompute degree and bitmask adjacency for fast operations
    deg = [len(adj_list[i]) for i in range(n)]
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # ----- Helper functions -----
    def is_valid_coloring(coloring):
        """Check if coloring is valid (no adjacent same color)."""
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def compact_colors(coloring):
        """Remap colors to 0..k-1 consecutively."""
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    def get_saturation(v, coloring):
        """Compute saturation degree of vertex v."""
        if coloring[v] != -1:
            return -1  # Already colored
        neighbor_colors = set()
        mask = bit_adj[v]
        u = 0
        while mask:
            if mask & 1:
                if coloring[u] != -1:
                    neighbor_colors.add(coloring[u])
            mask >>= 1
            u += 1
        return len(neighbor_colors)

    def get_uncolored_degree(v, colored):
        """Degree in the subgraph induced by uncolored vertices."""
        if colored[v]:
            return -1
        count = 0
        mask = bit_adj[v]
        u = 0
        while mask:
            if mask & 1 and not colored[u]:
                count += 1
            mask >>= 1
            u += 1
        return count

    # ----- DSATUR with degree tie-breaking -----
    def dsatur():
        coloring = [-1] * n
        colored = [False] * n
        # Start with vertex of highest degree
        v = max(range(n), key=lambda x: deg[x])
        coloring[v] = 0
        colored[v] = True

        for _ in range(n - 1):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            candidates = []
            max_sat = -1
            for v in range(n):
                if not colored[v]:
                    sat = get_saturation(v, coloring)
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                v = max(candidates, key=lambda x: get_uncolored_degree(x, colored))
            else:
                v = candidates[0]
            # Assign smallest available color
            used = [False] * (n + 1)  # n colors enough
            mask = bit_adj[v]
            u = 0
            while mask:
                if mask & 1 and coloring[u] != -1:
                    used[coloring[u]] = True
                mask >>= 1
                u += 1
            for c in range(n + 1):
                if not used[c]:
                    coloring[v] = c
                    break
            colored[v] = True
        return compact_colors(coloring[:])

    # ----- RLF (Recursive Largest First) -----
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored_set = set(range(n))

        while uncolored_set:
            # Step 1: pick vertex with max degree in G[R]
            R = list(uncolored_set)
            if not R:
                break
            v = max(R, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored_set))
            # Initialize independent set S and partitions U, W
            S = {v}
            U = {u for u in R if u != v and u not in adj_list[v]}
            W = {u for u in R if u != v and u in adj_list[v]}

            # Step 4: grow S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = sum(1 for nb in adj_list[u] if nb in U)
                        deg_best = sum(1 for nb in adj_list[best_u] if nb in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break  # Should not happen
                # Add best_u to S, move from U to S, and update W
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for vertex in S:
                coloring[vertex] = color
                uncolored_set.remove(vertex)
            color += 1
        return compact_colors(coloring[:])

    # ----- Smallest-Last ordering greedy -----
    def smallest_last_greedy():
        # Compute smallest-last ordering (peeling order)
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll simulate peeling by repeatedly removing min degree vertex
        # For efficiency, we use buckets since n <= 100
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    degree[nb] -= 1
        # Color in reverse peeling order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            for c in range(n + 1):
                if not used[c]:
                    coloring[v] = c
                    break
        return compact_colors(coloring[:])

    # ----- Kempe chain color reduction -----
    def kempe_reduce(coloring):
        """Try to reduce number of colors by eliminating the last color class."""
        if not is_valid_coloring(coloring):
            return coloring  # Should not happen if input is valid
        max_color = max(coloring) if n > 0 else -1
        if max_color < 0:
            return coloring
        # Try to eliminate colors from highest down
        for target_color in range(max_color, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue  # Already empty
            # Try to recolor each vertex in this class
            made_progress = False
            for v in verts:
                # Try direct reassignment to a lower color
                used = [False] * (target_color + 1)  # only need up to target_color
                for nb in adj_list[v]:
                    c = coloring[nb]
                    if c < target_color:
                        used[c] = True
                for c in range(target_color):
                    if not used[c]:
                        coloring[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break  # Reassign one vertex and restart
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find (c, target_color)-Kempe chain containing v
                    # BFS to get component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for nb in adj_list[x]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if we can swap: no neighbor of component has color c outside component
                    # Actually, swapping is always valid; we just need to see if it helps free the color
                    # Swap colors c and target_color in component
                    for x in component:
                        if coloring[x] == c:
                            coloring[x] = target_color
                        else:
                            coloring[x] = c
                    # After swap, check if v is no longer target_color (it should be c now)
                    if coloring[v] != target_color:
                        made_progress = True
                        break
                    # Otherwise, swap back (though in theory it should have changed)
                    for x in component:
                        if coloring[x] == c:
                            coloring[x] = target_color
                        else:
                            coloring[x] = c
                if made_progress:
                    break
            if not made_progress:
                # Cannot eliminate this color, try next lower
                continue
            else:
                # Made progress, need to re-check from highest because coloring changed
                # Recurse or restart
                return kempe_reduce(coloring)
        # After trying, compact colors
        return compact_colors(coloring[:])

    # ----- Main execution with time budget -----
    start_time = time.time()
    best_coloring = None
    best_colors = float('inf')

    # List of heuristics to run
    heuristics = [dsatur, rlf, smallest_last_greedy]

    for heuristic in heuristics:
        if time.time() - start_time > 0.04:  # Leave some margin
            break
        try:
            coloring = heuristic()
            if not is_valid_coloring(coloring):
                continue
            num_colors = len(set(coloring))
            if num_colors < best_colors:
                best_colors = num_colors
                best_coloring = coloring[:]
        except Exception:
            continue  # Skip if heuristic fails

    # If no heuristic succeeded, fall back to simple greedy
    if best_coloring is None:
        coloring = [-1] * n
        # Order by degree descending
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        for v in order:
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            for c in range(n + 1):
                if not used[c]:
                    coloring[v] = c
                    break
        best_coloring = compact_colors(coloring)

    # Apply Kempe reduction if time permits
    if time.time() - start_time < 0.045:
        try:
            reduced = kempe_reduce(best_coloring[:])
            if is_valid_coloring(reduced):
                num_colors = len(set(reduced))
                if num_colors < best_colors:
                    best_coloring = reduced
        except Exception:
            pass

    # Final validation and compacting
    if not is_valid_coloring(best_coloring):
        # Last resort: greedy in order 0..n-1
        coloring = [-1] * n
        for v in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            for c in range(n + 1):
                if not used[c]:
                    coloring[v] = c
                    break
        best_coloring = compact_colors(coloring)
    else:
        best_coloring = compact_colors(best_coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count number of colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                # degree in uncolored subgraph
                deg = (bit_adj[v] & sum((1 << u) for u in uncolored)).bit_count()
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # Strategy 2: Recursive Largest First (RLF)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: (bit_adj[x] & sum((1 << u) for u in uncolored)).bit_count())
            independent_set = {v}
            # Partition: U = vertices not adjacent to any in independent_set, W = adjacent
            # We maintain U and W as sets
            U = uncolored - {v} - {u for u in adj_list[v] if u in uncolored}
            W = {u for u in adj_list[v] if u in uncolored}
            # While U not empty, select u in U with max |N(u) ∩ W|
            while U:
                best_u = -1
                best_score = -1
                best_deg_in_U = -1
                for u in U:
                    # score: number of neighbors in W
                    score = (bit_adj[u] & sum((1 << w) for w in W)).bit_count()
                    # tie-break: min degree in G[U]
                    deg_in_U = (bit_adj[u] & sum((1 << w) for w in U)).bit_count()
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U) or (score == best_score and deg_in_U == best_deg_in_U and u < best_u):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Strategy 3: Smallest-Last (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[v]) for v in range(n)]
        # We'll update degrees as we remove vertices
        # Use bucket queue for efficiency, but n <= 100 so we can scan
        temp_deg = degrees[:]
        remaining_set = set(range(n))
        for _ in range(n):
            # Find vertex with min temp_deg in remaining_set
            v = min(remaining_set, key=lambda x: temp_deg[x])
            order.append(v)
            remaining_set.remove(v)
            for u in adj_list[v]:
                if u in remaining_set:
                    temp_deg[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Simple degree ordering (Welsh-Powell)
    def degree_order():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, degree_order]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except:
            continue

    # If no valid candidate (should not happen), fall back to greedy on natural order
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select candidate with fewest colors
    best_coloring = min(candidates, key=count_colors)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class that is non-empty
            color_classes = {}
            for v in range(n):
                c = col[v]
                color_classes.setdefault(c, []).append(v)
            if not color_classes:
                break
            max_color = max(color_classes.keys())
            # Try to eliminate color classes from highest down, but we target the smallest class
            # Actually, we try to reduce the total number of colors by eliminating the highest color if possible
            # But the literature suggests eliminating the smallest color class can allow compaction
            # We'll try to see if we can recolor any vertex of color max_color to a lower color
            # via Kempe chain or direct move
            target_color = max_color
            if target_color == 0:
                break  # cannot reduce further
            # For each vertex v of target_color, see if we can recolor it to a color < target_color
            for v in color_classes.get(target_color, []):
                # Try direct reassignment to any lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    neighbor_colors.add(col[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Direct move possible
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v and any vertex of color c are in the same Kempe chain for (c, target_color)
                    # We'll do BFS/DFS on the subgraph induced by colors c and target_color
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in adj_list[x]:
                            if col[y] == c or col[y] == target_color:
                                if y not in visited:
                                    visited.add(y)
                                    queue.append(y)
                    # If there is no vertex of color c in this component, we can swap
                    has_color_c = any(col[x] == c for x in component)
                    if not has_color_c:
                        # Swap colors c and target_color in this component
                        for x in component:
                            if col[x] == c:
                                col[x] = target_color
                            elif col[x] == target_color:
                                col[x] = c
                        changed = True
                        break
                if changed:
                    break
            # If we made a change, we might have reduced the number of colors
            # Compact colors if necessary (but we try to keep them consecutive)
            if changed:
                # Re-map colors to be consecutive starting from 0
                # But only if there are gaps
                used_colors = set(col)
                if len(used_colors) == n:  # optimization: if all colors used, skip
                    pass
                else:
                    mapping = {}
                    sorted_used = sorted(used_colors)
                    for new, old in enumerate(sorted_used):
                        mapping[old] = new
                    col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction to the best candidate
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid(improved) and count_colors(improved) <= count_colors(best_coloring):
            best_coloring = improved
    except:
        pass  # fallback to best_coloring

    # Final validation and compacting
    # Ensure coloring is valid
    if not is_valid(best_coloring):
        # Last resort: greedy on random order until valid (should not happen)
        for _ in range(10):
            order = list(range(n))
            random.shuffle(order)
            col = greedy_color(order)
            if is_valid(col):
                best_coloring = col
                break
        else:
            best_coloring = greedy_color(list(range(n)))

    # Compact colors to 0..k-1
    used = set(best_coloring)
    if used:
        mapping = {old: new for new, old in enumerate(sorted(used))]
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

