    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if v < n:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR
    try:
        color = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = saturated[u].bit_count()
                deg = sum(1 for nb in adj_list[u] if nb in uncolored)
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and u > v):
                    max_sat = sat
                    max_deg = deg
                    v = u
            if v == -1:
                break  # should not happen

            # Assign smallest available color
            avail = ~saturated[v]
            c = 0
            while avail & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation of neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    saturated[nb] |= (1 << c)

        k = num_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]
