        pass

    # 2. RLF (Recursive Largest First)
    try:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: sum(1 for nb in adj_list[u] if nb in uncolored))
            S.append(v)
            # U: vertices not adjacent to S (eligible)
            U = {u for u in uncolored if u != v and all(nb not in S for nb in adj_list[u])}
            # W: vertices adjacent to S (ineligible)
            W = uncolored - {v} - U

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or (nw == max_nw and deg_u == min_deg_u and u < u_star):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                if u_star == -1:
                    break
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1

        k = num_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]
    except Exception:
        pass

    # 3. Smallest-Last ordering (Matula & Beck)
    try:
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)

        for _ in range(n):
            # Find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d_nb = degree[nb]
                    buckets[d_nb].remove(nb)
                    degree[nb] -= 1
                    buckets[degree[nb]].append(nb)

        # Color in reverse order
        color = greedy_color(reversed(order))
        k = num_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]
    except Exception:
        pass

    # Fallback: simple greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
