        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].append(u)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # Remove a vertex from bucket[ptr]
            while buckets[ptr] and (buckets[ptr][-1] not in remaining):
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for w in adj_list[v]:
                if w in remaining:
                    degrees[w] -= 1
                    if degrees[w] < ptr:
                        ptr = degrees[w]
                    buckets[degrees[w]].append(w)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for w in adj_list[v]:
                if color[w] != -1:
                    neighbor_colors |= (1 << color[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        color = coloring[:]
        # Map color to list of vertices
        while True:
            # Find color classes
            max_color = max(color) if n > 0 else -1
            if max_color < 0:
                break
            classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                classes[color[v]].append(v)
            # Try to eliminate the last color class (highest color)
            target = max_color
            if not classes[target]:
                # Already empty, compact
                mapping = {}
                new_color = 0
                for c in range(max_color + 1):
                    if classes[c]:
                        for v in classes[c]:
                            color[v] = new_color
                        new_color += 1
                # Rebuild classes
                max_color = new_color - 1
                classes = [[] for _ in range(new_color)]
                for v in range(n):
                    classes[color[v]].append(v)
                continue
            # Try to recolor each vertex in target class
            removed = False
            for v in classes[target][:]:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for w in adj_list[v]:
                    if color[w] != -1:
                        neighbor_colors |= (1 << color[w])
                for c in range(target):
                    if not (neighbor_colors & (1 << c)):
                        # Move v to color c
                        color[v] = c
                        classes[target].remove(v)
                        classes[c].append(v)
                        removed = True
                        break
                if removed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target):
                    # If v already has color c due to prior move, skip
                    if color[v] == c:
                        continue
                    # Check if v and any vertex of color c are in the same Kempe chain
                    # We'll do BFS from v in the subgraph of colors {c, target}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    chain_v = []
                    while queue:
                        u = queue.popleft()
                        chain_v.append(u)
                        for w in adj_list[u]:
                            if not visited[w] and (color[w] == c or color[w] == target):
                                visited[w] = True
                                queue.append(w)
                    # Now, check if there's a vertex of color c not reachable from v in this subgraph
                    # Actually, we want to see if we can swap: if the component of v does not contain all color c,
                    # but we can simply try to swap the component and see if it frees color c for v
                    # Instead, we check if there exists a vertex of color c that is not in the same component as v
                    # in the (c, target) subgraph. If so, swapping the component of v will not introduce conflict.
                    has_color_c_outside = False
                    for u in classes[c]:
                        if not visited[u]:
                            has_color_c_outside = True
                            break
                    if has_color_c_outside:
                        # Swap colors c and target in the component of v
                        for u in chain_v:
                            if color[u] == c:
                                color[u] = target
                            elif color[u] == target:
                                color[u] = c
                        # Update classes
                        for u in chain_v:
                            if color[u] == target:
                                classes[target].append(u)
                                if u in classes[c]:
                                    classes[c].remove(u)
                            elif color[u] == c:
                                classes[c].append(u)
                                if u in classes[target]:
                                    classes[target].remove(u)
                        # Now v should be color c
                        if color[v] == target:
                            # Actually, we swapped, so v is now c if it was target
                            pass
                        # Now try to assign v to c (should be free now)
                        neighbor_colors = 0
                        for w in adj_list[v]:
                            if color[w] != -1:
                                neighbor_colors |= (1 << color[w])
                        if not (neighbor_colors & (1 << c)):
                            color[v] = c
                            # Move v from target to c in classes
                            if v in classes[target]:
                                classes[target].remove(v)
                            classes[c].append(v)
                            removed = True
                            break
                if removed:
                    break
            if not removed:
                break  # Cannot reduce further
            # Compact colors if needed
            max_color = max(color) if n > 0 else -1
            if max_color < 0:
                break
            classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                classes[color[v]].append(v)
            # Check for empty classes and compact
            new_color = 0
            mapping = {}
            for c in range(max_color + 1):
                if classes[c]:
                    mapping[c] = new_color
                    new_color += 1
            if new_color == max_color + 1:
                break  # No empty classes
            for v in range(n):
                color[v] = mapping[color[v]]
        return color

    # Run all heuristics
    best_coloring = None
    best_colors = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            coloring = func()
            # Validate
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue
            num_colors = len(set(coloring))
            if num_colors < best_colors:
                best_colors = num_colors
                best_coloring = coloring[:]
        except Exception:
            continue

    # Fallback: greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        color = [-1] * n
        for u in order:
            neighbor_colors = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    neighbor_colors |= (1 << color[v])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[u] = c
        best_coloring = color

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
    except Exception:
        pass

    # Final validation and compacting
    # Ensure colors are consecutive
    if n > 0:
        unique_colors = sorted(set(best_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

