def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        neighbors = [set(lst) for lst in adj]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (saturated[x], len([u for u in neighbors[x] if u in uncolored]), x))
            # Find smallest available color
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] += 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            independent_set = {v}
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v} - neighbors[v]
            W = neighbors[v] & uncolored
            # Greedily add vertices from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([w for w in neighbors[x] if w in U]), x))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                W.update(nbrs_u)
                U -= nbrs_u
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[v]) for v in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[deg[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate (should not happen), fallback to trivial
    if not candidates:
        color = [0] * n
        for i in range(1, n):
            color[i] = i
        return color

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal k
        changed = True
        while changed and k > 1:
            changed = False
            # Find smallest color class (highest index, assuming compact)
            # We'll try to eliminate color k-1
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compacted?
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                used_by_neighbors = set()
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used_by_neighbors.add(coloring[u])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Skip if v already has color c (shouldn't happen)
                    if coloring[v] == c:
                        continue
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # Only if v has color target_color (it does)
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == target_color or coloring[u] == c):
                                    stack.append(u)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see
                    # if we can swap without causing conflict. Swapping is safe if no neighbor of v
                    # outside the component has color c (because after swap, v would get c).
                    # More precisely: after swapping colors target_color and c in the component,
                    # v will get color c. This is valid if no neighbor of v has color c after swap.
                    # Neighbors of v: if in component, their color flips (so if they were target_color, become c; if c, become target_color).
                    # We need to ensure that no neighbor of v ends up with color c.
                    # Let's compute: after swap, a neighbor u of v will have:
                    #   - if u in component: color flips between target_color and c
                    #   - if u not in component: color unchanged
                    # So neighbor u has color c after swap iff:
                    #   (u in component and coloring[u] == target_color) OR (u not in component and coloring[u] == c)
                    # We want this to be false for all u in neighbors[v].
                    conflict = False
                    for u in neighbors[v]:
                        if (u in component and coloring[u] == target_color) or (u not in component and coloring[u] == c):
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            # If we made a change, check if target color class is now empty
            if changed:
                # Recompute k and compact if needed
                used_colors = set(coloring)
                if not used_colors:
                    k = 0
                else:
                    k = max(used_colors) + 1
                # Compact colors to 0..k-1
                mapping = {}
                next_c = 0
                for old in sorted(used_colors):
                    mapping[old] = next_c
                    next_c += 1
                for i in range(n):
                    coloring[i] = mapping[coloring[i]]
            else:
                # Could not reduce further
                break
        return coloring

    # Apply Kempe reduction
    best = kempe_reduce(best)
    # Final validation (should hold)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    return best

