def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor bitmasks
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= 1 << j
    else:
        for i in range(n):
            for nb in adj[i]:
                bit_adj[i] |= 1 << nb

    def bit_count(x: int) -> int:
        return x.bit_count()

    def neighbors_of(v: int) -> int:
        return bit_adj[v]

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and bit_count(neighbors_of(u) & sum(1 << w for w in uncolored)) > max_deg):
                    max_sat = sat[u]
                    max_deg = bit_count(neighbors_of(u) & sum(1 << w for w in uncolored))
                    v = u
            if v == -1:
                v = next(iter(uncolored))
            # find smallest color not used by neighbors
            used = 0
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                c = color[w]
                if c >= 0:
                    used |= 1 << c
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                if color[w] == -1:
                    sat[w] += 1
                nb &= nb - 1
        return color

    # RLF (Recursive Largest First)
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in induced subgraph of uncolored
            deg = {}
            for v in uncolored:
                deg[v] = bit_count(neighbors_of(v) & sum(1 << w for w in uncolored))
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to any in S
            # W: vertices adjacent to at least one in S
            U = set()
            W = set()
            for w in uncolored:
                if neighbors_of(w) & sum(1 << s for s in S):
                    W.add(w)
                else:
                    U.add(w)
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = None
                for u in U:
                    score = bit_count(neighbors_of(u) & sum(1 << w for w in W))
                    degU = bit_count(neighbors_of(u) & sum(1 << w for w in U))
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                nb = neighbors_of(u)
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    nb &= nb - 1
            # assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # core decomposition to get order
        deg = [bit_count(neighbors_of(v)) for v in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = deg[v]
        # simulate removal
        for _ in range(n):
            # find min degree vertex in remaining
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # update neighbors
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                if w in remaining:
                    # decrease degree of w
                    old_deg = pos[w]
                    buckets[old_deg].remove(w)
                    pos[w] -= 1
                    new_deg = pos[w]
                    buckets[new_deg].append(w)
                nb &= nb - 1
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                cw = color[w]
                if cw >= 0:
                    used |= 1 << cw
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(color_init: list[int]) -> list[int]:
        color = color_init[:]
        # map color to vertices
        while True:
            # determine number of colors used
            max_color = max(color) if n > 0 else -1
            if max_color < 0:
                return color
            # build color classes
            classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                classes[color[v]].append(v)
            # find smallest non-empty color class (by index, but we target highest color for removal)
            # we try to eliminate the highest color class
            target = max_color
            if not classes[target]:
                # should not happen, but compact
                # remap colors to be consecutive
                mapping = {}
                new_color = [-1] * n
                next_c = 0
                for v in range(n):
                    if color[v] not in mapping:
                        mapping[color[v]] = next_c
                        next_c += 1
                    new_color[v] = mapping[color[v]]
                color = new_color
                continue
            # try to recolor each vertex in target class to a lower color
            moved = False
            for v in classes[target]:
                # try direct reassignment to a lower color
                used = 0
                nb = neighbors_of(v)
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    cw = color[w]
                    if cw >= 0:
                        used |= 1 << cw
                    nb &= nb - 1
                for c in range(target):
                    if not (used & (1 << c)):
                        color[v] = c
                        moved = True
                        break
                if moved:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # if v already has color c after possible direct move, skip
                    if color[v] == c:
                        continue
                    # check if there is a Kempe chain (v, target) <-> (c) that does not include any other target-colored vertex besides v
                    # we BFS from v in the subgraph of colors {target, c}
                    from collections import deque
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    component = []
                    has_other_target = False
                    while q:
                        u = q.popleft()
                        component.append(u)
                        if color[u] == target and u != v:
                            has_other_target = True
                        # explore neighbors with color target or c
                        nb = neighbors_of(u)
                        while nb:
                            w = (nb & -nb).bit_length() - 1
                            if not visited[w] and (color[w] == target or color[w] == c):
                                visited[w] = True
                                q.append(w)
                            nb &= nb - 1
                    if not has_other_target:
                        # swap colors target and c in this component
                        for u in component:
                            if color[u] == target:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target
                        moved = True
                        break
                if moved:
                    break
            if not moved:
                # cannot reduce further
                break
        # compact colors to be 0..k-1
        mapping = {}
        next_c = 0
        for v in range(n):
            if color[v] not in mapping:
                mapping[color[v]] = next_c
                next_c += 1
            color[v] = mapping[color[v]]
        return color

    # Run all heuristics
    best_color = None
    best_k = float('inf')
    for func in (dsatur, rlf, smallest_last):
        try:
            col = func()
            col = kempe_reduce(col)
            # validate
            ok = True
            for u in range(n):
                nb = neighbors_of(u)
                while nb:
                    v = (nb & -nb).bit_length() - 1
                    if color[u] == color[v]:
                        ok = False
                        break
                    nb &= nb - 1
                if not ok:
                    break
            if not ok:
                continue
            k = len(set(col))
            if k < best_k:
                best_k = k
                best_color = col
        except Exception:
            continue
    if best_color is None:
        # fallback to greedy
        best_color = [0] * n
        for i in range(n):
            used = 0
            nb = neighbors_of(i)
            while nb:
                w = (nb & -nb).bit_length() - 1
                used |= 1 << best_color[w]
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            best_color[i] = c
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
    else:
        for u in range(n):
            if isinstance(adj[u], list):
                for v in adj[u]:
                    if 0 <= v < n:
                        neighbors[u].add(v)

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    best_coloring = None
    best_k = float('inf')

    # Helper: validate coloring and compute number of colors
    def validate_and_get_k(coloring):
        if len(coloring) != n:
            return float('inf')
        seen = set()
        for u in range(n):
            c = coloring[u]
            if c < 0:
                return float('inf')
            seen.add(c)
            # Check neighbors
            mask = bit_adj[u]
            v = 0
            while mask:
                if mask & 1:
                    if coloring[v] == c:
                        return float('inf')
                mask >>= 1
                v += 1
        return len(seen)

    # Helper: convert to consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return [0] * n
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(neighbors[u]) for u in range(n)]
        # Saturation sets: track distinct neighbor colors per vertex
        saturation_sets = [set() for _ in range(n)]
        # Colored neighbor count not needed explicitly

        for _ in range(n):
            # Select uncolored vertex with max saturation degree, tie-break by degree, then random
            cand = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat = len(saturation_sets[u])
                    deg = degrees[u]
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or \
                       (sat == max_sat and deg == max_deg and (cand == -1 or random.random() < 0.5)):
                        max_sat = sat
                        max_deg = deg
                        cand = u
            if cand == -1:
                break  # should not happen
            # Find smallest available color
            used = saturation_sets[cand]
            c = 0
            while c in used:
                c += 1
            colors[cand] = c
            # Update saturation sets of uncolored neighbors
            for v in neighbors[cand]:
                if colors[v] == -1:
                    saturation_sets[v].add(c)
        return colors

    # RLF: Recursive Largest First via independent set extraction
    def rlf():
        if n == 0:
            return [0] * n
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            S = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            if uncolored:
                v = max(uncolored, key=lambda u: len(neighbors[u] & uncolored))
                S.add(v)
                uncolored.remove(v)
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            W = set()
            for u in S:
                W.update(neighbors[u])
            U = uncolored - W

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    deg_in_U = len(neighbors[u] & U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for v in neighbors[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for u in S:
                colors[u] = color
            color += 1
            # Next iteration: uncolored becomes W (vertices adjacent to S)
            uncolored = W
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return [0] * n
        # Compute degeneracy ordering via min-degree peeling
        remaining = set(range(n))
        degree = [len(neighbors[u]) for u in range(n)]
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for v in neighbors[v_min]:
                if v in remaining:
                    degree[v] -= 1
        # Color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        while changed:
            changed = False
            # Get color classes
            color_classes = {}
            for v in range(n):
                c = current[v]
                color_classes.setdefault(c, []).append(v)
            if not color_classes:
                break
            max_color = max(color_classes.keys())
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
                if target_color not in color_classes or not color_classes[target_color]:
                    continue
                # Try to recolor each vertex in this class
                eliminated = True
                for v in color_classes[target_color][:]:  # iterate over copy
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if current[u] != -1:
                            neighbor_colors.add(current[u])
                    for c in range(target_color):  # only try colors < target_color
                        if c not in neighbor_colors:
                            # Move v to color c
                            current[v] = c
                            changed = True
                            break
                    else:
                        # Direct reassignment not possible, try Kempe chains
                        found = False
                        for c in range(target_color):
                            # Skip if color c not present (optional optimization)
                            if c not in color_classes:
                                continue
                            # Check if v is adjacent to any vertex of color c
                            adj_to_c = False
                            for u in neighbors[v]:
                                if current[u] == c:
                                    adj_to_c = True
                                    break
                            if adj_to_c:
                                continue  # Kempe chain swap would not help directly
                            # Build (target_color, c)-Kempe chain containing v
                            stack = [v]
                            visited = set()
                            component = set()
                            while stack:
                                node = stack.pop()
                                if node in visited:
                                    continue
                                visited.add(node)
                                if current[node] == target_color or current[node] == c:
                                    component.add(node)
                                    for w in neighbors[node]:
                                        if w not in visited and (current[w] == target_color or current[w] == c):
                                            stack.append(w)
                            # Check if swapping this component is safe: 
                            # No vertex in component should have a neighbor of color c outside component (would cause conflict after swap)
                            safe = True
                            for node in component:
                                for w in neighbors[node]:
                                    if current[w] == c and w not in component:
                                        safe = False
                                        break
                                if not safe:
                                    break
                            if safe:
                                # Perform swap: target_color <-> c in component
                                for node in component:
                                    if current[node] == target_color:
                                        current[node] = c
                                    else:  # must be c
                                        current[node] = target_color
                                changed = True
                                found = True
                                break
                        if found:
                            # After successful Kempe swap, v might still be target_color? 
                            # Actually, if v was target_color and we swapped, it becomes c.
                            # So we break and restart the color class iteration
                            break
                # After processing all vertices in target_color, check if class is empty
                if target_color in color_classes and not color_classes[target_color]:
                    # Remove this color by shifting higher colors down
                    for v in range(n):
                        if current[v] > target_color:
                            current[v] -= 1
                    changed = True
                    break  # restart while loop as coloring changed
                elif not changed:
                    # Could not eliminate this color, try next lower
                    pass
        return current

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        k1 = validate_and_get_k(c1)
        if k1 < best_k:
            best_k = k1
            best_coloring = c1
        candidates.append(c1)
    except Exception:
        pass

    # RLF
    try:
        c2 = rlf()
        k2 = validate_and_get_k(c2)
        if k2 < best_k:
            best_k = k2
            best_coloring = c2
        candidates.append(c2)
    except Exception:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        k3 = validate_and_get_k(c3)
        if k3 < best_k:
            best_k = k3
            best_coloring = c3
        candidates.append(c3)
    except Exception:
        pass

    # Apply Kempe reduction to each candidate and keep the best
    for cand in candidates:
        try:
            reduced = kempe_reduce(cand)
            k_red = validate_and_get_k(reduced)
            if k_red < best_k:
                best_k = k_red
                best_coloring = reduced
        except Exception:
            pass

    # Fallback: if no candidate succeeded, use greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_coloring = colors

    # Normalize to ensure consecutive colors starting from 0
    best_coloring = normalize(best_coloring)
    # Final validation (should be valid by construction)
    # In case of any issue, return a valid but possibly non-optimal coloring
    final_k = validate_and_get_k(best_coloring)
    if final_k == float('inf'):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))

    return best_coloring

