            for v in uncolored:
                for u in neigh[v]:
                    if u in uncolored:
                        deg[v] += 1
            # start with max degree vertex
            v = max(uncolored, key=lambda x: (deg[x], random.random()))
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - set(neigh[v])
