                            for y in neigh[x]:
                                if col[x] == col[y]:
                                    ok = False
                                    break
                            if not ok:
                                break
                        if ok:
                            swapped = True
                            changed = True
                            break  # break color loop
                        else:
                            # swap back
                            for x in range(n):
                                if visited[x]:
                                    if col[x] == target:
                                        col[x] = c
                                    else:
                                        col[x] = target
                    if swapped:
                        break  # break vertex loop
                if not eliminated:
                    # cannot eliminate this color class, break to try next lower? 
                    # Actually, if we couldn't eliminate this class, we break and try next target?
                    # But we are iterating from high to low, so if we can't eliminate target, 
                    # we break and try to eliminate a lower one? 
                    # However, eliminating a lower color class might be easier.
                    # We'll break the vertex loop and continue to next target.
                    # But we set eliminated=False if any vertex couldn't be recolored.
                    # We'll break and try next target.
                    break
                else:
                    # all vertices of target color recolored, so color target is eliminated
                    # compact colors later
                    break
            # if we eliminated a color, restart the while loop
            if changed:
                break
        # compact colors to 0..k-1
        return normalize(col)
    # Run all heuristics
    start = time.perf_counter()
    best_coloring = None
    best_k = math.inf
    # DSATUR
    if time.perf_counter() - start < 0.05:
        col = dsatur()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # RLF
    if time.perf_counter() - start < 0.05:
        col = rlf()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # Smallest-Last
    if time.perf_counter() - start < 0.05:
        col = smallest_last()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # If none worked (should not happen), fallback to greedy
    if best_coloring is None:
        # simple greedy in vertex order
        col = [-1] * n
        for v in range(n):
            used = 0
            for u in neigh[v]:
                if col[u] != -1:
                    used |= (1 << col[u])
            c = 0
            while used & (1 << c):
                c += 1
            col[v] = c
        best_coloring = col
    # Apply Kempe reduction
    if time.perf_counter() - start < 0.05:
        best_coloring = kempe_reduce(best_coloring)
    # Final validation and normalization
    if not is_valid(best_coloring):
        # emergency fix: greedy
        col = [-1] * n
        for v in range(n):
            used = 0
            for u in neigh[v]:
                if col[u] != -1:
                    used |= (1 << col[u])
            c = 0
            while used & (1 << c):
                c += 1
            col[v] = c
        best_coloring = col
    best_coloring = normalize(best_coloring)
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in adj_list[u]:
                bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: convert to compact 0..k-1 colors
    def compact_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # Precompute neighbor bitmasks for saturation
        neighbor_mask = bit_adj[:]
        # Degree for tie-breaking
        degree = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                # Compute saturation: distinct colors in neighbors
                sat = 0
                seen = 0
                for u in adj_list[v]:
                    if colored[u]:
                        c = colors[u]
                        if not (seen >> c) & 1:
                            seen |= (1 << c)
                            sat += 1
                if sat > best_sat or (sat == best_sat and degree[v] > best_deg):
                    best_sat = sat
                    best_deg = degree[v]
                    best_v = v
                elif sat == best_sat and degree[v] == best_deg and v < best_v:
                    best_v = v  # deterministic tie-break by index

            v = best_v
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if colored[u]:
                    c = colors[u]
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
        return compact_colors(colors)

    # RLF: Recursive Largest First (maximal independent set extraction)
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color = 0
        # Precompute degree in full graph for initial selection
        full_degree = [len(adj_list[i]) for i in range(n)]

        while not all(colored):
            # Find uncolored vertex with max degree in uncolored subgraph
            best_v = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                # Count uncolored neighbors
                deg = 0
                for u in adj_list[v]:
                    if not colored[u]:
                        deg += 1
                if deg > best_deg or (deg == best_deg and v < best_v):
                    best_deg = deg
                    best_v = v

            # Build independent set for this color
            S = [best_v]
            colored[best_v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if colored[u]:
                    continue
                adjacent_to_S = False
                for v in S:
                    if u in adj_list[v]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # Count neighbors in W
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u

                u = best_u
                S.append(u)
                colored[u] = True
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1

        return compact_colors(colors)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees and adjacency for peeling
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will hold vertices in removal order
        # We'll maintain a list of vertices for each degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(bins):
                bins[degree[v]].append(v)
        # Pointer to current min degree
        min_deg = 0

        for _ in range(n):
            # Find non-empty bin with smallest degree
            while min_deg < len(bins) and not bins[min_deg]:
                min_deg += 1
            if min_deg >= len(bins):
                break  # should not happen
            v = bins[min_deg].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    old_deg = degree[u]
                    degree[u] -= 1
                    if old_deg < len(bins):
                        bins[old_deg].remove(u)  # O(n) but n <= 100
                    if degree[u] < len(bins):
                        bins[degree[u]].append(u)
                    if degree[u] < min_deg:
                        min_deg = degree[u]

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Make a copy we can modify
        cols = colors[:]
        changed = True
        # We'll try to eliminate the highest color class repeatedly
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if cols[v] == target_color]
            if not target_vertices:
                # Already compacted?
                k = num_colors(cols)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if cols[u] != -1:
                        used |= (1 << cols[u])
                for c in range(target_color):  # only lower colors
                    if not (used & (1 << c)):
                        cols[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart scan as colors changed
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has color c from direct reassignment above, skip
                    if cols[v] == c:
                        continue
                    # Check if v can be swapped via (target_color, c) Kempe chain
                    # We'll do BFS to find the component of v in the subgraph of colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    has_target = False
                    has_c = False
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        col_node = cols[node]
                        if col_node == target_color:
                            has_target = True
                        elif col_node == c:
                            has_c = True
                        for nb in adj_list[node]:
                            if not visited[nb] and (cols[nb] == target_color or cols[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # If the component does not contain color c, we can swap
                    if not has_c:
                        # Swap colors in component: target_color <-> c
                        for node in component:
                            if cols[node] == target_color:
                                cols[node] = c
                            elif cols[node] == c:
                                cols[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # Compact colors after change
                cols = compact_colors(cols)
                k = num_colors(cols)
        return cols

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))

    # Choose best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compact
    if not is_valid_coloring(best):
        # Should not happen, but fallback to DSATUR
        best = dsatur()
    return compact_colors(best)

import math
