    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        # Precompute degrees
        deg = [len(neighbors[i]) for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                # Compute saturation: distinct colors in neighbors
                sat_set = set()
                for u in neighbors[v]:
                    if color[u] != -1:
                        sat_set.add(color[u])
                sat = len(sat_set)
                # Current degree in uncolored subgraph
                cur_deg = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cur_deg += 1
                if sat > best_sat or (sat == best_sat and (cur_deg > best_deg or (cur_deg == best_deg and random.random() < 0.5))):
                    best_sat = sat
                    best_deg = cur_deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            S = set()
            # Find vertex with max degree in G[uncolored]
            max_deg = -1
            v0 = -1
            for v in uncolored:
                deg_in_uncolored = 0
                for u in neighbors[v]:
