                        if not conflict:
                            # Perform swap: a<->b in the component
                            for x in comp:
                                if col[x] == a:
                                    col[x] = b
                                elif col[x] == b:
                                    col[x] = a
                            changed = True
                            break  # break from color c loop
                    if changed:
