    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation degree: bitmask of colors used by colored neighbors
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and (len([w for w in adj_list[u] if w in uncolored]) > max_deg)):
                    max_sat = s
                    max_deg = len([w for w in adj_list[u] if w in uncolored])
                    v = u
                elif s == max_sat and len([w for w in adj_list[u] if w in uncolored]) == max_deg:
                    if random.random() < 0.5:  # random tie-break
                        v = u
            if v == -1:
                v = next(iter(uncolored))
            uncolored.remove(v)
            # Find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([w for w in adj_list[x] if w in uncolored]))
            independent_set = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to any in S, W = adjacent to at least one in S
            U = {u for u in uncolored if not any(w in adj_list[u] for w in independent_set)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = len([w for w in adj_list[u] if w in W])
                    deg_u = len([w for w in adj_list[u] if w in U])
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                if u_star == -1:
                    u_star = next(iter(U))
                independent_set.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to independent set
            for v in independent_set:
                color[v] = c
            c += 1
            uncolored = W  # Next iteration colors the vertices adjacent to current independent set
        return color

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Heuristic 4: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Run all heuristics
    for heuristic in [dsatur, rlf, smallest_last, welsh_powell]:
        coloring = heuristic()
        k = count_colors(coloring)
        if k < best_k or (k == best_k and best_coloring is None):
            best_k = k
            best_coloring = coloring[:]

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # Make a copy to work on
        color = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class (highest color index that is used)
            max_color = max(color) if color else -1
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                # Get vertices with target_color
                verts = [v for v in range(n) if color[v] == target_color]
                if not verts:
                    continue
                # Try to recolor each vertex in this class
                eliminated = True
                new_color = color[:]  # tentative
                for v in verts:
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in adj_list[v]:
                        c = new_color[u]
                        if c != -1:
                            used |= (1 << c)
                    found = False
                    for c in range(target_color):  # only try colors < target_color
                        if not (used & (1 << c)):
                            new_color[v] = c
                            found = True
                            break
                    if not found:
                        eliminated = False
                        break
                if eliminated:
                    # Successfully recolored all vertices of target_color to lower colors
                    color = new_color
                    changed = True
                    break  # restart from highest color
                else:
                    # Try Kempe chains for each vertex in target_color class
                    for v in verts:
                        # For each lower color c
                        for c in range(target_color):
                            # Check if v can be swapped via Kempe chain (c, target_color)
                            # If v is not adjacent to any vertex of color c, we could swap directly, but we already tried direct
                            # Instead, build the Kempe chain component containing v for colors c and target_color
                            from collections import deque
                            visited = [False] * n
                            queue = deque([v])
                            visited[v] = True
                            component = []
                            while queue:
