            U = uncolored - {v}
            W = set()
            # move neighbors of v from U to W
            for nb in list(U):
                if nb in neighbors[v]:
                    U.remove(nb)
                    W.add(nb)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = len([w for w in neighbors[u] if w in W])
                    deg_U = len([w for w in neighbors[u] if w in U])
