                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in list(U):
                    if nb in neighbors[u]:
                        U.remove(nb)
                        W.add(nb)
