        min_deg = 0
        order = []
        # copy of degrees
        curr_deg = deg[:]
        # set of remaining vertices
        remaining = set(range(n))
        while remaining:
            # find non-empty bin with min degree
            while min_deg <= max_deg and not bins[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = bins[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for nb in neighbors[v]:
                if nb in remaining:
                    d = curr_deg[nb]
                    # remove from current bin
                    bins[d].remove(nb)
                    curr_deg[nb] -= 1
                    d_new = curr_deg[nb]
                    bins[d_new].add(nb)
                    pos[nb] = d_new
                    if d_new < min_deg:
                        min_deg = d_new
