        changed = True
        while changed:
            changed = False
            k = num_colors(color)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target = k - 1
            target_vertices = [v for v in range(n) if color[v] == target]
            if not target_vertices:
                # should not happen, but compact
                color = compact(color)
                continue
