    except Exception:
        pass
    # If no candidate, fallback to greedy
    if not candidates:
        color = [-1] * n
        for i in range(n):
            used = 0
            for nb in neighbors[i]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
