                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for vertex in S:
                color[vertex] = c
                uncolored.remove(vertex)
            c += 1
        return color
    # Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering via repeated removal of min degree
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # current degrees in remaining subgraph
        curr_deg = degrees[:]
        # bucket queue for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[curr_deg[i]].append(i)
        # pointer to current min non-empty bucket
        min_ptr = 0
        while remaining:
            # find next non-empty bucket
            while min_ptr <= max_deg and not buckets[min_ptr]:
                min_ptr += 1
            if min_ptr > max_deg:
                break
            v = buckets[min_ptr].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = curr_deg[u]
                    buckets[old_deg].remove(u)
                    curr_deg[u] -= 1
                    new_deg = curr_deg[u]
                    if new_deg >= len(buckets):
                        buckets.extend([[] for _ in range(new_deg - len(buckets) + 1)])
                    buckets[new_deg].append(u)
                    if new_deg < min_ptr:
                        min_ptr = new_deg
        # color in reverse order
        return greedy_color(order[::-1])
    # Kempe chain elimination
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        # try to eliminate colors from highest down
        changed = True
        while changed and k > 0:
            changed = False
            # target smallest color class (highest index)
            target = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target]
            if not target_vertices:
                # already empty, compact
                for v in range(n):
                    if coloring[v] > target:
                        coloring[v] -= 1
                k -= 1
                changed = True
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # BFS to find Kempe chain of colors {target, c} containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target or coloring[node] == c:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (coloring[nb] == target or coloring[nb] == c):
                                    stack.append(nb)
                    # check if inverting this component would free color c for v
                    # after inversion, v would get color c (since it was target)
                    # we need to ensure no neighbor of v gets color c from inversion
                    conflict = False
                    for nb in neighbors[v]:
                        if nb in component:
                            # nb would flip from target to c or c to target
                            orig = coloring[nb]
                            newc = c if orig == target else target
                            if newc == c:
                                conflict = True
                                break
                        else:
                            if coloring[nb] == c:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for node in component:
                            if coloring[node] == target:
                                coloring[node] = c
                            else:
                                coloring[node] = target
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors if needed
                # recompute k and reindex
                k = num_colors(coloring)
                # create mapping from old colors to new consecutive colors
                unique_colors = sorted(set(coloring))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                for v in range(n):
                    coloring[v] = mapping[coloring[v]]
        return coloring
    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except Exception:
        pass
    # Fallback: greedy by natural order
    try:
        col_greedy = greedy_color(list(range(n)))
        candidates.append(col_greedy)
    except Exception:
        pass
    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        if col is None:
            continue
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best = col
    if best is None:
        best = [0] * n
    # Apply Kempe reduction to best candidate
    best = kempe_reduce(best)
    # Final validation and compacting
    # Ensure proper coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best[u] == best[v]:
                # Should not happen, but fallback to greedy
                best = greedy_color(list(range(n)))
                break
        else:
            continue
        break
    # Compact colors
    if best:
        unique_colors = sorted(set(best))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        for v in range(n):
            best[v] = mapping[best[v]]
    return best

