import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        neighbors = [ [j for j, val in enumerate(row) if val] for row in adj ]
    else:
        # Adjacency list (ensure each element is a list)
        neighbors = [list(lst) for lst in adj]
    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to list if needed
    def ensure_list(coloring):
        return list(coloring)

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmask for fast distinct count
        neighbor_colors = [0] * n
        uncolored = set(range(n))
        # initial degrees for tie-breaking
        degrees = [len(neighbors[u]) for u in range(n)]
        while uncolored:
            # select vertex with max saturation, break ties by degree, then random
            v = max(uncolored, key=lambda x: (saturation[x], degrees[x], random.random()))
            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    # if this color is new in u's neighbor colors
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return color

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # start with vertex of max degree in uncolored subgraph
            # compute degree in uncolored subgraph
            deg_in_uncolored = {}
            for v in uncolored:
                # count neighbors that are also uncolored
                cnt = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cnt += 1
                deg_in_uncolored[v] = cnt
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: (deg_in_uncolored[x], random.random()))
            independent_set = {v}
            # eligible: vertices not adjacent to any in independent_set
            ineligible = set()
            for u in neighbors[v]:
                if u in uncolored:
                    ineligible.add(u)
            eligible = uncolored - {v} - ineligible
            # while there are eligible vertices
            while eligible:
                # select u in eligible with max neighbors in ineligible
                # tie-break by min degree in eligible subgraph
                best_u = None
                best_score = -1
                best_deg = None
                for u in eligible:
                    # score: number of neighbors in ineligible
                    score = 0
                    for w in neighbors[u]:
                        if w in ineligible:
                            score += 1
                    # degree in eligible subgraph
                    deg_eligible = 0
                    for w in neighbors[u]:
                        if w in eligible:
                            deg_eligible += 1
                    if score > best_score or (score == best_score and (best_deg is None or deg_eligible < best_deg)):
                        best_score = score
                        best_deg = deg_eligible
                        best_u = u
                u = best_u
                independent_set.add(u)
                eligible.remove(u)
                # move neighbors of u from eligible to ineligible
                for w in neighbors[u]:
                    if w in eligible:
                        eligible.remove(w)
                        ineligible.add(w)
            # assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck) greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].add(v)
        # simulate peeling
        for _ in range(n):
            # find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            # decrease degree of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from its current bucket
                    buckets[degree[u]].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].add(u)
            remaining.remove(v)
        # color in reverse order using first-fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy we can modify
        color = list(coloring)
        # helper to get vertices of a color
        def color_class(c):
            return [v for v in range(n) if color[v] == c]
        # helper to check if moving v to color c is valid
        def can_move(v, c):
            for u in neighbors[v]:
                if color[u] == c:
                    return False
            return True
        # helper to get kempe chain component for colors a,b starting from v
        def kempe_component(v, a, b):
            if color[v] not in (a, b):
                return set()
            stack = [v]
            comp = set()
            while stack:
                x = stack.pop()
                if x in comp:
                    continue
                comp.add(x)
                for y in neighbors[x]:
                    if color[y] in (a, b) and y not in comp:
                        stack.append(y)
            return comp
        # main reduction loop
        improved = True
        while improved:
            improved = False
            k = num_colors(color)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = color_class(target_color)
            if not target_vertices:
                # should not happen, but compact anyway
                # remap colors to be consecutive
                mapping = {}
                next_c = 0
                for v in range(n):
                    c = color[v]
                    if c not in mapping:
                        mapping[c] = next_c
                        next_c += 1
                    color[v] = mapping[c]
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct move to a lower color
                for c in range(target_color):
                    if can_move(v, c):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chain swaps
                for c in range(target_color):
                    comp = kempe_component(v, target_color, c)
                    # check if swapping comp frees color c for v
                    # after swap, v would get color c, so we need that no neighbor of v has color c outside comp
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c and u not in comp:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for x in comp:
                            if color[x] == target_color:
                                color[x] = c
                            else:  # color[x] == c
                                color[x] = target_color
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # cannot reduce further
                break
        # compact colors to be consecutive starting from 0
        mapping = {}
        next_c = 0
        for v in range(n):
            c = color[v]
            if c not in mapping:
                mapping[c] = next_c
                next_c += 1
            color[v] = mapping[c]
        return color

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')
    for func in [dsatur, rlf, smallest_last]:
        try:
            coloring = func()
            if not is_valid(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            continue

    # fallback: greedy by initial degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = color

    # Apply Kempe reduction to improve
    best_coloring = kempe_reduce(best_coloring)
    # Final validation (should be valid)
    if not is_valid(best_coloring):
        # as last resort, assign distinct colors
        best_coloring = list(range(n))
    return best_coloring

import math
