def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format and convert to adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = [list(neighbors) for neighbors in adj]

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring given an ordering
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    best_colors = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree (distinct neighbor colors)
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (saturated[x], len([y for y in adj_list[x] if y in uncolored]), random.random()))
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Recompute saturation: count distinct colors in neighbors
                    mask = 0
                    for w in adj_list[u]:
                        if colors[w] != -1:
                            mask |= (1 << colors[w])
                    saturated[u] = mask.bit_count()
