    # 2. RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set S for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = {u for u in uncolored if u not in S and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([y for y in adj_list[x] if y in W]), -len([y for y in adj_list[x] if y in U]), random.random()))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

    # 3. Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len([y for y in adj_list[x] if y in remaining]) for x in range(n)]
        # Use bucket sort for efficiency
        max_deg = n - 1
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = len([y for y in adj_list[v] if y in remaining])
            buckets[d].append(v)
