                    if cur_colors[v] != target_color:
                        continue
                    # BFS to get component
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for y in adj_list[x]:
                            if cur_colors[y] in (c, target_color) and y not in comp:
                                comp.add(y)
                                queue.append(y)
                    # Check if swapping c and target_color in comp is valid and frees target_color for v
                    # After swap, v would become c, so we need that no neighbor of v is c (outside comp) or becomes c via swap?
                    # Actually, we need that after swap, v's color c does not conflict.
