                    # Neighbors of v that are in comp and had color c become target_color -> safe
                    # Neighbors of v not in comp and had color c -> conflict
                    # Neighbors of v that had target_color become c -> if not in comp, they become c and are neighbor -> conflict
                    # Actually, simpler: after swap, for any neighbor u of v:
                    #   if u in comp: new color = c if old was target_color, else target_color if old was c
                    #   if u not in comp: color unchanged
                    # So v becomes c. We need that no neighbor u of v has color c after swap.
                    conflict = False
