        unique_colors = sorted(set(cur_colors))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        compacted = [mapping[c] for c in cur_colors]
        return compacted

    # Apply Kempe reduction
    final_colors = kempe_reduce(best_colors)
    # Final validation (should always pass)
    for u in range(n):
        for v in adj_list[u]:
