        sat = [0] * n  # saturation degree
        uncolored = set(range(n))
        order = []
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([u for u in neighbors[x] if u in uncolored])))
            order.append(v)
            uncolored.remove(v)
