    def rlf_order():
        uncolored = set(range(n))
        order = []
        while uncolored:
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            color_class = [v]
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            S = {v}
            U = {u for u in uncolored if not any(u in neighbors[w] for w in S)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: len([w for w in neighbors[x] if w in W]))
                # Tie-break: min degree in U
                u = min(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), len([w for w in neighbors[x] if w in U])))
                color_class.append(u)
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            order.extend(color_class)
            uncolored = W
        return order

    candidates.append(rlf_order())

