    comp_adj = [[] for _ in range(n)]
    for i in range(n):
        neighbors = set(adj_list[i])
        for j in range(n):
            if i != j and j not in neighbors:
                comp_adj[i].append(j)

    # Greedy coloring via maximal independent set extraction using complement
    uncolored = set(range(n))
    color = [-1] * n
    c = 0

    while uncolored:
        # Start with vertex of max degree in G'[uncolored]
        v = max(uncolored, key=lambda x: len([n for n in comp_adj[x] if n in uncolored]))
        independent_set = {v}
        to_remove = {v}
        # Candidates: uncolored vertices not adjacent to v in G (i.e., neighbors in G')
        candidates = {u for u in uncolored if u != v and u in comp_adj[v]}

        while candidates:
            # Select vertex in candidates with most neighbors in to_remove (in G')
            u = max(candidates, key=lambda x: len([n for n in comp_adj[x] if n in to_remove]))
            independent_set.add(u)
            to_remove.add(u)
            candidates.remove(u)
            # Update candidates: remove u and its neighbors in G (non-neighbors in G')
            candidates -= {u}
            neighbors_u = set(adj_list[u])
            candidates -= {w for w in candidates if w in neighbors_u}

        # Assign color c to all vertices in independent_set
        for vertex in independent_set:
            color[vertex] = c
        uncolored -= independent_set
        c += 1

    return color

