                    best_sat = s
                    best_v = v
                    best_deg = sum(1 for u in neighbors[v] if u in uncolored)
                elif s == best_sat:
                    deg = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            v = best_v
            # Assign smallest color not used by colored neighbors
            used = colored_neighbors_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation and colored neighbors mask for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # If this is a new color for neighbor u, increase saturation
                    if not (colored_neighbors_mask[u] & (1 << c)):
                        sat[u] += 1
                        colored_neighbors_mask[u] |= 1 << c
        return coloring

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build maximal independent set S for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - S
            W = set()
            for u in U:
                if any(w in neighbors[u] for w in S):
                    W.add(u)
            U -= W
            # While U not empty, add vertex with max neighbors in W, tie-break by min degree in U
            while U:
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_u = sum(1 for x in neighbors[u] if x in U)
                    elif score == best_score:
                        deg_u = sum(1 for x in neighbors[u] if x in U)
                        if deg_u < best_deg_u:
                            best_deg_u = deg_u
                            best_u = u
                        elif deg_u == best_deg_u:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            uncolored -= S
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [0] * n
        for u in range(n):
            degrees[u] = len(neighbors[u])
        # We'll use a bucket queue for efficiency, but n<=100 so we can do linear scan
        temp_deg = degrees[:]
        remaining_set = set(range(n))
        while remaining_set:
            # Find vertex with min temp_deg in remaining_set
            v = min(remaining_set, key=lambda x: temp_deg[x])
            order.append(v)
            remaining_set.remove(v)
            for nb in neighbors[v]:
                if nb in remaining_set:
                    temp_deg[nb] -= 1
        # Reverse order for coloring
        order.reverse()
        return greedy_coloring(order)

    # Welsh-Powell ordering (by initial degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_coloring(order)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Try to eliminate the highest color class
            k = num_colors(col)
            if k <= 1:
                break
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if col[v] == target_color]
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for nb in neighbors[v]:
                    c = col[nb]
                    if c != -1:
                        used_by_neighbors |= 1 << c
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break
                # If direct reassignment not possible, try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be swapped via (target_color, c) Kempe chain
                    # We'll do BFS/DFS to find the Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in neighbors[u]:
                            if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see if
                    # swapping the component would cause a conflict. Swapping is safe if no neighbor
                    # of any vertex in the component (outside the component) has the color we are swapping to.
                    # More precisely: after swapping, vertices in component that were target_color become c,
                    # and vice versa. So we need to ensure that no neighbor of a vertex in the component
                    # (that is not in the component) has color c (for those becoming c) or target_color (for those becoming target_color).
                    # But note: neighbors inside the component are fine because they will swap accordingly.
                    # So we check:
                    # For each vertex u in component:
                    #   If col[u] == target_color (will become c): check that no neighbor outside component has color c.
                    #   If col[u] == c (will become target_color): check that no neighbor outside component has color target_color.
                    # However, note that if a neighbor outside component has color c, and u is target_color becoming c,
                    # then after swap u and neighbor both have c -> conflict.
                    safe = True
                    for u in component:
                        if col[u] == target_color:  # will become c
                            for nb in neighbors[u]:
                                if not visited[nb] and col[nb] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                        else:  # col[u] == c, will become target_color
                            for nb in neighbors[u]:
                                if not visited[nb] and col[nb] == target_color:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        # Perform swap
                        for u in component:
                            if col[u] == target_color:
                                col[u] = c
                            else:
                                col[u] = target_color
                        changed = True
                        break
                if changed:
                    break
            # If we eliminated the target color (no vertex has it), compact colors
            if target_color not in col:
                # Compact: map colors to 0..k-2
                mapping = {}
                next_c = 0
                for v in range(n):
                    if col[v] not in mapping:
                        mapping[col[v]] = next_c
                        next_c += 1
                    col[v] = mapping[col[v]]
                changed = True  # to continue trying to reduce further
        return col

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            c1 = compact_colors(c1)
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            c2 = compact_colors(c2)
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            c3 = compact_colors(c3)
            candidates.append(c3)
    except Exception:
        pass
    # Welsh-Powell
    try:
        c4 = welsh_powell()
        if is_valid(c4):
            c4 = compact_colors(c4)
            candidates.append(c4)
    except Exception:
        pass

    # If no candidates (should not happen), fallback to trivial greedy
    if not candidates:
        order = list(range(n))
        coloring = greedy_coloring(order)
        coloring = compact_colors(coloring)
        candidates.append(coloring)

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    best = compact_colors(best)
    # Final validation (should be valid by construction)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
        best = compact_colors(best)
    return best

