def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Ensure undirected (symmetric)
    for i in range(n):
        for j in adj_list[i]:
            if i not in adj_list[j]:
                adj_list[j].append(i)
                bit_adj[j] |= (1 << i)

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor_colors[v] = bitmask of colors used by neighbors
        neighbor_colors = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by max degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if saturation[u] > max_sat or (saturation[u] == max_sat and uncolored_deg[u] > max_deg):
                    max_sat = saturation[u]
                    max_deg = uncolored_deg[u]
                    v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Add color c to neighbor's used colors
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
                    uncolored_deg[u] -= 1
        return color

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build maximal independent set for current_color
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            independent_set = {v}
            to_check = set()
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            W = set()
            for u in adj_list[v]:
                if u in uncolored:
                    W.add(u)
            U = uncolored - {v} - W

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len([x for x in adj_list[u] if x in W])
                    deg_in_U = len([x for x in adj_list[u] if x in U])
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for u in adj_list[best_u]:
                    if u in U:
                        U.remove(u)
                        W.add(u)
            # Assign color to independent_set
            for v in independent_set:
                color[v] = current_color
                uncolored.remove(v)
            current_color += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        color = [-1] * n
        # Copy of degrees
        deg = [len(adj_list[i]) for i in range(n)]
        # Set of unremoved vertices
        remaining = set(range(n))
        order = []  # removal order

        # Repeatedly remove vertex of minimum degree
        for _ in range(n):
            if not remaining:
                break
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    deg[u] -= 1

        # Color in reverse removal order
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid

        # Make a copy to work on
        color = coloring[:]
        k = num_colors(color)
        if k <= 1:
            return color

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if color[v] == target_color]
            if not target_vertices:
                # Already compacted?
                k = num_colors(color)
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if color[u] != -1:
                        used_by_neighbors |= (1 << color[u])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (used_by_neighbors & (1 << c)):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    # After recoloring v, check if target_color is now unused
                    if target_color not in color:
                        k = num_colors(color)
                        color = normalize(color)
                        break  # restart outer while loop
                    else:
                        # Revert and try Kempe chains
                        color[v] = target_color

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors (target_color, c)
                    # Only if v is not already color c (it isn't, since we're trying to move from target_color)
                    # We'll do BFS to find the component containing v in the subgraph induced by colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque()
                    # Start BFS from v only if it has color target_color (it does)
                    if color[v] == target_color:
                        queue.append(v)
                        visited[v] = True
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (color[nb] == target_color or color[nb] == c):
                                visited[nb] = True
                                queue.append(nb)

                    # Check if any neighbor of v in the component has color c? Actually, we want to see if we can swap
                    # without causing conflict. Swapping is safe if no neighbor of the component has color c (for target_color->c) 
                    # or color target_color (for c->target_color) outside the component? 
                    # Standard Kempe: swapping colors in a component is always safe because adjacent vertices have different colors.
                    # But we want to free color target_color for v? Actually, we want to move v from target_color to c.
                    # After swap, v will have color c. We need to ensure that no neighbor of v has color c after swap.
                    # Before swap, neighbors of v cannot have color c if they are in the component? 
                    # Actually, in the component, vertices have alternating colors. If we swap, v (target_color) becomes c.
                    # Its neighbors in the component that were c become target_color, so they are not c anymore.
                    # Neighbors not in the component: if they have color c, then after swap they still have color c, and v becomes c -> conflict.
                    # So we need that no neighbor of v outside the component has color c.
                    conflict = False
                    for nb in adj_list[v]:
                        if nb not in component and color[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: in component, swap target_color <-> c
                        for node in component:
                            if color[node] == target_color:
                                color[node] = c
                            elif color[node] == c:
                                color[node] = target_color
                        improved = True
                        # Check if target_color is now unused
                        if target_color not in color:
                            k = num_colors(color)
                            color = normalize(color)
                            break
                if improved and target_color not in color:
                    break
            # If we didn't eliminate target_color, try next lower color class? 
            # But we are targeting the highest color class; if we can't eliminate it, we stop.
            if not improved:
                break
        return color

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            c1 = normalize(c1)
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            c2 = normalize(c2)
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            c3 = normalize(c3)
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        color = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if color[j] != -1:
                    used |= (1 << color[j])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        candidates.append(normalize(color))

    # Select candidate with fewest colors
    best_coloring = min(candidates, key=num_colors)

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid(improved) and num_colors(improved) < num_colors(best_coloring):
            best_coloring = improved
    except:
        pass

    # Final normalization and validation
    best_coloring = normalize(best_coloring)
    if not is_valid(best_coloring):
        # Last resort: greedy
        color = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if color[j] != -1:
                    used |= (1 << color[j])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        best_coloring = normalize(color)

    return best_coloring

