def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert adjacency to bitmask representation
    is_matrix = (len(adj[0]) == n) if n > 0 else False
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)

    def greedy_color(order):
        colors = [-1] * n
        used_colors = [0] * n  # bitmask of colors used by neighbors
        for u in order:
            # Find smallest color not used by neighbors
            c = 0
            while used_colors[u] & (1 << c):
                c += 1
            colors[u] = c
            # Update neighbors' used colors
            mask = bit_adj[u]
            v = 0
            while mask:
                if mask & 1:
                    used_colors[v] |= (1 << c)
                mask >>= 1
                v += 1
        return colors

    def local_search(colors, max_iter=1000):
        current = colors[:]
        n_colors = max(current) + 1 if current else 0
        # Try to reduce colors by recoloring conflicting vertices
        for _ in range(max_iter):
            # Find a conflicting vertex
            conflict = -1
            for u in range(n):
                mask = bit_adj[u]
                v = 0
                while mask:
                    if mask & 1:
                        if current[u] == current[v]:
                            conflict = u
                            break
                    mask >>= 1
                    v += 1
                if conflict != -1:
                    break
            if conflict == -1:
                break  # No conflicts
            u = conflict
            # Try to recolor u with a color that minimizes conflicts
            best_color = current[u]
            best_conflicts = n  # upper bound
            # Try all possible colors up to n_colors (and one extra for potential new color)
            for c in range(n_colors + 1):
                if c == current[u]:
                    continue
                # Check if color c is valid (no neighbor has color c)
                valid = True
                mask = bit_adj[u]
                v = 0
                while mask:
                    if mask & 1:
                        if current[v] == c:
                            valid = False
                            break
                    mask >>= 1
                    v += 1
                if not valid:
                    continue
                # Count conflicts if we recolor u to c (should be zero, but check for safety)
                conflicts = 0
                mask = bit_adj[u]
                v = 0
                while mask:
                    if mask & 1:
                        if current[v] == c:
                            conflicts += 1
                    mask >>= 1
                    v += 1
                if conflicts < best_conflicts:
                    best_conflicts = conflicts
                    best_color = c
            if best_color != current[u]:
                current[u] = best_color
                # If we introduced a new color, update n_colors
                if best_color == n_colors:
                    n_colors += 1
        return current

    best_colors = None
    best_num_colors = float('inf')

    # Run multiple greedy passes with random orders
    for _ in range(20):  # 20 passes
        # Random order
        order = list(range(n))
        random.shuffle(order)
        colors = greedy_color(order)
        # Apply local search to improve
        colors = local_search(colors, max_iter=200)
        num_colors = max(colors) + 1 if colors else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_colors = colors[:]
        # Early exit if we found a coloring with 1 color (only possible for edgeless graph)
        if best_num_colors == 1:
            break

    # Ensure colors are compact (0..k-1)
    if best_colors is not None:
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_colors[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_colors[i] = unique_colors[c]

    return best_colors if best_colors is not None else [0] * n

