    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    for i in range(n):
        if is_matrix:
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
        else:
            for j in adj[i]:
                neighbors[i].add(j)
                bit_adj[i] |= (1 << j)

    # Ensure symmetry
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len(neighbors[x] & uncolored), x))
            # Compute used colors by colored neighbors
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            # Find smallest available color
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
