    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            S = {v}
            # Partition uncolored - {v} into U (not adj to S) and W (adj to S)
            U = uncolored - {v} - neighbors[v]
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len(neighbors[x] & W), -len(neighbors[x] & U), x))
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                nbrs_in_U = neighbors[u] & U
                U -= nbrs_in_U
                W |= nbrs_in_U
            # Assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
