    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].add(i)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # Remove u from current degree bucket
                    buckets[deg[u]].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain swap for (a,b)
    def kempe_swap(color, a, b, v):
        # Find the Kempe chain component containing v for colors a and b
        stack = [v]
        visited = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for u in neighbors[node]:
                if color[u] == a or color[u] == b:
                    if u not in visited:
                        stack.append(u)
        # Swap colors a and b in the component
        for node in visited:
            if color[node] == a:
                color[node] = b
            elif color[node] == b:
                color[node] = a
        return color

    # Try to eliminate the smallest color class via Kempe chains
    def reduce_colors(color):
        # Map color to list of vertices
        color_classes = {}
        for v in range(n):
            c = color[v]
            color_classes.setdefault(c, []).append(v)
        if not color_classes:
            return color
        max_color = max(color_classes.keys())
        # Try to eliminate colors from highest downwards
        for target in range(max_color, 0, -1):
            if target not in color_classes:
                continue
            verts = color_classes[target][:]
            # Try to recolor each vertex in this class
            for v in verts:
                if color[v] != target:  # might have been recolored
                    continue
