                            # Actually, after swap, v's color becomes c if it was target, or target if it was c
                            # We want v to be color c, so if it was target, after swap it's c -> success
                            if color[v] == c:
                                break
                            else:
                                # Revert swap if not helpful
                                color = kempe_swap(color, c, target, v)
                    else:
                        continue  # no break in inner loop
                    break  # break outer loop if Kempe succeeded
                else:
                    # Failed to recolor v, cannot eliminate target color
                    return None
            # After processing all vertices, check if target color is eliminated
            if target not in [color[v] for v in range(n)]:
                # Compact colors: remap higher colors down
                mapping = {}
                next_c = 0
                for orig in sorted(set(color.values())):
                    if orig < target:
                        mapping[orig] = orig
                    elif orig > target:
                        mapping[orig] = next_c
                        next_c += 1
                # target color is removed
                new_color = [mapping[color[v]] for v in range(n)]
                return reduce_colors(new_color)  # recurse
        return color

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass

    # Select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for col in candidates:
        if len(set(col)) < best_colors:
            best_colors = len(set(col))
            best = col

    if best is None:
        # Fallback: greedy by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best = color

    # Apply Kempe chain reduction
    reduced = reduce_colors(best[:])
    if reduced is not None and len(set(reduced)) < len(set(best)):
        best = reduced

    # Validate and ensure consecutive colors
    # Verify proper coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best[u] == best[v]:
                # Conflict, apply greedy fix
                order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
                color = [-1] * n
                for v in order:
                    used = 0
                    for u in neighbors[v]:
                        if color[u] != -1:
                            used |= (1 << color[u])
                    c = 0
                    while used & (1 << c):
                        c += 1
                    color[v] = c
                best = color
                break
        else:
            continue
        break

    # Remap to consecutive colors
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best = [mapping[c] for c in best]

    return best

