                if color[u] == -1:  # only update uncolored neighbors
                    neighbor_colors[u] |= (1 << c)
                    saturation[u] = neighbor_colors[u].bit_count()
        return compact_colors(color)

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # build maximal independent set for current_color
            S = []
            # degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                cnt = 0
                for nb in adj_list[v]:
                    if nb in uncolored:
                        cnt += 1
                deg_uncolored[v] = cnt

            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S.append(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = None
                for u in U:
                    # count neighbors in W
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    deg_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to S
            for v in S:
                color[v] = current_color
            # remove S from uncolored
            uncolored -= set(S)
            current_color += 1
        return compact_colors(color)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        degree = [len(adj_list[i]) for i in range(n)]
        # bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].append(v)
        # pointer to current non-empty bin
        pos = 0
        ordering = []
        # current degree copy
        curr_deg = degree[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bin
            while pos <= max_deg and not bins[pos]:
                pos += 1
            if pos > max_deg:
                break  # should not happen
            v = bins[pos].pop()
            removed[v] = True
            ordering.append(v)
            # update neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    d = curr_deg[nb]
                    if d > 0:
                        # move nb from bin d to d-1
                        bins[d].remove(nb)
                        bins[d-1].append(nb)
                        curr_deg[nb] = d - 1
        # color in reverse order
        color = [-1] * n
        for v in reversed(ordering):
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return compact_colors(color)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # target the smallest color class (highest index)
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                # already compacted?
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
                continue

            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for nb in adj_list[v]:
                    if coloring[nb] != -1:
                        neighbor_colors.add(coloring[nb])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be recolored to c via Kempe chain (target_color, c)
                    # Build the Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_conflict = False
                    for node in component:
                        for nb in adj_list[node]:
                            if coloring[nb] == c and nb not in component:
                                has_conflict = True
                                break
                        if has_conflict:
                            break
                    if not has_conflict:
                        # swap colors in component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                # compact colors after potential elimination
                coloring = compact_colors(coloring)
                k = num_colors(coloring)

        return coloring

    # Run all heuristics with time budget
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    if time.time() - start_time < 0.05:  # 50ms budget
        col = dsatur()
        if is_valid_coloring(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col

    # RLF
    if time.time() - start_time < 0.05:
        col = rlf()
        if is_valid_coloring(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col

    # Smallest-Last
    if time.time() - start_time < 0.05:
        col = smallest_last()
        if is_valid_coloring(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col

    # Fallback: greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = compact_colors(color)

    # Apply Kempe reduction if time permits
    if time.time() - start_time < 0.05 and best_coloring is not None:
        best_coloring = kempe_reduce(best_coloring)

    # Final validation and compact
    if not is_valid_coloring(best_coloring):
        # emergency fallback: greedy
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = compact_colors(color)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        # Adjacency list
        neighbors = [list(row) for row in adj]

    # Precompute bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    def compact_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # degree for tie-breaking
        deg = [len(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # compute saturation: number of distinct colors in neighbors
                neighbor_colors = 0
                for w in neighbors[u]:
                    if colored[w]:
                        neighbor_colors |= (1 << colors[w])
                sat = neighbor_colors.bit_count()
                if sat > max_sat or (sat == max_sat and (deg[u] > max_deg or (deg[u] == max_deg and random.random() < 0.5))):
                    max_sat = sat
                    max_deg = deg[u]
                    v = u
            # assign smallest available color
            used = 0
            for w in neighbors[v]:
                if colored[w]:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
        return compact_colors(colors)

    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build independent set for this color
            # step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda u: sum(1 for w in neighbors[u] if w in uncolored))
            independent_set = {v}
            # partition: U = not adj to any in S, W = adj to at least one in S
            U = {u for u in uncolored if u != v and all(w not in independent_set for w in neighbors[u])}
            W = {u for u in uncolored if u != v and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: sum(1 for w in neighbors[x] if w in W))
                # tie-break: min degree in G[U]
                u = min(U, key=lambda x: (sum(1 for w in neighbors[x] if w in U), random.random()))
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color
            for u in independent_set:
                colors[u] = color
                uncolored.remove(u)
            color += 1
        return compact_colors(colors)

    def smallest_last():
        # degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # we need dynamic degree updates
        deg = degrees[:]
        # bucket sort like
        buckets = [[] for _ in range(n)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = buckets[deg[v]].index(v) if v in buckets[deg[v]] else -1
        min_deg = 0
        for _ in range(n):
            # find first non-empty bucket
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            v = buckets[min_deg].pop()
            pos[v] = -1
            order.append(v)
            # update neighbors
            for w in neighbors[v]:
                if w not in remaining:
                    continue
                # remove w from its bucket
                d = deg[w]
                if pos[w] != -1 and pos[w] < len(buckets[d]):
                    buckets[d].pop(pos[w])
                deg[w] -= 1
                if deg[w] < 0:
                    deg[w] = 0
                buckets[deg[w]].append(w)
                pos[w] = len(buckets[deg[w]]) - 1
            remaining.remove(v)
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for w in neighbors[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    def kempe_reduce(colors):
        if not colors:
            return colors
        # make sure colors are compact
        colors = compact_colors(colors)
        k = max(colors) + 1 if colors else 0
        improved = True
        while improved and k > 0:
            improved = False
            # find smallest color class
            classes = [[] for _ in range(k)]
            for v, c in enumerate(colors):
                classes[c].append(v)
            # find smallest non-empty class
            target = -1
            min_size = n + 1
            for c in range(k):
                if classes[c] and len(classes[c]) < min_size:
                    min_size = len(classes[c])
                    target = c
            if target == -1:
                break
            # try to recolor each vertex in target class
            for v in classes[target][:]:
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for w in neighbors[v]:
                    if colors[w] != -1:
                        neighbor_colors |= (1 << colors[w])
                for c in range(target):
                    if not (neighbor_colors & (1 << c)):
                        # move v to color c
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    # re-compact and restart
                    colors = compact_colors(colors)
                    k = max(colors) + 1 if colors else 0
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # BFS to find Kempe chain of colors {target, c} containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in neighbors[u]:
                            if not visited[w] and (colors[w] == target or colors[w] == c):
                                visited[w] = True
                                queue.append(w)
                    # check if we can swap: after swap, no vertex in component gets color target from outside?
                    # Actually, swapping preserves validity. We want to free color target for v.
                    # After swap, v will have color c. We need to ensure that no neighbor of v has color c after swap?
                    # But swapping only changes colors within component: target<->c.
                    # So after swap, v has color c. Its neighbors: if neighbor has color c and is in component, it becomes target -> ok.
                    # If neighbor has color c and is not in component, then after swap it remains c -> conflict.
                    # So we need that no neighbor of v has color c and is outside the component.
                    conflict = False
                    for w in neighbors[v]:
                        if colors[w] == c and not visited[w]:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for u in component:
                            if colors[u] == target:
                                colors[u] = c
                            elif colors[u] == c:
                                colors[u] = target
                        colors = compact_colors(colors)
                        k = max(colors) + 1 if colors else 0
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # cannot eliminate target color, break
                break
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')
    for func in (dsatur, rlf, smallest_last):
        try:
            cols = func()
            if not is_valid_coloring(cols):
                continue
            k = max(cols) + 1 if cols else 0
            if k < best_k or (k == best_k and best_colors is None):
                best_k = k
                best_colors = cols
        except Exception:
            continue

    if best_colors is None:
        # fallback: greedy by degree order
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for w in neighbors[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe reduction
    best_colors = kempe_reduce(best_colors)
    # Final validation and compact
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            used = 0
            for w in neighbors[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)
    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if adjacency matrix (square, binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        # Saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        # Degree in uncolored subgraph (initially full degree)
        deg_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by deg_uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg_uncolored[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and v > best_v):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in adj_list[w] for w in S)}
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_u = -1
                for u in U:
                    score = len([w for w in adj_list[u] if w in W])
                    deg_u = len([w for w in adj_list[u] if w in U])
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and u < best_u):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last (Matula & Beck)
    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(adj_list[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = deg[i]
            if d < len(buckets):
                buckets[d].append(i)
        # Pointer to current non-empty bucket
        pos = 0
        order = []
        # Copy of degrees for modification
        curr_deg = deg[:]
        removed = [False] * n
        for _ in range(n):
            # Find next non-empty bucket
            while pos < len(buckets) and not buckets[pos]:
                pos += 1
            if pos >= len(buckets):
                break
            v = buckets[pos].pop()
            while removed[v]:
                if not buckets[pos]:
                    break
                v = buckets[pos].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d < len(buckets):
                        buckets[d].remove(u)
                    curr_deg[u] -= 1
                    if curr_deg[u] < len(buckets):
                        buckets[curr_deg[u]].append(u)
                    if curr_deg[u] < pos:
                        pos = curr_deg[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except:
        pass
    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except:
        pass
    # Also try Welsh-Powell (degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        col_wp = greedy_color(order_wp)
        candidates.append(col_wp)
    except:
        pass
    # Try random orders a few times
    for _ in range(5):
        try:
            order_rand = list(range(n))
            random.shuffle(order_rand)
            col_rand = greedy_color(order_rand)
            candidates.append(col_rand)
        except:
            pass

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
