                            neighbor_colors.add(c)
                    # try direct reassignment to a lower color
                    for c in range(target):
                        if c not in neighbor_colors:
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        # after recoloring v, break to restart scan
                        break
                if changed:
                    break
                # if no direct reassignment, try Kempe chains
                for v in verts:
                    neighbor_colors = set()
                    for u in adj_list[v]:
                        c = col[u]
                        if c != -1:
                            neighbor_colors.add(c)
                    # try each lower color
                    for c in range(target):
                        if c in neighbor_colors:
                            continue
                        # check if v is isolated in (target, c) Kempe subgraph
                        # BFS/DFS from v in subgraph induced by colors target and c
                        stack = [v]
                        visited = set()
                        component_target = set()
                        component_c = set()
                        while stack:
                            x = stack.pop()
                            if x in visited:
                                continue
                            visited.add(x)
                            if col[x] == target:
                                component_target.add(x)
                            elif col[x] == c:
                                component_c.add(x)
                            else:
                                continue
                            for y in adj_list[x]:
                                if col[y] == target or col[y] == c:
                                    if y not in visited:
                                        stack.append(y)
                        # if v's component does not contain any vertex of color c, we can swap
                        if not component_c:
                            # swap colors target <-> c in the component
                            for x in component_target:
                                col[x] = c
                            for x in component_c:
                                col[x] = target
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # after each successful reduction, compact colors to be consecutive
            if changed:
                # remap colors to 0..k-1
                unique = {}
                next_color = 0
                for v in range(n):
                    c = col[v]
                    if c not in unique:
                        unique[c] = next_color
                        next_color += 1
                    col[v] = unique[c]
        return col
    # Apply Kempe reduction
    try:
        best_col = kempe_reduction(best_col)
    except Exception:
        pass
    # Final validation and compacting
    if not is_valid_coloring(best_col):
        # last resort: greedy by DSATUR order
        best_col = dsatur()
    # ensure colors are consecutive
    unique = {}
    next_color = 0
    for v in range(n):
        c = best_col[v]
        if c not in unique:
            unique[c] = next_color
            next_color += 1
        best_col[v] = unique[c]
    return best_col

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        neighbors = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        neighbors = [list(lst) for lst in adj]
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Helper: compute number of colors used
    def num_colors(col):
        return max(col) + 1 if col else 0

    # Helper: validate coloring
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    return False
        return True

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = 0
                for nb in neighbors[v]:
                    if nb in uncolored:
                        deg += 1
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # assign smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of neighbors
            for nb in neighbors[v]:
                if nb in uncolored:
                    saturated[nb] |= (1 << c)
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in uncolored subgraph
            deg = {}
            for v in uncolored:
                d = 0
                for nb in neighbors[v]:
                    if nb in uncolored:
                        d += 1
                deg[v] = d
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            while U:
                # select u in U with max neighbors in W
                best_u = -1
                best_score = -1
                best_deg_u = -1
                for u in U:
                    score = 0
                    for nb in neighbors[u]:
                        if nb in W:
                            score += 1
                    deg_u = 0
                    for nb in neighbors[u]:
                        if nb in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and u < best_u):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[v]) for v in range(n)]
        # we need updated degrees as we remove vertices
        deg = degrees[:]
        for _ in range(n):
            # find vertex with minimum degree in remaining
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for nb in neighbors[v]:
                if nb in remaining:
                    deg[nb] -= 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Also try Welsh-Powell (sort by degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    candidates.append(greedy_color(order_wp))

    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select the coloring with the fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_color = col

    # If no valid found (should not happen), fallback to greedy
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = num_colors(best_color)

    # Kempe chain based color reduction
    def eliminate_color_class(col, target_color):
        """Try to eliminate target_color by recoloring its vertices.
        Returns new coloring if successful, else None."""
        # vertices with target_color
        verts = [v for v in range(n) if col[v] == target_color]
        if not verts:
            return col  # already empty
        # Try direct reassignment
        for v in verts:
            used = 0
            for nb in neighbors[v]:
                if col[nb] != target_color:  # only consider colors < target_color? but we allow any
                    used |= (1 << col[nb])
            # find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            if c != target_color:
                # recolor v to c
                new_col = col[:]
                new_col[v] = c
                # after recoloring, we may have duplicated colors, but we will compact later
                return new_col
        # Try Kempe chains for each pair (target_color, c) with c < target_color
        for c in range(target_color):
            # Try to swap along Kempe chains to free target_color for some vertex
            # We'll attempt to find a vertex v in target_color that can be swapped with c
            # via a Kempe chain that does not pull other target_color vertices into c
            # Build components of the subgraph induced by colors target_color and c
            visited = [False] * n
            for v in verts:
                if not visited[v]:
                    # BFS to get component
                        stack = [v]
                        visited[v] = True
                        comp = []
                        has_c = False
                        while stack:
                            node = stack.pop()
                            comp.append(node)
                            if col[node] == c:
                                has_c = True
                            for nb in neighbors[node]:
                                if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                    visited[nb] = True
                                    stack.append(nb)
                        # If component does not contain color c, we can swap
                        if not has_c:
                            new_col = col[:]
                            for node in comp:
                                if new_col[node] == target_color:
                                    new_col[node] = c
                                else:
                                    new_col[node] = target_color
                            return new_col
        return None

    # Iteratively try to reduce colors
    current = best_color[:]
    changed = True
    while changed:
        changed = False
        k = num_colors(current)
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            new_col = eliminate_color_class(current, target_color)
            if new_col is not None:
                # compact colors: remap to 0..k'-1
                mapping = {}
                next_color = 0
                for v in range(n):
                    col_val = new_col[v]
                    if col_val not in mapping:
                        mapping[col_val] = next_color
                        next_color += 1
                current = [mapping[col_val] for col_val in new_col]
                changed = True
                break  # restart from highest color after a successful elimination
        # loop continues if changed

    # Final validation and ensure consecutive colors
    if not is_valid(current):
        # fallback to greedy
        current = greedy_color(list(range(n)))
    # remap to consecutive
    mapping = {}
    next_color = 0
    for v in range(n):
        col_val = current[v]
        if col_val not in mapping:
            mapping[col_val] = next_color
            next_color += 1
    current = [mapping[col_val] for col_val in current]

    return current

