import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if entries are 0/1 integers
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor bitmasks and neighbor lists
    bit_adj = [0] * n
    neighbors = [None] * n
    if is_matrix:
        for u in range(n):
            mask = 0
            for v in range(n):
                if adj[u][v]:
                    mask |= (1 << v)
            bit_adj[u] = mask
            neighbors[u] = [v for v in range(n) if adj[u][v]]
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                mask |= (1 << v)
            bit_adj[u] = mask
            neighbors[u] = adj[u][:]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[u]) for u in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best = u
            u = best
            uncolored.remove(u)
            # assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            # update neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    sat[v] |= (1 << c)
                    uncolored_deg[v] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in uncolored subgraph
            deg_in_uncolored = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in neighbors[u]:
                    if v in uncolored:
                        deg_in_uncolored[u] += 1
            # start with vertex of max degree
            v = max(uncolored, key=lambda u: deg_in_uncolored[u])
            S = {v}
            # U: vertices not adjacent to S
            U = {u for u in uncolored if u != v and v not in neighbors[u]}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u != v and v in neighbors[u]}
            while U:
                # select u in U with max neighbors in W, then min degree in U
                best_u = -1
                best_score = -1
                best_deg = -1
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_count += 1
                    # degree in U
                    u_deg = 0
                    for w in neighbors[u]:
                        if w in U:
                            u_deg += 1
                    if w_count > best_score or (w_count == best_score and u_deg < best_deg) or (w_count == best_score and u_deg == best_deg and random.random() < 0.5):
                        best_score = w_count
                        best_deg = u_deg
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(neighbors[u]) for u in range(n)]
        # buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            d = deg[u]
            if d <= max_deg:
                buckets[d].append(u)
        # pointer to current min degree
        min_deg = 0
        order = []
        # copy of degrees for updating
        curr_deg = deg[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            u = buckets[min_deg].pop()
            removed[u] = True
            order.append(u)
            for v in neighbors[u]:
                if not removed[v]:
                    d = curr_deg[v]
                    if d <= max_deg:
                        # remove v from bucket d
                        if v in buckets[d]:
                            buckets[d].remove(v)
                    curr_deg[v] -= 1
                    d_new = curr_deg[v]
                    if d_new <= max_deg:
                        buckets[d_new].append(v)
                    if d_new < min_deg:
                        min_deg = d_new
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    start = time.time()
    # DSATUR
    if time.time() - start < 0.04:  # leave buffer
        col = dsatur()
        if is_valid(col):
            candidates.append(col)
    # RLF
    if time.time() - start < 0.04:
        col = rlf()
        if is_valid(col):
            candidates.append(col)
    # Smallest-Last
    if time.time() - start < 0.04:
        col = smallest_last()
        if is_valid(col):
            candidates.append(col)

    # If no candidate (should not happen), fallback to greedy by index
    if not candidates:
        col = greedy_color(list(range(n)))
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    k = count_colors(best_coloring)

    # Iterative Kempe chain color reduction
    improved = True
    while improved and k > 1 and time.time() - start < 0.045:
        improved = False
        # Build color classes
        classes = [[] for _ in range(k)]
        for u in range(n):
            classes[best_coloring[u]].append(u)
        # Target smallest color class (last color)
        target = k - 1
        if not classes[target]:
            # should not happen, but skip
            break
        # Try to recolor each vertex in target class
        for v in classes[target][:]:
            # Try direct reassignment to a lower color
            used_by_neighbors = 0
            for u in neighbors[v]:
                c = best_coloring[u]
                if c != -1:
                    used_by_neighbors |= (1 << c)
            for c in range(target):
                if not (used_by_neighbors & (1 << c)):
                    # move v to color c
                    best_coloring[v] = c
                    classes[target].remove(v)
                    classes[c].append(v)
                    improved = True
                    break
            if improved:
                break
            # Try Kempe chains with each lower color
            for c in range(target):
                # BFS to find Kempe chain of colors c and target starting from v
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                while queue:
                    u = queue.popleft()
                    component.append(u)
                    for w in neighbors[u]:
                        if not visited[w]:
                            col_w = best_coloring[w]
                            if col_w == c or col_w == target:
                                visited[w] = True
                                queue.append(w)
                # Check if any neighbor of v in the component has color c? Actually, we want to see if we can swap
                # After swap, v would get color c. Check if any neighbor of v has color c (which would cause conflict)
                conflict = False
                for w in neighbors[v]:
                    if best_coloring[w] == c:
                        # after swap, w would become target, so check if w is in component
                        if w in component:
                            conflict = True
                            break
                if not conflict:
                    # perform swap: c <-> target in component
                    for u in component:
                        if best_coloring[u] == c:
                            best_coloring[u] = target
                        elif best_coloring[u] == target:
                            best_coloring[u] = c
                    # update classes
                    classes[target].remove(v)
                    classes[c].append(v)
                    improved = True
                    break
            if improved:
                break
        if improved:
            # compact colors: reindex to 0..k-1
            # but we may have holes; rebuild mapping
            used_colors = set(best_coloring)
            mapping = {old: new for new, old in enumerate(sorted(used_colors))]
            best_coloring = [mapping[c] for c in best_coloring]
            k = len(used_colors)
        else:
            break

    # Final validation and compacting
    if not is_valid(best_coloring):
        # fallback to greedy
        best_coloring = greedy_color(list(range(n)))
    # ensure colors are 0..k-1 consecutive
    used = set(best_coloring)
    mapping = {old: new for new, old in enumerate(sorted(used))]
    best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

