            v = best_v
            # compute available colors: smallest not in neighborhood
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and uncolored degree for neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # update saturation: if color c is new in neighborhood
                    if not (colored_mask[u] & (1 << c)):
                        colored_mask[u] |= (1 << c)
                        saturation[u] += 1
                    uncolored_deg[u] -= 1
        return coloring

    # RLF: Recursive Largest First (independent set extraction)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any((1 << u) & bit_adj[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_U < best_uncolored_deg):
                        best_score = score
                        best_uncolored_deg = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        ordering = []
        # copy of degrees
        deg = [len(neighbors[i]) for i in range(n)]
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min non-empty bucket
        min_deg = 0
        for _ in range(n):
            # find min degree vertex in remaining
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            while v not in remaining:
                if not buckets[min_deg]:
                    min_deg += 1
                    while min_deg <= max_deg and not buckets[min_deg]:
                        min_deg += 1
                    if min_deg > max_deg:
                        break
                    v = buckets[min_deg].pop()
                else:
                    v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            ordering.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    # move u from bucket d to d-1
                    if d <= max_deg:
                        buckets[d].remove(u)  # O(n) but n <= 100, acceptable
                    if deg[u] >= 0:
                        if deg[u] >= len(buckets):
                            buckets.extend([[] for _ in range(deg[u] - len(buckets) + 1)])
                        buckets[deg[u]].append(u)
        # color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(ordering):
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make coloring compact first
        coloring = compact_coloring(coloring[:])
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest down
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already compacted?
                coloring = compact_coloring(coloring)
                k = num_colors(coloring)
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        neighbor_colors |= (1 << coloring[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c from direct reassignment above, skip
                    if coloring[v] == c:
                        continue
                    # find the Kempe chain component of v in colors {c, target_color}
                    # BFS/DFS to get component
                    stack = [v]
                    visited = set()
                    comp_color = coloring[v]  # should be target_color
                    other_color = c
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == comp_color or coloring[node] == other_color:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (coloring[nb] == comp_color or coloring[nb] == other_color):
                                    stack.append(nb)
                    # check if any neighbor of component has color other_color
                    # if not, we can swap colors in component
                    has_other_color_neighbor = False
                    for node in component:
                        for nb in neighbors[node]:
                            if coloring[nb] == other_color and nb not in component:
                                has_other_color_neighbor = True
                                break
                        if has_other_color_neighbor:
                            break
                    if not has_other_color_neighbor:
                        # swap colors in component
                        for node in component:
                            if coloring[node] == comp_color:
                                coloring[node] = other_color
                            else:
                                coloring[node] = comp_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors
                coloring = compact_coloring(coloring)
                k = num_colors(coloring)
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if coloring[j] != -1:
                    used |= (1 << coloring[j])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Apply Kempe reduction to each candidate and pick best
    best_coloring = None
    best_k = float('inf')
    for cand in candidates:
        reduced = kempe_reduce(cand[:])
        if not is_valid(reduced):
            # fallback: ensure validity by greedy repair
            reduced = [-1] * n
            for i in range(n):
                used = 0
                for j in neighbors[i]:
                    if reduced[j] != -1:
                        used |= (1 << reduced[j])
                c = 0
                while used & (1 << c):
                    c += 1
                reduced[i] = c
        reduced = compact_coloring(reduced)
        k = num_colors(reduced)
        if k < best_k or (k == best_k and best_coloring is None):
            best_k = k
            best_coloring = reduced

    return best_coloring

