    def normalize_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmask for efficiency
        neighbor_colors = [0] * n

        # Order by degree descending for initial tie-breaking in saturation
        order = list(range(n))
        order.sort(key=lambda x: (-deg[x], x))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in order:
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = deg[u]
                    if sat_u > max_sat or (sat_u == max_sat and (deg_u > max_deg or (deg_u == max_deg and u < v))):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # If this color is new in u's neighborhood
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1

        return normalize_colors(coloring)

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0

        while True:
            # Find uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    # count uncolored neighbors
                    d = 0
                    for w in adj_list[u]:
                        if not colored[w]:
                            d += 1
                    if d > max_deg:
                        max_deg = d
                        v = u
            if v == -1:
                break  # all colored

            # Build independent set for this color
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if not colored[u]:
                    if v == u or (bit_adj[v] >> u) & 1:
                        W.add(u)
                    else:
                        U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen

                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1

        return normalize_colors(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # removal order
        deg_copy = deg[:]  # current degree in remaining graph

        # Use bucket sort for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg_copy[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # extend buckets if needed (should not happen as deg_copy <= max_deg)
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(v)

        # Pointer to current min non-empty bucket
        min_bucket = 0

        for _ in range(n):
            # Find first non-empty bucket
            while min_bucket < len(buckets) and not buckets[min_bucket]:
                min_bucket += 1
            if min_bucket >= len(buckets):
                break  # should not happen
            v = buckets[min_bucket].pop()
            if v not in remaining:
                # already removed, skip
