            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_d = deg_copy[u]
                    new_d = old_d - 1
                    deg_copy[u] = new_d
                    # remove u from old bucket
                    if old_d < len(buckets) and u in buckets[old_d]:
                        buckets[old_d].remove(u)
                    # add to new bucket
                    if new_d < len(buckets):
                        buckets[new_d].append(u)
                    else:
                        while len(buckets) <= new_d:
                            buckets.append([])
                        buckets[new_d].append(u)
                    # update min_bucket if needed
                    if new_d < min_bucket:
                        min_bucket = new_d

        # Color in reverse order using First-Fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
