            # Find the current number of colors
            max_color = max(current) if current else -1
            if max_color < 0:
                return current
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                # Collect vertices with target_color
                vertices_target = [v for v in range(n) if current[v] == target_color]
                if not vertices_target:
                    # This color already eliminated, continue
                    continue
                # Try to recolor each vertex in this class
                eliminated = True
                for v in vertices_target:
