                        # and no neighbor of v has color target_color (because they become c).
                        # But wait: if a neighbor has color target_color, after swap it becomes c -> conflict.
                        # So we need that v has no neighbor with color c or target_color? 
                        # That can't be right because then we could have reassigned directly.
                        # Correct condition: In the Kempe chain (target_color, c) containing v, 
                        # if there is no vertex in the chain that is adjacent to v and has color c, 
                        # then swapping the chain will not introduce a conflict? 
                        # Actually, standard condition: we can swap the chain if it does not contain 
                        # any neighbor of v that has color c. Because after swap, those neighbors 
                        # would remain c (if they were c) or become c (if they were target_color) -> conflict.
                        # So we need that the chain does NOT contain any vertex that is a neighbor of v 
                        # and has color c. But note: v itself is in the chain and has target_color, not c.
                        # So we do BFS from v on the subgraph induced by vertices of color target_color or c.
                        # If we encounter a vertex u that is a neighbor of v and has color c, then we cannot swap.
                        # Otherwise, we can swap the entire chain.
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        safe = True
                        while queue:
                            x = queue.popleft()
                            # If x is a neighbor of v and has color c, then unsafe
                            if x != v and (bit_adj[v] >> x) & 1 and current[x] == c:
