                    elif deg == max_deg:
                        best.append(u)
                candidates = best
            # Final tie-break: random
            u = random.choice(candidates)
            # Find smallest color not used by neighbors
            used = colored_neighbors[u]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
            uncolored.remove(u)
            # Update saturation and colored_neighbors for uncolored neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    # If this is a new color for v's neighbors, increase sat
                    if not (colored_neighbors[v] & (1 << c)):
                        sat[v] += 1
                        colored_neighbors[v] |= (1 << c)
        return coloring

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color_idx = 0
        uncolored = set(range(n))
        while uncolored:
            # Build maximal independent set for color_idx
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex with max degree in G[uncolored]
            u = max(uncolored, key=lambda x: sum(1 for v in neighbors[x] if v in uncolored))
            S = {u}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible for this color)
            W = set(neighbors[u]) & uncolored
            U = uncolored - {u} - W
            while U:
                # Select u* in U with max |N(u*) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for uu in U:
                    w_neighbors = sum(1 for v in neighbors[uu] if v in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = [uu]
                        min_deg_in_U = sum(1 for v in neighbors[uu] if v in U)
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = sum(1 for v in neighbors[uu] if v in U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = [uu]
                        elif deg_in_U == min_deg_in_U:
                            best_u.append(uu)
                if best_u is None:
                    break
                uu = random.choice(best_u)
                S.add(uu)
                U.remove(uu)
                # Move neighbors of uu that are in U to W
                for v in neighbors[uu]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color_idx to all in S
            for uu in S:
                coloring[uu] = color_idx
            uncolored -= S
            color_idx += 1
        return coloring

    # Strategy 4: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for i in range(n):
            if deg[i] < len(buckets):
                buckets[deg[i]].add(i)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break
            # Take a vertex from bucket[ptr]
            u = buckets[ptr].pop()
            order.append(u)
            remaining.remove(u)
            # Update degrees of neighbors
            for v in neighbors[u]:
                if v in remaining:
                    d = deg[v]
                    if d < len(buckets):
                        buckets[d].discard(v)
                    deg[v] -= 1
                    if deg[v] < len(buckets):
                        buckets[deg[v]].add(v)
        # Color in reverse order
        coloring = greedy_color(order[::-1])
        return coloring

    # Generate candidate colorings
    candidates = []
    try:
        c1 = bfs_bipartite_plus()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = dsatur()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = rlf()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    try:
        c4 = smallest_last()
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # If no candidates, fallback to greedy on natural order
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Iterative Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal n, neighbors
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Try to eliminate the largest color index (we'll compact later)
            # Instead, try to reduce the number of colors by eliminating one color class
            # We'll attempt to remove color k-1 by recoloring its vertices
            # But we don't know k yet, so we'll try to see if we can reduce the max color
            max_color = max(col) if col else -1
            if max_color <= 0:
                break
            # Try to eliminate color max_color
            # Get vertices with this color
            verts = [i for i in range(n) if col[i] == max_color]
            if not verts:
                # Already compacted?
                break
            # Try to recolor each vertex in verts to a lower color if possible
            made_progress = False
            for v in verts:
                # Try direct reassignment to a lower color
                for c in range(max_color):
                    conflict = False
                    for u in neighbors[v]:
                        if col[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        col[v] = c
                        changed = True
                        made_progress = True
                        break
                if made_progress:
                    break
            if made_progress:
                continue
            # If no direct reassignment, try Kempe chains
            for v in verts:
                for c in range(max_color):
                    # Check if we can swap colors along a (c, max_color) Kempe chain
                    # starting from v to free color c for v
                    # We'll do BFS to find the Kempe chain component containing v
                    # in the subgraph induced by colors c and max_color
                    from collections import deque as Queue
                    visited = [False] * n
                    queue = Queue()
                    # Only traverse if neighbor has color c or max_color
                    if col[v] != max_color:
                        continue  # should not happen
                    queue.append(v)
                    visited[v] = True
                    component = []
                    while queue:
                        uu = queue.popleft()
                        component.append(uu)
                        for w in neighbors[uu]:
                            if not visited[w] and (col[w] == c or col[w] == max_color):
                                visited[w] = True
                                queue.append(w)
                    # Check if any neighbor of v has color c (which would cause conflict after swap)
                    has_c_neighbor = False
                    for w in neighbors[v]:
                        if col[w] == c:
                            has_c_neighbor = True
                            break
                    # If no neighbor of v has color c, we can swap the component
                    if not has_c_neighbor:
                        # Swap colors c and max_color in the component
                        for uu in component:
                            if col[uu] == c:
                                col[uu] = max_color
                            else:
                                col[uu] = c
                        changed = True
                        made_progress = True
                        break
                if made_progress:
                    break
            # If we made progress, we'll try again; else break
            if not made_progress:
                break
        # Compact colors: map used colors to 0..k-1
        used = set(col)
        if not used:
            return [0] * n
        mapping = {c: i for i, c in enumerate(sorted(used))]
        return [mapping[c] for c in col]

    # Apply Kempe reduction
    best = kempe_reduce(best)
    # Final validation (should be valid)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            if is_matrix:
                for val in adj[i]:
                    if val not in (0, 1):
                        is_matrix = False
                        break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Ensure symmetry for undirected graph
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].append(i)
                bit_adj[j] |= (1 << i)

    # Helper: greedy coloring given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Order 1: DSATUR
    try:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([nbr for nbr in neighbors[x] if nbr in uncolored])))
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # Order 2: RLF (Recursive Largest First)
    try:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([nbr for nbr in neighbors[x] if nbr in uncolored]))
                S.append(v)
                # U: vertices not adjacent to any in S (eligible)
                # W: vertices adjacent to at least one in S (ineligible)
                U = {u for u in uncolored if u not in S and all(u not in neighbors[s] for s in S)}
                W = {u for u in uncolored if u not in S and u not in U}
                while U:
                    # Select u in U with max neighbors in W, tie-break by min degree in U
                    u_star = max(U, key=lambda x: (len([nbr for nbr in neighbors[x] if nbr in W]), -len([nbr for nbr in neighbors[x] if nbr in U])))
                    S.append(u_star)
                    U.remove(u_star)
                    # Move neighbors of u_star in U to W
                    for nbr in neighbors[u_star]:
                        if nbr in U:
                            U.remove(nbr)
                            W.add(nbr)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # Order 3: Smallest-Last (Matula-Beck) ordering
    try:
        # Compute degeneracy ordering (smallest-last)
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll simulate peeling by repeatedly removing min degree vertex
        temp_degree = degree[:]
        remaining_set = set(range(n))
        for _ in range(n):
            # Find vertex with min degree in remaining_set
            v = min(remaining_set, key=lambda x: temp_degree[x])
            order.append(v)
            remaining_set.remove(v)
            for u in neighbors[v]:
                if u in remaining_set:
                    temp_degree[u] -= 1
        # Color in reverse order
        color = greedy_color(order[::-1])
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # Order 4: Welsh-Powell (sort by degree descending)
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        color = greedy_color(order)
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # Order 5: Random walk diffusion for spectral-like clustering
    try:
        # Compute a diffusion vector using random walk (approximate Fiedler vector)
        # Use multiple random starts and average to get stable clustering
        vec = [0.0] * n
        num_walks = 10
        walk_length = 20
        for _ in range(num_walks):
            start = random.randrange(n)
            prob = [0.0] * n
            prob[start] = 1.0
            for step in range(walk_length):
                new_prob = [0.0] * n
                for v in range(n):
                    if prob[v] > 0:
                        deg = len(neighbors[v])
                        if deg > 0:
                            for u in neighbors[v]:
                                new_prob[u] += prob[v] / deg
                prob = new_prob
            for i in range(n):
                vec[i] += prob[i]
        # Normalize
        avg = sum(vec) / n
        vec = [v - avg for v in vec]
        # Order by the diffusion vector value
        order = sorted(range(n), key=lambda x: vec[x])
        color = greedy_color(order)
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # If no valid coloring found (should not happen), fall back to greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        if not is_valid(best_coloring):
            # Force validation by adjusting (should be rare)
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and best_coloring[u] == best_coloring[v]:
                        # Simple conflict resolution: increment one color
                        best_coloring[v] = max(best_coloring) + 1

    # Compact colors to 0..k-1
    unique_colors = sorted(set(best_coloring))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    compacted = [mapping[c] for c in best_coloring]

    # Final validation
    assert is_valid(compacted), "Invalid coloring produced"
    return compacted

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list and bitmask representation
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [list(row) for row in adj]
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        colored = [False] * n
        saturation = [0] * n
        degree = [len(neighbors[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = [i for i in range(n) if not colored[i]]
            if not candidates:
                break
            max_sat = max(saturation[i] for i in candidates)
            max_sat_vertices = [i for i in candidates if saturation[i] == max_sat]
            if len(max_sat_vertices) > 1:
                max_deg = max(degree[i] for i in max_sat_vertices)
                max_deg_vertices = [i for i in max_sat_vertices if degree[i] == max_deg]
                v = random.choice(max_deg_vertices)
            else:
                v = max_sat_vertices[0]

            # Find smallest available color
            used = 0
            for u in neighbors[v]:
                if colored[u]:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u] += 1
        return normalize(coloring)

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
                S.append(v)
                uncolored.remove(v)
                # W: vertices adjacent to S (ineligible)
                W = set()
                for u in S:
                    for w in neighbors[u]:
                        if w in uncolored:
                            W.add(w)
                # U: uncolored and not adjacent to S (eligible)
                U = uncolored - W
                while U:
                    # Select u in U with max neighbors in W
                    best_u = None
                    max_w_neighbors = -1
                    min_deg_in_U = float('inf')
                    for u in U:
                        w_count = sum(1 for w in neighbors[u] if w in W)
                        if w_count > max_w_neighbors or (w_count == max_w_neighbors and sum(1 for x in neighbors[u] if x in U) < min_deg_in_U):
                            max_w_neighbors = w_count
                            min_deg_in_U = sum(1 for x in neighbors[u] if x in U)
                            best_u = u
                    if best_u is None:
                        break
                    S.append(best_u)
                    uncolored.remove(best_u)
                    # Update W and U: add neighbors of best_u in U to W, remove from U
                    for w in neighbors[best_u]:
                        if w in U:
                            W.add(w)
                            U.remove(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        temp_degree = degree[:]
        remaining_set = set(range(n))
        for _ in range(n):
            # Find vertex of minimum degree in remaining
            v = min(remaining_set, key=lambda x: temp_degree[x])
            order.append(v)
            remaining_set.remove(v)
            for u in neighbors[v]:
                if u in remaining_set:
                    temp_degree[u] -= 1
        # Color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already empty, compact
                mapping = {c: c for c in range(k)}
                if target_color in mapping:
                    del mapping[target_color]
                # Shift down higher colors
                for c in range(target_color + 1, k):
                    mapping[c] = c - 1
                coloring = [mapping[c] for c in coloring]
                k -= 1
                changed = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used_by_neighbors |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor directly
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is in a Kempe chain of (target_color, c) that does not include any other target_color vertex?
                    # We'll try to swap the component containing v if it frees color c for v
                    # Build the Kempe chain component for colors {target_color, c} containing v
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for y in neighbors[x]:
                            if y not in comp and (coloring[y] == target_color or coloring[y] == c):
                                comp.add(y)
                                queue.append(y)
                    # Check if any neighbor of v has color c (if so, swapping might not free c for v)
                    has_c_neighbor = any(coloring[u] == c for u in neighbors[v])
                    if not has_c_neighbor:
                        # Swap colors in the component
                        for x in comp:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            elif coloring[x] == c:
                                coloring[x] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # Compact colors
                mapping = {}
                next_c = 0
                for c in range(k):
                    if any(coloring[v] == c for v in range(n)):
                        mapping[c] = next_c
                        next_c += 1
                coloring = [mapping[c] for c in coloring]
                k = next_c
        return normalize(coloring)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no valid candidate, fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(normalize(coloring))

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and normalization
    if not is_valid(best):
        # Last resort: greedy
        coloring = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best = normalize(coloring)
    return best

