import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list if needed
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = [list(neighbors) for neighbors in adj]

    # Ensure symmetry and no self-loops
    for i in range(n):
        adj_list[i] = [j for j in adj_list[i] if j != i]
        for j in adj_list[i]:
            if i not in adj_list[j]:
                adj_list[j].append(i)

    # Precompute degrees
    degrees = [len(adj_list[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_coloring(order):
        coloring = [-1] * n
        for u in order:
            used = [False] * (num_colors(coloring) + 1)  # +1 for potential new color
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used[coloring[v]] = True
            for c in range(len(used)):
                if not used[c]:
                    coloring[u] = c
                    break
        return coloring

    # Helper: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-degrees[x], x))
        return greedy_coloring(order)

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        deg = degrees[:]
        order = []
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
            else:
                # Extend buckets if needed (shouldn't happen with proper deg)
                buckets.extend([[] for _ in range(deg[v] - len(buckets) + 1)])
                buckets[deg[v]].append(v)

        for _ in range(n):
            # Find non-empty bucket with smallest degree
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    # Move u to lower bucket
                    if old_deg < len(buckets) and u in buckets[old_deg]:
                        buckets[old_deg].remove(u)
                    if deg[u] < len(buckets):
                        buckets[deg[u]].append(u)
                    else:
                        buckets.extend([[] for _ in range(deg[u] - len(buckets) + 1)])
                        buckets[deg[u]].append(u)
        # Reverse to get smallest-last order
        order.reverse()
        return greedy_coloring(order)

    # Helper: DSATUR
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor sets for efficiency
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                # degree in uncolored subgraph
                deg_uncolored = sum(1 for u in adj_list[v] if u in uncolored)
                if sat > best_sat or (sat == best_sat and deg_uncolored > best_deg) or \
                   (sat == best_sat and deg_uncolored == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg_uncolored
                    best_v = v
            v = best_v
            # Find smallest available color
            used = [False] * (n + 1)  # safe upper bound
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < len(used) and used[c]:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return coloring

    # Helper: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(w in adj_list[u] for w in independent_set):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in G[U]
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return coloring

    # Generate candidate colorings
    candidates = []
    start_time = time.time()

    # Welsh-Powell
    if time.time() - start_time < 0.04:  # 40ms budget for heuristics
        candidates.append(welsh_powell())
    # Smallest-Last
    if time.time() - start_time < 0.04:
        candidates.append(smallest_last())
    # DSATUR
    if time.time() - start_time < 0.04:
        candidates.append(dsatur())
    # RLF
    if time.time() - start_time < 0.04:
        candidates.append(rlf())

    # If no candidates (shouldn't happen), fallback to trivial
    if not candidates:
        candidates.append([0] * n)

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)
    best_k = num_colors(best_coloring)

    # If already optimal (lower bound: max clique size, but we use greedy bound)
    # Try to reduce colors via Kempe chain swaps and recoloring
    def try_reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex to a lower color if possible
            made_change = False
            for v in verts:
                used = [False] * (target_color + 1)  # only need to check colors < target_color
                for u in adj_list[v]:
                    if coloring[u] < target_color:
                        used[coloring[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        coloring[v] = c
                        made_change = True
                        break
            if not made_change:
                # Try Kempe chains for swapping
                for v in verts:
                    for c in range(target_color):
                        # Check if v can be swapped with color c via Kempe chain
                        # Build (target_color, c)-component containing v
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if coloring[node] == target_color or coloring[node] == c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if nb not in visited and (coloring[nb] == target_color or coloring[nb] == c):
                                        stack.append(nb)
                        # Check if any neighbor of v has color c (would cause conflict if swapped)
                        conflict = False
                        for nb in adj_list[v]:
                            if coloring[nb] == c and nb not in component:
                                conflict = True
                                break
                        if not conflict:
                            # Swap colors in component
                            for node in component:
                                if coloring[node] == target_color:
                                    coloring[node] = c
                                elif coloring[node] == c:
                                    coloring[node] = target_color
                            made_change = True
                            break
                    if made_change:
                        break
            if made_change:
                # Break and restart from highest color since coloring changed
                return try_reduce_colors(coloring)
        # Compact colors: remap to 0..k'-1
        color_map = {}
        next_color = 0
        for v in range(n):
            if coloring[v] not in color_map:
                color_map[coloring[v]] = next_color
                next_color += 1
        for v in range(n):
            coloring[v] = color_map[coloring[v]]
        return coloring

    # Apply color reduction with time check
    if time.time() - start_time < 0.045:  # leave 5ms for reduction
        best_coloring = try_reduce_colors(best_coloring[:])  # work on copy

    # Final validation and compacting
    if not is_valid(best_coloring):
        # Fallback to greedy on random order if invalid
        order = list(range(n))
        random.shuffle(order)
        best_coloring = greedy_coloring(order)

    # Ensure colors are consecutive starting from 0
    used_colors = set(best_coloring)
    color_map = {old: new for new, old in enumerate(sorted(used_colors)))
    best_coloring = [color_map[c] for c in best_coloring]

    return best_coloring

