    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return len(set(coloring)) if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # Precompute neighbor masks for saturation
        neighbor_mask = bit_adj[:]
        # Saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # Degree in uncolored subgraph
        deg_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg_uncolored[v]
                if s > best_sat or (s == best_sat and d > best_deg) or \
                   (s == best_sat and d == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1
            # Pick start vertex: max degree in uncolored
            start = max(uncolored, key=lambda v: deg_uncolored[v])
            S = {start}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {start}
            # Remove neighbors of start from U
            for u in adj_list[start]:
                if u in U:
                    U.remove(u)
            W = set()
            for u in adj_list[start]:
                if u in uncolored and u not in S:
                    W.add(u)
            # Grow independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_u = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_u += 1
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and (best_u == -1 or random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        if nb in uncolored and nb not in S:
                            W.add(nb)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(adj_list[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        order = []
        # Current degree (will be updated)
        curr_deg = deg[:]
        removed = [False] * n
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if removed[v]:
                # Find another in this bucket
                while buckets[ptr] and removed[buckets[ptr][-1]]:
                    buckets[ptr].pop()
                if not buckets[ptr]:
                    ptr += 1
                    while ptr <= max_deg and not buckets[ptr]:
                        ptr += 1
                    if ptr > max_deg:
                        break
                    v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    # Remove u from bucket d
                    if buckets[d] and buckets[d][-1] == u:
                        buckets[d].pop()
                    else:
                        # Linear search (small n)
                        try:
                            idx = buckets[d].index(u)
                            buckets[d].pop(idx)
                        except ValueError:
                            pass
                    curr_deg[u] -= 1
                    if curr_deg[u] >= 0:
                        buckets[curr_deg[u]].append(u)
                    else:
                        curr_deg[u] = 0  # shouldn't happen
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except:
        pass
    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except:
        pass
    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid(col3):
            candidates.append(col3)
    except:
        pass
    # Fallback: greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        col4 = greedy_color(order)
        if is_valid(col4):
            candidates.append(col4)
    except:
        pass
    # Fallback: greedy by index
    try:
        col5 = greedy_color(list(range(n)))
        if is_valid(col5):
            candidates.append(col5)
    except:
        pass

    # Select best candidate (fewest colors)
    if not candidates:
        # Last resort: assign all distinct colors
        best_coloring = list(range(n))
    else:
        best_coloring = min(candidates, key=count_colors)

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color
        n = len(coloring)
        # Build color classes
        color_classes = [[] for _ in range(max(coloring) + 1) if coloring]
        if not color_classes:
            return coloring
        max_color = len(color_classes) - 1
        if target_color < 0 or target_color > max_color:
            return coloring
        # Ensure we have enough classes
        while len(color_classes) <= max_color:
            color_classes.append([])
        for v in range(n):
            c = coloring[v]
            if c < len(color_classes):
                color_classes[c].append(v)

        # Try to recolor each vertex in target_color class
        for v in color_classes[target_color]:
            used_by_neighbors = 0
            for u in adj_list[v]:
                cu = coloring[u]
                if cu < len(color_classes):  # always true
                    used_by_neighbors |= (1 << cu)
            # Try direct reassignment to a lower color
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
                    # Move v to color c
                    coloring[v] = c
                    color_classes[target_color].remove(v)
                    if c < len(color_classes):
                        color_classes[c].append(v)
                    # Successfully recolored, break to next vertex
                    break
            else:
                # Direct reassignment failed, try Kempe chains
                for c in range(target_color):
                    # Check if v and any vertex of color c are in different Kempe chains
                    # Build component of colors {c, target_color} containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb]:
                                col_nb = coloring[nb]
                                if col_nb == c or col_nb == target_color:
                                    visited[nb] = True
                                    queue.append(nb)
                    # Check if any vertex of color c is NOT in this component
                    has_external = False
                    for u in color_classes[c]:
                        if not visited[u]:
                            has_external = True
                            break
                    if has_external:
                        # Swap colors c and target_color in component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        # Update color classes: swap roles
                        # Rebuild color_classes for simplicity (small n)
                        color_classes = [[] for _ in range(max(coloring) + 1) if coloring]
                        if not color_classes:
                            color_classes = [[]]
                        for node in range(n):
                            col_node = coloring[node]
                            if col_node >= len(color_classes):
                                # Extend if needed
                                while len(color_classes) <= col_node:
                                    color_classes.append([])
                            color_classes[col_node].append(node)
                        # Successfully recolored v (now color c)
                        break
                else:
                    # Could not recolor v, fail
                    return None
        # After processing, check if target_color class is empty
        if not color_classes[target_color]:
            # Compact colors: shift down all colors > target_color
            new_coloring = [-1] * n
            for v in range(n):
                c = coloring[v]
                if c > target_color:
                    new_coloring[v] = c - 1
                elif c == target_color:
                    # Should not happen
                    new_coloring[v] = c
                else:
                    new_coloring[v] = c
            return new_coloring
        else:
            return coloring

    # Apply color reduction iteratively
    current = best_coloring[:]
    improved = True
    while improved and max(current) >= 0:
        improved = False
        # Try to eliminate the highest color class first (often smallest)
        max_color = max(current) if current else -1
        for target in range(max_color, -1, -1):
            new_coloring = eliminate_color_class(current[:], target)
            if new_coloring is not None and new_coloring != current:
                if is_valid(new_coloring):
                    current = new_coloring
                    improved = True
                    break  # Restart from new max color
        # If no improvement, break

    # Final validation and compacting
    if not is_valid(current):
        # Fallback to DSATUR if invalid
        current = dsatur()
        if not is_valid(current):
            # Ultimate fallback: greedy
            order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
            current = greedy_color(order)

    # Ensure colors are consecutive starting from 0
    if current:
        # Map colors to 0..k-1
        unique_colors = sorted(set(current))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        current = [mapping[c] for c in current]

    return current

