    triangle_counts = [0] * n
    for u in range(n):
        for v in neighbors[u]:
            if v > u:
                common = neighbors[u] & neighbors[v]
                for w in common:
                    if w > v:
                        triangle_counts[u] += 1
                        triangle_counts[v] += 1
