        # Check if we can swap: after swap, no neighbor of any node in component gets color conflict?
        # Actually, swapping a<->b in a Kempe chain preserves validity, so we can always swap.
        # But we want to free color a for v? We'll swap the component.
        for node in component:
            if colors[node] == a:
                colors[node] = b
            else:
                colors[node] = a
        return True

    # Helper: try to eliminate the smallest color class using Kempe chains
    def reduce_colors(colors):
        # Make a copy to work on
        cur_colors = colors[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = [[] for _ in range(n)]  # up to n colors
            max_color = -1
            for v in range(n):
                c = cur_colors[v]
                classes[c].append(v)
                if c > max_color:
                    max_color = c
            # Try to eliminate from highest color down? Actually target smallest non-empty class
            # But literature says target smallest color class (often highest index if we use first-fit)
            # We'll target the largest color index that is non-empty, as it's likely smallest class in DSATUR/RLF
            # Find non-empty classes from high to low
            for color in range(max_color, -1, -1):
                if not classes[color]:
                    continue
                # Try to recolor each vertex in this class to a lower color
                eliminated = True
                for v in classes[color]:
                    # Check if v can take any color < color without conflict
                    found = False
                    for c in range(color):
                        conflict = False
                        for u in adj_list[v]:
                            if cur_colors[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            cur_colors[v] = c
                            found = True
                            break
                    if found:
                        continue
                    # Try Kempe chain with each lower color
                    kempe_found = False
                    for c in range(color):
                        # Try to swap along (color, c) Kempe chain starting at v
                        # Make a copy to test
                        test_colors = cur_colors[:]
                        if kempe_swap(test_colors, color, c, v):
                            # After swap, check if v now has color c (which it should if it was color)
                            # Actually, we want to see if after swap, v is no longer color 'color'
                            if test_colors[v] != color:
                                # Accept the swap
                                cur_colors = test_colors
                                kempe_found = True
                                break
                    if kempe_found:
                        continue
                    # If we couldn't recolor v, we cannot eliminate this color class yet
                    eliminated = False
                    break
                if eliminated:
                    # Successfully eliminated color class: remap colors above down by one
                    for v in range(n):
                        if cur_colors[v] > color:
                            cur_colors[v] -= 1
                    changed = True
                    break  # restart from scratch after change
        return cur_colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        valid, k1 = validate_and_count(c1)
        if valid:
            candidates.append((k1, c1))
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        valid, k2 = validate_and_count(c2)
        if valid:
            candidates.append((k2, c2))
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        valid, k3 = validate_and_count(c3)
        if valid:
            candidates.append((k3, c3))
    except Exception:
        pass
    # Fallback: greedy by degree order
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c4 = greedy_color(order)
        valid, k4 = validate_and_count(c4)
        if valid:
            candidates.append((k4, c4))
    except Exception:
        pass

    if not candidates:
        # Ultimate fallback: assign each vertex a unique color
        return list(range(n))

    # Select candidate with minimal colors
    best_k, best_colors = min(candidates, key=lambda x: x[0])
    # Apply Kempe chain reduction to try to improve
    try:
        reduced = reduce_colors(best_colors)
        valid, k_red = validate_and_count(reduced)
        if valid and k_red < best_k:
            best_colors = reduced
            best_k = k_red
    except Exception:
        pass

    # Ensure colors are compact (0..k-1)
    # Remap colors to consecutive indices
    color_map = {}
    next_color = 0
    for v in range(n):
        c = best_colors[v]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best_colors[v] = color_map[c]
    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits
    def popcount(x: int) -> int:
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        # saturation: set of neighbor colors for each vertex
        sat_sets = [set() for _ in range(n)]
        uncolored = set(range(n))
        # Precompute degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = len(sat_sets[v])
                # degree in uncolored subgraph
                deg_uncolored = popcount(bit_adj[v] & sum((1 << u) for u in uncolored))
                if sat > best_sat or (sat == best_sat and (deg_uncolored > best_deg or (deg_uncolored == best_deg and random.random() < 0.5))):
                    best_sat = sat
                    best_deg = deg_uncolored
                    best_v = v
            v = best_v
            # Find smallest color not used by neighbors
            neighbor_mask = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_mask |= (1 << color[u])
            c = 0
            while neighbor_mask & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation sets of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat_sets[u].add(c)
        return color

    # RLF (Recursive Largest First)
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: popcount(bit_adj[x] & sum((1 << u) for u in uncolored)))
                S.add(v)
                uncolored.remove(v)
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in G[U]
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = 10**9
                for u in U:
                    w_neighbors = popcount(bit_adj[u] & sum((1 << w) for w in W))
                    deg_U = popcount(bit_adj[u] & sum((1 << x) for x in U))
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_U < best_deg_U):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for v in adj_list[u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color c to all vertices in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Smallest-Last ordering greedy
    def smallest_last() -> list[int]:
        # Compute degeneracy ordering (smallest-last)
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[i]) for i in range(n)]
        # current degree in remaining subgraph
        curr_deg = deg[:]
        while remaining:
            # find vertex with minimum current degree
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            neighbor_mask = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_mask |= (1 << color[u])
            c = 0
            while neighbor_mask & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except Exception:
        pass
    try:
        candidates.append(rlf())
    except Exception:
        pass
    try:
        candidates.append(smallest_last())
    except Exception:
        pass
    # Fallback: simple greedy by index
    greedy = [-1] * n
    for v in range(n):
        neighbor_mask = 0
        for u in adj_list[v]:
            if greedy[u] != -1:
                neighbor_mask |= (1 << greedy[u])
        c = 0
        while neighbor_mask & (1 << c):
            c += 1
        greedy[v] = c
    candidates.append(greedy)

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if all(c != -1 for c in col):
            k = max(col) + 1 if col else 0
            if k < best_k:
                best_k = k
                best_color = col[:]
    if best_color is None:
        best_color = greedy

    # Kempe chain color reduction
    def kempe_reduce(color_in: list[int]) -> list[int]:
        color = color_in[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class (largest index)
            max_color = max(color) if color else -1
            if max_color <= 0:
                break
            # Try to eliminate color classes from high to low
            for target_c in range(max_color, 0, -1):
                # Collect vertices with color target_c
                verts = [v for v in range(n) if color[v] == target_c]
                if not verts:
                    continue
                # Try to recolor each vertex in this class
                eliminated = True
                new_color = color[:]
                for v in verts:
                    # Try direct reassignment to a lower color
                    neighbor_mask = 0
                    for u in adj_list[v]:
                        if new_color[u] != -1:
                            neighbor_mask |= (1 << new_color[u])
                    found = False
                    for c in range(target_c):
                        if not (neighbor_mask & (1 << c)):
                            new_color[v] = c
                            found = True
                            break
                    if found:
                        continue
                    # Try Kempe chain swap with each lower color
                    swapped = False
                    for c in range(target_c):
                        # Build Kempe chain for colors (c, target_c) containing v
                        # Only consider vertices with color c or target_c
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if color[node] == c or color[node] == target_c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if color[nb] == c or color[nb] == target_c:
                                        if nb not in visited:
                                            stack.append(nb)
                        # Check if swapping this component would cause conflict
                        # After swap, vertices in component with color c become target_c and vice versa
                        # We need to ensure no adjacent vertices have same color after swap
                        ok = True
                        for node in component:
                            new_col = c if color[node] == target_c else target_c
                            for nb in adj_list[node]:
                                nb_col = color[nb]
                                if nb == node:
                                    continue
                                if nb in component:
                                    nb_col_after = c if color[nb] == target_c else target_c
                                else:
                                    nb_col_after = nb_col
                                if new_col == nb_col_after:
                                    ok = False
                                    break
                            if not ok:
                                break
                        if ok:
                            # Perform swap
                            for node in component:
                                if color[node] == c:
                                    new_color[node] = target_c
                                else:
                                    new_color[node] = c
                            swapped = True
                            break
                    if swapped:
                        continue
                    # If we couldn't recolor v, we cannot eliminate this color class yet
                    eliminated = False
                    break
                if eliminated:
                    # Successfully eliminated color target_c: remap colors > target_c down by 1
                    for v in range(n):
                        if color[v] > target_c:
                            new_color[v] -= 1
                    color = new_color
                    changed = True
                    break  # restart while loop
                else:
                    # Could not eliminate this target_c, try next lower
                    continue
            # If we went through all target_c and no elimination, break
            if not changed:
                break
        return color

    # Apply Kempe reduction to the best candidate
    best_color = kempe_reduce(best_color)

    # Validate and ensure consecutive colors
    # Verify proper coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v:  # check each edge once
                if best_color[u] == best_color[v]:
                    # Should not happen, but fallback to greedy
                    greedy = [-1] * n
                    for v in range(n):
                        neighbor_mask = 0
                        for u in adj_list[v]:
                            if greedy[u] != -1:
                                neighbor_mask |= (1 << greedy[u])
                        c = 0
                        while neighbor_mask & (1 << c):
                            c += 1
                        greedy[v] = c
                    best_color = greedy
                    break
            else:
                continue
            break

    # Compact colors to 0..k-1
    # Map used colors to consecutive integers
    used = set()
    for c in best_color:
        used.add(c)
    if not used:
        return [0] * n
    mapping = {old: new for new, old in enumerate(sorted(used))]
    best_color = [mapping[c] for c in best_color]

    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    # Ensure symmetry (undirected graph)
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].append(i)
                bit_adj[j] |= (1 << i)
    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: count distinct colors
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    # Heuristic 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = uncolored_deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and v > best_v):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
