    # Heuristic 2: RLF (Largest First Independent Set)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set = {v}
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v} - set(neighbors[v])
            W = set(neighbors[v]) & uncolored
            # Greedily add vertices from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    score = sum(1 for y in neighbors[u] if y in W)
                    deg_in_U = sum(1 for y in neighbors[u] if y in U)
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U) or (score == best_score and deg_in_U == best_deg_in_U and u < best_u):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
