                    # Actually, we check: if no neighbor of v is colored c in the current coloring, then after swap v becomes c and it's safe
                    # But if there is a neighbor u of v with color c, then after swap v becomes c and conflict with u.
                    # However, if that neighbor u is in the component, then after swap u becomes target_color, so no conflict.
                    # So condition: all neighbors of v that are colored c must be in the component.
                    conflict = False
