        # All vertices recolored, target color eliminated
        return coloring, True
    # Iteratively try to eliminate highest color
    k = count_colors(best)
    changed = True
    while changed and k > 0:
        changed = False
        target = k - 1
        new_coloring, eliminated = eliminate_color_class(best[:], target)  # work on copy
        if eliminated:
            # Remap colors to be consecutive
            mapping = {}
            next_color = 0
            for i in range(n):
                c = new_coloring[i]
                if c not in mapping:
