    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = []
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            row = []
            mask = 0
            for j, val in enumerate(adj[i]):
                if val:
                    row.append(j)
                    mask |= 1 << j
            neighbors.append(row)
            bit_adj[i] = mask
    else:
        for i in range(n):
            nbrs = adj[i][:]
            neighbors.append(nbrs)
            mask = 0
            for v in nbrs:
                mask |= 1 << v
            bit_adj[i] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    try:
        color = [-1] * n
        colored = [False] * n
        saturation = [0] * n  # bitmask of colors used by neighbors
        degree = [len(neighbors[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    sat = saturation[i].bit_count()
                    if sat > max_sat or (sat == max_sat and degree[i] > max_deg):
                        max_sat = sat
                        max_deg = degree[i]
                        v = i
            if v == -1:
                break  # should not happen

            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            colored[v] = True

