    try:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S = {v}
            to_check = {v}
            U = uncolored - {v}
            W = set()

            while to_check:
                x = to_check.pop()
                for y in neighbors[x]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
                        to_check.add(y)

            # Now grow independent set S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = -1
                max_w = -1
                min_deg_u = float('inf')
                for cand in U:
                    w_count = sum(1 for nb in neighbors[cand] if nb in W)
                    deg_u = sum(1 for nb in neighbors[cand] if nb in U)
                    if w_count > max_w or (w_count == max_w and deg_u < min_deg_u):
                        max_w = w_count
                        min_deg_u = deg_u
                        u = cand
