        if k < best_k:
            best_k = k
            best_coloring = color[:]
    except Exception:
        pass

    # 3. Smallest-Last (degeneracy ordering)
    try:
        # Compute degeneracy ordering (smallest-last)
        remaining = set(range(n))
        degree_in_subgraph = [len(neighbors[i]) for i in range(n)]
        order = []
