                    break

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find the (c, target_color) Kempe chain containing v
                    # BFS to get component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)

                    # Check if swapping c and target_color in component is valid
                    # It is always valid for Kempe chain, but we need to ensure
                    # that after swap, v gets color c and no conflict
                    # Actually, swapping preserves validity, so we can do it
                    # and then v will have color c (since it was target_color)
                    # But we want to remove v from target_color class, so after swap
                    # v becomes c, which is what we want.
                    # However, we must ensure that we don't accidentally pull another
                    # vertex into target_color class? No, because we are swapping:
                    # vertices that were c become target_color and vice versa.
                    # So the size of target_color class may change, but we are
                    # only interested in removing v from it.
                    # After swap, v will be color c, so it leaves target_color class.
                    # We can perform the swap and break.
                    for x in component:
                        if coloring[x] == c:
                            coloring[x] = target_color
                        elif coloring[x] == target_color:
                            coloring[x] = c
                    made_change = True
                    break
                if made_change:
                    break
            if not made_change:
                # Could not eliminate this color class, move to next lower
                continue
            else:
                # After making a change, we may have duplicates or gaps;
                # but we will re-run the reduction loop from the top
                # to try to eliminate higher colors again.
                # To avoid infinite loop, we break and let outer loop restart
                # by returning and letting caller re-call kempe_reduce
                return kempe_reduce(coloring)  # recurse to restart from highest

        # If we get here, no more reductions possible
        return coloring

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring[:])
    except Exception:
        pass

    # Final validation and compacting
    def validate_and_compact(coloring):
        # Check validity
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    # Invalid, but we try to fix by greedy re-color
