        if trial_k < best_k:
            best_k = trial_k
            best_coloring = trial_coloring

    # Ensure colors are compact
    if best_coloring:
        unique_colors = set(best_coloring)
        mapping = {c: i for i, c in enumerate(sorted(unique_colors))]
        best_coloring = [mapping[c] for c in best_coloring]

    # Final validation (should always hold)
    if not is_valid_coloring(best_coloring):
