def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Convert to adjacency list and bitmask
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]):
        # Adjacency matrix
        neighbors = []
        bit_adj = [0] * n
        for i in range(n):
            row = []
            mask = 0
            for j in range(n):
                if adj[i][j]:
                    row.append(j)
                    mask |= 1 << j
            neighbors.append(row)
            bit_adj[i] = mask
    else:
        # Adjacency list
        neighbors = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in neighbors[i]:
                mask |= 1 << j
            bit_adj[i] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial: pick vertex with max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (sat[x], len([y for y in neighbors[x] if y in uncolored]), random.random()))
            # Find smallest available color
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
                    # If neighbor gets a new color, update saturation of its uncolored neighbors
                    if color[u] == c:  # This neighbor just got colored? No, u is uncolored here.
                        pass
                    # Actually, we need to update saturation for neighbors of v that are uncolored
                    # But we already did: for each uncolored neighbor u of v, we increased sat[u] by 1
                    # However, if u's saturation increased because v got a new color, we need to propagate?
                    # Standard DSATUR: when a vertex is colored, for each uncolored neighbor, increase sat by 1 if the new color is not already in its neighborhood.
                    # But we don't track which colors are in the neighborhood, so we approximate by increasing sat by 1 always.
                    # This is an approximation; to be exact, we would need to check if the color is new to the neighbor's neighborhood.
                    # For simplicity and speed, we use the approximation (increase by 1).
        return color

    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            independent_set = {v}
            # Partition: U = vertices not adjacent to any in independent_set, W = adjacent
            W = set()
            for u in uncolored:
                if u != v and any(w in neighbors[u] for w in independent_set):
                    W.add(u)
            U = uncolored - independent_set - W
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: len([y for y in neighbors[x] if y in W]))
                # Tie-break: min degree in G[U]
                u = min((x for x in U if len([y for y in neighbors[x] if y in W]) == len([y for y in neighbors[u] if y in W])), 
                        key=lambda x: len([y for y in neighbors[x] if y in U]), default=u)
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # Remove u from its current bucket
                    old_deg = degree[u]
                    buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    buckets[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg
        # Color in reverse order
        return greedy_color(order[::-1])

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(color, a, b, v):
        # Returns new color array if swap is performed, else None
        stack = [v]
        visited = set()
        component = []
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            component.append(node)
            for u in neighbors[node]:
                if color[u] == a or color[u] == b:
                    if u not in visited:
                        stack.append(u)
        # Check if swapping is valid: no neighbor outside component has color a or b that would conflict
        # Actually, Kempe swap always preserves validity if we swap a whole component.
        # But we want to free color b for v? We are trying to recolor v from a to b via swap.
        # We will swap colors a and b in the component.
        new_color = color[:]
        for node in component:
            if new_color[node] == a:
                new_color[node] = b
            elif new_color[node] == b:
                new_color[node] = a
        return new_color

    # Helper: try to eliminate a color class
    def eliminate_color(color, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if color[v] == target_color]
        if not verts:
            return color  # already eliminated
        # Try to recolor each vertex to a lower color
        for v in verts:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= 1 << color[u]
            for c in range(target_color):  # try colors 0..target_color-1
                if not (used & (1 << c)):
                    # Direct reassignment possible
                    new_color = color[:]
                    new_color[v] = c
                    # Check if this causes any conflict? Should not by construction.
                    # But we need to ensure we don't break anything else? No, only v changed.
                    return new_color
        # Try Kempe chains
        for v in verts:
            for c in range(target_color):
                # Try to swap along Kempe chain of colors target_color and c
                # We want to see if we can free color c for v by swapping a component
                # that does not contain any neighbor of v colored c? Actually, standard:
                # If in the Kempe chain of v (colors target_color and c), the component does not contain
                # any neighbor of v that is colored c, then swapping will free color c for v.
                # Let's get the component of v in the subgraph induced by colors target_color and c.
                stack = [v]
                visited = set()
                component = []
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    component.append(node)
                    for u in neighbors[node]:
                        if color[u] == target_color or color[u] == c:
                            if u not in visited:
                                stack.append(u)
                # Check if any neighbor of v is in this component and has color c
                conflict = False
                for u in neighbors[v]:
                    if u in component and color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    # Swap colors target_color and c in the component
                    new_color = color[:]
                    for node in component:
                        if new_color[node] == target_color:
                            new_color[node] = c
                        elif new_color[node] == c:
                            new_color[node] = target_color
                    return new_color
        return None  # cannot eliminate

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        # Validate
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if col_dsatur[u] == col_dsatur[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            candidates.append(col_dsatur)
    except:
        pass
    # RLF
    try:
        col_rlf = rlf()
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if col_rlf[u] == col_rlf[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            candidates.append(col_rlf)
    except:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if col_sl[u] == col_sl[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            candidates.append(col_sl)
    except:
        pass
    # If no candidates, fallback to greedy by index
    if not candidates:
        col_greedy = greedy_color(list(range(n)))
        candidates.append(col_greedy)

    # Select candidate with fewest colors
    best = min(candidates, key=lambda c: max(c) + 1 if c else 0)
    k = max(best) + 1 if best else 0

    # Iterative color reduction using Kempe chains
    improved = True
    while improved and k > 0:
        improved = False
        # Try to eliminate color k-1
        new_color = eliminate_color(best, k-1)
        if new_color is not None:
            # Compact colors: relabel to 0..new_k-1
            # First, get mapping
            used_colors = set(new_color)
            mapping = {old: new for new, old in enumerate(sorted(used_colors))]
            compacted = [mapping[c] for c in new_color]
            # Validate compacted
            valid = True
            for u in range(n):
                for v in neighbors[u]:
                    if compacted[u] == compacted[v]:
