                        break
                if not valid:
                    break
            if valid:
                best = compacted
                k = max(best) + 1 if best else 0
                improved = True
        else:
            break

    # Ensure consecutive colors
    used = set(best)
    mapping = {old: new for new, old in enumerate(sorted(used))]
    best = [mapping[c] for c in best]

    return best

