def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= (1 << v)

    # Helper functions
    def is_proper(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1 and coloring[u] == coloring[v]:
                    return False
        return True

    def get_degree(u):
        return bit_adj[u].bit_count()

    def get_neighbors(u):
        return [v for v in range(n) if (bit_adj[u] >> v) & 1]

    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in get_neighbors(u):
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # DSATUR
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            candidates = [u for u in range(n) if coloring[u] == -1]
            if not candidates:
                break
            max_sat = max(saturated[u] for u in candidates)
            max_candidates = [u for u in candidates if saturated[u] == max_sat]
            if len(max_candidates) > 1:
                u = max(max_candidates, key=get_degree)
            else:
                u = max_candidates[0]
            # Assign smallest available color
            used = 0
            for v in get_neighbors(u):
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
            # Update saturation of neighbors
            for v in get_neighbors(u):
                if coloring[v] == -1:
                    saturated[v] += 1
        return coloring

    # RLF
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Start with max degree vertex in uncolored subgraph
            v = max(uncolored, key=lambda u: sum(1 for w in get_neighbors(u) if w in uncolored))
            independent_set = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            S = {v}
            U = {u for u in uncolored if not any((bit_adj[u] >> w) & 1 for w in S)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: sum(1 for w in get_neighbors(x) if w in W))
                # Tie-break: min degree in G[U]
                min_deg_u = min(U, key=lambda x: sum(1 for w in get_neighbors(x) if w in U))
                if sum(1 for w in get_neighbors(u) if w in W) == sum(1 for w in get_neighbors(min_deg_u) if w in W):
                    u = min_deg_u
                independent_set.add(u)
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in get_neighbors(u):
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for u in independent_set:
                coloring[u] = color
            color += 1
            uncolored = W
        return coloring

    # Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        degrees = [get_degree(u) for u in range(n)]
        order = []
        remaining = set(range(n))
        for _ in range(n):
            v = min(remaining, key=lambda u: degrees[u])
            order.append(v)
            remaining.remove(v)
            for w in get_neighbors(v):
                if w in remaining:
                    degrees[w] -= 1
        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Generate initial colorings
    colorings = []
    colorings.append(dsatur())
    colorings.append(rlf())
    colorings.append(smallest_last())

    # Select best initial coloring (fewest colors)
    best_coloring = min(colorings, key=lambda c: max(c) + 1 if c else 0)
    k = max(best_coloring) + 1 if best_coloring else 0

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        nonlocal k
        changed = True
        while changed and k > 1:
            changed = False
            # Target smallest color class (k-1)
            target_color = k - 1
            vertices = [u for u in range(n) if coloring[u] == target_color]
            if not vertices:
                # Compact colors
                mapping = {}
                new_color = 0
                for c in range(k):
                    if any(coloring[u] == c for u in range(n)):
                        mapping[c] = new_color
                        new_color += 1
                for u in range(n):
                    coloring[u] = mapping[coloring[u]]
                k = new_color
                continue
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to lower color
                for c in range(target_color):
                    if all(coloring[u] != c for u in get_neighbors(v)):
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find (c, target_color)-Kempe chain containing v
                    visited = set()
                    stack = [v]
                    component = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        if coloring[u] == c or coloring[u] == target_color:
                            component.add(u)
                            for w in get_neighbors(u):
                                if w not in visited and (coloring[w] == c or coloring[w] == target_color):
                                    stack.append(w)
                    # Check if we can swap: no neighbor of component has color c outside component
                    conflict = False
                    for u in component:
                        for w in get_neighbors(u):
                            if w not in component and coloring[w] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap
                        for u in component:
                            if coloring[u] == c:
                                coloring[u] = target_color
                            else:
                                coloring[u] = c
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                break
        return coloring

    best_coloring = kempe_reduce(best_coloring[:])
    # Final validation and compacting
    if not is_proper(best_coloring):
        # Fallback to DSATUR if something went wrong
        best_coloring = dsatur()
    # Ensure colors are consecutive starting from 0
    used_colors = set(best_coloring)
    mapping = {old: new for new, old in enumerate(sorted(used_colors))]
    best_coloring = [mapping[c] for c in best_coloring]
    return best_coloring

