import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count number of colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, break ties by max uncolored degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                deg = uncolored_deg[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.add(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in S for w in adj_list[u]):
                    W.add(u)
                    U.remove(u)
            # grow independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    # count neighbors in W
                    score = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if score > best_score or (score == best_score and deg_u < best_deg_u):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for v in S:
                color[v] = current_color
            current_color += 1
            uncolored -= S
        return color

    # Strategy 3: Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # maintain pointer to first non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < ptr:
                        ptr = d-1
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best initial candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    if not is_valid(best_coloring):
        # fallback to simple greedy if invalid (should not happen)
        best_coloring = greedy_color(list(range(n)))

    # Compact initial coloring
    best_coloring = compact_colors(best_coloring)
    k = count_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal k
        improved = True
        while improved and k > 1:
            improved = False
            # target the highest color class
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    c = coloring[u]
                    if c != -1:
                        used_by_neighbors |= (1 << c)
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # recolor v to c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Find the (target_color, c)-Kempe chain containing v
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in adj_list[node]:
                            if not visited[u] and (coloring[u] == target_color or coloring[u] == c):
                                visited[u] = True
                                stack.append(u)
                    # Check if any neighbor of v in the component has color c (would cause conflict if swapped)
                    has_c_neighbor = False
                    for node in component:
                        for u in adj_list[node]:
                            if coloring[u] == c and u in component:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # Perform swap: target_color <-> c in component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Could not eliminate target color, try next lower
                k -= 1
        return coloring

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)
    # Final compact and validate
    best_coloring = compact_colors(best_coloring)
    if not is_valid(best_coloring):
        # last resort: greedy
        best_coloring = greedy_color(list(range(n)))
        best_coloring = compact_colors(best_coloring)
    return best_coloring

