    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                neighbors[i].append(j)
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        used = [0] * n  # bitmask of colors used by neighbors
        for v in order:
            c = 0
            while used[v] & (1 << c):
                c += 1
            color[v] = c
            for u in neighbors[v]:
                used[u] |= (1 << c)
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

