    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        sat = [0] * n  # saturation degree
        # neighbor colors as bitmask for fast sat update
        neighbor_color_mask = [0] * n

        while uncolored:
            # select vertex with max sat, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                if sat[v] > best_sat or (sat[v] == best_sat and bin(neighbor_color_mask[v]).count('1') > best_sat):
                    # Actually, we need to break tie by degree in uncolored subgraph
                    deg_uncolored = 0
                    for u in neighbors[v]:
                        if u in uncolored:
                            deg_uncolored += 1
                    if sat[v] > best_sat or (sat[v] == best_sat and deg_uncolored > best_deg):
                        best_sat = sat[v]
                        best_deg = deg_uncolored
                        best_v = v
                    elif sat[v] == best_sat and deg_uncolored == best_deg:
                        if v < best_v or best_v == -1:
                            best_v = v
                elif sat[v] == best_sat:
                    deg_uncolored = 0
                    for u in neighbors[v]:
                        if u in uncolored:
                            deg_uncolored += 1
                    if deg_uncolored > best_deg:
                        best_deg = deg_uncolored
                        best_v = v
                    elif deg_uncolored == best_deg and v < best_v:
                        best_v = v
            if best_v == -1:
                best_v = next(iter(uncolored))

            # assign smallest available color
            c = 0
            while neighbor_color_mask[best_v] & (1 << c):
                c += 1
            color[best_v] = c
            uncolored.remove(best_v)

            # update saturation and neighbor color masks
            for u in neighbors[best_v]:
                if u in uncolored:
                    if not (neighbor_color_mask[u] & (1 << c)):
                        neighbor_color_mask[u] |= (1 << c)
                        sat[u] += 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            S = set()
            # start with max degree vertex in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # U: vertices not adjacent to S, W: adjacent to S
            U = set(uncolored - {v})
            W = set()
            for u in list(U):
                if any(w in S for w in neighbors[u]):
                    W.add(u)
                    U.remove(u)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                    elif score == best_score and deg_U == best_deg_U and u < best_u:
                        best_u = u
                if best_u == -1:
                    best_u = next(iter(U))
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    if d > 0:
                        deg[u] -= 1
                        buckets[d].remove(u)
                        buckets[d-1].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for color elimination
    def kempe_swap(coloring, target_color):
        # Try to eliminate target_color by recoloring its vertices
        # using direct reassignment or Kempe chains
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True  # already eliminated

        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in neighbors[v]:
                used |= (1 << coloring[u])
            for c in range(target_color):  # only try lower colors
                if not (used & (1 << c)):
                    # move v to color c
                    coloring[v] = c
                    vertices.remove(v)
                    # if we can eliminate the color, recurse
                    if kempe_swap(coloring, target_color):
                        return True
                    # backtrack
                    coloring[v] = target_color
                    vertices.append(v)
            # if not moved, restore vertices list
            vertices = [v for v in range(n) if coloring[v] == target_color]

        # Try Kempe chains for each vertex in target color
        for v in vertices:
            for c in range(target_color):
                # build (target_color, c)-Kempe chain containing v
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if coloring[node] == target_color or coloring[node] == c:
                        component.add(node)
                        for u in neighbors[node]:
                            if u not in visited and (coloring[u] == target_color or coloring[u] == c):
                                stack.append(u)
                # check if we can swap: no neighbor of component has color c outside component
                # Actually, swapping is always valid, but we want to free color c for v?
                # After swap, v will have color c if it was target_color
                # We want to see if after swap, v is no longer target_color (it will be c)
                # and we don't introduce conflict? Kempe swap preserves validity.
                # So we can always swap, but we want to eliminate target_color.
                # After swap, vertices in component that were target_color become c, and vice versa.
                # So the number of target_color vertices may change.
                # We want to reduce the count of target_color.
                # Count how many target_color in component become c, and how many c become target_color.
                target_in_comp = sum(1 for node in component if coloring[node] == target_color)
                c_in_comp = sum(1 for node in component if coloring[node] == c)
                # After swap, target_color count change: -target_in_comp + c_in_comp
                new_target_count = len([x for x in range(n) if coloring[x] == target_color]) - target_in_comp + c_in_comp
                if new_target_count < len([x for x in range(n) if coloring[x] == target_color]):
                    # perform swap
                    for node in component:
                        if coloring[node] == target_color:
                            coloring[node] = c
                        elif coloring[node] == c:
                            coloring[node] = target_color
                    return kempe_swap(coloring, target_color)
        return False

    # Iterative Kempe-based color reduction
    def reduce_colors(initial_coloring):
        coloring = initial_coloring[:]
        k = num_colors(coloring)
        changed = True
        while changed and k > 0:
            changed = False
            # try to eliminate color classes from highest to lowest
            for target_color in range(k-1, -1, -1):
                if kempe_swap(coloring, target_color):
                    changed = True
                    break
            # compact colors
            if changed:
                # remap colors to 0..k'-1
                mapping = {}
                next_color = 0
                for v in range(n):
                    c = coloring[v]
                    if c not in mapping:
                        mapping[c] = next_color
                        next_color += 1
                    coloring[v] = mapping[c]
                k = next_color
        return coloring

    # Generate candidates
    start = time.time()
    candidates = []

    # DSATUR
    col_dsatur = dsatur()
    if is_valid(col_dsatur):
        candidates.append(col_dsatur)

    # RLF
    col_rlf = rlf()
    if is_valid(col_rlf):
        candidates.append(col_rlf)

    # Smallest-Last
    col_sl = smallest_last()
    if is_valid(col_sl):
        candidates.append(col_sl)

    # Greedy by degree (Welsh-Powell)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    col_wp = greedy_color(order_wp)
    if is_valid(col_wp):
        candidates.append(col_wp)

    # Greedy by random order (multiple trials)
    for _ in range(10):
        if time.time() - start > 0.04:  # leave time for reduction
            break
        order = list(range(n))
        random.shuffle(order)
        col_rand = greedy_color(order)
        if is_valid(col_rand):
            candidates.append(col_rand)

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best = col
    if best is None:
        # fallback: greedy by degree
        best = greedy_color(order_wp)

    # Apply Kempe chain reduction
    best = reduce_colors(best)

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(best):
        # last resort: greedy DSATUR
        best = dsatur()
        k = num_colors(best)
        mapping = {}
        next_color = 0
        for v in range(n):
            c = best[v]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            best[v] = mapping[c]
    else:
        # compact colors
        mapping = {}
        next_color = 0
        for v in range(n):
            c = best[v]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            best[v] = mapping[c]

    return best

