    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor sets
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        neighbors = [set(lst) for lst in adj]
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n  # n colors enough
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color
    # Helper: count colors used
    def count_colors(col):
        if not col:
            return 0
        return max(col) + 1
    # Helper: validate coloring
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True
    # Helper: 1-opt local improvement
    def local_improve(col):
        improved = True
        while improved:
            improved = False
            # Try to reduce color of each vertex
            for v in range(n):
                used = [False] * (count_colors(col) + 1)
                for u in neighbors[v]:
                    if col[u] != -1:
                        used[col[u]] = True
                # Find smallest available color
                for c in range(len(used)):
                    if not used[c]:
                        if c < col[v]:
                            col[v] = c
                            improved = True
                        break
        return col
    best_coloring = None
    best_k = float('inf')
    # Try multiple random orderings
    for _ in range(20):  # 20 passes
        order = list(range(n))
        random.shuffle(order)
        col = greedy_color(order)
        col = local_improve(col)
        k = count_colors(col)
        if k < best_k and is_valid(col):
            best_k = k
            best_coloring = col[:]
    # Fallback: if no valid found (shouldn't happen), use degree ordering
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col = greedy_color(order)
        col = local_improve(col)
        best_coloring = col
    return best_coloring

