                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    deg = [len(adj_list[i]) for i in range(n)]

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to consecutive 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturation = [0] * n
        colored = [False] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    if saturation[u] > max_sat or (saturation[u] == max_sat and deg[u] > max_deg) or \
                       (saturation[u] == max_sat and deg[u] == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = saturation[u]
                        max_deg = deg[u]
                        v = u
            # Assign smallest available color
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if colored[nb]:
                    used[coloring[nb]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
            colored[v] = True
            # Update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if not colored[nb]:
                    # Count distinct colors in neighbors of nb
                    neighbor_colors = set()
                    for nn in adj_list[nb]:
                        if colored[nn]:
                            neighbor_colors.add(coloring[nn])
                    saturation[nb] = len(neighbor_colors)
        return coloring

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build maximal independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            S.append(v)
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            W = set()
            for nb in adj_list[v]:
                if nb in uncolored:
                    W.add(nb)
            U = uncolored - {v} - W
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)
                    if (w_neighbors > max_w_neighbors or
                        (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or
                        (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5))):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            uncolored -= S
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        ordering = []
        degrees = deg[:]
        remaining = set(range(n))
        # Repeatedly remove vertex of minimum degree
        for _ in range(n):
            v = min(remaining, key=lambda x: degrees[x])
            ordering.append(v)
            remaining.remove(v)
            for nb in adj_list[v]:
                if nb in remaining:
                    degrees[nb] -= 1
        # Color in reverse order using First-Fit
        coloring = [-1] * n
        for v in reversed(ordering):
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        if coloring[v] not in (a, b):
            return False
        stack = [v]
        visited = set()
        component = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] in (a, b):
                component.append(u)
                for nb in adj_list[u]:
                    if nb not in visited and coloring[nb] in (a, b):
                        stack.append(nb)
        # Swap colors in component
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            else:
                coloring[u] = a
        return True

    # Try to eliminate the last color via Kempe chains or reassignment
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try repeatedly to remove color k-1
        while True:
            last_color = k - 1
            vertices_last = [v for v in range(n) if coloring[v] == last_color]
            if not vertices_last:
                break
            made_progress = False
            # Try direct reassignment
            for v in vertices_last[:]:
                used = [False] * (k)  # colors 0..k-1
                for nb in adj_list[v]:
                    c = coloring[nb]
                    if c < k:
                        used[c] = True
                for c in range(k):
                    if not used[c]:
                        coloring[v] = c
                        vertices_last.remove(v)
                        made_progress = True
                        break
            if not vertices_last:
                k -= 1
                continue
            # Try Kempe chains with each lower color
            for v in vertices_last[:]:
                for c in range(last_color):
                    if kempe_swap(coloring, last_color, c, v):
                        # After swap, check if v changed color
                        if coloring[v] != last_color:
                            vertices_last.remove(v)
                            made_progress = True
                            break
                if made_progress:
                    break
            if not made_progress:
                break
            k = num_colors(coloring)
        # Reindex colors to be consecutive
        return normalize(coloring)

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Apply Kempe reduction to each candidate
    reduced = [reduce_colors(c[:]) for c in candidates]

    # Select the valid coloring with fewest colors
    best = None
    best_k = float('inf')
    for coloring in reduced:
        if is_valid(coloring):
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best = coloring

    # Fallback: if no candidate valid (should not happen), use DSATUR
    if best is None:
        best = dsatur()
        best = reduce_colors(best)

    return normalize(best)

