def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True
    # Build adjacency list and bit masks
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    neighbors[u].append(v)
                    bit_adj[u] |= 1 << v
    else:
        for u in range(n):
            for v in adj[u]:
                if v < n:
                    neighbors[u].append(v)
                    bit_adj[u] |= 1 << v
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color
    # Candidate 1: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree as bitmask of neighbor colors
        uncolored = set(range(n))
        # Initial pick: max degree
        if uncolored:
            u = max(uncolored, key=lambda x: len(neighbors[x]))
            color[u] = 0
            uncolored.remove(u)
            for v in neighbors[u]:
                sat[v] |= 1 << 0
        while uncolored:
            # select vertex with max saturation degree (number of distinct colors in sat)
            u = max(uncolored, key=lambda x: (sat[x].bit_count(), len(neighbors[x]), -x))
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            uncolored.remove(u)
            for v in neighbors[u]:
                if v in uncolored:
                    sat[v] |= 1 << c
        return color
    # Candidate 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # start with vertex of max degree in uncolored subgraph
            S = set()
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
                S.add(v)
                uncolored.remove(v)
                # U: vertices not adjacent to S (eligible)
                U = {u for u in uncolored if not any(w in S for w in neighbors[u])}
                # W: vertices adjacent to S (ineligible)
                W = uncolored - U
                while U:
                    # select u in U with max neighbors in W, tie-break by min degree in U
                    u = max(U, key=lambda x: (sum(1 for y in neighbors[x] if y in W), -sum(1 for y in neighbors[x] if y in U), -x))
                    S.add(u)
                    U.remove(u)
                    # move neighbors of u from U to W
                    for y in neighbors[u]:
                        if y in U:
                            U.remove(y)
                            W.add(y)
            for u in S:
                color[u] = c
            c += 1
        return color
    # Candidate 3: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering (smallest last)
        remaining = set(range(n))
        order = []
        deg = [len(neighbors[u]) for u in range(n)]
        while remaining:
            # pick vertex of minimum degree in remaining subgraph
            u = min(remaining, key=lambda x: deg[x])
            order.append(u)
            remaining.remove(u)
            for v in neighbors[u]:
                if v in remaining:
                    deg[v] -= 1
        # color in reverse order
        return greedy_color(list(reversed(order)))
    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except Exception:
        pass
    try:
        candidates.append(rlf())
    except Exception:
        pass
    try:
        candidates.append(smallest_last())
    except Exception:
        pass
    # Also try Welsh-Powell (degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        candidates.append(greedy_color(order_wp))
    except Exception:
        pass
    # Choose best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if all(0 <= c < n for c in col):
            k = max(col) + 1 if col else 0
            if k < best_k:
                best_k = k
                best_color = col
    if best_color is None:
        best_color = [0] * n
    # Kempe chain color reduction
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True
    def kempe_reduce(col):
        # map color to list of vertices
        color_classes = [[] for _ in range(n)]
        for v, c in enumerate(col):
            color_classes[c].append(v)
        # remove empty classes at high end
        while color_classes and not color_classes[-1]:
            color_classes.pop()
        k = len(color_classes)
        improved = True
        while improved and k > 1:
            improved = False
            # target smallest color class (last)
            target_c = k - 1
            target_vertices = color_classes[target_c][:]
            # Try to recolor each vertex in target class
            for v in target_vertices:
                if col[v] != target_c:
                    continue  # already recolored
                # try direct reassignment to a lower color
                free = [False] * k
                for u in neighbors[v]:
                    c = col[u]
                    if c < k:
                        free[c] = True
                for c in range(k):
                    if not free[c]:
                        # move v to color c
                        col[v] = c
                        color_classes[target_c].remove(v)
                        color_classes[c].append(v)
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chain swaps with each lower color
                for c in range(target_c):
                    # BFS to find Kempe chain component of v in colors {target_c, c}
                    from collections import deque
                    comp = []
                    visited = [False] * n
                    dq = deque([v])
                    visited[v] = True
                    while dq:
                        x = dq.popleft()
                        comp.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (col[y] == target_c or col[y] == c):
                                visited[y] = True
                                dq.append(y)
                    # check if swapping colors in component frees color target_c for v
                    # after swap, v will have color c; we need that no neighbor of v has color c outside component
                    conflict = False
                    for x in comp:
                        for y in neighbors[x]:
                            if not visited[y] and col[y] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # perform swap
                        for x in comp:
                            if col[x] == target_c:
                                col[x] = c
                                color_classes[target_c].remove(x)
                                color_classes[c].append(x)
                            else:  # col[x] == c
                                col[x] = target_c
                                color_classes[c].remove(x)
                                color_classes[target_c].append(x)
                        improved = True
                        break
                if improved:
                    break
            # remove empty classes at high end again
            while color_classes and not color_classes[-1]:
                color_classes.pop()
            k = len(color_classes)
        # compact colors to 0..k-1
        mapping = {}
        new_color = 0
        for c in range(len(color_classes)):
            if color_classes[c]:
                mapping[c] = new_color
                new_color += 1
        for v in range(n):
            if col[v] in mapping:
                col[v] = mapping[col[v]]
        return col
    if n > 0:
        best_color = kempe_reduce(best_color[:])
        # final validation (should be valid)
        if not is_valid(best_color):
            # fallback to greedy with DSATUR order
            best_color = dsatur()
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
        # Ensure symmetric (undirected) and no self-loops
        for i in range(n):
            adj_list[i] = [j for j in adj_list[i] if j != i and 0 <= j < n]

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor masks for fast saturation update
        colored_mask = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                if sat[v] > best_sat or (sat[v] == best_sat and len([u for u in adj_list[v] if u in uncolored]) > best_deg):
                    best_sat = sat[v]
                    best_deg = len([u for u in adj_list[v] if u in uncolored])
                    best_v = v
                elif sat[v] == best_sat and len([u for u in adj_list[v] if u in uncolored]) == best_deg:
                    if best_v == -1 or v < best_v:
                        best_v = v
            v = best_v
            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if not (colored_mask[u] & (1 << c)):
                        colored_mask[u] |= (1 << c)
                        sat[u] += 1
        return normalize(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build independent set for this color
            S = []  # independent set
            # Step 1: pick vertex with max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.append(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = set(uncolored)  # candidates
            W = set()           # blocked
            # Remove v from U
            U.remove(v)
            # Move neighbors of v in U to W
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # While U not empty
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = -1
                for u in U:
                    w_neighbors = len([w for w in adj_list[u] if w in W])
                    deg_U = len([x for x in adj_list[u] if x in U])
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_U < best_deg_U):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                    elif w_neighbors == best_w_neighbors and deg_U == best_deg_U:
                        if best_u == -1 or u < best_u:
                            best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                colors[v] = color_idx
            color_idx += 1
            # Next round: uncolored becomes W
            uncolored = W
        return normalize(colors)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        # We'll use a list of sets for buckets, but n <= 100 so we can do simple scan
        order = []
        remaining = set(range(n))
        # current degrees in the remaining graph
        curr_deg = deg[:]
        for _ in range(n):
            # find vertex with minimum curr_deg in remaining
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # Color in reverse order using greedy
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # already empty, compact
                mapping = {c: c for c in range(k) if c != target_color}
                # shift down colors above target
                for c in range(target_color + 1, k):
                    mapping[c] = c - 1
                colors = [mapping[c] for c in colors]
                k -= 1
                changed = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors |= (1 << colors[u])
                for c in range(target_color):  # try colors 0..target_color-1
                    if not (neighbor_colors & (1 << c)):
                        # direct move possible
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart from highest color after change
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # We consider swapping colors target_color and c
                    # Build the Kempe chain component containing v in the subgraph of colors {c, target_color}
                    # Only if v is colored target_color
                    if colors[v] != target_color:
                        continue
                    # BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == c or colors[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping this component is safe: 
                    # After swap, no neighbor of any node in component should have the new color
                    # For each node in component, if it was color c, it becomes target_color; if target_color, becomes c.
                    # We need to ensure that for every node in component:
                    #   - if it becomes c, none of its neighbors are c (after swap, but note neighbors not in component keep their color)
                    #   - if it becomes target_color, none of its neighbors are target_color (after swap)
                    # However, note: neighbors in the component will also swap, so we only need to check neighbors outside the component.
                    safe = True
                    for node in component:
                        orig_color = colors[node]
