                        for x in component:
                            if col[x] == target_color:
                                col[x] = c
                            elif col[x] == c:
                                col[x] = target_color
                        changed = True
                        break
            if changed:
                # compact colors: remap to 0..k-1
                # but we already try to keep colors small, so just return
                # actually, we should remap to ensure consecutive
                mapping = {}
                next_color = 0
                for i in range(n):
                    if col[i] not in mapping:
                        mapping[col[i]] = next_color
                        next_color += 1
                for i in range(n):
                    col[i] = mapping[col[i]]
        return col

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduction(best_coloring)
    except Exception:
        pass

    # Final validation and compacting
    # Ensure valid coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # conflict, apply greedy fallback
                best_coloring = greedy_color(list(range(n)))
                break
        else:
