    # Compact colors to 0..k-1
    if best_coloring:
        mapping = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        for i in range(n):
            best_coloring[i] = mapping[best_coloring[i]]

    return best_coloring

