    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    # Ensure symmetry for undirected graph (if needed)
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].append(i)
                bit_adj[j] |= (1 << i)
