    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
