        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        colored = [False] * n
        for _ in range(n):
            # select uncolored vertex with max sat, tie-break by max uncolored_deg, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    s = sat[i].bit_count()
                    if s > max_sat or (s == max_sat and uncolored_deg[i] > max_deg) or (s == max_sat and uncolored_deg[i] == max_deg and i < v):
                        max_sat = s
                        max_deg = uncolored_deg[i]
                        v = i
            if v == -1:
                break  # should not happen
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            colored[v] = True
            # update neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color
    col_dsatur = dsatur()
    k_dsatur = num_colors(col_dsatur)
    if k_dsatur < best_k:
        best_k = k_dsatur
        best_coloring = col_dsatur[:]
    # 2. RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in uncolored subgraph
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg[v] += 1
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S
            # W: vertices adjacent to at least one in S
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    # count neighbors in W
                    score = sum(1 for w in neighbors[u] if w in W)
                    # tie-break by min degree in G[U]
                    degU = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and u < best_u):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
