    if k_rlf < best_k:
        best_k = k_rlf
        best_coloring = col_rlf[:]
    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        deg = [len(neighbors[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg[v]
            if d >= 0:
                buckets[d].append(v)
        # track current degree and position
        order = []
        # we will remove vertices
        removed = [False] * n
        # current degree array
        cur_deg = deg[:]
        # pointer to non-empty bucket
        for _ in range(n):
            # find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            # get a vertex from bucket[d]
            while buckets[d] and removed[buckets[d][-1]]:
                buckets[d].pop()
            if not buckets[d]:
                continue
            v = buckets[d].pop()
            removed[v] = True
            order.append(v)
            # decrease degree of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d_u = cur_deg[u]
                    cur_deg[u] -= 1
                    if cur_deg[u] < d_u:
                        buckets[cur_deg[u]].append(u)
        # reverse order for coloring
        order.reverse()
        return greedy_color(order)
    col_sl = smallest_last()
    k_sl = num_colors(col_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = col_sl[:]
    # If we already have a coloring with 1 color (edgeless) or 2 colors (bipartite) we can't improve
    # but we still attempt Kempe to be safe
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find color classes
            max_color = max(col) if col else -1
            if max_color <= 0:
                break
            # try to eliminate the highest color class (or smallest? we try highest as it's likely sparse)
            # Actually, we try to reduce the number of colors by eliminating the highest color
            target_color = max_color
            # collect vertices with target_color
            targets = [v for v in range(n) if col[v] == target_color]
            # try to recolor each target vertex to a lower color if possible
            for v in targets:
                # colors used by neighbors
                used = 0
                for u in neighbors[v]:
                    c = col[u]
                    if c != -1:
                        used |= (1 << c)
                # find smallest color < target_color not used
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # can recolor directly
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # after recoloring one vertex, break to restart scan
                    break
            if changed:
                continue
            # if no direct recoloring, try Kempe chains
            for v in targets:
                used = 0
                for u in neighbors[v]:
                    c = col[u]
                    if c != -1:
                        used |= (1 << c)
                # try each lower color
                for c in range(target_color):
                    if used & (1 << c):
                        # color c is present in neighbors, try Kempe chain (target_color, c)
                        # We want to see if we can swap in the component of v to free color c for v
                        # Actually, we check if v is not in the same Kempe component as any vertex of color c that is adjacent? 
                        # Standard: if there is no path from v to any vertex of color c using only colors target_color and c, then we can swap in the component of v.
                        # But easier: try to swap the component containing v and see if it frees color c for v.
                        # Build the Kempe component of v with colors {target_color, c}
                        from collections import deque
                        comp = set()
                        q = deque([v])
                        comp.add(v)
                        while q:
                            x = q.popleft()
                            for y in neighbors[x]:
                                if col[y] == target_color or col[y] == c:
                                    if y not in comp:
                                        comp.add(y)
                                        q.append(y)
                        # Check if any neighbor of v has color c and is in the component? 
                        # Actually, if we swap the component, vertices of color target_color become c and vice versa.
                        # After swap, v will become color c.
                        # We need to ensure that no neighbor of v becomes color c (other than v) causing conflict.
                        # But if a neighbor u of v has color c and is in the component, after swap it becomes target_color, so no conflict.
                        # If a neighbor u of v has color c and is not in the component, after swap it remains c, and v becomes c -> conflict.
                        # So we can swap only if no neighbor of v with color c is outside the component.
                        conflict = False
                        for u in neighbors[v]:
                            if col[u] == c and u not in comp:
                                conflict = True
                                break
                        if not conflict:
                            # perform swap
                            for x in comp:
                                if col[x] == target_color:
                                    col[x] = c
                                else:  # col[x] == c
                                    col[x] = target_color
                            changed = True
                            break
                if changed:
                    break
            if changed:
                continue
            # if we couldn't recolor any vertex of target_color, we cannot reduce this color
            break
        # compact colors: map to 0..k-1
        # but we already use small colors, just ensure consecutive
        # remap colors to be dense
        mapping = {}
        next_color = 0
        for v in range(n):
            c = col[v]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            col[v] = mapping[c]
        return col
    # Apply Kempe reduction to the best coloring found
    final_col = kempe_reduce(best_coloring)
    # Validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    if not is_valid(final_col):
        # fallback to best_coloring (should be valid)
        final_col = best_coloring
    # Ensure consecutive colors
    mapping = {}
    next_color = 0
    for v in range(n):
        c = final_col[v]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        final_col[v] = mapping[c]
    return final_col

