    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        # colored neighbor count for tie-breaking
        colored_neighbors = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg_uncolored = -1
            for u in range(n):
                if coloring[u] != -1:
                    continue
                sat = len(saturation[u])
                if sat > max_sat:
                    max_sat = sat
                    max_deg_uncolored = colored_neighbors[u]
                    v = u
                elif sat == max_sat:
                    if colored_neighbors[u] > max_deg_uncolored:
                        max_deg_uncolored = colored_neighbors[u]
                        v = u
            if v == -1:  # should not happen
                break

            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c

            # Update saturation and colored_neighbors for uncolored neighbors
            for w in adj_list[v]:
                if coloring[w] == -1:
                    saturation[w].add(c)
                    colored_neighbors[w] += 1
