    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Find vertex in uncolored with max degree in induced subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                # count neighbors in uncolored
                cnt = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        cnt += 1
                if cnt > max_deg:
                    max_deg = cnt
                    v = u
            if v == -1:
                break  # should not happen

            # Build independent set for this color
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in S:
                    if w in adj_list[u] or u in adj_list[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_nw = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    nw = 0
                    for w in adj_list[u]:
                        if w in W:
                            nw += 1
                    if nw > max_nw:
                        max_nw = nw
                        min_deg_U = len([x for x in adj_list[u] if x in U])
                        u_star = u
                    elif nw == max_nw:
                        deg_U = len([x for x in adj_list[u] if x in U])
                        if deg_U < min_deg_U:
                            min_deg_U = deg_U
                            u_star = u
                if u_star == -1:
                    break  # should not happen
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
                uncolored.remove(u)
            color += 1
        return coloring

