        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        degree = deg[:]  # current degree in remaining subgraph
        order = []  # removal order
        # We'll use a list of sets for buckets, but n is small so we can scan
        for _ in range(n):
            # find vertex in remaining with min degree
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for w in adj_list[v]:
                if w in remaining:
                    degree[w] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = set()
            for w in adj_list[v]:
                if coloring[w] != -1:
                    used.add(coloring[w])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return False  # should not happen
        # BFS to get the Kempe chain component
        stack = [v]
        visited = set()
        component = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] == a or coloring[u] == b:
                component.add(u)
                for w in adj_list[u]:
                    if w not in visited and (coloring[w] == a or coloring[w] == b):
                        stack.append(w)
        # Try to swap: if no neighbor of component has color b (for a->b) or a (for b->a) outside?
        # Actually, swapping is always valid as long as we stay within the component.
        # But we want to free a color for v? We'll just swap and check if v gets the other color.
        # Swap colors a and b in the component
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            else:
                coloring[u] = a
