    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors_kempe(coloring):
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(col)
            if k <= 1:
                break
            # Find smallest color class
            color_classes = [[] for _ in range(k)]
            for i in range(n):
                if col[i] < k:  # should always be true
                    color_classes[col[i]].append(i)
            # Find the smallest non-empty color class
            min_size = float('inf')
            min_color = -1
            for c in range(k):
                if 0 < len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    min_color = c
            if min_color == -1:
                break
            # Try to recolor each vertex in min_color class
            for v in color_classes[min_color]:
