    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fall back to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = set()
            for w in adj_list[i]:
                if coloring[w] != -1:
                    used.add(coloring[w])
            c = 0
            while c in used:
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Choose the candidate with fewest colors
    best = min(candidates, key=num_colors)
    best = compact_colors(best)

    # Apply Kempe chain reduction to try to improve
    best = reduce_colors_kempe(best)
    best = compact_colors(best)

    # Final validation (should be valid)
    if not is_valid(best):
