        while uncolored:
            # degree in current uncolored subgraph
            deg_uncolored = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to S, W: adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                adjacent = False
                for w in S:
                    if u in adj_list[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # grow independent set S
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    degU = 0
                    for w in adj_list[u]:
                        if w in U:
                            degU += 1
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
