    # RLF
    try:
        col2 = rlf()
        candidates.append((num_colors(col2), col2))
    except Exception:
        pass
    # Smallest-Last
    try:
        col3 = smallest_last()
        candidates.append((num_colors(col3), col3))
    except Exception:
        pass

    # If no candidates, fall back to trivial
    if not candidates:
        return [0] * n

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=lambda x: x[0])[1]
    best_k = num_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, -1, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            made_change = False
            for v in verts:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):  # only try lower colors
                    if c not in neighbor_colors:
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # skip if color already used by neighbor (would conflict after swap)
                    # Find the Kempe chain component of v for colors (target_color, c)
                    # We'll do BFS to get the component containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping colors in this component would cause conflict
                    # Specifically, for any node in component, after swap, its new color must not conflict with neighbors
                    valid = True
                    for node in component:
                        new_color = c if coloring[node] == target_color else target_color
                        for nb in adj_list[node]:
                            if coloring[nb] == new_color:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                # After change, we may have emptied target_color; restart reduction from scratch
                return kempe_reduce(coloring)
        return coloring

    # Apply Kempe reduction
    try:
        improved = kempe_reduce(best_coloring[:])  # work on a copy
        if num_colors(improved) < best_k:
            best_coloring = improved
            best_k = num_colors(best_coloring)
    except Exception:
        pass

    # Ensure colors are consecutive starting from 0
    # Map colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]

    return best_coloring

