    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
