        best_k = num_colors(best_col)
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make copy
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest index)
            # we try to eliminate the highest color present
            max_color = max(col) if col else -1
            for target in range(max_color, -1, -1):
