        # but we already use lower colors, so just reindex
        # collect used colors
        used_colors = set(col)
        if not used_colors:
            return [0]*n
        mapping = {}
        for i, c in enumerate(sorted(used_colors)):
            mapping[c] = i
        col = [mapping[c] for c in col]
        return col
    # Apply Kempe reduction
    try:
        col_kempe = kempe_reduce(best_col)
        if is_valid(col_kempe):
            best_col = col_kempe
    except Exception:
        pass
    # Final validation and compactness
    # Ensure colors are 0..k-1
    used = set(best_col)
    if used:
        mapping = {c: i for i, c in enumerate(sorted(used))]
        best_col = [mapping[c] for c in best_col]
