    if not is_valid(best_col):
        # last resort: greedy
        best_col = greedy_color(list(range(n)))
        used = set(best_col)
        if used:
            mapping = {c: i for i, c in enumerate(sorted(used))]
            best_col = [mapping[c] for c in best_col]
    return best_col

