            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and u < v):
                    max_sat = s
                    max_deg = d
                    v = u
