    if n == 0:
        return []
    if n > 0 and len(adj[0]) == n and all(all(x in (0, 1) for x in row) for row in adj):
        # adjacency matrix
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # adjacency list
        graph = adj

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in graph[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if n > 0 else 0

    # Helper: check validity
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: BFS layering (bipartite attempt)
    color_bfs = [-1] * n
    visited = [False] * n
    from collections import deque
    max_color_used = 0
    for i in range(n):
        if not visited[i]:
            visited[i] = True
            color_bfs[i] = 0
            q = deque([i])
            while q:
                u = q.popleft()
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        color_bfs[v] = color_bfs[u] ^ 1
                        q.append(v)
                    elif color_bfs[v] == color_bfs[u]:
                        # conflict: not bipartite
                        pass
                max_color_used = max(max_color_used, color_bfs[u])
    # Ensure colors are compact
    if max(color_bfs) >= 0:
        max_color_used = max(color_bfs)
    # Try to reduce by reassigning
    # For simplicity, we keep as is; may use 2 colors even if not bipartite, but may have conflicts
    # We'll fix conflicts later if any

    # Strategy 2: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        # degree in uncolored subgraph
        uncolored_deg = [len(graph[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = len(saturation[u])
                if sat > max_sat or (sat == max_sat and uncolored_deg[u] > max_deg):
                    max_sat = sat
                    max_deg = uncolored_deg[u]
                    v = u
                elif sat == max_sat and uncolored_deg[u] == max_deg:
                    if v == -1 or u < v:
                        v = u
            # assign smallest available color
            used = [False] * (n + 1)
            for u in graph[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and degrees
            for u in graph[v]:
                if u in uncolored:
                    saturation[u].add(c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 3: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # start with max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in graph[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to S
            # W: vertices adjacent to S
            U = {u for u in uncolored if u != v and all(u not in graph[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in graph[w] for w in S)}
            while U:
                # select u in U with max neighbors in W, then min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = len([w for w in graph[u] if w in W])
                    deg_u = len([w for w in graph[u] if w in U])
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                    elif nw == max_nw and deg_u == min_deg_u:
                        if u_star == -1 or u < u_star:
                            u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in graph[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 4: Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        deg = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)
        for _ in range(n):
            # find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            for u in graph[v]:
                if u in remaining:
                    # move u to lower bucket
                    old_deg = deg[u]
                    buckets[old_deg].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].add(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    # BFS attempt
    if is_valid(color_bfs):
        candidates.append(color_bfs)
    else:
        # try to fix by using a third color where needed
        color_fixed = color_bfs[:]
        for u in range(n):
            for v in graph[u]:
                if color_fixed[u] == color_fixed[v]:
                    # assign a new color to v if possible
                    used = [False] * (n + 1)
                    for w in graph[v]:
                        if color_fixed[w] != -1:
                            used[color_fixed[w]] = True
                    c = 0
                    while used[c]:
                        c += 1
                    color_fixed[v] = c
        if is_valid(color_fixed):
            candidates.append(color_fixed)

    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-Last
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_coloring = None
    min_colors = float('inf')
    for coloring in candidates:
        if is_valid(coloring):
            k = count_colors(coloring)
            if k < min_colors:
                min_colors = k
                best_coloring = coloring

    # If none valid (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))

    # Ensure colors are consecutive starting from 0
    # Map colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]

    return best_coloring

