import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to zero-based consecutive colors
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_degree = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, break ties by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u].bit_count()
                deg_u = uncolored_degree[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_degree[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - set(neighbors[v])
            W = set(neighbors[v]) & uncolored
            # Greedily add vertices from U
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_u_degree = float('inf')
                for u in U:
                    w_neighbors = len([y for y in neighbors[u] if y in W])
                    u_degree = len([y for y in neighbors[u] if y in U])
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and u_degree < min_u_degree) or \
                       (w_neighbors == max_w_neighbors and u_degree == min_u_degree and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Core decomposition: repeatedly remove min degree vertex
        order = []
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        # We'll simulate removal
        temp_degree = degree[:]
        for _ in range(n):
            # Find vertex with min temp_degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if temp_degree[u] < min_deg:
                    min_deg = temp_degree[u]
                    v = u
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    temp_degree[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate initial colorings
    colorings = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            colorings.append(compact_colors(c1[:]))
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            colorings.append(compact_colors(c2[:]))
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            colorings.append(compact_colors(c3[:]))
    except:
        pass
    # Fallback: simple greedy by index
    try:
        c4 = greedy_color(list(range(n)))
        if is_valid(c4):
            colorings.append(compact_colors(c4[:]))
    except:
        pass

    # Select best initial coloring (fewest colors)
    if not colorings:
        # Last resort: assign all vertices color 0 (may be invalid, but we'll fix)
        best_color = [0] * n
    else:
        best_color = min(colorings, key=num_colors)

    # Ensure it's valid and compact
    if not is_valid(best_color):
        # Try to fix by greedy re-color in random order
        order = list(range(n))
        random.shuffle(order)
        best_color = greedy_color(order)
        best_color = compact_colors(best_color)
    best_color = compact_colors(best_color)

    # Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        """Try to eliminate target_color by recoloring its vertices to lower colors."""
        # Get vertices with target_color
        verts = [i for i in range(n) if coloring[i] == target_color]
        if not verts:
            return True, coloring  # already empty

        # Try to recolor each vertex
        for v in verts:
            used_by_neighbors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used_by_neighbors |= (1 << coloring[u])
            # Find smallest available color < target_color
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
                    # Direct reassignment possible
                    coloring[v] = c
                    break
            else:
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Build (c, target_color) Kempe chain containing v
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if we can swap: after swap, v would get color c
                    # We need to ensure no neighbor of v has color c after swap
                    # Actually, in the component, colors c and target_color are swapped.
                    # So after swap, v gets color c.
                    # We need to check that no neighbor outside the component has color c
                    # (because if a neighbor outside has color c and is adjacent to v, then after swap it's still c -> conflict)
                    # But note: if a neighbor is in the component, it will get swapped to target_color, so no conflict.
                    conflict = False
                    for nb in neighbors[v]:
                        if not visited[nb] and coloring[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: invert colors c and target_color in component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        # Now v has color c
                        break
                else:
                    # Could not recolor v
                    return False, coloring
        return True, coloring

    # Try to reduce colors from highest downward
    k = num_colors(best_color)
    # We'll try to eliminate colors k-1, k-2, ... until we can't
    changed = True
    while changed and k > 0:
        changed = False
        target = k - 1
        success, new_coloring = eliminate_color_class(best_color[:], target)
        if success:
            # Check if target color is now unused
            if target not in new_coloring:
                best_color = compact_colors(new_coloring)
                k = num_colors(best_color)
                changed = True
            else:
                # Color not eliminated, but we tried
                pass
        # If we couldn't eliminate, break
        if not changed:
            break

    # Final validation and compaction
    if not is_valid(best_color):
        # Last resort: greedy in natural order
        best_color = greedy_color(list(range(n)))
    best_color = compact_colors(best_color)

    return best_color

