                v = max(uncolored, key=lambda u: sum(1 for w in neighbors[u] if w in uncolored))
                independent_set.append(v)
                # Partition uncolored \ {v} into U (not adj to any in S) and W (adj to at least one in S)
                U = set()
                W = set()
                for u in uncolored:
                    if u == v:
                        continue
                    if any(w in neighbors[u] for w in independent_set):
                        W.add(u)
                    else:
                        U.add(u)

                while U:
                    # Select u in U with max |N(u) ∩ W|
                    best_u = -1
                    max_w_neighbors = -1
                    min_deg_in_U = float('inf')
                    for u in U:
                        w_neighbors = sum(1 for w in neighbors[u] if w in W)
                        deg_in_U = sum(1 for w in neighbors[u] if w in U)
                        if w_neighbors > max_w_neighbors or \
                           (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                            max_w_neighbors = w_neighbors
                            min_deg_in_U = deg_in_U
                            best_u = u
                    if best_u == -1:
                        break
                    independent_set.append(best_u)
                    U.remove(best_u)
                    # Move neighbors of best_u that are in U to W
                    for w in neighbors[best_u]:
                        if w in U:
                            U.remove(w)
                            W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize(coloring)

    # Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # Build degeneracy ordering (smallest last)
        remaining = set(range(n))
        order = []  # will be peeled order, we color in reverse
        degrees = [degree(v) for v in range(n)]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0

        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            # Get a vertex from bucket[ptr]
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            remaining.remove(v)
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    degrees[u] -= 1
                    buckets[old_deg].remove(u)  # O(n) but n<=100
                    buckets[degrees[u]].append(u)
                    if degrees[u] < ptr:
                        ptr = degrees[u]

        # Color in reverse order (largest first)
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Kempe chain swap: swap colors c1 and c2 in the component containing v
    def kempe_swap(coloring, v, c1, c2):
        if coloring[v] not in (c1, c2):
            return False  # should not happen
        stack = [v]
        visited = set()
        component = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] == c1 or coloring[u] == c2:
                component.append(u)
                for w in neighbors[u]:
                    if w not in visited and (coloring[w] == c1 or coloring[w] == c2):
                        stack.append(w)
        # Swap colors in component
        for u in component:
            if coloring[u] == c1:
                coloring[u] = c2
            else:
                coloring[u] = c1
        return True

    # Try to eliminate the last color using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        # Get vertices with target color
        target_vertices = [v for v in range(n) if coloring[v] == target_color]
        # Try each vertex in target color
        for v in target_vertices:
            # Try to move v to a lower color directly
            for c in range(target_color):
                conflict = False
                for u in neighbors[v]:
                    if coloring[u] == c:
                        conflict = True
                        break
                if not conflict:
                    coloring[v] = c
                    break
            else:  # if not broken, direct move not possible
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is in a Kempe chain of (target_color, c) that does not contain any other vertex of color c
                    # We will try to swap and see if it frees the target color for v
                    # But we need to ensure we don't create conflict
                    # Instead, we check: after swapping, will v be able to take color c?
                    # Actually, standard: if we swap the component of v in (target_color, c), then v will get color c
                    # We need to ensure that no neighbor of v has color c after swap (but they might if they are in the component)
                    # Alternative: check if there is no neighbor of v with color c in the same Kempe component? 
                    # Simpler: attempt the swap and then check if v can be recolored to c (but we already know it will be c after swap)
                    # Instead, we do: if the Kempe component of v does not contain any neighbor of v that is colored c (which would remain c after swap? no)
                    # Actually, after swap, neighbors of v that were c and in component become target_color, and vice versa.
                    # So we need that no neighbor of v is colored c and is NOT in the component (because those remain c and would conflict)
                    # Let's compute the component and check
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        if coloring[u] == target_color or coloring[u] == c:
                            component.add(u)
                            for w in neighbors[u]:
                                if w not in visited and (coloring[w] == target_color or coloring[w] == c):
                                    stack.append(w)
                    # Check if any neighbor of v that is colored c is NOT in component -> would remain c and conflict
                    can_swap = True
                    for u in neighbors[v]:
                        if coloring[u] == c and u not in component:
                            can_swap = False
                            break
                    if can_swap:
                        # Perform swap
                        kempe_swap(coloring, v, target_color, c)
                        # Now v should be color c (since it was target_color and we swapped)
                        break
                else:  # if we broke out of Kempe loop, we reassigned v
                    continue
                # if we didn't break, v still has target_color
        # After trying to reassign all target vertices, see if any still have target_color
        if any(coloring[v] == target_color for v in range(n)):
            return coloring  # could not eliminate
        else:
            # Successfully eliminated target_color, renormalize
            return normalize(coloring)

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select the one with fewest colors
    best = min(candidates, key=num_colors)

    # Iteratively try to reduce colors using Kempe chains
    current = best[:]
    improved = True
    # Limit iterations to avoid infinite loops
    for _ in range(10):  # more than enough for n<=100
        prev_colors = num_colors(current)
        current = reduce_colors(current)
        if num_colors(current) >= prev_colors:
            break

    # Final validation and normalization
    if not is_valid(current):
        # Fallback to greedy by degree order
        order = sorted(range(n), key=lambda v: degree(v), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        current = normalize(coloring)

    return current

