    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [list(lst) for lst in adj]  # copy to avoid side effects

    # Precompute triangle count for each vertex
    triangle_count = [0] * n
    for u in range(n):
        nbrs = neighbors[u]
        deg_u = len(nbrs)
        for i in range(deg_u):
            v = nbrs[i]
            for j in range(i+1, deg_u):
                w = nbrs[j]
                if w in neighbors[v]:
                    triangle_count[u] += 1

    # Order vertices by triangle count descending, then by degree descending
    order = list(range(n))
    order.sort(key=lambda v: (triangle_count[v], len(neighbors[v])), reverse=True)

    # Greedy coloring in the computed order
    color = [-1] * n
    for v in order:
        used = [False] * n  # n is safe upper bound for colors needed
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    # Compact colors to 0..k-1
    unique_colors = set(color)
    if not unique_colors:
        return [0] * n
    mapping = {old: new for new, old in enumerate(sorted(unique_colors))]
    color = [mapping[c] for c in color]

    return color

