def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []

    n = len(adj)

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            if is_matrix:
                for val in adj[i]:
                    if val not in (0, 1):
                        is_matrix = False
                        break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = []
        bit_adj = [0] * n
        for i in range(n):
            row = []
            mask = 0
            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
                    mask |= (1 << j)
            adj_list.append(row)
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in adj_list[u]:
                mask |= (1 << v)
            bit_adj[u] = mask

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            # Compute neighbor colors mask
            neighbor_mask = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_mask |= (1 << color[u])
            # Find smallest color not used by neighbors
            c = 0
            while neighbor_mask & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: apply 1-opt local search (try to reduce color of each vertex)
    def local_search_1opt(coloring):
        improved = True
        while improved:
            improved = False
            # Try vertices in random order to avoid cycles
            order = list(range(n))
            random.shuffle(order)
            for v in order:
                used = [False] * (num_colors(coloring) + 1)  # +1 for safety
                for u in adj_list[v]:
                    c = coloring[u]
                    if c < len(used):
                        used[c] = True
                # Find smallest available color
                for c in range(len(used)):
                    if not used[c]:
                        if c < coloring[v]:
                            coloring[v] = c
                            improved = True
                        break
        return coloring

    # Generate multiple random orderings and apply greedy + local search
    best_coloring = None
    best_k = float('inf')

    # Try 10 random permutations (adjustable for time budget)
    for _ in range(10):
        # Random vertex order
        order = list(range(n))
        random.shuffle(order)
        # Greedy coloring
        coloring = greedy_color(order)
        # Apply 1-opt local search
        coloring = local_search_1opt(coloring)
        k = num_colors(coloring)
        if k < best_k or (k == best_k and best_coloring is None):
            best_k = k
            best_coloring = coloring[:]

    # Fallback: if no valid coloring found (should not happen), use greedy by degree
    if best_coloring is None or not is_valid(best_coloring):
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_coloring = greedy_color(order)
        best_coloring = local_search_1opt(best_coloring)

    # Ensure colors are compact (0..k-1)
    if best_coloring:
        # Relabel colors to be consecutive
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]

    return best_coloring

