def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix
    is_matrix = (len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))
    # Build neighbor sets
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        neighbors = [set(row) for row in adj]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = {color[u] for u in neighbors[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: Welsh-Powell ordering (degree descending)
    def welsh_powell_order():
        return sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial selection: vertex with max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break: max degree in uncolored subgraph
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    deg = len(neighbors[v] & uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        deg_candidates = [v]
                    elif deg == max_deg:
                        deg_candidates.append(v)
                if len(deg_candidates) == 1:
                    v = deg_candidates[0]
                else:
                    v = random.choice(deg_candidates)
            # Assign smallest available color
            used = {color[u] for u in neighbors[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            independent_set = {v}
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                max_nw = -1
                best_u = None
                for u in U:
                    nw = len(neighbors[u] & W)
                    if nw > max_nw:
                        max_nw = nw
                        best_u = u
                    elif nw == max_nw:
                        if best_u is None or len(neighbors[u] & U) < len(neighbors[best_u] & U):
                            best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to independent set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[v]) for v in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)
        # Peel
        for _ in range(n):
            # Find first non-empty bucket
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # Welsh-Powell
    candidates.append(greedy_color(welsh_powell_order()))
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-Last
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to lower colors
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True  # already empty
        # Try direct reassignment first
        for v in vertices:
            used = {coloring[u] for u in neighbors[v] if coloring[u] != target_color}
            for c in range(target_color):
                if c not in used:
                    coloring[v] = c
                    vertices.remove(v)
                    break
        if not vertices:
            return True
        # Try Kempe chains for each vertex
        for v in vertices:
            for c in range(target_color):
                # Check if v can be swapped via Kempe chain (c, target_color)
                # Only if v has no neighbor of color c (otherwise direct move would work)
                if any(coloring[u] == c for u in neighbors[v]):
                    continue
                # Build Kempe chain component containing v in colors {c, target_color}
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if coloring[node] == c or coloring[node] == target_color:
                        component.add(node)
                        for u in neighbors[node]:
                            if coloring[u] == c or coloring[u] == target_color:
                                if u not in visited:
                                    stack.append(u)
                # Check if component has no vertex of color c adjacent to outside of component with color target_color?
                # Actually, swapping is safe if no neighbor of any node in component with color c is outside and has color target_color?
                # Standard condition: the component does not contain both colors in a way that causes conflict? 
                # Actually, swapping colors in a Kempe chain always preserves validity.
                # So we can always swap, but we want to eliminate target_color: after swap, vertices in component that were target_color become c, and vice versa.
                # We want to reduce the number of vertices with target_color.
                # After swap, the number of target_color vertices in component becomes the number that were c.
                # So if the component has no vertex of color c, then after swap, all target_color in component become c -> good.
                # If the component has some c, then after swap, those c become target_color -> might increase or decrease.
                # We want the number of target_color after swap to be less than before.
                # Let a = |{v in component: coloring[v] == c}|
                # Let b = |{v in component: coloring[v] == target_color}|
                # After swap: target_color count becomes a.
                # We want a < b.
                a = sum(1 for node in component if coloring[node] == c)
                b = sum(1 for node in component if coloring[node] == target_color)
                if a < b:
                    # Perform swap
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = target_color
                        else:  # must be target_color
                            coloring[node] = c
                    return True
        return False

    # Iteratively try to eliminate the highest color class
    changed = True
    while changed and best_k > 0:
        changed = False
        target_color = best_k - 1
        if eliminate_color_class(best_color, target_color):
            # Reindex colors to be consecutive
            # Map colors to 0..new_k-1
            unique_colors = {}
            new_color = 0
            for v in range(n):
                c = best_color[v]
                if c not in unique_colors:
                    unique_colors[c] = new_color
                    new_color += 1
                best_color[v] = unique_colors[c]
            best_k = new_color
            changed = True

    # Final validation (optional, but safe)
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_color[u] == best_color[v]:
                # Conflict: should not happen, fallback to DSATUR
                return dsatur()
    return best_color

