                if color[i] == -1:
                    if saturation[i] > max_sat:
                        max_sat = saturation[i]
                        candidates = [i]
                    elif saturation[i] == max_sat:
                        candidates.append(i)
            # tie-break by degree in the uncolored subgraph
            if len(candidates) > 1:
                # degree in uncolored subgraph
                uncolored_deg = [0] * n
                for i in range(n):
                    if color[i] == -1:
                        cnt = 0
                        for u in adj_list[i]:
                            if color[u] == -1:
                                cnt += 1
                        uncolored_deg[i] = cnt
                v = max(candidates, key=lambda i: (uncolored_deg[i], i))
            else:
                v = candidates[0]
