            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == v0:
                    continue
                adjacent = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)

            # Step 2: while U not empty, select vertex with max neighbors in W
            while U:
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if (w_neighbors > max_w_neighbors or
                        (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                # add best_u to S
                S.append(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                color[v] = current_color
            uncolored -= set(S)
            current_color += 1
        return normalize(color)

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # we will remove min degree vertex each time
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            # update degree of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    degree[u] -= 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Run all strategies and pick the best
    strategies = [dsatur, rlf, smallest_last, welsh_powell]
    best_coloring = None
    best_k = float('inf')
    for strat in strategies:
        try:
            coloring = strat()
            if not is_valid(coloring):
                continue
            k = count_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            continue

    # Fallback: if no strategy succeeded, use Welsh-Powell (should not happen)
    if best_coloring is None:
        best_coloring = welsh_powell()
        if not is_valid(best_coloring):
            # last resort: assign each vertex a unique color
