    if n == 1:
        return [0]

    # Detect adjacency matrix or adjacency list
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))
    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring given an ordering
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        colored = [False] * n
        sat = [0] * n
        # Initialize: pick vertex with max degree
        deg = [bit_adj[i].bit_count() for i in range(n)]
        v = max(range(n), key=lambda i: deg[i])
        color[v] = 0
        colored[v] = True
        # Update saturation of neighbors
        for u in range(n):
            if (bit_adj[v] >> u) & 1 and not colored[u]:
                sat[u] += 1
        # Color remaining vertices
        for _ in range(n - 1):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for i in range(n):
                if not colored[i]:
                    if sat[i] > max_sat:
                        max_sat = sat[i]
                        candidates = [i]
                    elif sat[i] == max_sat:
                        candidates.append(i)
            if max_sat == -1:
                break  # no uncolored vertices
            # Tie-break: max degree in uncolored subgraph
            def uncolored_deg(v):
                return (bit_adj[v] & ~sum((1 << j) for j in range(n) if colored[j])).bit_count()
            v = max(candidates, key=uncolored_deg)
            # Assign smallest available color
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and not colored[u]:
                    # Check if color c is new to u's neighbors
                    new = True
                    for w in range(n):
                        if (bit_adj[u] >> w) & 1 and color[w] == c:
                            new = False
                            break
                    if new:
                        sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: (bit_adj[x] & sum((1 << j) for j in uncolored)).bit_count())
            S.add(v)
            # Partition: U = uncolored \ S not adjacent to S, W = adjacent to S
            adj_S = 0
            for u in S:
                adj_S |= bit_adj[u]
            U = {u for u in uncolored if u not in S and not ((bit_adj[u] & adj_S) != 0)}
            W = uncolored - S - U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = (bit_adj[u] & sum((1 << w) for w in W)).bit_count()
                    if score > best_score or (score == best_score and (best_u is None or u < best_u)):
                        best_score = score
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_U = bit_adj[u] & sum((1 << w) for w in U)
                to_remove = set()
                for w in U:
                    if (nbrs_U >> w) & 1:
                        to_remove.add(w)
                U -= to_remove
                W |= to_remove
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        deg = [bit_adj[i].bit_count() for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            d = deg[v]
            if d < n:
                buckets[d].append(v)
        ptr = 0
        for _ in range(n):
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break
            v = buckets[ptr].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and not removed[u]:
                    d = deg[u]
                    deg[u] -= 1
                    if deg[u] < n:
                        buckets[deg[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Run all heuristics and pick best
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in range(u + 1, n):
                if ((bit_adj[u] >> v) & 1) and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if col else 0
        if k < best_k:
            best_k = k
            best_color = col[:]

    if best_color is None:
        # Fallback: greedy by degree
        order = sorted(range(n), key=lambda i: bit_adj[i].bit_count(), reverse=True)
        best_color = greedy_color(order)

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[i] = unique_colors[c]

    # Iterative Kempe chain color reduction
    def kempe_reduction(color):
        while True:
            # Find smallest color class (largest index)
            classes = [[] for _ in range(max(color) + 1) if color]
            if not color:
                break
            max_c = max(color)
            classes = [[] for _ in range(max_c + 1)]
            for v in range(n):
                classes[color[v]].append(v)
            # Find smallest non-empty class from the top
            target_c = -1
            for c in range(max_c, -1, -1):
                if classes[c]:
                    target_c = c
                    break
            if target_c == 0:
                break  # cannot reduce further
            target_vertices = classes[target_c]
            made_progress = False
            # Try to recolor each vertex in target class
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        used |= (1 << color[u])
                for c in range(target_c):
                    if not (used & (1 << c)):
                        color[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_c):
                    # Find the Kempe chain component of v in colors {c, target_c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and not visited[y]:
                                if color[y] == c or color[y] == target_c:
                                    visited[y] = True
                                    queue.append(y)
                    # Check if swapping this component frees color c for v
                    # After swap, v would get color c; need to ensure no neighbor has color c
                    conflict = False
                    for x in component:
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and color[y] == c and y not in component:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap: c <-> target_c in component
                        for x in component:
                            if color[x] == c:
                                color[x] = target_c
                            elif color[x] == target_c:
                                color[x] = c
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                break
            # Compact colors again
            unique_colors = {}
            next_color = 0
            for i in range(n):
                c = color[i]
                if c not in unique_colors:
                    unique_colors[c] = next_color
                    next_color += 1
                color[i] = unique_colors[c]
        return color

    best_color = kempe_reduction(best_color)
    return best_color

