    if is_matrix:
        adj_list = []
        bit_adj = [0] * n
        for u in range(n):
            neighbors = []
            mask = 0
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors.append(v)
                    mask |= (1 << v)
            adj_list.append(neighbors)
            bit_adj[u] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in adj_list[u]:
                mask |= (1 << v)
            bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << 0)
        while uncolored:
            # Select vertex with max saturation degree (number of colors in saturation)
            v = max(uncolored, key=lambda x: (saturation[x].bit_count(), len(adj_list[x]), -x))
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to any in S, W = adjacent to at least one in S
            U = {u for u in uncolored if not any(y in independent_set for y in adj_list[u])}
            W = uncolored - U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: (sum(1 for y in adj_list[x] if y in W), -sum(1 for y in adj_list[x] if y in U), -x))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            c += 1
        return color

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # Pointer to current min degree
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
                    # If degree decreased below ptr, we may need to adjust ptr later
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-Last
    candidates.append(smallest_last())
    # Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: (-len(adj_list[x]), x))
