    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col

    if best_color is None:
        # Fallback: greedy on natural order
        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduction(color):
        # Make color indices consecutive
        unique_colors = sorted(set(color))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        k = len(unique_colors)
        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Try to remove color k-1
            target_color = k - 1
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                # Should not happen, but skip
                k -= 1
                continue
            # Try to recolor each vertex in target_color
            for v in vertices:
                # Check if can move to any lower color directly
                neighbor_colors = set()
                for u in adj_list[v]:
                    neighbor_colors.add(color[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Move v to color c
                        color[v] = c
                        improved = True
                        break
                if improved:
                    # After moving one vertex, break to restart
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Skip if c is present in neighbors (direct move not possible)
                    if c in neighbor_colors:
                        # Find the Kempe chain component of v in colors {c, target_color}
                        from collections import deque
                        comp = set()
                        queue = deque([v])
                        comp.add(v)
                        while queue:
                            x = queue.popleft()
                            for y in adj_list[x]:
                                if color[y] == c or color[y] == target_color:
                                    if y not in comp:
                                        comp.add(y)
                                        queue.append(y)
                        # Check if any neighbor of the component has color c (would cause conflict if swapped)
                        has_c_neighbor = False
                        for x in comp:
                            for y in adj_list[x]:
                                if color[y] == c and y not in comp:
                                    has_c_neighbor = True
                                    break
                            if has_c_neighbor:
                                break
                        if not has_c_neighbor:
                            # Swap colors c and target_color in the component
                            for x in comp:
                                if color[x] == c:
                                    color[x] = target_color
                                elif color[x] == target_color:
                                    color[x] = c
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if not improved:
                # Could not eliminate target_color, try next lower
                k -= 1
            else:
                # Recompute k after possible reduction
                unique_colors = sorted(set(color))
                mapping = {c: i for i, c in enumerate(unique_colors)}
                color = [mapping[c] for c in color]
                k = len(unique_colors)
        return color

    best_color = kempe_reduction(best_color)

    # Final validation and compacting
    unique_colors = sorted(set(best_color))
    mapping = {c: i for i, c in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]

    # Double-check validity
    for u in range(n):
        for v in adj_list[u]:
            if best_color[u] == best_color[v]:
                # In case of error, fallback to greedy
                return greedy_color(list(range(n)))

    return best_color

