    def normalize(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # saturation degree
        # degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        # start with vertex of highest degree
        v = max(range(n), key=lambda i: degrees[i])
        color[v] = 0
        # update saturation of neighbors
        neighbors_v = adj_list[v]
        for u in neighbors_v:
            saturation[u] = 1  # neighbor of colored vertex with color 0

