                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                color[v] = current_color
            uncolored -= set(S)
            current_color += 1
        return normalize(color)

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # we will remove min degree vertex each time
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            # update degree of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    degree[u] -= 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Run all strategies and pick the best
    strategies = [dsatur, rlf, smallest_last, welsh_powell]
    best_coloring = None
    best_k = float('inf')
    for strat in strategies:
        try:
            coloring = strat()
            if not is_valid(coloring):
                continue
            k = count_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            continue

    # Fallback: if no strategy succeeded, use Welsh-Powell (should not happen)
    if best_coloring is None:
        best_coloring = welsh_powell()
        if not is_valid(best_coloring):
            # last resort: assign each vertex a unique color
            best_coloring = list(range(n))

    # Ensure colors are normalized and valid
    best_coloring = normalize(best_coloring)
    if not is_valid(best_coloring):
        # debug fallback
        best_coloring = list(range(n))
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list and compute bit masks
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Compute degree and bit adjacency masks
    degree = [len(adj_list[i]) for i in range(n)]
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for neighbor in adj_list[i]:
            mask |= (1 << neighbor)
        bit_adj[i] = mask

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        # colored neighbor count for tie-breaking
        colored_neighbor_count = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat = len(saturation[u])
                    if sat > max_sat or (sat == max_sat and degree[u] > max_deg) or \
                       (sat == max_sat and degree[u] == max_deg and random.random() < 0.5):
                        max_sat = sat
                        max_deg = degree[u]
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c

            # Update saturation and colored neighbor count for uncolored neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    saturation[u].add(c)
                    colored_neighbor_count[u] += 1
        return normalize(colors)

    # RLF algorithm
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for current color
            # Find vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                # count neighbors in uncolored
                cnt = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        cnt += 1
                if cnt > max_deg:
                    max_deg = cnt
                    v = u
            if v == -1:
                break

            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in independent_set:
                    if w in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_cnt = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_cnt += 1
                    # degree in U
                    u_cnt = 0
                    for w in adj_list[u]:
                        if w in U:
                            u_cnt += 1
                    if w_cnt > max_w_neighbors or (w_cnt == max_w_neighbors and u_cnt < min_deg_in_U) or \
                       (w_cnt == max_w_neighbors and u_cnt == min_deg_in_U and random.random() < 0.5):
                        max_w_neighbors = w_cnt
                        min_deg_in_U = u_cnt
                        best_u = u
                if best_u == -1:
                    break

                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to independent_set
            for u in independent_set:
                colors[u] = color
            color += 1
            # Remove independent_set from uncolored
            uncolored -= independent_set

        return normalize(colors)

    # Smallest-Last (Matula-Beck) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree_copy = degree[:]  # current degree in remaining subgraph
        order = []
        # Use buckets for efficiency (since n <= 100)
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = degree_copy[i]
            if d < len(buckets):
                buckets[d].append(i)
            else:
                # extend buckets if needed (should not happen with copy)
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(i)

        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = degree_copy[u]
                    degree_copy[u] -= 1
                    new_deg = degree_copy[u]
                    # remove u from old bucket
                    if old_deg < len(buckets) and u in buckets[old_deg]:
                        buckets[old_deg].remove(u)
                    # add u to new bucket
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    else:
                        while len(buckets) <= new_deg:
                            buckets.append([])
                        buckets[new_deg].append(u)

        # Color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors, a, b, v):
        n_local = len(colors)
        if a == b:
            return False
        # BFS to get the Kempe chain component containing v
        from collections import deque
        visited = [False] * n_local
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            node = queue.popleft()
            component.append(node)
            for neighbor in adj_list[node]:
                if not visited[neighbor] and (colors[neighbor] == a or colors[neighbor] == b):
                    visited[neighbor] = True
                    queue.append(neighbor)
        # Check if swapping is safe: no neighbor outside component has color a or b that would conflict
        # Actually, swapping within a component always preserves validity
        # Perform swap
        for node in component:
            if colors[node] == a:
                colors[node] = b
            else:
                colors[node] = a
        return True

    # Try to eliminate a color class using Kempe chains
    def reduce_colors(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            vertices = [i for i in range(n) if colors[i] == target_color]
            if not vertices:
                continue
            # Try to recolor each vertex
            made_progress = False
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if colors[u] < target_color:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is not adjacent to any vertex of color c (so Kempe chain swap might free c)
                    # Actually, we can always try the swap; if it doesn't create conflict, it's valid.
                    # But we need to ensure that after swap, v gets color c and no conflict.
                    # Instead, we check: if there is no neighbor of v with color c, then swapping the (c, target_color) chain
                    # containing v will set v to c and since no neighbor has c, it's safe.
                    has_neighbor_with_c = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            has_neighbor_with_c = True
                            break
                    if not has_neighbor_with_c:
                        # Perform Kempe swap on the component of v for colors (c, target_color)
                        # This will set v to c
                        kempe_swap(colors, c, target_color, v)
                        made_progress = True
                        break
                if made_progress:
                    break
            if made_progress:
                # After recoloring, re-normalize and try again from the same target_color (since colors shifted)
                colors = normalize(colors)
                # Reset target_color to re-check the same index (now might be different)
                target_color = k  # will be decreased by loop, so effectively stay
            else:
                # Could not eliminate this color class, try lower
                continue
        return normalize(colors)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = set()
            for u in adj_list[i]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[i] = c
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_colors = normalize(best)

    # Apply Kempe chain reduction iteratively
    current = best_colors[:]
    prev_num = num_colors(current)
    for _ in range(10):  # limit iterations to avoid infinite loop
        reduced = reduce_colors(current)
        reduced = normalize(reduced)
        curr_num = num_colors(reduced)
        if curr_num < prev_num:
            current = reduced
            prev_num = curr_num
        else:
            break

    # Final validation and normalization
    if not is_valid_coloring(current):
        # Fallback to greedy if something went wrong
        colors = [-1] * n
        for i in range(n):
            used = set()
            for u in adj_list[i]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[i] = c
        current = normalize(colors)

    return current

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in adj_list[u]:
                bit_adj[u] |= (1 << v)

    # Helper: compute degree from bitmask
    def degree_from_bit(u):
        return bit_adj[u].bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: count number of colors used
    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmasks for fast saturation update
        neighbor_colors = [0] * n
        colored = [False] * n

        # Order by initial degree descending for tie-breaking in saturation
        order = list(range(n))
        order.sort(key=lambda x: degree_from_bit(x), reverse=True)

        for _ in range(n):
            # Select uncolored vertex with max saturation, break ties by degree (uncolored subgraph)
            v = -1
            max_sat = -1
            max_deg = -1
            for u in order:
                if colored[u]:
                    continue
                sat_u = saturation[u]
                if sat_u > max_sat:
                    max_sat = sat_u
                    v = u
                    max_deg = degree_from_bit(u)
                elif sat_u == max_sat:
                    deg_u = degree_from_bit(u)
                    if deg_u > max_deg:
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True

            # Update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    # Update neighbor color bitmask
                    neighbor_colors[u] |= (1 << c)
                    # Update saturation: count bits in neighbor_colors[u]
                    saturation[u] = neighbor_colors[u].bit_count()
        return compact_colors(colors)

    # RLF: Recursive Largest First via independent set extraction
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color_idx = 0

        while not all(colored):
            # Find uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # degree in uncolored subgraph: neighbors that are also uncolored
                deg = 0
                for w in adj_list[u]:
                    if not colored[w]:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                break

            # Build independent set S for this color
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible for this color)
            U = set()
            W = set()
            for u in range(n):
                if colored[u]:
                    continue
                adjacent_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)

            # Greedily expand S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for u in S:
                colors[u] = color_idx
            color_idx += 1

        return compact_colors(colors)

    # Smallest-Last (Matula & Beck) ordering greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # removal order
        deg = [degree_from_bit(u) for u in range(n)]
        # We'll simulate removal
        while remaining:
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    deg[u] -= 1

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = count_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Target the smallest color class (highest index)
            target_color = k - 1
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # Already compacted? should not happen
                break

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used_by_neighbors |= (1 << colors[u])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor v to c
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from highest color after change

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Skip if v already has a neighbor with color c (direct move blocked)
                    has_c_neighbor = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            has_c_neighbor = True
                            break
                    if has_c_neighbor:
                        continue

                    # Build Kempe chain for colors (target_color, c) starting from v
                    # We'll do BFS to find the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == target_color or colors[nb] == c):
                                visited[nb] = True
                                queue.append(nb)

                    # Check if any node in component has a neighbor with color c (for target_color -> c swap)
                    # Actually, we want to swap: target_color <-> c in the component.
                    # After swap, we need to ensure no conflict.
                    # The swap is safe if no node in the component adjacent to a vertex of color c outside the component
                    # when we are changing target_color to c, and vice versa.
                    # More precisely: after swap, nodes originally target_color become c, and vice versa.
                    # Conflict can only occur if:
                    #   - A node originally target_color (now c) is adjacent to a node of color c outside component -> two c's
                    #   - A node originally c (now target_color) is adjacent to a node of color target_color outside component -> two target_color's
                    # But note: if a node originally c is adjacent to a node of color target_color outside component,
                    #   after swap, that node becomes target_color and the outside is target_color -> conflict.
                    # So we need to check both.

                    safe = True
                    for node in component:
                        orig_color = colors[node]
                        new_color = c if orig_color == target_color else target_color
                        for nb in adj_list[node]:
                            if nb not in component:  # outside component
                                if colors[nb] == new_color:
                                    safe = False
                                    break
                        if not safe:
                            break

                    if safe:
                        # Perform the swap
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:  # must be c
                                colors[node] = target_color
                        improved = True
                        break  # break color loop
                if improved:
                    break  # break vertex loop

            if improved:
                # Compact colors and update k
                colors = compact_colors(colors)
                k = count_colors(colors)
            else:
                # Could not reduce further
                break

        return colors

    # Generate candidate colorings
    start_time = time.time()
    candidates = []

    # DSATUR
    c1 = dsatur()
    if is_valid_coloring(c1):
        candidates.append(c1)

    # RLF
    c2 = rlf()
    if is_valid_coloring(c2):
        candidates.append(c2)

    # Smallest-Last
    c3 = smallest_last()
    if is_valid_coloring(c3):
        candidates.append(c3)

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        # Simple greedy in order 0..n-1
        colors = [-1] * n
        for u in range(n):
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=count_colors)
    best_colors = compact_colors(best)

    # Apply Kempe chain reduction to try to improve
    if time.time() - start_time < 0.04:  # leave some time for Kempe
        reduced = kempe_reduce(best_colors[:])  # work on a copy
        if is_valid_coloring(reduced) and count_colors(reduced) < count_colors(best_colors):
            best_colors = reduced

    # Final validation and compact
    if not is_valid_coloring(best_colors):
        # Fallback: should not happen, but ensure validity
        best_colors = dsatur()
        best_colors = compact_colors(best_colors)

    return best_colors

