def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect if input is adjacency matrix (square, binary entries)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list and build bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask: bit i set if neighbor i exists
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring: list[int]) -> bool:
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring: list[int]) -> int:
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1 consecutive
    def normalize(coloring: list[int]) -> list[int]:
        if not coloring:
            return coloring
        # Map existing colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR algorithm
    def dsatur() -> list[int]:
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph (for tie-breaking)
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    if saturation[u] > max_sat or \
                       (saturation[u] == max_sat and uncolored_deg[u] > max_deg) or \
                       (saturation[u] == max_sat and uncolored_deg[u] == max_deg and random.random() < 0.5):
                        max_sat = saturation[u]
                        max_deg = uncolored_deg[u]
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for nb in adj_list[v]:
                c = coloring[nb]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and uncolored degree for neighbors
            for nb in adj_list[v]:
                if coloring[nb] == -1:  # nb is uncolored
                    # Update saturation: if this neighbor's color is new to nb's neighbors
                    # We check if color c is already present in nb's colored neighbors
                    has_color = False
                    for nn in adj_list[nb]:
                        if coloring[nn] == c:
                            has_color = True
                            break
                    if not has_color:
                        saturation[nb] += 1
                    uncolored_deg[nb] -= 1
            uncolored_count -= 1

        return normalize(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf() -> list[int]:
        if n == 0:
            return []
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build independent set for this color
            S = []
            # degree in the current uncolored subgraph
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for nb in adj_list[v]:
                    if nb in uncolored:
                        deg[v] += 1

            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg[x])
            S.append(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v}
            W = set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_nb_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_nb_count += 1
                    # Degree in U subgraph
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    # Select: max w_nb_count, then min deg_in_U, then random
                    if w_nb_count > max_w_neighbors or \
                       (w_nb_count == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_nb_count == max_w_neighbors and deg_in_U == min_deg_in_U and random.random() < 0.5):
                        max_w_neighbors = w_nb_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color to all in S
            for v in S:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        if n == 0:
            return []
        # Copy of degrees
        degree = [len(adj_list[i]) for i in range(n)]
        # Set of remaining vertices
        remaining = set(range(n))
        order = []  # will store vertices in removal order

        for _ in range(n):
            # Find vertex with minimum degree in remaining subgraph
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    degree[nb] -= 1

        # Color in reverse order using greedy (first-fit)
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for nb in adj_list[v]:
                c = coloring[nb]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring: list[int]) -> list[int]:
        if n <= 1:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        improved = True
        while improved:
            improved = False
            k = num_colors(current)
            if k <= 1:
                break
            # Try to eliminate color k-1
            target_color = k - 1
            # Vertices with target color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # Already normalized, should not happen
                break

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for nb in adj_list[v]:
                    c = current[nb]
                    if c != -1:
                        neighbor_colors |= (1 << c)
                found = False
                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (neighbor_colors & (1 << c)):
                        current[v] = c
                        found = True
                        improved = True
                        break
                if found:
                    continue  # move to next target vertex

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Check if v is in a Kempe chain of (target_color, c) that does not include any other target_color vertex?
                    # We'll build the component containing v in the subgraph of colors {target_color, c}
                    # If the component does not contain any vertex of color c that is adjacent to a target_color vertex outside? 
                    # Standard: if we swap the component, v becomes c, and we need to ensure no conflict.
                    # Actually, swapping a Kempe chain preserves validity.
                    # We want to know if after swap, v is no longer target_color, and we don't introduce duplicate target_color elsewhere?
                    # The goal is to free the target_color on v, so that we might eventually eliminate the color.
                    # We do the swap and see if it reduces the number of target_color vertices without increasing elsewhere? 
                    # But note: swapping may move another vertex to target_color.
                    # Instead, we check: if the Kempe chain component of v does not contain any vertex of color c that is adjacent to a vertex of target_color outside the component? 
                    # Actually, a simpler approach: if the component does not contain any vertex of color c, then after swap, v becomes c and we lose one target_color.
                    # But if the component contains a vertex of color c, then after swap, that vertex becomes target_color -> we might not reduce the count.
                    # We want to know if the component contains no vertex of color c? Then swapping removes target_color from v and adds c (which was absent) -> net reduction in target_color by 1.
                    # However, if the component contains both colors, swapping preserves the count of each.
                    # So we only want to swap if the component has no vertex of color c? 
                    # But note: v is target_color, so the component has at least v (target_color). If it has no c, then after swap: v becomes c, and no vertex becomes target_color -> target_color count reduces by 1.
                    # If it has at least one c, then after swap: v becomes c, and one c becomes target_color -> target_color count unchanged.
                    # Therefore, we only perform swap if the component has no vertex of color c.

                    # Build the Kempe chain component containing v for colors {target_color, c}
                    from collections import deque
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    has_color_c = False
                    while q:
                        node = q.popleft()
                        for nb in adj_list[node]:
                            if nb in comp:
                                continue
                            col_nb = current[nb]
                            if col_nb == target_color or col_nb == c:
                                comp.add(nb)
                                q.append(nb)
                                if col_nb == c:
                                    has_color_c = True
                    # If the component does not contain any vertex of color c, then swapping will reduce target_color count
                    if not has_color_c:
                        # Perform swap: target_color <-> c in the component
                        for node in comp:
                            if current[node] == target_color:
                                current[node] = c
                            elif current[node] == c:
                                current[node] = target_color
                        improved = True
                        break  # break from color loop, go to next target vertex
                # End for c in range(target_color)
            # End for v in target_vertices

            # If we made progress, re-normalize and continue
            if improved:
                current = normalize(current)
            else:
                break  # no improvement in this round

        return current

    # Run all heuristics and pick the best
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    c1 = dsatur()
    k1 = num_colors(c1)
    if k1 < best_k:
        best_k = k1
        best_coloring = c1

    # RLF
    c2 = rlf()
    k2 = num_colors(c2)
    if k2 < best_k:
        best_k = k2
        best_coloring = c2

    # Smallest-Last
    c3 = smallest_last()
    k3 = num_colors(c3)
    if k3 < best_k:
        best_k = k3
        best_coloring = c3

    # Apply Kempe reduction to the best candidate
    reduced = kempe_reduce(best_coloring[:])
    k_reduced = num_colors(reduced)
    if k_reduced < best_k:
        best_k = k_reduced
        best_coloring = reduced

    # Final validation and normalization
    if not is_valid(best_coloring):
        # Fallback: greedy by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for nb in adj_list[v]:
                c = coloring[nb]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            neighbors = adj[i]
            adj_list[i] = neighbors[:]
            mask = 0
            for j in neighbors:
                mask |= (1 << j)
            bit_adj[i] = mask

    # Helper: compute number of edges for potential use
    total_edges = 0
    for i in range(n):
        total_edges += bit_adj[i].bit_count()
    total_edges //= 2

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: convert coloring to consecutive indices starting from 0
    def normalize_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [bit_adj[i].bit_count() for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colors[v] != -1:
                    continue
                # Compute saturation: distinct colors in neighbors
                neighbor_colors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors |= (1 << colors[u])
                sat = neighbor_colors.bit_count()
                if sat > best_sat or (sat == best_sat and degrees[v] > best_deg) or \
                   (sat == best_sat and degrees[v] == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = degrees[v]
                    best_v = v
            v = best_v
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize_colors(colors)

    # Helper: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
                S.append(v)
                uncolored.remove(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            W = set()
            for u in S:
                for w in adj_list[u]:
                    if w in uncolored:
                        W.add(w)
            U = uncolored - W
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = -1
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                uncolored.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
                # Recompute U (should be uncolored - W, but we update incrementally)
                U = uncolored - W
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
        return normalize_colors(colors)

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core ordering by repeatedly removing min degree vertex
        degrees = [bit_adj[i].bit_count() for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use a list of sets for bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for i in range(n):
            d = degrees[i]
            buckets[d].add(i)
        # Pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d_u = degrees[u]
                    buckets[d_u].remove(u)
                    degrees[u] -= 1
                    d_u_new = degrees[u]
                    buckets[d_u_new].add(u)
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize_colors(colors)

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors, a, b, v):
        # Find the connected component of v in the subgraph induced by colors a and b
        stack = [v]
        visited = set()
        component = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if colors[node] == a or colors[node] == b:
                component.add(node)
                for nb in adj_list[node]:
                    if nb not in visited and (colors[nb] == a or colors[nb] == b):
                        stack.append(nb)
        # Swap colors a and b in the component
        for node in component:
            if colors[node] == a:
                colors[node] = b
            elif colors[node] == b:
                colors[node] = a
        return colors, component

    # Helper: try to eliminate the last color using Kempe chains
    def reduce_colors(colors):
        if not colors:
            return colors
        max_color = max(colors)
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            # Get vertices with this color
            verts = [i for i, c in enumerate(colors) if c == target_color]
            if not verts:
                continue
            # Try to recolor each vertex to a lower color
            made_change = False
            for v in verts:
                used = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                # Try direct reassignment to any lower color
                for c in range(target_color):
                    if not (used & (1 << c)):
                        colors[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is adjacent to any vertex of color c
                    has_adjacent_c = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            has_adjacent_c = True
                            break
                    if not has_adjacent_c:
                        # Direct reassignment already checked, but if not possible due to used, skip
                        continue
                    # Perform Kempe swap between target_color and c, starting from v
                    new_colors, component = kempe_swap(colors[:], target_color, c, v)
                    # Check if after swap, v can take color c (i.e., no neighbor has color c)
                    # Actually, after swap, v's color becomes c, so we need to ensure no neighbor has c
                    conflict = False
                    for u in adj_list[v]:
                        if new_colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[:] = new_colors
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                # Re-normalize colors to be consecutive
                colors = normalize_colors(colors)
                # Break to restart from highest color again
                break
        return colors

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidates, fall back to simple greedy
    if not candidates:
        colors = [-1] * n
        order = list(range(n))
        random.shuffle(order)
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(normalize_colors(colors))

    # Select candidate with minimal number of colors
    best = min(candidates, key=lambda x: max(x) + 1 if x else 0)
    # Apply Kempe reduction iteratively (limited iterations for speed)
    current = best[:]
    for _ in range(10):  # limit iterations to stay within time
        new_colors = reduce_colors(current[:])
        if new_colors == current:
            break
        current = new_colors
    # Final normalization
    return normalize_colors(current)

