            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to consecutive 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0,1,2,...
        used = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in coloring]

    # DSATUR implementation
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph (for tie-breaking)
        uncolored_degree = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex: max saturation, then max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                deg_u = uncolored_degree[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used_colors |= (1 << coloring[u])
            c = 0
            while used_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update uncolored set and degrees
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    uncolored_degree[u] -= 1
                    # Update saturation if v got a new color
                    if coloring[v] != -1:
                        # Check if this color is new in u's neighborhood
                        has_color = False
                        for w in neighbors[u]:
                            if coloring[w] == coloring[v]:
                                has_color = True
                                break
                        if not has_color:
                            saturation[u] += 1
        return coloring

    # RLF implementation (Largest First Independent Set)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S.add(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adj_to_S = any(w in neighbors[u] for w in S)
                if adj_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                min_deg_U = float('inf')
                for u in U:
                    score = len([w for w in neighbors[u] if w in W])
                    deg_in_U = len([w for w in neighbors[u] if w in U])
                    if score > best_score or (score == best_score and deg_in_U < min_deg_U) or \
                       (score == best_score and deg_in_U == min_deg_U and random.random() < 0.5):
                        best_score = score
                        min_deg_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            # Next color class: uncolored becomes W
            uncolored = W
            color += 1
        return coloring

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        if n == 0:
            return []
        # Peeling order: remove min degree vertex repeatedly
        degrees = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will be peeled order (first peeled first in list)
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # find unremoved vertex with min degree
            v = -1
            min_deg = float('inf')
            for i in range(n):
                if not removed[i] and degrees[i] < min_deg:
                    min_deg = degrees[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # decrease degree of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    degrees[u] -= 1
        # Color in reverse peeling order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Ensure coloring uses consecutive colors
        coloring = compact_colors(coloring)
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest downward
        improved = True
        while improved and k > 1:
            improved = False
            # Try to remove the last color (k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already compacted?
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used_by_neighbors |= (1 << coloring[u])
                for c in range(target_color):  # try colors 0..k-2
                    if not (used_by_neighbors & (1 << c)):
                        # can move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from scratch after any change

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component of v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap invalid)
                    has_adj_c = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            has_adj_c = True
                            break
                    if has_adj_c:
                        continue  # swapping would cause conflict

                    # Build the Kempe chain: connected component of v in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Swap colors c and target_color in the component
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = target_color
                        elif coloring[node] == target_color:
                            coloring[node] = c
                    # After swap, check if v is now color c (it should be, since we swapped)
                    if coloring[v] == c:
                        improved = True
                        break  # break color loop
                    # else, revert swap? Actually, we don't revert because we want to try other vertices
                    # But to be safe, we revert if not helpful? However, we break on success.
                    # For simplicity, we revert the swap if it didn't help v, to keep state clean for next tries.
                    if not improved:
                        # revert the swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                if improved:
                    break  # break vertex loop
            if improved:
                # compact colors and try again
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
            else:
                # cannot reduce further
                break
        return coloring

    # Run all heuristics with time budget
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # List of heuristic functions
    heuristics = [dsatur, rlf, smallest_last]

    for heuristic in heuristics:
        # Check time
        if time.time() - start_time > 0.04:  # leave 10ms for reduction
            break
        coloring = heuristic()
        if not is_valid(coloring):
            # fallback: should not happen, but just in case
            continue
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]
        # Early exit if we hit lower bound (clique size or max degree+1 not easily computed)
        # but we can't compute clique quickly, so skip

    # If no heuristic worked (should not happen), use greedy
    if best_coloring is None:
        best_coloring = [0] * n
        for i in range(n):
            used = 0
            for nb in neighbors[i]:
                if best_coloring[nb] != -1:
                    used |= (1 << best_coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            best_coloring[i] = c

    # Apply Kempe reduction to try to improve
    if time.time() - start_time < 0.045:
        reduced = kempe_reduce(best_coloring)
        if is_valid(reduced):
            k_red = num_colors(reduced)
            if k_red < best_k:
                best_coloring = reduced
                best_k = k_red

    # Final validation and compaction
    if not is_valid(best_coloring):
        # Last resort: greedy sequential
        best_coloring = [-1] * n
        for i in range(n):
            used = 0
            for nb in neighbors[i]:
                if best_coloring[nb] != -1:
                    used |= (1 << best_coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            best_coloring[i] = c
    best_coloring = compact_colors(best_coloring)

    return best_coloring

import math
