def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        adj_list = adj

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: compute degree (number of neighbors)
    def degree(u):
        return bit_adj[u].bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            mask = bit_adj[u]
            while mask:
                v = (mask & -mask).bit_length() - 1
                if coloring[v] == cu:
                    return False
                mask &= mask - 1
        return True

    # Helper: count distinct colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor masks for each vertex
        colored_mask = [0] * n

        # Order vertices by degree descending for initial tie-breaking in degree
        order = list(range(n))
        order.sort(key=lambda u: degree(u), reverse=True)

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree (uncolored subgraph), then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in order:
                if coloring[u] != -1:
                    continue
                if sat[u] > max_sat:
                    max_sat = sat[u]
                    max_deg = degree(u)  # degree in full graph, but we want uncolored subgraph degree
                    # Recompute degree in uncolored subgraph: neighbors that are uncolored
                    uncolored_mask = 0
                    for w in range(n):
                        if coloring[w] == -1:
                            uncolored_mask |= (1 << w)
                    deg_uncolored = (bit_adj[u] & uncolored_mask).bit_count()
                    max_deg = deg_uncolored
                    v = u
                elif sat[u] == max_sat:
                    # compute degree in uncolored subgraph
                    uncolored_mask = 0
                    for w in range(n):
                        if coloring[w] == -1:
                            uncolored_mask |= (1 << w)
                    deg_uncolored = (bit_adj[u] & uncolored_mask).bit_count()
                    if deg_uncolored > max_deg:
                        max_deg = deg_uncolored
                        v = u
                    elif deg_uncolored == max_deg:
                        if u < v:  # tie-break by index
                            v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by colored neighbors
            neighbor_colors = 0
            mask = bit_adj[v]
            while mask:
                w = (mask & -mask).bit_length() - 1
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
                mask &= mask - 1
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation for uncolored neighbors of v
            mask = bit_adj[v]
            while mask:
                w = (mask & -mask).bit_length() - 1
                if coloring[w] == -1:
                    sat[w] += 1
                mask &= mask - 1

        return compact_colors(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: (bit_adj[u] & sum((1 << w) for w in uncolored)).bit_count())
            S.add(v)
            # Partition uncolored - {v} into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in U:
                if bit_adj[u] & (1 << v):
                    W.add(u)
                else:
                    # u not adjacent to v, so still in U
                    pass
            # Actually, we need to recompute U and W properly: U = vertices in uncolored not adjacent to any in S
            # W = vertices in uncolored adjacent to at least one in S
            U = set()
            W = set()
            for u in uncolored:
                if u in S:
                    continue
                adjacent = False
                for s in S:
                    if bit_adj[u] & (1 << s):
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_common = -1
                min_deg_U = float('inf')
                for u in U:
                    # common neighbors with W
                    common = 0
                    mask = bit_adj[u]
                    w_mask = 0
                    for w in W:
                        w_mask |= (1 << w)
                    common = (mask & w_mask).bit_count()
                    # degree in U-induced subgraph
                    u_mask = 0
                    for w in U:
                        u_mask |= (1 << w)
                    deg_U = (mask & u_mask).bit_count()
                    if common > max_common:
                        max_common = common
                        min_deg_U = deg_U
                        best_u = u
                    elif common == max_common:
                        if deg_U < min_deg_U:
                            min_deg_U = deg_U
                            best_u = u
                        elif deg_U == min_deg_U:
                            if u < best_u:
                                best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                mask = bit_adj[best_u]
                while mask:
                    w = (mask & -mask).bit_length() - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    mask &= mask - 1

            # Assign color to all vertices in S
            for u in S:
                coloring[u] = color
            color += 1
            # Remove S from uncolored
            uncolored -= S

        return compact_colors(coloring)

    # Smallest-Last (SL) ordering greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # will be removal order
        # We'll compute degrees in the remaining graph dynamically
        deg = [degree(u) for u in range(n)]
        # We need to update degrees as we remove vertices
        # Use bucket sort like approach, but n <= 100, so we can do O(n^2)
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            mask = bit_adj[v]
            while mask:
                w = (mask & -mask).bit_length() - 1
                if w in remaining:
                    deg[w] -= 1
                mask &= mask - 1

        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            mask = bit_adj[v]
            while mask:
                w = (mask & -mask).bit_length() - 1
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
                mask &= mask - 1
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return compact_colors(coloring)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        current = coloring[:]
        k = count_colors(current)
        # Try to reduce from k down to 1
        improved = True
        while improved and k > 1:
            improved = False
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [u for u in range(n) if current[u] == target_color]
            if not target_vertices:
                # Already compacted?
                current = compact_colors(current)
                k = count_colors(current)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                mask = bit_adj[v]
                while mask:
                    w = (mask & -mask).bit_length() - 1
                    if current[w] != -1:
                        neighbor_colors |= (1 << current[w])
                    mask &= mask - 1
                # Find smallest color not in neighbor_colors
                c = 0
                while c < target_color and (neighbor_colors & (1 << c)):
                    c += 1
                if c < target_color:
                    # Can recolor directly
                    current[v] = c
                    improved = True
                    break  # break to restart from color reduction
                else:
                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        # Check if v is adjacent to any vertex of color c
                        has_neighbor_c = False
                        mask = bit_adj[v]
                        while mask:
                            w = (mask & -mask).bit_length() - 1
                            if current[w] == c:
                                has_neighbor_c = True
                                break
                            mask &= mask - 1
                        if has_neighbor_c:
                            continue  # Kempe chain swap would not help if adjacent
                        # Build the (c, target_color) Kempe chain containing v
                        # We'll BFS/DFS over vertices colored c or target_color
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        while queue:
                            u = queue.popleft()
                            component.add(u)
                            # Traverse to neighbors with color c or target_color
                            mask = bit_adj[u]
                            while mask:
                                w = (mask & -mask).bit_length() - 1
                                if current[w] == c or current[w] == target_color:
                                    if w not in visited:
                                        visited.add(w)
                                        queue.append(w)
                                mask &= mask - 1
                        # Swap colors c and target_color in the component
                        for u in component:
                            if current[u] == c:
                                current[u] = target_color
                            elif current[u] == target_color:
                                current[u] = c
                        # After swap, check if v is no longer target_color (should be c now)
                        if current[v] != target_color:
                            improved = True
                            break  # break to restart
                    if improved:
                        break
            if improved:
                # Compact colors after any change
                current = compact_colors(current)
                k = count_colors(current)
        return current

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate, fallback to simple greedy
    if not candidates:
        coloring = [-1] * n
        order = list(range(n))
        order.sort(key=lambda u: degree(u), reverse=True)
        for v in order:
            neighbor_colors = 0
            mask = bit_adj[v]
            while mask:
                w = (mask & -mask).bit_length() - 1
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
                mask &= mask - 1
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(compact_colors(coloring))

    # Select the candidate with the fewest colors
    best = min(candidates, key=lambda col: count_colors(col))
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid_coloring(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    best = compact_colors(best)
    return best

