def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    n = len(adj)
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        # Check if it's a binary matrix
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            # Compute forbidden colors from neighbors
            forbidden = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    forbidden |= (1 << color[v])
            # Find smallest available color (MEX)
            c = 0
            while forbidden & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Precompute degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        # Track saturation: for each vertex, bitmask of colors used by colored neighbors
        saturation = [0] * n
        # Set of uncolored vertices
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, break ties by degree in uncolored subgraph, then randomly
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v].bit_count()
                if sat_v > best_sat:
                    best_sat = sat_v
                    best_v = v
                    best_deg = 0
                    # Compute degree in uncolored subgraph
                    for u in adj_list[v]:
                        if u in uncolored:
                            best_deg += 1
                elif sat_v == best_sat:
                    # Compute degree in uncolored subgraph
                    deg_v = 0
                    for u in adj_list[v]:
                        if u in uncolored:
                            deg_v += 1
                    if deg_v > best_deg:
                        best_deg = deg_v
                        best_v = v
                    elif deg_v == best_deg:
                        # Break tie randomly
                        if random.random() < 0.5:
                            best_v = v
                            best_deg = deg_v
            v = best_v
            uncolored.remove(v)
            # Assign smallest available color
            forbidden = saturation[v]
            c = 0
            while forbidden & (1 << c):
                c += 1
            color[v] = c
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set.add(v)
            # Partition: U = vertices not adjacent to any in independent_set, W = others
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in independent_set:
                    if w in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add vertices from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = -1
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if w_neighbors > best_w_neighbors:
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                    elif w_neighbors == best_w_neighbors:
                        if deg_u < best_deg_u:
                            best_deg_u = deg_u
                            best_u = u
                        elif deg_u == best_deg_u:
                            if random.random() < 0.5:
                                best_u = u
                                best_deg_u = deg_u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
            # Remove colored vertices from uncolored
            uncolored -= independent_set
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        # Current degree in remaining graph
        current_deg = deg[:]
        # Remaining vertices
        remaining = set(range(n))
        order = []  # removal order
        for _ in range(n):
            # Find vertex with min current degree
            v = min(remaining, key=lambda x: current_deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    current_deg[u] -= 1
        # Color in reverse removal order
        return greedy_color(list(reversed(order)))

    # Kempe chain swap attempt for a vertex
    def kempe_swap_attempt(coloring, v, target_color):
        current_color = coloring[v]
        if target_color == current_color:
            return True
        # Check if target_color is available directly (no neighbor has it)
        for u in adj_list[v]:
            if coloring[u] == target_color:
                break
        else:
            # Direct reassignment possible
            coloring[v] = target_color
            return True
        # Try Kempe chain swap between current_color and target_color
        # We'll try to find the component of v in the subgraph induced by {current_color, target_color}
        # and see if we can swap without pulling other target_color vertices into current_color's class
        # We do BFS to get the component
        from collections import deque
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            node = queue.popleft()
            component.append(node)
            for nb in adj_list[node]:
                if not visited[nb] and (coloring[nb] == current_color or coloring[nb] == target_color):
                    visited[nb] = True
                    queue.append(nb)
        # Check if any neighbor of the component has target_color (would cause conflict if we swap)
        # Actually, after swap, vertices in component with current_color become target_color and vice versa.
        # So we need to ensure that no vertex in the component that is currently target_color has a neighbor
        # outside the component that is target_color (because after swap it becomes current_color, and if neighbor is target_color, then edge between current_color and target_color is ok, but wait...)
        # Let's think: after swap, a vertex in component that was target_color becomes current_color.
        # Its neighbors: if a neighbor is in component and was target_color -> becomes current_color: same color -> conflict? 
        # But wait, if two adjacent vertices are both in the component and both were target_color, after swap both become current_color -> conflict.
        # However, the component is defined by the subgraph of vertices with colors in {current_color, target_color}. 
        # If two adjacent vertices are both in the component and both have target_color, then they are adjacent and same color -> but the original coloring is valid, so this cannot happen.
        # Similarly, two adjacent vertices both with current_color cannot happen.
        # Therefore, the only edges in the component are between current_color and target_color.
        # After swapping, edges become between target_color and current_color -> still valid.
        # However, we must also consider edges from the component to outside.
        # Consider a vertex x in component that is currently target_color. After swap, it becomes current_color.
        # Its neighbors outside the component: 
        #   - If a neighbor y has color target_color: then after swap, x is current_color and y is target_color -> ok.
        #   - If a neighbor y has color current_color: then after swap, x is current_color and y is current_color -> conflict.
        #   - If a neighbor y has other color: no problem.
        # Similarly, a vertex x in component that is currently current_color becomes target_color.
        #   - Neighbor y outside with color current_color: after swap, x is target_color, y is current_color -> ok.
        #   - Neighbor y outside with color target_color: after swap, x is target_color, y is target_color -> conflict.
        # Therefore, to avoid conflict, we require:
        #   - No vertex in the component that is currently target_color has a neighbor outside the component with color current_color.
        #   - No vertex in the component that is currently current_color has a neighbor outside the component with color target_color.
        # But note: if such a neighbor exists, it means that the Kempe chain is not maximal? Actually, our BFS should have included all vertices reachable via alternating colors.
        # However, if there is an edge from a target_color vertex in the component to a current_color vertex outside, then that outside vertex should have been included in the component (because we traverse from target_color to current_color). 
        # Similarly, the other way.
        # Therefore, by the definition of the component (connected via alternating colors), there should be no such edges.
        # Hence, the swap is always safe? 
        # Actually, the standard Kempe chain swap for two colors in a valid coloring always preserves validity when swapping a connected component.
        # So we can simply swap the colors in the component.
        for node in component:
            if coloring[node] == current_color:
                coloring[node] = target_color
            else:
                coloring[node] = current_color
        return True

    # Try to reduce colors by eliminating the highest color class
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try from highest color down to 1
        for target_color in range(k-1, 0, -1):
            # Get vertices with this color
            vertices = [i for i in range(n) if coloring[i] == target_color]
            # Try to recolor each vertex to a lower color
            made_change = False
            for v in vertices:
                # Try all lower colors in order
                for c in range(target_color):
                    # Save current state in case we need to backtrack
                    original_color_v = coloring[v]
                    # Try direct assignment or Kempe swap
                    if kempe_swap_attempt(coloring, v, c):
                        made_change = True
                        break  # move to next vertex
                    else:
                        # Restore if swap failed (though our kempe_swap_attempt doesn't fail currently)
                        coloring[v] = original_color_v
                if made_change:
                    break  # break outer loop to restart from highest color (since coloring changed)
            if made_change:
                # Restart reduction from highest color again
                return reduce_colors(coloring)
        # If no changes, try to compact colors (though we assume colors are 0..k-1)
        return coloring

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except:
        pass

    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except:
        pass

    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid(col3):
            candidates.append(col3)
    except:
        pass

    # If no candidates, fall back to simple greedy
    if not candidates:
        col_greedy = greedy_color(list(range(n)))
        if is_valid(col_greedy):
            candidates.append(col_greedy)

    # Select the candidate with fewest colors
    best = min(candidates, key=num_colors) if candidates else [0]*n

    # Apply color reduction via Kempe chains
    best = reduce_colors(best)

    # Ensure colors are compact (0..k-1)
    # Map colors to consecutive integers
    if best:
        unique_colors = sorted(set(best))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best = [mapping[c] for c in best]

    return best

