                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                uncolored.remove(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in uncolored and w in U:
                        U.remove(w)
                        W.add(w)
