    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Precompute neighbor sets and degrees
    neighbor_sets = [set(neighbors) for neighbors in adj_list]
    degrees = [len(neighbors) for neighbors in adj_list]

    # Triangle counting
    triangle_count = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            if v > u:
                common = neighbor_sets[u] & neighbor_sets[v]
                for w in common:
                    if w > v:
                        triangle_count[u] += 1
                        triangle_count[v] += 1
                        triangle_count[w] += 1

    # Heuristic 1: DSATUR with triangle-aware tie-breaking
    def dsatur():
        color = [-1] * n
        colored = [False] * n
        # saturation: set of colors used by colored neighbors
        saturation = [set() for _ in range(n)]
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then triangle count, then index
            v = -1
            max_sat = -1
            max_deg = -1
            max_tri = -1
            for u in range(n):
                if not colored[u]:
                    sat = len(saturation[u])
                    if sat > max_sat or (sat == max_sat and (degrees[u] > max_deg or (degrees[u] == max_deg and (triangle_count[u] > max_tri or (triangle_count[u] == max_tri and u > v))))):
                        max_sat = sat
                        max_deg = degrees[u]
                        max_tri = triangle_count[u]
                        v = u
            if v == -1:
                break
            # find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            colored[v] = True
            # update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if not colored[nb]:
                    saturation[nb].add(c)
        return color

    # Heuristic 2: RLF with triangle-aware independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (len([nb for nb in adj_list[x] if nb in uncolored]), triangle_count[x], degrees[x], x))
            S.add(v)
            uncolored.remove(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any(nb in S for nb in adj_list[u])}
            W = uncolored - U
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U, then triangle count, then index
                u = max(U, key=lambda x: (len([nb for nb in adj_list[x] if nb in W]), -len([nb for nb in adj_list[x] if nb in U]), -triangle_count[x], x))
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            for vertex in S:
                color[vertex] = c
            c += 1
        return color

    # Heuristic 3: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # degeneracy ordering
        remaining = set(range(n))
        degree_in_subgraph = [len([nb for nb in adj_list[v] if nb in remaining]) for v in range(n)]
        order = []
        # we will store the order in which vertices are removed (smallest last)
        # we need to update degrees as we remove vertices
        deg = degree_in_subgraph[:]
        removed = [False] * n
        for _ in range(n):
            # find vertex with minimum degree in remaining graph
            v = -1
            min_deg = n + 1
            for u in range(n):
                if not removed[u] and deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # update degrees of neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    deg[nb] -= 1
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used.add(color[nb])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Run all heuristics and pick best
    candidates = []
    for heuristic in [dsatur, rlf, smallest_last]:
        col = heuristic()
        # validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            unique_colors = len(set(col))
            candidates.append((unique_colors, col))
    if not candidates:
        # fallback: greedy by degree
        order = sorted(range(n), key=lambda x: (-degrees[x], -triangle_count[x], x))
        color = [-1] * n
        for v in order:
            used = set()
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used.add(color[nb])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        candidates.append((len(set(color)), color))
    # select candidate with minimal colors
    best = min(candidates, key=lambda x: x[0])[1]
    # compact colors to 0..k-1
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    compacted = [mapping[c] for c in best]
    # final validation (should be valid)
    for u in range(n):
        for v in adj_list[u]:
            if compacted[u] == compacted[v]:
                # in case of error, return greedy fallback
                order = sorted(range(n), key=lambda x: (-degrees[x], -triangle_count[x], x))
                color = [-1] * n
                for v in order:
                    used = set()
                    for nb in adj_list[v]:
                        if color[nb] != -1:
                            used.add(color[nb])
                    c = 0
                    while c in used:
                        c += 1
                    color[v] = c
                return color
    return compacted

