def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in adj_list[i]:
                mask |= (1 << j)
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in adj_list[i]:
                mask |= (1 << j)
            bit_adj[i] = mask

    # Ensure symmetry
    for i in range(n):
        for j in adj_list[i]:
            if i not in adj_list[j]:
                adj_list[j].append(i)
                bit_adj[j] |= (1 << i)

    best_coloring = None
    best_k = float('inf')

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets for saturation update
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)

            # tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    deg = sum(1 for u in adj_list[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
                    elif deg == max_deg and v < best_v:
                        best_v = v
                v = best_v
            else:
                v = candidates[0]

            # assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1

        return normalize(coloring)

    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = None
            for v in uncolored:
                deg = sum(1 for u in adj_list[v] if u in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
                elif deg == max_deg and v < v0:
                    v0 = v
            if v0 is None:
                break

            independent_set = {v0}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = set(uncolored)
            U.remove(v0)
            W = set()
            for u in adj_list[v0]:
                if u in U:
                    U.remove(u)
                    W.add(u)

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = sum(1 for nb in adj_list[u] if nb in U)
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = sum(1 for nb in adj_list[u] if nb in U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                        elif deg_in_U == min_deg_in_U and u < best_u:
                            best_u = u

                if best_u is None:
                    break  # should not happen

                independent_set.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # assign color to independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[v]) for v in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)

        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    # remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]

        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already empty, compact
                coloring = [c if c < target_color else c - 1 for c in coloring]
                k -= 1
                improved = True
                continue

            # Try to recolor each target vertex
            for v in target_vertices[:]:  # copy as we may modify
                # Try direct reassignment to lower color
                used_by_neighbors = set()
                for u in adj_list[v]:
                    if coloring[u] != -1 and coloring[u] < target_color:
                        used_by_neighbors.add(coloring[u])
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        # direct move possible
                        coloring[v] = c
                        target_vertices.remove(v)
                        improved = True
                        break
                if improved:
                    break  # restart scanning

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find (c, target_color) Kempe chain containing v
                    # BFS to get component
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    component = set()
                    while queue:
                        node = queue.popleft()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (coloring[nb] == c or coloring[nb] == target_color):
                                    queue.append(nb)

                    # Check if swapping frees color c for v
                    # After swap, v would have color c
                    # Check if any neighbor of v has color c (they shouldn't in the component)
                    # Actually, in the component, neighbors of v with color c are included, so after swap they become target_color
                    # So we need to ensure no neighbor outside the component has color c
                    can_swap = True
                    for nb in adj_list[v]:
                        if nb not in component and coloring[nb] == c:
                            can_swap = False
                            break
                    if can_swap:
                        # perform swap: c <-> target_color in component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        # now v has color c
                        coloring[v] = c
                        target_vertices.remove(v)
                        improved = True
                        break
                if improved:
                    break

            # If no improvement, try to see if target color class can be eliminated by checking if it's empty
            if not improved:
                # Re-check if any vertex still has target color
                still_has = any(coloring[v] == target_color for v in range(n))
                if not still_has:
                    coloring = [c if c < target_color else c - 1 for c in coloring]
                    k -= 1
                    improved = True

        return normalize(coloring)

    # Generate candidate colorings
    candidates = []

    # DSATUR
    start = time.time()
    col_dsatur = dsatur()
    if time.time() - start < 0.05:  # time check
        candidates.append(col_dsatur)

    # RLF
    start = time.time()
    col_rlf = rlf()
    if time.time() - start < 0.05:
        candidates.append(col_rlf)

    # Smallest-Last
    start = time.time()
    col_sl = smallest_last()
    if time.time() - start < 0.05:
        candidates.append(col_sl)

    # Evaluate candidates
    for col in candidates:
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]

    # Fallback: greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Apply Kempe reduction to best candidate
    if best_coloring is not None:
        best_coloring = kempe_reduce(best_coloring)

    # Final validation and normalization
    if not is_valid(best_coloring):
        # emergency fallback: greedy
        order = list(range(n))
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Convert input to adjacency list and bitmask representation
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue  # skip invalid indices
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if n > 0 else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: 1-opt local search
    def local_search_1opt(coloring):
        improved = True
        best_coloring = coloring[:]
        best_k = count_colors(best_coloring)
        while improved:
            improved = False
            for v in range(n):
                used = 0
                for u in adj_list[v]:
                    c = best_coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(best_k + 1):  # try current max + 1
                    if not (used & (1 << c)):
                        old_c = best_coloring[v]
                        if old_c == c:
                            continue
                        best_coloring[v] = c
                        if is_valid(best_coloring):
                            new_k = count_colors(best_coloring)
                            if new_k < best_k:
                                best_k = new_k
                                improved = True
                                break  # break color loop, restart vertex loop
                        best_coloring[v] = old_c  # revert
                if improved:
                    break  # break vertex loop to restart
        return best_coloring

    # Generate multiple orderings with random perturbations
    vertices = list(range(n))
    degrees = [len(adj_list[i]) for i in range(n)]
    orderings = []

    # 1. Degree descending
    orderings.append(sorted(vertices, key=lambda x: (-degrees[x], x)))
    # 2. Degree ascending
    orderings.append(sorted(vertices, key=lambda x: (degrees[x], x)))
    # 3. Random
    orderings.append(random.sample(vertices, n))
    # 4. Degree descending + random tie-break
    orderings.append(sorted(vertices, key=lambda x: (-degrees[x], random.random())))
    # 5. Randomized degree descending (shuffle same-degree groups)
    deg_groups = {}
    for v in vertices:
        d = degrees[v]
        deg_groups.setdefault(d, []).append(v)
    order5 = []
    for d in sorted(deg_groups.keys(), reverse=True):
        group = deg_groups[d][:]
        random.shuffle(group)
        order5.extend(group)
    orderings.append(order5)
    # 6. Saturation degree inspired initial order (approximate)
    orderings.append(sorted(vertices, key=lambda x: (-degrees[x], -sum(degrees[u] for u in adj_list[x])), ))
    # 7-10: More random variations
    for _ in range(4):
        orderings.append(random.sample(vertices, n))

    # Evaluate all orderings with greedy + local search
    best_coloring = None
    best_k = float('inf')
    for order in orderings:
        col = greedy_color(order)
        if not is_valid(col):
            continue  # should not happen, but safeguard
        col = local_search_1opt(col)
        if not is_valid(col):
            continue
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # Fallback: if no valid coloring found (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        if not is_valid(best_coloring):
            # emergency fix: assign each vertex a unique color
            best_coloring = list(range(n))

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    compacted = [0] * n
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        compacted[i] = unique_colors[c]

    return compacted

