        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build independent set for current color
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in get_neighbors(x) if nb in uncolored))
            S.add(v)
            uncolored.remove(v)

            # Partition: U (eligible), W (ineligible)
            U = set()
            W = set()
            for nb in get_neighbors(v):
                if nb in uncolored:
                    W.add(nb)
            for u in uncolored:
                if u not in W:
                    U.add(u)

            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = -1
                for u in U:
                    w_neighbors = sum(1 for nb in get_neighbors(u) if nb in W)
                    deg_U = sum(1 for nb in get_neighbors(u) if nb in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_U < best_deg_U) or (w_neighbors == best_w_neighbors and deg_U == best_deg_U and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                uncolored.remove(u)
                U.remove(u)

                # Move neighbors of u from U to W
                for nb in get_neighbors(u):
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to S
            for v in S:
                colors[v] = color_idx
