    # Smallest-Last (SL) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        degrees = [get_degree(i) for i in range(n)]
        adj_sets = [set(get_neighbors(i)) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for i in range(n):
            d = degrees[i]
            if d < n:
                buckets[d].append(i)

        for _ in range(n):
            # Find non-empty bucket with smallest degree
            d = 0
            while d < n and not buckets[d]:
                d += 1
            if d >= n:
                break
            v = buckets[d].pop()
            while removed[v]:
                if not buckets[d]:
                    d += 1
                    while d < n and not buckets[d]:
                        d += 1
                    if d >= n:
                        break
                    v = buckets[d].pop()
                else:
                    break
            if removed[v]:
                break
            removed[v] = True
            order.append(v)
            for nb in get_neighbors(v):
                if not removed[nb]:
                    d_nb = degrees[nb]
                    degrees[nb] -= 1
                    if degrees[nb] < n:
                        buckets[degrees[nb]].append(nb)

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for nb in get_neighbors(v):
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain swap for (a,b) component containing v
    def kempe_swap(coloring, a, b, v):
        n_local = len(coloring)
        visited = [False] * n_local
        stack = [v]
        component = []
        while stack:
            node = stack.pop()
            if visited[node]:
                continue
            visited[node] = True
            component.append(node)
            for nb in get_neighbors(node):
                if not visited[nb] and (coloring[nb] == a or coloring[nb] == b):
                    stack.append(nb)
        # Swap colors in component
        for node in component:
            if coloring[node] == a:
                coloring[node] = b
            elif coloring[node] == b:
                coloring[node] = a
        return coloring

    # Kempe-based color reduction
    def reduce_colors_kempe(initial_coloring):
        if n == 0:
            return initial_coloring
        best = initial_coloring[:]
        improved = True
        while improved:
            improved = False
            # Try to eliminate the last color class
            max_color = max(best) if best else -1
            if max_color < 0:
                break
            # Vertices with color max_color
            verts = [i for i in range(n) if best[i] == max_color]
            if not verts:
                # Already compacted
                best = compact_colors(best)
                continue
            # Try to recolor each vertex in this class
            for v in verts:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for nb in get_neighbors(v):
                    if best[nb] != -1:
                        neighbor_colors.add(best[nb])
                for c in range(max_color):
                    if c not in neighbor_colors:
                        best[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(max_color):
                    # Check if v can take color c via Kempe swap
                    # Temporarily consider swapping along (c, max_color) chain
                    # Find component of v in subgraph of colors c and max_color
                    stack = [v]
                    visited = [False] * n
                    component = []
                    can_swap = True
                    while stack:
                        node = stack.pop()
                        if visited[node]:
                            continue
                        visited[node] = True
                        component.append(node)
                        for nb in get_neighbors(node):
                            if not visited[nb] and (best[nb] == c or best[nb] == max_color):
                                stack.append(nb)
                    # Check if any neighbor in component has color c (would cause conflict after swap)
                    conflict = False
                    for node in component:
                        for nb in get_neighbors(node):
                            if best[nb] == c and nb not in component:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if best[node] == c:
                                best[node] = max_color
                            elif best[node] == max_color:
                                best[node] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                best = compact_colors(best)
        return best

    # Run all heuristics
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to simple greedy
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = set()
            for nb in get_neighbors(i):
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[i] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best_candidate = min(candidates, key=lambda x: len(set(x)) if x else 0)

    # Apply Kempe reduction to improve
    try:
        improved = reduce_colors_kempe(best_candidate)
        if is_valid_coloring(improved):
            best_candidate = improved
    except:
        pass

    # Final validation and compaction
    if not is_valid_coloring(best_candidate):
        # Fallback to DSATUR if invalid
        best_candidate = dsatur()
        if not is_valid_coloring(best_candidate):
            # Ultimate fallback: greedy
            colors = [-1] * n
            for i in range(n):
                used = set()
                for nb in get_neighbors(i):
                    if colors[nb] != -1:
                        used.add(colors[nb])
                c = 0
                while c in used:
                    c += 1
                colors[i] = c
            best_candidate = compact_colors(colors)

    return compact_colors(best_candidate)

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if binary entries
        is_matrix = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bit masks
    if is_matrix:
        neighbors = []
        bit_adj = [0] * n
        for u in range(n):
            row = []
            mask = 0
            for v in range(n):
                if adj[u][v] == 1:
                    row.append(v)
                    mask |= (1 << v)
            neighbors.append(row)
            bit_adj[u] = mask
    else:
        neighbors = adj
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in neighbors[u]:
                mask |= (1 << v)
            bit_adj[u] = mask

    # Helper to compute degree
    def degree(u):
        return len(neighbors[u])

    # Helper to check if coloring is valid
    def is_valid_coloring(col):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True

    # Helper to normalize colors to 0..k-1
    def normalize(col):
        if not col:
            return col
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bit masks for efficiency
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = sum(1 for u in neighbors[v] if u in uncolored)
                elif sat == best_sat:
                    deg = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:  # random tie-break
                            best_v = v
            v = best_v
            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # Add color c to u's neighbor colors if not present
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return normalize(color)

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build maximal independent set for current_color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to independent_set (ineligible)
            U = uncolored - {v}
            W = set()
            for u in neighbors[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    score = sum(1 for w in neighbors[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_in_U = sum(1 for x in neighbors[u] if x in U)
                    elif score == best_score:
                        deg_in_U = sum(1 for x in neighbors[u] if x in U)
                        if deg_in_U < best_deg_in_U:
                            best_deg_in_U = deg_in_U
                            best_u = u
                        elif deg_in_U == best_deg_in_U:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                color[v] = current_color
                uncolored.remove(v)
            current_color += 1

        return normalize(color)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree_in_remaining = [degree(u) for u in range(n)]
        order = []
        # Buckets for degrees
        max_deg = max(degree_in_remaining) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            d = degree_in_remaining[u]
            buckets[d].append(u)
        # Pointer to current min degree
        min_deg = 0
        while remaining:
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree_in_remaining[u]
                    # remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree_in_remaining[u] -= 1
                    d_new = degree_in_remaining[u]
                    if d_new < len(buckets):
                        buckets[d_new].append(u)
                    else:
                        # extend buckets if needed
                        while len(buckets) <= d_new:
                            buckets.append([])
                        buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return normalize(color)

    # Kempe chain color reduction
    def kempe_reduce(color_in):
        color = color_in[:]
        if not is_valid_coloring(color):
            return color  # should not happen

        # Try to eliminate color classes from highest downward
        changed = True
        while changed:
            changed = False
            max_color = max(color) if color else -1
            for target_color in range(max_color, 0, -1):
                # Get vertices with target_color
                targets = [i for i, c in enumerate(color) if c == target_color]
                if not targets:
                    continue
                # Try to recolor each target vertex
                eliminated = True
                for v in targets:
                    # Check if can move to a lower color directly
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if color[u] != -1:
                            neighbor_colors.add(color[u])
                    found = False
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            color[v] = c
                            found = True
                            break
                    if found:
                        continue
                    # Try Kempe chains with each lower color
                    kempe_found = False
                    for c in range(target_color):
                        # If v already has color c due to prior swap in this loop, skip
                        if color[v] == c:
                            kempe_found = True
                            break
                        # Check if v is connected to color c via Kempe chain
                        # We'll try to swap in the component of v in (target_color, c) subgraph
                        # Only if v is not already in that color
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        # Build component of v in colors {target_color, c}
                        while queue:
                            node = queue.popleft()
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (color[nb] == target_color or color[nb] == c):
                                    visited.add(nb)
                                    queue.append(nb)
                        # Check if any neighbor of v in component has color c? Actually, we want to see
                        # if swapping frees color c for v. After swap, v will have color c.
                        # We need to ensure that no neighbor of v has color c after swap.
                        # After swap, neighbors in component that had color c will become target_color,
                        # and those with target_color become c.
                        # So v's neighbors that are in component and had color c will become target_color (not c).
                        # Neighbors not in component keep their color.
                        # So we need that no neighbor of v has color c after swap.
                        # That is: for all neighbors u of v:
                        #   if u in component: after swap, color becomes (target_color if was c else c)
                        #   so if u in component and had color c, becomes target_color != c (since target_color > c)
                        #   if u in component and had target_color, becomes c -> conflict if u is neighbor of v
                        #   if u not in component: color unchanged.
                        # Therefore, conflict occurs if:
                        #   there exists neighbor u of v such that:
                        #     (u in component and color[u] == target_color) OR
                        #     (u not in component and color[u] == c)
                        conflict = False
                        for u in neighbors[v]:
                            if color[u] == c and u not in component:
                                conflict = True
                                break
                            if color[u] == target_color and u in component:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap
                            for node in component:
                                if color[node] == target_color:
                                    color[node] = c
                                elif color[node] == c:
                                    color[node] = target_color
                            kempe_found = True
                            break
                    if kempe_found:
                        continue
                    # If we couldn't recolor v, this color class cannot be eliminated yet
                    eliminated = False
                    break
                if eliminated:
                    # Successfully eliminated target_color: remap colors above down by one
                    for i in range(n):
                        if color[i] > target_color:
                            color[i] -= 1
                    changed = True
                    break  # restart from highest color
        return normalize(color)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        color = [-1] * n
        for u in range(n):
            used = 0
            for v in neighbors[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        candidates.append(normalize(color))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda c: (max(c) + 1 if c else 0))
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation (should be valid)
    if not is_valid_coloring(best):
        # Fallback to simple greedy
        color = [-1] * n
        for u in range(n):
            used = 0
            for v in neighbors[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        best = normalize(color)
    return best

