def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                neighbors[i].add(j)
                bit_adj[i] |= (1 << j)

    # Ensure symmetry for undirected graph
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # DSATUR algorithm
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n

        # initial vertex: highest degree
        v = max(range(n), key=lambda x: len(neighbors[x]))
        color[v] = 0
        # update neighbors of v
        for u in neighbors[v]:
            neighbor_color_mask[u] |= (1 << 0)
            saturation[u] = bit_count(neighbor_color_mask[u])

        for _ in range(1, n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = [-1] * n  # -1 for colored, else saturation
            for i in range(n):
                if color[i] == -1:
                    candidates[i] = saturation[i]

            max_sat = max(candidates)
            if max_sat == -1:  # should not happen
                break

            # get vertices with max saturation
            max_vertices = [i for i in range(n) if candidates[i] == max_sat]
            # tie-break by degree in uncolored subgraph
            if len(max_vertices) > 1:
                max_vertices.sort(key=lambda x: len([y for y in neighbors[x] if color[y] == -1]), reverse=True)
                # if still tie, random shuffle
                if len(max_vertices) > 1 and len(set(len([y for y in neighbors[x] if color[y] == -1]) for x in max_vertices)) == 1:
                    random.shuffle(max_vertices)
            v = max_vertices[0]

            # find smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # update neighbors
            for u in neighbors[v]:
                if color[u] == -1:  # only update uncolored neighbors
                    neighbor_color_mask[u] |= (1 << c)
                    saturation[u] = bit_count(neighbor_color_mask[u])

        return color

    # RLF algorithm
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            # build independent set for color c
            independent_set = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            independent_set.add(v)
            # partition: U = vertices not adjacent to any in independent_set, W = adjacent
            U = {x for x in uncolored if x not in independent_set and not any(y in independent_set for y in neighbors[x])}
            W = {x for x in uncolored if x not in independent_set and x not in U}

            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                def score(u):
                    num_w = len([y for y in neighbors[u] if y in W])
                    deg_u = len([y for y in neighbors[u] if y in U])
                    return (num_w, -deg_u)  # max num_w, min deg_u
                u = max(U, key=score)
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)

            # assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1

        return color

    # Smallest-Last (Matula-Beck) greedy
    def smallest_last():
        # degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # removal order
        deg = [len(neighbors[i]) for i in range(n)]
        # we need to update degrees as we remove vertices
        # use bucket sort for efficiency, but n<=100 so simple is fine
        temp_remaining = set(range(n))
        temp_deg = deg[:]
        while temp_remaining:
            # find vertex with min degree in temp_remaining
            v = min(temp_remaining, key=lambda x: temp_deg[x])
            order.append(v)
            temp_remaining.remove(v)
            for u in neighbors[v]:
                if u in temp_remaining:
                    temp_deg[u] -= 1
