        for target_color in range(max_color, 0, -1):
            # get vertices with target_color
            verts = [i for i in range(n) if color[i] == target_color]
            if not verts:
                continue  # already empty

            # try to recolor each vertex in this class
            changed = True
            while changed and verts:
                changed = False
                # we'll try to recolor one vertex at a time
                for v in verts[:]:  # iterate over copy
                    if color[v] != target_color:
                        continue  # already recolored
                    # try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if color[u] != -1:
                            neighbor_colors.add(color[u])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            color[v] = c
                            changed = True
                            verts.remove(v)
