                independent_set.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for neighbor in adj_list[best_u]:
                    if neighbor in U:
                        U.remove(neighbor)
                        W.add(neighbor)

            # Assign color to independent_set
            for u in independent_set:
                colors[u] = color_idx
            uncolored -= set(independent_set)
            color_idx += 1

        return normalize(colors)

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        if n == 0:
            return []
        # Build core ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []  # will be removal order
        # We need to update degrees as we remove vertices
        # Use bucket sort for efficiency, but n<=100 so we can do simple
        temp_degree = degree[:]  # copy
        remaining_set = set(remaining)
        for _ in range(n):
            # Find vertex with min degree in remaining_set
            v = -1
            min_deg = float('inf')
            for u in remaining_set:
                if temp_degree[u] < min_deg:
                    min_deg = temp_degree[u]
                    v = u
                elif temp_degree[u] == min_deg:
                    if v == -1 or u < v:
                        v = u
            if v == -1:
                break
            order.append(v)
            remaining_set.remove(v)
            # Update neighbors' degrees
            for neighbor in adj_list[v]:
                if neighbor in remaining_set:
                    temp_degree[neighbor] -= 1

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for neighbor in adj_list[v]:
                if colors[neighbor] != -1:
                    c = colors[neighbor]
                    if c <= n:
                        used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c

        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make sure coloring is normalized
        coloring = normalize(coloring)
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        # We'll try to reduce the number of colors by eliminating the last color
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [i for i in range(n) if coloring[i] == target_color]
            if not target_vertices:
                # Should not happen if normalized, but safety
                coloring = [c if c < target_color else c-1 for c in coloring]
                k -= 1
                improved = True
                continue

            # Try to recolor each target vertex
            # We'll attempt to move each vertex to a lower color if possible
            # Use Kempe chains for swapping
            made_change = False
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] < target_color:  # only consider colors we might swap to
                        neighbor_colors.add(coloring[u])
                # Find smallest color not in neighbor_colors
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Direct move possible
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Check if v can be swapped to color c via Kempe chain
                    # We consider the subgraph induced by colors c and target_color
                    # Find the Kempe chain containing v in the (c, target_color) subgraph
                    # If the chain does not contain any vertex of color c that is adjacent to v? 
                    # Actually, we want to swap the component of v in the (c, target_color) subgraph
                    # After swap, v becomes color c, and we free target_color for v only if
                    # no neighbor of v is in the component and colored c? 
                    # Standard: if in the (c, target_color) component of v, there is no neighbor of v 
                    # that is colored c and outside the component? 
                    # Simpler: we can swap the component if it does not cause conflict.
                    # We'll build the component and check if after swap, v's neighbors don't have color c.
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for neighbor in adj_list[node]:
                            if neighbor not in visited:
                                col_neighbor = coloring[neighbor]
                                if col_neighbor == c or col_neighbor == target_color:
                                    visited.add(neighbor)
                                    queue.append(neighbor)
                    # Now, check if any neighbor of v is in the component and has color c? 
                    # Actually, after swap, v becomes c. We need to ensure no neighbor of v is c after swap.
                    # Neighbors of v that are in the component: if they are colored target_color, they become c -> conflict.
                    # Neighbors of v that are not in the component: if they are colored c, they remain c -> conflict.
                    # So we need: 
                    #   - No neighbor of v in the component is colored target_color (because they become c)
                    #   - No neighbor of v not in the component is colored c (because they stay c)
                    # But note: v itself is in the component and colored target_color -> after swap becomes c, which is fine.
                    conflict = False
                    for neighbor in adj_list[v]:
                        if neighbor in component:
                            if coloring[neighbor] == target_color:
                                conflict = True
                                break
                        else:
                            if coloring[neighbor] == c:
                                conflict = True
                                break
                    if not conflict:
                        # Perform swap: swap colors c and target_color in the component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        made_change = True
                        break
                if made_change:
                    break

            if made_change:
                # Re-normalize and update k
                coloring = normalize(coloring)
                k_new = num_colors(coloring)
                if k_new < k:
                    k = k_new
                    improved = True
                else:
                    # Should not happen, but break to avoid infinite loop
                    break
            else:
                # Could not eliminate target_color, break
                break

        return coloring

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    # List of heuristic functions
    heuristics = [dsatur, rlf, smallest_last]

    for heuristic in heuristics:
        try:
            coloring = heuristic()
            if not is_valid_coloring(coloring):
                # Fallback: if invalid, try to fix by greedy? but should not happen
                # For now, skip invalid
                continue
            k = num_colors(coloring)
            if k < best_k or (k == best_k and best_coloring is None):
                best_k = k
                best_coloring = coloring
        except Exception:
            # In case of error, skip this heuristic
            continue

    # If all heuristics failed (should not happen), use a simple greedy
    if best_coloring is None:
        # Simple greedy by vertex order
        colors = [-1] * n
        for v in range(n):
            used = [False] * (n + 1)
            for neighbor in adj_list[v]:
                if colors[neighbor] != -1:
                    c = colors[neighbor]
                    if c <= n:
                        used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
        best_coloring = normalize(colors)

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < num_colors(best_coloring):
                best_coloring = improved
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))

    return normalize(best_coloring)

