def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj
    degrees = [len(adj_list[i]) for i in range(n)]
    # Convert adjacency list to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask
    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True
    # Helper: Welsh-Powell ordering (descending degree)
    def wp_order():
        return sorted(range(n), key=lambda x: degrees[x], reverse=True)
    # Helper: Smallest-Last ordering
    def sl_order():
        if n == 0:
            return []
        rem = set(range(n))
        deg = degrees[:]
        order = []
        for _ in range(n):
            # find vertex with min degree in rem
            v = min(rem, key=lambda x: deg[x])
            order.append(v)
            rem.remove(v)
            for u in adj_list[v]:
                if u in rem:
                    deg[u] -= 1
        return order[::-1]  # reverse
    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then index
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                if s > best_sat:
                    best_sat = s
                    best_v = v
                    best_deg = sum(1 for u in adj_list[v] if u in uncolored)
                elif s == best_sat:
                    deg_uncolored = sum(1 for u in adj_list[v] if u in uncolored)
                    if deg_uncolored > best_deg:
                        best_deg = deg_uncolored
                        best_v = v
                    elif deg_uncolored == best_deg and v < best_v:
                        best_v = v
            v = best_v
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color
    # Helper: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for u in adj_list[x] if u in uncolored))
            S = {v}
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((adj_list[u] & (1 << w)) for w in S):  # adjacent to S
                    W.add(u)
                else:
                    U.add(u)
            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    if w_neighbors > best_w_neighbors:
                        best_w_neighbors = w_neighbors
                        best_u = u
                        best_deg_U = sum(1 for x in adj_list[u] if x in U)
                    elif w_neighbors == best_w_neighbors:
                        deg_U = sum(1 for x in adj_list[u] if x in U)
                        if deg_U < best_deg_U:
                            best_deg_U = deg_U
                            best_u = u
                        elif deg_U == best_deg_U and u < best_u:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u in U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass
    # Welsh-Powell
    try:
        col_wp = greedy_color(wp_order())
        if is_valid(col_wp):
            candidates.append(col_wp)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = greedy_color(sl_order())
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass
    # If no candidate (should not happen), fallback to trivial
    if not candidates:
        # greedy in order 0..n-1
        col = greedy_color(list(range(n)))
        candidates.append(col)
    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            colors = sorted(classes.keys())
            k = len(colors)
            # Try to eliminate the smallest color class (largest color index)
            if k <= 1:
                break
            target_color = colors[-1]  # largest color index
            # Try to recolor each vertex in target_color
            for v in classes[target_color]:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    neighbor_colors.add(col[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build the (c, target_color) Kempe chain containing v
                    # BFS/DFS over vertices colored c or target_color
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if col[node] == c or col[node] == target_color:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (col[nb] == c or col[nb] == target_color):
                                    stack.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see if swapping frees color c for v
                    # After swap, v would get color c if it is in the component and currently has target_color.
                    # We need to ensure that no neighbor of v has color c after swap.
                    # Currently, neighbors of v have colors in neighbor_colors.
                    # After swapping the component, a neighbor u of v that is in the component will have its color flipped.
                    # So if u is in component and currently has color c, after swap it becomes target_color -> no conflict.
                    # If u is in component and currently has target_color, after swap it becomes c -> conflict if u is neighbor of v.
                    # Therefore, we can swap only if no neighbor of v that is in the component has color target_color (because after swap it becomes c and conflicts with v's new color c).
                    # Actually, we are going to recolor v to c, so we need that after swap, no neighbor of v has color c.
                    # Let's compute: after swap, for a neighbor u of v:
                    #   if u in component: new color = c if old was target_color, else target_color if old was c.
                    #   if u not in component: color unchanged.
                    # We need that for all neighbors u of v, new color != c.
                    # So condition: for all neighbors u of v:
                    #   if u in component: then old color of u must not be target_color (because then it becomes c)
                    #   if u not in component: then old color of u must not be c.
                    safe = True
                    for u in adj_list[v]:
                        if u in component:
                            if col[u] == target_color:
                                safe = False
                                break
                        else:
                            if col[u] == c:
                                safe = False
                                break
                    if safe:
                        # perform swap
                        for node in component:
                            if col[node] == c:
                                col[node] = target_color
                            else:  # must be target_color
                                col[node] = c
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                break
            # Rebuild color classes and compact if needed
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            colors = sorted(classes.keys())
            # Compact colors to 0..k-1
            mapping = {old: new for new, old in enumerate(colors)}
            col = [mapping[c] for c in col]
        return col
    # Apply Kempe reduction
    best = kempe_reduce(best)
    # Final validation (should be valid)
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
    return best

