            color += 1

        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # We'll compute the ordering by repeatedly removing min degree vertex
        # Works on the current graph (unremoved vertices)
        remaining = set(range(n))
        order = []  # will be removal order
        # Current degree in the remaining subgraph
        degree = [0] * n
        for i in range(n):
            degree[i] = sum(1 for j in adj_list[i] if j in remaining)

        # We'll use a list of sets for bucket sort by degree
        max_deg = n
        buckets = [set() for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].add(i)

        # Pointer to current min non-empty bucket
        min_deg = 0

        for _ in range(n):
            # Find first non-empty bucket from min_deg upwards
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # no vertices left
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = degree[u]
                    new_deg = old_deg - 1
                    # Move u from old bucket to new bucket
                    buckets[old_deg].remove(u)
                    buckets[new_deg].add(u)
                    degree[u] = new_deg
                    if new_deg < min_deg:
                        min_deg = new_deg

        # Now color in reverse order (last removed first)
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        col = coloring[:]
        changed = True
        # We'll try to reduce colors until no improvement
        while changed:
            changed = False
            k = num_colors(col)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Vertices with target color
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                # Already normalized, should not happen
                break

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    if col[u] != -1:
                        neighbor_colors |= (1 << col[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # Can recolor v to c
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # After recoloring one vertex, we break to restart the scan
                    # because the color class changed
                    break

            if changed:
                # Renormalize and continue
                col = normalize(col)
                continue

            # If no direct reassignment, try Kempe chains
            for v in target_vertices:
                # For each lower color c
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (target_color, c)
                    # We consider the subgraph induced by colors target_color and c
                    # Find the Kempe chain containing v in this subgraph
                    # If the chain does not contain any vertex of color c that is adjacent to a vertex of color target_color outside the chain? 
                    # Actually, we can swap the chain if it doesn't cause conflict.
                    # Standard: swap the connected component of v in the (target_color, c) subgraph.
                    # After swap, v will have color c, and we need to check that no neighbor of v has color c (but since we swap, neighbors that were target_color become c and vice versa)
                    # Actually, after swap, the neighbors of v that were in the component and had color target_color become c, and those with color c become target_color.
                    # So for v to be safely recolored to c, we need that after swap, no neighbor has color c.
                    # But note: neighbors of v that are in the component and had color c will become target_color, so they are not c anymore.
                    # Neighbors not in the component keep their color.
                    # So the only potential issue is if there is a neighbor of v that is not in the component and has color c.
                    # Because after swap, that neighbor remains c, and v becomes c -> conflict.
                    # Therefore, we can swap the component if and only if no neighbor of v outside the component has color c.

                    # Build the component: all vertices reachable from v via alternating colors target_color and c
                    from collections import deque
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    while q:
                        node = q.popleft()
                        for nb in adj_list[node]:
                            if nb in comp:
                                continue
                            if col[nb] == target_color or col[nb] == c:
                                comp.add(nb)
                                q.append(nb)

                    # Check if any neighbor of v outside comp has color c
                    conflict = False
                    for nb in adj_list[v]:
                        if nb not in comp and col[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: in component, swap target_color <-> c
                        for node in comp:
                            if col[node] == target_color:
                                col[node] = c
                            elif col[node] == c:
                                col[node] = target_color
                        changed = True
                        col = normalize(col)
                        break
                if changed:
                    break
            if changed:
                continue
            # If we couldn't recolor any vertex in target color, we cannot reduce
            break

        return col

    # Time budget management
    start_time = time.time()
    time_limit = 0.05  # 50 ms

    best_coloring = None
    best_k = float('inf')

    # Run DSATUR
    if time.time() - start_time < time_limit:
        c = dsatur()
        if is_valid(c):
            k = num_colors(c)
            if k < best_k:
                best_k = k
                best_coloring = c

    # Run RLF
    if time.time() - start_time < time_limit:
        c = rlf()
        if is_valid(c):
            k = num_colors(c)
            if k < best_k:
                best_k = k
                best_coloring = c

    # Run Smallest-Last
    if time.time() - start_time < time_limit:
        c = smallest_last()
        if is_valid(c):
            k = num_colors(c)
            if k < best_k:
                best_k = k
                best_coloring = c

    # Apply Kempe reduction to the best so far
    if best_coloring is not None and time.time() - start_time < time_limit:
        c = kempe_reduce(best_coloring[:])
        if is_valid(c):
            k = num_colors(c)
            if k < best_k:
                best_k = k
                best_coloring = c

    # Fallback: if nothing worked, use greedy by node order
    if best_coloring is None:
        coloring = [-1] * n
        for i in range(n):
            neighbor_colors = 0
            for j in adj_list[i]:
                if coloring[j] != -1:
                    neighbor_colors |= (1 << coloring[j])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[i] = c
        best_coloring = normalize(coloring)

    return best_coloring

