    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        deg = [bin(bit_adj[i]).count('1') for i in range(n)]
        while uncolored:
            # Find vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # Compute used colors from neighbors
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] == -1:
                    sat[u] += 1
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in uncolored if (bit_adj[x] >> u) & 1))
            S = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any((bit_adj[s] >> u) & 1 for s in S)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (sum(1 for w in W if (bit_adj[x] >> w) & 1), -sum(1 for y in U if (bit_adj[x] >> y) & 1)))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs = {w for w in U if (bit_adj[u] >> w) & 1}
                U -= nbrs
                W |= nbrs
            for vertex in S:
                color[vertex] = c
            c += 1
            uncolored = W
        return color

    # 3. Smallest-Last (SL) ordering greedy
    def smallest_last():
        # Compute degeneracy ordering
        deg = [bin(bit_adj[i]).count('1') for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = deg[v]
        # Peeling
        for _ in range(n):
            # Find min degree vertex in remaining
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            while buckets[d] and (buckets[d][-1] not in remaining):
                buckets[d].pop()
            if not buckets[d]:
                d += 1
                while d <= max_deg and not buckets[d]:
                    d += 1
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    # Decrease degree of u
                    old_deg = pos[u]
                    pos[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)
                    if pos[u] <= max_deg:
                        buckets[pos[u]].append(u)
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            # Validate
            valid = True
            for u in range(n):
                for v in range(u + 1, n):
                    if ((bit_adj[u] >> v) & 1) and col[u] == col[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                k = max(col) + 1 if col else 0
                if k < best_k:
                    best_k = k
                    best_colors = col[:]
        except Exception:
            continue

    # Fallback: if no candidate succeeded, use greedy by index
    if best_colors is None:
        best_colors = greedy_color(list(range(n)))
        best_k = max(best_colors) + 1 if best_colors else 0

    # Kempe chain color reduction
    def kempe_reduce(color):
        nonlocal best_k
        changed = True
        while changed and best_k > 0:
            changed = False
            # Find smallest color class
            classes = [[] for _ in range(best_k)]
            for v in range(n):
                if color[v] < best_k:
                    classes[color[v]].append(v)
            # Try to eliminate color classes from highest to lowest
            for c in range(best_k - 1, -1, -1):
                if not classes[c]:
                    # Already empty, shift down
                    for v in range(n):
                        if color[v] > c:
                            color[v] -= 1
                    best_k -= 1
                    changed = True
                    classes = [[] for _ in range(best_k)]
                    for v in range(n):
                        if color[v] < best_k:
                            classes[color[v]].append(v)
                    break  # Restart after shift
                # Try to recolor each vertex in class c
                for v in classes[c][:]:
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1 and color[u] != -1:
                            used |= (1 << color[u])
                    for c2 in range(c):
                        if not (used & (1 << c2)):
                            color[v] = c2
                            changed = True
                            # Update classes
                            classes[c].remove(v)
                            classes[c2].append(v)
                            break
                    if changed:
                        break
                    # Try Kempe chains with each lower color
                    for c2 in range(c):
                        # BFS to find Kempe chain of colors c and c2 containing v
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in range(n):
                                if (bit_adj[x] >> y) & 1 and not visited[y]:
                                    if color[y] == c or color[y] == c2:
                                        visited[y] = True
                                        queue.append(y)
                        # Check if we can swap: no neighbor of component has color c2 outside component
                        can_swap = True
                        for x in component:
                            for y in range(n):
                                if (bit_adj[x] >> y) & 1 and color[y] == c2 and y not in component:
                                    can_swap = False
                                    break
                            if not can_swap:
                                break
                        if can_swap:
                            # Swap colors c and c2 in component
                            for x in component:
                                if color[x] == c:
                                    color[x] = c2
                                elif color[x] == c2:
                                    color[x] = c
                            changed = True
                            # Update classes
                            classes[c] = [x for x in classes[c] if x not in component]
                            classes[c2] = [x for x in classes[c2] if x not in component]
                            for x in component:
                                if color[x] == c:
                                    classes[c].append(x)
                                elif color[x] == c2:
                                    classes[c2].append(x)
                            break
                    if changed:
                        break
                if changed:
                    break
            # End for c
        return color

    if best_colors is not None:
        best_colors = kempe_reduce(best_colors)
        # Final validation and compaction
        # Ensure colors are consecutive
        used_colors = set(best_colors)
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        best_colors = [mapping[c] for c in best_colors]
        best_k = len(used_colors)

    return best_colors

