def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix or list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        adj = adj_list
    else:
        # Ensure adjacency list format (make a copy to avoid side effects)
        adj = [list(neighbors) for neighbors in adj]

    # Precompute neighbor bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj[u]:
            bit_adj[u] |= (1 << v)

    # Helper: compute number of colors used in a coloring
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colors as bitmask for fast saturation update
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > best_sat:
                    best_sat = sat_v
                    best_v = v
                    best_deg = sum(1 for u in adj[v] if u in uncolored)
                elif sat_v == best_sat:
                    deg_v = sum(1 for u in adj[v] if u in uncolored)
                    if deg_v > best_deg:
                        best_deg = deg_v
                        best_v = v
                    elif deg_v == best_deg:
                        if random.random() < 0.5:  # random tie-break
                            best_v = v
