    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass
    # If no candidate (should not happen), assign all zeros (invalid but safe)
    if not candidates:
        return [0] * n

    # Select candidate with minimal number of colors
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Iterative color reduction via Kempe chains and direct reassignment
    improved = True
    while improved and k > 1:
        improved = False
        # Target the last color (k-1)
        target_color = k - 1
        # Vertices with target color
        target_vertices = [v for v in range(n) if best[v] == target_color]
        if not target_vertices:
            # Should not happen, but skip
            break
        # Try to recolor each target vertex
        for v in target_vertices:
