        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            col = coloring[u]
            if col == a:
                comp_color_a.add(u)
            elif col == b:
                comp_color_b.add(u)
            for w in neighbors[u]:
                if w not in visited and coloring[w] in (a, b):
                    stack.append(w)
