            # Partition remaining uncolored into U (eligible) and W (ineligible)
            # Ineligible: adjacent to any vertex in independent_set
            ineligible = set()
            for vtx in independent_set:
                for u in adj_list[vtx]:
                    if u in uncolored:
                        ineligible.add(u)
            eligible = uncolored - ineligible

            # Greedily add vertices from eligible that have most neighbors in ineligible
            while eligible:
                # Select u in eligible with max |N(u) ∩ ineligible|
                best_u = -1
                max_w_neighbors = -1
                min_deg_eligible = float('inf')
                for u in eligible:
                    # Count neighbors in ineligible
                    w_count = 0
                    for w in adj_list[u]:
                        if w in ineligible:
                            w_count += 1
                    # Tie-break: min degree in eligible subgraph
                    deg_in_eligible = 0
                    for w in adj_list[u]:
                        if w in eligible:
                            deg_in_eligible += 1
                    if w_count > max_w_neighbors or \
                       (w_count == max_w_neighbors and deg_in_eligible < min_deg_eligible) or \
                       (w_count == max_w_neighbors and deg_in_eligible == min_deg_eligible and random.random() < 0.5):
                        max_w_neighbors = w_count
                        min_deg_eligible = deg_in_eligible
                        best_u = u
                if best_u == -1:
                    break  # should not happen if eligible not empty
                # Add best_u to independent set
                independent_set.add(best_u)
                eligible.remove(best_u)
                # Move best_u from eligible to ineligible (since it's now in independent set)
                # Actually, we need to move its neighbors from eligible to ineligible
                for u in adj_list[best_u]:
                    if u in eligible:
                        eligible.remove(u)
                        ineligible.add(u)
                    elif u in uncolored and u not in independent_set and u not in ineligible:
                        # u is in uncolored but not yet classified; it should go to ineligible now
                        ineligible.add(u)
                # Update degrees: removing best_u from uncolored affects its uncolored neighbors
                for u in adj_list[best_u]:
                    if u in uncolored:
                        deg_uncolored[u] -= 1
                uncolored.remove(best_u)

            # Assign color to independent set
            for vtx in independent_set:
                colors[vtx] = color_idx
            color_idx += 1

        return normalize(colors)

    # Smallest-Last (SL) ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees for peeling
        deg = [len(adj_list[i]) for i in range(n)]
        # Remaining vertices
        remaining = set(range(n))
        order = []  # will store vertices in order of removal (smallest last)

        while remaining:
            # Find vertex with minimum degree in remaining subgraph
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    deg[u] -= 1

        # Color in reverse order (largest last first)
        colors = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        best = coloring[:]
        improved = True
        # Try to reduce colors iteratively
        while improved:
            improved = False
            k = num_colors(best)
            if k <= 1:
                break
            # Try to eliminate color k-1
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [i for i in range(n) if best[i] == target_color]
            if not target_vertices:
                # Should not happen if k is correct
                break

            # Try to recolor each target vertex
            # We'll try to move them to lower colors if possible
            # Make a copy to modify
            current = best[:]
            success = True
            for v in target_vertices:
                # Try direct reassignment to a lower color
                moved = False
                # Try colors from 0 to target_color-1
                for c in range(target_color):
                    # Check if color c is available (no neighbor has color c)
                    conflict = False
                    for u in adj_list[v]:
                        if best[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Also need to ensure that after moving, we don't create conflict
                        # But since we check neighbors, it's safe
                        current[v] = c
                        moved = True
                        break
                if not moved:
                    # Try Kempe chain swap with each lower color
                    kempe_success = False
                    for c in range(target_color):
                        # We'll try to swap colors c and target_color in the Kempe chain of v
                        # Only if v is not adjacent to any vertex of color c (otherwise swap might not help directly)
                        # Actually, we can try to find the Kempe chain component containing v in colors {c, target_color}
                        # and see if swapping frees color c for v
                        # But standard approach: if v has no neighbor of color c, we can try to swap in the component
                        # However, if v has a neighbor of color c, swapping might pull that neighbor to target_color
                        # We'll do: find the connected component of v in the subgraph induced by colors c and target_color
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for u in adj_list[node]:
                                if not visited[u] and (best[u] == c or best[u] == target_color):
                                    visited[u] = True
                                    queue.append(u)
                        # Check if any neighbor of v has color c (in the original coloring)
                        has_c_neighbor = False
                        for u in adj_list[v]:
                            if best[u] == c:
                                has_c_neighbor = True
                                break
                        # If v has no neighbor of color c, then swapping the component will give v color c
                        if not has_c_neighbor:
                            # Perform swap: c <-> target_color in component
                            for node in component:
                                if best[node] == c:
                                    current[node] = target_color
                                elif best[node] == target_color:
                                    current[node] = c
                            # Now v has color c
                            kempe_success = True
                            break
                    if kempe_success:
                        moved = True
                    else:
                        # Could not move v
                        success = False
                        break
                # If we moved v, we need to update best for next vertices? 
                # But to keep it simple, we break and retry with the new coloring
                # Instead, we'll apply all moves and then check validity
            if success and is_valid(current):
                # Update best and try to reduce further
                best = current[:]
                improved = True
            else:
                # If not successful, break
                break
        return best

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to trivial greedy
    if not candidates:
        # Simple greedy by vertex order
        colors = [-1] * n
        for i in range(n):
            used = set()
            for u in adj_list[i]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[i] = c
        candidates.append(normalize(colors))

    # Select candidate with fewest colors
    best_candidate = min(candidates, key=lambda x: num_colors(x))

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best_candidate)
        if is_valid(improved) and num_colors(improved) <= num_colors(best_candidate):
            best_candidate = improved
    except:
        pass

    # Final validation and normalization
    if not is_valid(best_candidate):
        # Last resort: assign each vertex a unique color
        best_candidate = list(range(n))
    best_candidate = normalize(best_candidate)

    return best_candidate

