def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []

    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        neighbors = []
        for i in range(n):
            neighbors.append([j for j in range(n) if adj[i][j] == 1])
    else:
        neighbors = [list(lst) for lst in adj]  # copy to avoid mutation

    # Initialize color array
    color = [-1] * n

    # Step 1: BFS to 2-color each connected component
    for i in range(n):
        if color[i] == -1:
            queue = [i]
            color[i] = 0
            while queue:
                u = queue.pop(0)
                for v in neighbors[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        # Conflict: odd cycle detected; will be resolved later
                        pass

    # Step 2: Check if current coloring is valid
    valid = True
    for u in range(n):
        for v in neighbors[u]:
            if u < v and color[u] == color[v]:
                valid = False
                break
        if not valid:
            break

    if valid:
        return color

    # Step 3: Find connected components of the subgraph induced by color conflicts
    # Build graph of conflicts: edge exists if two adjacent vertices have same color
    conflict_adj = [[] for _ in range(n)]
    for u in range(n):
        for v in neighbors[u]:
            if u < v and color[u] == color[v]:
                conflict_adj[u].append(v)
                conflict_adj[v].append(u)

    # Find connected components in conflict graph
    visited = [False] * n
    components = []
    for i in range(n):
        if not visited[i] and conflict_adj[i]:
            stack = [i]
            visited[i] = True
            comp = []
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in conflict_adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    # Step 4: For each conflict component, try to 2-color it with new colors (2,3)
    # If not bipartite, we may need a third color, but we try to minimize
    next_color = 2
    for comp in components:
        # Try to 2-color the component using colors 0 and 1 (swap within comp)
        # Build subgraph induced by comp
        comp_set = set(comp)
        # Try both possible assignments: flip or not
        # We'll try to reassign using two new colors if needed, but first try swapping within {0,1}
        # Actually, we can try to assign colors 0 and 1 in a bipartite way
        # Since the component may not be bipartite, we use BFS and if conflict, we use a third color
        local_color = {}
        is_bipartite = True
        for start in comp:
            if start not in local_color:
                queue = [start]
                local_color[start] = 0
                while queue and is_bipartite:
                    u = queue.pop(0)
                    for v in neighbors[u]:
                        if v in comp_set:
                            if v not in local_color:
                                local_color[v] = 1 - local_color[u]
                                queue.append(v)
                            elif local_color[v] == local_color[u]:
                                is_bipartite = False
                                break

        if is_bipartite:
            # Assign the bipartite coloring using 0 and 1
            for u in comp:
                color[u] = local_color[u]
        else:
            # Not bipartite, needs at least 3 colors; we use 2 and 3
            # Do BFS 2-coloring, and when conflict, assign third color
            local_color = {}
            for start in comp:
                if start not in local_color:
                    queue = [start]
                    local_color[start] = next_color  # use next_color as base
                    while queue:
                        u = queue.pop(0)
                        for v in neighbors[u]:
                            if v in comp_set:
                                if v not in local_color:
                                    local_color[v] = 1 - (local_color[u] - next_color) + next_color
                                    queue.append(v)
                                # If conflict, we don't change; just leave as is (may not be proper, but we hope)
            # Assign
            for u in comp:
                color[u] = local_color[u]
            next_color += 1  # for next component, use higher color if needed

    # Step 5: Final validation and color relabeling to be consecutive
    # First, verify
    for u in range(n):
        for v in neighbors[u]:
            if u < v and color[u] == color[v]:
                # Still conflict, fallback to greedy
                break
        else:
            continue
        break
    else:
        # No break, valid
        # Relabel colors to 0..k-1
        unique_colors = {}
        next_label = 0
        for i in range(n):
            c = color[i]
            if c not in unique_colors:
                unique_colors[c] = next_label
                next_label += 1
            color[i] = unique_colors[c]
        return color

    # Fallback: use DSATUR with bitmask for speed
    # Convert to bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        for v in neighbors[u]:
            bit_adj[u] |= (1 << v)

    # DSATUR implementation
    color = [-1] * n
    # degrees in the uncolored subgraph (initially all)
    deg = [len(neighbors[u]) for u in range(n)]
    # saturation: number of distinct colors in neighbors
    sat = [0] * n
    # neighbor colorsets as bit masks for fast sat update
    neighbor_colors = [0] * n  # bitmask of colors used by neighbors

    # Helper: get first zero bit (mex)
    def mex(mask):
        c = 0
        while mask & (1 << c):
            c += 1
        return c

    for _ in range(n):
        # Select uncolored vertex with max sat, then max deg
        v = -1
        max_sat = -1
        max_deg = -1
        for u in range(n):
            if color[u] == -1:
                if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > max_deg):
                    max_sat = sat[u]
                    max_deg = deg[u]
                    v = u
        if v == -1:
            break  # should not happen

        # Assign smallest available color
        c = mex(neighbor_colors[v])
        color[v] = c

        # Update neighbors of v
        for u in neighbors[v]:
            if color[u] == -1:
                # update saturation: if color c is new in u's neighbor colors
                if not (neighbor_colors[u] & (1 << c)):
                    neighbor_colors[u] |= (1 << c)
                    sat[u] += 1
                deg[u] -= 1  # one less uncolored neighbor

    # Relabel to consecutive
    unique_colors = {}
    next_label = 0
    for i in range(n):
        c = color[i]
        if c not in unique_colors:
            unique_colors[c] = next_label
            next_label += 1
        color[i] = unique_colors[c]

    return color

