import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = (len(adj[0]) == n and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = adj

    # Precompute degrees and bitmasks
    deg = [len(neighbors[i]) for i in range(n)]
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= 1 << j
        bit_adj[i] = mask

    # Helper: count bits
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: validate coloring
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(col):
        return max(col) + 1 if col else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(col):
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        colored = [False] * n
        sat = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > max_deg) or \
                   (sat[u] == max_sat and deg[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat[u]
                    max_deg = deg[u]
                    v = u
            # Assign smallest available color
            used = 0
            for nb in neighbors[v]:
                if color[nb] != -1:
                    used |= 1 << color[nb]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            colored[v] = True
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if not colored[nb]:
                    sat[nb] = bit_count(used & bit_adj[nb])
        return compact_colors(color)

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in neighbors[x] if nb in uncolored))
            S.append(v)
            # Partition: U = not adj to S, W = adj to S
            U = uncolored - {v}
            W = set()
            for nb in neighbors[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            # Grow S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = sum(1 for nb in neighbors[u] if nb in W)
                    degU = sum(1 for nb in neighbors[u] if nb in U)
                    if score > best_score or (score == best_score and degU < best_degU) or \
                       (score == best_score and degU == best_degU and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return compact_colors(color)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len([nb for nb in neighbors[i] if nb in remaining]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in neighbors[v]:
                if nb in remaining:
                    old_deg = degree[nb]
                    degree[nb] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(nb)
                    if degree[nb] <= max_deg:
                        buckets[degree[nb]].append(nb)
        # Color in reverse order using First-Fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in neighbors[v]:
                if color[nb] != -1:
                    used |= 1 << color[nb]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return compact_colors(color)

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduce(col):
        nonlocal best_k
        changed = True
        while changed and num_colors(col) > 1:
            changed = False
            k = num_colors(col)
            # Target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for nb in neighbors[v]:
                    if col[nb] != -1:
                        used |= 1 << col[nb]
                for c in range(target_color):
                    if not (used & (1 << c)):
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build (c, target_color)-Kempe component containing v
                    stack = [v]
                    visited = set()
                    comp = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        if col[u] == c or col[u] == target_color:
                            comp.add(u)
                            for nb in neighbors[u]:
                                if col[nb] == c or col[nb] == target_color:
                                    if nb not in visited:
                                        stack.append(nb)
                    # Check if color c is absent in the component's neighborhood
                    # Actually, we can swap if the component does not touch a vertex of color c outside?
                    # Standard: swapping is always valid; we do it and see if it frees target_color for v
                    # Perform swap
                    for u in comp:
                        if col[u] == c:
                            col[u] = target_color
                        elif col[u] == target_color:
                            col[u] = c
                    # After swap, check if v is no longer target_color (should be c now)
                    if col[v] != target_color:
                        changed = True
                        break
                    # Otherwise, swap back (though not strictly necessary if we break on success)
                    for u in comp:
                        if col[u] == c:
                            col[u] = target_color
                        elif col[u] == target_color:
                            col[u] = c
                if changed:
                    break
            if changed:
                # Compact colors after potential removal of a color
                col = compact_colors(col)
        return col

    # Apply Kempe reduction to best candidate
    improved = kempe_reduce(best[:])
    if num_colors(improved) < num_colors(best):
        best = improved

    # Final validation and compact
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    best = compact_colors(best)

    return best

