        uncolored = set(range(n))
        c = 0

        while uncolored:
            # Build independent set for color c
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            to_check = {u for u in adj_list[v] if u in uncolored}
            in_set = {v}

            while to_check:
                # Select vertex with max neighbors in uncolored - independent_set (i.e., in to_check's forbidden)
                # Actually, we want max neighbors in the set of vertices adjacent to independent_set
                forbidden = set()
                for x in independent_set:
                    forbidden.update(y for y in adj_list[x] if y in uncolored)
                # U = uncolored - forbidden
                U = uncolored - forbidden
                if not U:
                    break
                # Select u in U with max neighbors in forbidden, tie-break by min degree in U
                u = None
                max_forb = -1
                min_deg_u = float('inf')
                for x in U:
                    forb_count = sum(1 for y in adj_list[x] if y in forbidden)
                    deg_u = sum(1 for y in adj_list[x] if y in U)
                    if forb_count > max_forb or (forb_count == max_forb and (deg_u < min_deg_u or 
                                                                          (deg_u == min_deg_u and x < (u if u is not None else -1)))):
                        max_forb = forb_count
                        min_deg_u = deg_u
                        u = x
                if u is None:
                    break
                independent_set.add(u)
                in_set.add(u)
                to_check.discard(u)
                to_check.update(y for y in adj_list[u] if y in uncolored and y not in in_set)

            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1

