    try:
        improved = kempe_reduction(best_coloring)
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and improved[u] == improved[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            # Count colors in improved
            k_improved = max(improved) + 1 if improved else 0
            k_best = max(best_coloring) + 1 if best_coloring else 0
            if k_improved < k_best:
                best_coloring = improved
    except:
        pass

    # Final validation and compacting
    # Ensure valid
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Fallback to greedy
                order = sorted(range(n), key=lambda x: (-degree[x], x))
                color = [-1] * n
                for v in order:
                    used = [False] * n
                    for u in adj_list[v]:
                        if color[u] != -1:
                            used[color[u]] = True
                    c = 0
                    while c < n and used[c]:
                        c += 1
                    color[v] = c
                best_coloring = color
                break

    # Compact colors to 0..k-1
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {c: i for i, c in enumerate(sorted(used_colors))]
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

