    # Precompute bitmasks and triangle counts
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Triangle count per vertex: number of triangles incident to u
    tri_count = [0] * n
    for u in range(n):
        neighbors = adj[u]
        deg = len(neighbors)
        for i in range(deg):
            v = neighbors[i]
            for j in range(i + 1, deg):
                w = neighbors[j]
                if w in adj[v]:  # or (bit_adj[v] >> w) & 1
                    tri_count[u] += 1
                    tri_count[v] += 1
                    tri_count[w] += 1
    # Each triangle counted 3 times, but we only need relative ordering, so keep as is

    # Order vertices by triangle count descending, then by degree descending
    order = list(range(n))
    order.sort(key=lambda x: (-tri_count[x], -len(adj[x])))

    # Greedy coloring in this order
    color = [-1] * n
    for u in order:
        used = 0
        for v in adj[u]:
            c = color[v]
            if c != -1:
                used |= 1 << c
        c = 0
        while used & (1 << c):
            c += 1
        color[u] = c

    # Kempe chain based color reduction
    def kempe_reduce(colors):
        if max(colors) < 0:
            return colors
        k = max(colors) + 1
        # Try to eliminate color classes from highest down
        for target_color in range(k - 1, -1, -1):
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            changed = True
            while changed and verts:
                changed = False
                v = verts.pop()
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if all(colors[u] != c for u in adj[v]):
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find (target_color, c)-Kempe chain containing v
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for nb in adj[node]:
                                if not visited[nb] and colors[nb] in (target_color, c):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if any neighbor of the component has color c (would cause conflict if swapped)
                        conflict = False
                        for node in component:
                            for nb in adj[node]:
                                if colors[nb] == c and nb not in component:
                                    conflict = True
                                    break
                            if conflict:
                                break
                        if not conflict:
                            # Perform swap
                            for node in component:
                                colors[node] = c if colors[node] == target_color else target_color
                            changed = True
                            break
            # Rebuild verts list after changes
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                # Successfully eliminated target_color, remap higher colors
                mapping = {}
                new_color = 0
                for orig in range(k):
                    if orig == target_color:
                        continue
                    mapping[orig] = new_color
                    new_color += 1
                for i in range(n):
                    if colors[i] > target_color:
                        colors[i] = mapping[colors[i]]
                return kempe_reduce(colors)  # Recurse to try further reduction
        return colors

    # Apply Kempe reduction
    final_color = kempe_reduce(color[:])

    # Ensure colors are consecutive starting from 0
    unique_colors = sorted(set(final_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    final_color = [mapping[c] for c in final_color]

    return final_color

