def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = (len(adj[0]) == n and 
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1 and i != j]
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Convert to bit masks for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in adj_list[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    def get_neighbors_mask(u):
        return bit_adj[u]

    def count_bits(x):
        return x.bit_count()

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                s = count_bits(sat[v])
                if s > max_sat:
                    max_sat = s
                    candidates = [v]
                elif s == max_sat:
                    candidates.append(v)

            if not candidates:
                break  # should not happen

            # Tie-break by degree in uncolored subgraph
            max_deg = -1
            best_v = candidates[0]
            for v in candidates:
                d = deg_uncolored[v]
                if d > max_deg:
                    max_deg = d
                    best_v = v
                elif d == max_deg and random.random() < 0.5:
                    best_v = v

            v = best_v
            uncolored.remove(v)

            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Update saturation and degrees for neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1

        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
                S.append(v)
                uncolored.remove(v)

            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored)
            W = set()
            for v in S:
                for u in adj_list[v]:
                    if u in uncolored:
                        if u in U:
                            U.remove(u)
                            W.add(u)

            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = len([y for y in adj_list[u] if y in W])
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = len([y for y in adj_list[u] if y in U])
                        deg_best = len([y for y in adj_list[best_u] if y in U]) if best_u is not None else float('inf')
                        if deg_u < deg_best or (deg_u == deg_best and random.random() < 0.5):
                            best_u = u

                if best_u is None:
                    break  # should not happen

                u = best_u
                S.append(u)
                U.remove(u)

                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1

        return color

    # Strategy 3: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))

        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]

        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Strategy 4: Jaccard-based heuristic for non-adjacent pairs
    def jaccard_heuristic():
        # Precompute Jaccard similarity for non-adjacent pairs
        similarities = []
        for i in range(n):
            for j in range(i+1, n):
                if j not in adj_list[i]:  # non-adjacent
                    set_i = set(adj_list[i])
                    set_j = set(adj_list[j])
                    union = set_i | set_j
                    if not union:
                        sim = 0.0
                    else:
                        sim = len(set_i & set_j) / len(union)
                    similarities.append((sim, i, j))

        # Sort by similarity descending
        similarities.sort(key=lambda x: -x[0])

        # Try to assign same color to high-similarity non-adjacent pairs
        color = [-1] * n
        # Process pairs in order of similarity
        for sim, i, j in similarities:
            if color[i] == -1 and color[j] == -1:
                # Try to assign the same smallest available color to both
                used_i = 0
                for u in adj_list[i]:
                    c = color[u]
                    if c != -1:
                        used_i |= (1 << c)
                used_j = 0
                for u in adj_list[j]:
                    c = color[u]
                    if c != -1:
                        used_j |= (1 << c)
                used = used_i | used_j
                c = 0
                while used & (1 << c):
                    c += 1
                # Assign color c to both if it doesn't conflict with already colored neighbors
                # (which we already checked via used mask)
                color[i] = c
                color[j] = c

        # Color remaining uncolored vertices greedily
        order = [v for v in range(n) if color[v] == -1]
        if order:
            # Use DSATUR-like ordering for remainder
            rem_color = greedy_color(order)
            for idx, v in enumerate(order):
                color[v] = rem_color[v]

        return color

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except:
        pass

    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except:
        pass

    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid(col3):
            candidates.append(col3)
    except:
        pass

    # Jaccard heuristic
    try:
        col4 = jaccard_heuristic()
        if is_valid(col4):
            candidates.append(col4)
    except:
        pass

    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: -len(adj_list[x]))
        col5 = greedy_color(order)
        if is_valid(col5):
            candidates.append(col5)
    except:
        pass

    # Select best candidate (fewest colors)
    for col in candidates:
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # If no candidate found (should not happen), use trivial coloring
    if best_coloring is None:
        best_coloring = list(range(n))

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]

    return best_coloring

