                U = uncolored - {v}
                W = set()
                for u in list(U):
                    if any(w in independent_set for w in adj_list[u]):
                        W.add(u)
                        U.remove(u)
                # while U not empty
                while U:
                    # select u in U with max neighbors in W
                    best_u = None
                    max_w_neighbors = -1
                    min_deg_in_U = float('inf')
                    for u in U:
                        w_neighbors = sum(1 for w in adj_list[u] if w in W)
