    best_k = num_colors(best_coloring)

    # If already optimal (lower bound from clique or degree), we could stop, but we try to reduce
    # Kempe chain based color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to free the color
        vertices = [v for v in range(n) if coloring[v] == target_color]
