            # Try to swap with each lower color
            for c in range(target_color):
                # Check if v can be recolored to c via Kempe chain (target_color, c)
                # Build the Kempe chain component containing v in colors {target_color, c}
                from collections import deque
                component = set()
                queue = deque([v])
                component.add(v)
                while queue:
                    node = queue.popleft()
                    for neighbor in adj_list[node]:
                        if neighbor not in component:
                            col_n = new_coloring[neighbor]
                            if col_n == target_color or col_n == c:
                                component.add(neighbor)
                                queue.append(neighbor)
                # Check if any neighbor of v in the component has color c? 
