                # The swap is safe if no neighbor of v has color c after swap? 
                # After swap, vertices in component: target_color <-> c
                # So v becomes c. We need that no neighbor of v has color c after swap.
                # Neighbors of v: if they are in component and had color c, they become target_color -> ok
                # If they are in component and had target_color, they become c -> conflict if adjacent to v? 
                # Actually, after swap, a neighbor u of v:
                #   if u in component and had color c -> becomes target_color (not c)
                #   if u in component and had target_color -> becomes c
                #   if u not in component -> color unchanged
                # So conflict occurs if there exists a neighbor u of v such that:
                #   (u in component and original color target_color) OR (u not in component and original color c)
                # Because after swap, u would have color c in first case, or keep color c in second.
                conflict = False
                for u in adj_list[v]:
                    col_u = new_coloring[u]
                    if (u in component and col_u == target_color) or (u not in component and col_u == c):
                        conflict = True
                        break
                if not conflict:
                    # perform swap
                    for node in component:
                        if new_coloring[node] == target_color:
                            new_coloring[node] = c
                        elif new_coloring[node] == c:
                            new_coloring[node] = target_color
                    # after swap, check if v's color changed to c (it should)
                    # Now check if target_color class is reduced
                    # We break and will check after processing all vertices? 
                    # For simplicity, we break and try to eliminate after this swap
                    break  # break from color loop
            else:
                continue  # only if inner loop didn't break
            break  # break from vertex loop if we did a swap

        # After potential swap, check if target_color is eliminated
        if target_color not in set(new_coloring):
            color_map = {}
            next_color = 0
            for i in range(n):
                col = new_coloring[i]
                if col not in color_map:
                    color_map[col] = next_color
                    next_color += 1
                new_coloring[i] = color_map[col]
            return new_coloring

        # If still not eliminated, return original (should not happen often)
        return coloring

    # Iterative color reduction
    current = best_coloring[:]
    max_steps = 50  # Tabu search steps as per directive
    tabu_tenure = 5
    tabu_list = []  # list of (vertex, color_from, color_to) or just vertex moves?

    # We'll use a simple Tabu search to resolve conflicts if any, but our colorings should be valid
    # Instead, we try to reduce color count
    for _ in range(max_steps):
        k = num_colors(current)
        if k <= 1:
            break
        target_color = k - 1  # try to eliminate the highest color
        new_current = eliminate_color_class(current, target_color)
        if num_colors(new_current) < k:
            current = new_current
            # reset tabu? or continue
        else:
