    # Ensure colors are consecutive starting from 0
    if current:
        color_map = {}
        next_color = 0
        for i in range(n):
            col = current[i]
            if col not in color_map:
                color_map[col] = next_color
                next_color += 1
            current[i] = color_map[col]

    return current

