def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor list
    if is_matrix:
        neighbors = [ [j for j, val in enumerate(row) if val] for row in adj ]
    else:
        neighbors = [ list(lst) for lst in adj ]

    # Precompute degree
    degree = [len(neighbors[i]) for i in range(n)]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Strategy 1: Static degree ordering (descending)
    order1 = sorted(range(n), key=lambda x: (-degree[x], x))
    color1 = greedy_color(order1)

    # Strategy 2: Static degree ordering (ascending)
    order2 = sorted(range(n), key=lambda x: (degree[x], x))
    color2 = greedy_color(order2)

    # Strategy 3: Dynamic degree ordering with neighbor discount
    colored = [False] * n
    dyn_order = []
    # We maintain a dynamic score: degree minus number of colored neighbors
    dyn_score = degree[:]  # initial score is degree
    for _ in range(n):
        # Select uncolored vertex with maximum dyn_score
        v = -1
        max_score = -1
        for i in range(n):
            if not colored[i] and dyn_score[i] > max_score:
                max_score = dyn_score[i]
                v = i
            elif not colored[i] and dyn_score[i] == max_score:
                if v == -1 or degree[i] > degree[v]:
                    v = i
        if v == -1:
            break  # should not happen
        dyn_order.append(v)
        colored[v] = True
        # Update scores of uncolored neighbors: subtract 1
        for u in neighbors[v]:
            if not colored[u]:
                dyn_score[u] -= 1

    color3 = greedy_color(dyn_order)

    # Strategy 4: DSATUR-inspired: dynamic saturation degree
    color = [-1] * n
    # saturation: number of distinct colors in neighbors
    saturation = [0] * n
    # neighbor color sets for saturation update
    neighbor_colors = [set() for _ in range(n)]
    for _ in range(n):
        # Select uncolored vertex with max saturation, tie-break by degree
        v = -1
        max_sat = -1
        for i in range(n):
            if color[i] == -1:
                if saturation[i] > max_sat:
                    max_sat = saturation[i]
                    v = i
                elif saturation[i] == max_sat:
                    if v == -1 or degree[i] > degree[v]:
                        v = i
        if v == -1:
            break
        # Find smallest available color
        used = [False] * n
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c
        # Update saturation of uncolored neighbors
        for u in neighbors[v]:
            if color[u] == -1:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1

    color4 = color

    # Collect all candidate colorings
    candidates = [color1, color2, color3, color4]
    # Filter valid ones
    valid_candidates = []
    for col in candidates:
        if all(col[u] != col[v] for u in range(n) for v in neighbors[u] if u < v):
            valid_candidates.append(col)

    if not valid_candidates:
        # fallback: greedy by index
        valid_candidates = [greedy_color(list(range(n)))]

    # Choose the one with minimal number of colors
    best = min(valid_candidates, key=count_colors)
    return best

