            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set.append(v)
            # U: vertices in uncolored not adjacent to v
            # W: vertices in uncolored adjacent to v
            U = uncolored - {v} - set(graph[v])
            W = set(graph[v]) & uncolored

            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = -1  # degree in U for tie-break
                for u in U:
                    # Count neighbors of u in W
                    w_neighbors = 0
                    for y in graph[u]:
                        if y in W:
                            w_neighbors += 1
                    # Degree in U
                    u_deg = 0
                    for y in graph[u]:
                        if y in U:
                            u_deg += 1
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or \
                       (w_neighbors == best_w_neighbors and u_deg == best_u_deg and (best_u == -1 or random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                independent_set.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in graph[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
            # Remove independent set from uncolored
            uncolored -= set(independent_set)
            color_idx += 1

        return normalize(colors)

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(graph[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # We'll use bucket sort for efficiency (since n <= 100)
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)

