        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in graph[v]:
                if not removed[u]:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]

        # Color in reverse order (last removed first)
        colors = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by neighbors
            used = [False] * (n + 1)  # safe upper bound
            for u in graph[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while used[c]:
                c += 1
            colors[v] = c

        return normalize(colors)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (shouldn't happen), fall back to greedy
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for j in graph[i]:
                if colors[j] != -1:
                    used[colors[j]] = True
            c = 0
            while used[c]:
                c += 1
            colors[i] = c
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: count_colors(x))

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        k = count_colors(coloring)
        # Try to eliminate color classes from highest downward
        for target_color in range(k-1, -1, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each target vertex
            made_change = False
            for v in target_vertices[:]:  # work on copy
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if coloring[u] < target_color:  # only consider colors we might reassign to
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
