                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    # After reassigning v, we might have emptied target_color class
                    # But continue to try to empty the whole class
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component containing v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap would cause conflict)
                    has_c_neighbor = any(coloring[u] == c for u in graph[v])
                    if has_c_neighbor:
                        continue  # swapping would put two c's together
                    # Build the Kempe chain: connected component of v in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    valid = True
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in graph[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any node in component has a neighbor with color c (outside component) that would cause conflict if swapped
                    # Actually, after swap, nodes originally color c become target_color and vice versa.
                    # Conflict would occur if a node in component (originally c) has a neighbor outside component that is target_color,
                    # or a node in component (originally target_color) has a neighbor outside component that is c.
                    # But we already know v has no c neighbor (has_c_neighbor false). Need to check others.
                    conflict = False
                    for node in component:
