def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        # Validate binary entries
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bit masks
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for v in adj[i]:
                neighbors[i].add(v)

    # Ensure undirected (symmetric)
    for i in range(n):
        for j in list(neighbors[i]):
            neighbors[j].add(i)

    # Convert to bit masks for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Helper: count bits in mask
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: get degree in subgraph induced by uncolored set
    def degree_in_uncolored(v: int, uncolored_mask: int) -> int:
        return bit_count(bit_adj[v] & uncolored_mask)

    # Helper: saturation degree (number of distinct colors in colored neighbors)
    def saturation_degree(v: int, colors: list[int]) -> int:
        mask = 0
        nb_mask = bit_adj[v]
        u = 0
        while nb_mask:
            if nb_mask & 1:
                if colors[u] != -1:
                    mask |= (1 << colors[u])
            nb_mask >>= 1
            u += 1
        return bit_count(mask)

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        colors = [-1] * n
        uncolored_mask = (1 << n) - 1

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1

            vmask = uncolored_mask
            while vmask:
                v = (vmask & -vmask).bit_length() - 1
                vmask &= vmask - 1

                sat = saturation_degree(v, colors)
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = degree_in_uncolored(v, uncolored_mask)
                elif sat == best_sat:
                    deg = degree_in_uncolored(v, uncolored_mask)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
                            best_deg = deg

            v = best_v
            # Find smallest available color
            used = 0
            nb_mask = bit_adj[v]
            u = 0
            while nb_mask:
                if nb_mask & 1:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                nb_mask >>= 1
                u += 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored_mask &= ~(1 << v)

        return colors

    # RLF: Recursive Largest First (independent set extraction)
    def rlf() -> list[int]:
        colors = [-1] * n
        uncolored_mask = (1 << n) - 1
        color = 0

        while uncolored_mask:
            # Find vertex with max degree in uncolored subgraph
            vmask = uncolored_mask
            best_v = -1
            best_deg = -1
            while vmask:
                v = (vmask & -vmask).bit_length() - 1
                vmask &= vmask - 1
                deg = degree_in_uncolored(v, uncolored_mask)
                if deg > best_deg:
                    best_deg = deg
                    best_v = v

            # Build independent set for this color
            independent_set = 0
            independent_set |= (1 << best_v)
            # W: vertices adjacent to independent set (cannot take this color)
            W = bit_adj[best_v] & uncolored_mask
            # U: vertices not adjacent to independent set (can take this color)
            U = uncolored_mask & ~W & ~(1 << best_v)

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_u = -1
                umask = U
                while umask:
                    u = (umask & -umask).bit_length() - 1
                    umask &= umask - 1
                    # Score: number of neighbors in W
                    score = bit_count(bit_adj[u] & W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_u = degree_in_uncolored(u, U)
                    elif score == best_score:
                        deg_u = degree_in_uncolored(u, U)
                        if deg_u < best_deg_u:
                            best_deg_u = deg_u
                            best_u = u
                        elif deg_u == best_deg_u:
                            if random.random() < 0.5:
                                best_u = u
                                best_deg_u = deg_u

                u = best_u
                independent_set |= (1 << u)
                # Move u from U to independent set, update W and U
                U &= ~(1 << u)
                # Add neighbors of u that are in U to W
                W |= (bit_adj[u] & U)
                # Remove from U any vertices now adjacent to independent set (i.e., in W)
                U &= ~W

            # Assign color to all in independent set
            imask = independent_set
            while imask:
                v = (imask & -imask).bit_length() - 1
                imask &= imask - 1
                colors[v] = color

            uncolored_mask &= ~independent_set
            color += 1

        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # Build core numbers via smallest-last ordering
        remaining = list(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        bucket = [[] for _ in range(n)]
        pos = [0] * n

        for v in range(n):
            d = degree[v]
            bucket[d].append(v)
            pos[v] = len(bucket[d]) - 1

        for d in range(n):
            while bucket[d]:
                # Find non-empty bucket
                while d < n and not bucket[d]:
                    d += 1
                if d >= n:
                    break
                v = bucket[d].pop()
                pos[v] = -1  # removed
                order.append(v)
                # Update neighbors
                for u in neighbors[v]:
                    if pos[u] >= 0:  # still in remaining
                        du = degree[u]
                        # remove u from bucket[du]
                        idx = pos[u]
                        last = bucket[du][-1]
                        bucket[du][idx] = last
                        pos[last] = idx
                        bucket[du].pop()
                        if pos[last] < len(bucket[du]):
                            pos[last] = pos[last]  # unchanged
                        degree[u] -= 1
                        dnew = degree[u]
                        bucket[dnew].append(u)
                        pos[u] = len(bucket[dnew]) - 1

        # Color in reverse order (largest last first)
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return colors

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors: list[int], a: int, b: int, v: int) -> list[int]:
        new_colors = colors[:]
        stack = [v]
        visited = [False] * n
        visited[v] = True
        # We will swap a<->b in the component containing v
        while stack:
            node = stack.pop()
            if new_colors[node] == a:
                new_colors[node] = b
            elif new_colors[node] == b:
                new_colors[node] = a
            for u in neighbors[node]:
                if not visited[u] and (new_colors[u] == a or new_colors[u] == b):
                    visited[u] = True
                    stack.append(u)
        return new_colors

    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors(colors: list[int]) -> list[int]:
        if max(colors) < 0:
            return colors
        k = max(colors) + 1
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Collect vertices with target_color
            targets = [v for v in range(n) if colors[v] == target_color]
            if not targets:
                continue
            # Try to recolor each target vertex
            made_progress = False
            for v in targets:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Found a free color, reassign
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is isolated in the (c, target_color) Kempe subgraph
                    # i.e., no neighbor of v has color c
                    has_c_neighbor = False
                    for u in neighbors[v]:
                        if colors[u] == c:
                            has_c_neighbor = True
                            break
                    if not has_c_neighbor:
                        # Swap the component: since v has no c neighbor, swapping will move v to c
                        colors = kempe_swap(colors, c, target_color, v)
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # Cannot eliminate this color class, move to next lower
                continue
            else:
                # Made progress, restart from highest color
                return reduce_colors(colors)
        # No progress made, return as is
        return colors

    # Validate coloring
    def is_valid(colors: list[int]) -> bool:
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Compact colors to 0..k-1
    def compact_colors(colors: list[int]) -> list[int]:
        if max(colors) < 0:
            return colors
        # Map existing colors to 0..k-1
        unique = {}
        next_color = 0
        for c in colors:
            if c not in unique:
                unique[c] = next_color
                next_color += 1
        return [unique[c] for c in colors]

    # Run multiple heuristics and pick best
    start_time = time.time()
    best_colors = None
    best_k = float('inf')

    # DSATUR
    if time.time() - start_time < 0.04:  # 40ms budget for heuristics
        c1 = dsatur()
        c1 = compact_colors(c1)
        if is_valid(c1):
            k1 = max(c1) + 1 if c1 else 0
            if k1 < best_k:
                best_k = k1
                best_colors = c1

    # RLF
    if time.time() - start_time < 0.04:
        c2 = rlf()
        c2 = compact_colors(c2)
        if is_valid(c2):
            k2 = max(c2) + 1 if c2 else 0
            if k2 < best_k:
                best_k = k2
                best_colors = c2

    # Smallest-Last
    if time.time() - start_time < 0.04:
        c3 = smallest_last()
        c3 = compact_colors(c3)
        if is_valid(c3):
            k3 = max(c3) + 1 if c3 else 0
            if k3 < best_k:
                best_k = k3
                best_colors = c3

    # If no valid coloring found (should not happen), fallback to greedy
    if best_colors is None:
        # Simple greedy by degree order
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe chain reduction to try to improve
    if time.time() - start_time < 0.045:  # Leave 5ms for reduction
        improved = reduce_colors(best_colors[:])
        improved = compact_colors(improved)
        if is_valid(improved):
            k_imp = max(improved) + 1 if improved else 0
            if k_imp < best_k:
                best_colors = improved

    # Final validation and compact
    if not is_valid(best_colors):
        # Last resort: greedy coloring
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    return best_colors

