def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input type
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmasks
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: convert adjacency list to bitmask for a set of vertices
    def mask_from_vertices(vertices):
        mask = 0
        for v in vertices:
            mask |= (1 << v)
        return mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # DSATUR
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for u in uncolored:
                sat = saturated[u]
                if sat > max_sat:
                    max_sat = sat
                    candidates = [u]
                elif sat == max_sat:
                    candidates.append(u)
            # Tie-break: degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                selected = candidates[0]
                for u in candidates:
                    deg = 0
                    for v in adj_list[u]:
                        if v in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        selected = u
                u = selected
            else:
                u = candidates[0]
            # Assign smallest available color
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            uncolored.remove(u)
            # Update saturation of uncolored neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    # Recompute saturation for v: number of distinct colors in its colored neighbors
                    neighbor_colors = 0
                    for w in adj_list[v]:
                        if color[w] != -1:
                            neighbor_colors |= (1 << color[w])
                    saturated[v] = neighbor_colors.bit_count()
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Choose vertex with max degree in uncolored subgraph
            max_deg = -1
            v1 = None
            for v in uncolored:
                deg = 0
                for w in adj_list[v]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v1 = v
            if v1 is None:
                break  # should not happen
            S.append(v1)
            # Partition: U = vertices not adjacent to any in S, W = adjacent to S
            U = set()
            W = set()
            for v in uncolored:
                if v == v1:
                    continue
                adjacent = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for w in adj_list[u]:
                            if w in U:
                                deg_u += 1
                        deg_best = 0
                        for w in adj_list[best_u]:
                            if w in U:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        while remaining:
            # Find vertex with minimum degree in remaining subgraph
            min_deg = float('inf')
            v_min = None
            for v in remaining:
                # Compute current degree in remaining subgraph
                deg = 0
                for w in adj_list[v]:
                    if w in remaining:
                        deg += 1
                if deg < min_deg:
                    min_deg = deg
                    v_min = v
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors (optional, but we recompute each time)
        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Kempe chain swap attempt to free a color
    def kempe_swap(coloring, target_color):
        # Try to recolor vertices of target_color to free the color
        vertices = [i for i in range(n) if coloring[i] == target_color]
        if not vertices:
            return True  # already free
        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target_color):  # only try colors < target_color
                if not (used & (1 << c)):
                    coloring[v] = c
                    vertices.remove(v)
                    break
        if not vertices:
            return True
        # Try Kempe chains for each remaining vertex
        for v in vertices[:]:  # copy as we may modify
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target_color):
                if used & (1 << c):
                    continue  # color c is present in neighbors, cannot assign directly
                # Try to swap along (c, target_color) Kempe chain
                # Find component of v in subgraph induced by colors c and target_color
                from collections import deque
                visited = set()
                queue = deque([v])
                visited.add(v)
                component = set()
                while queue:
                    x = queue.popleft()
                    component.add(x)
                    for y in adj_list[x]:
                        if y not in visited and (coloring[y] == c or coloring[y] == target_color):
                            visited.add(y)
                            queue.append(y)
                # Check if any neighbor of the component has color c (would cause conflict if swapped)
                conflict = False
                for x in component:
                    for y in adj_list[x]:
                        if y not in component and coloring[y] == c:
                            conflict = True
                            break
                    if conflict:
                        break
                if not conflict:
                    # Perform swap: c <-> target_color in component
                    for x in component:
                        if coloring[x] == c:
                            coloring[x] = target_color
                        elif coloring[x] == target_color:
                            coloring[x] = c
                    # Now v should be color c (since it was target_color)
                    coloring[v] = c
                    vertices.remove(v)
                    break
            if not vertices:
                break
        return len(vertices) == 0

    # Try multiple heuristics
    for heuristic_name, heuristic in [('DSATUR', dsatur), ('RLF', rlf), ('Smallest-Last', smallest_last)]:
        try:
            coloring = heuristic()
            if is_valid(coloring):
                k = count_colors(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring[:]
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_coloring = greedy_color(order)
        best_k = count_colors(best_coloring)

    # Ensure colors are compact (0..k-1)
    # Relabel colors to be consecutive
    if best_coloring:
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]

    # Iterative Kempe chain reduction
    current_k = count_colors(best_coloring)
    improved = True
    while improved and current_k > 1:
        improved = False
        # Try to eliminate color classes from highest to lowest
        for target_color in range(current_k - 1, -1, -1):
            # Make a copy to try on
            trial = best_coloring[:]
            if kempe_swap(trial, target_color):
                # Success: color class eliminated, compact colors
                # Relabel
                used_colors = set(trial)
                mapping = {}
                next_c = 0
                for c in sorted(used_colors):
                    mapping[c] = next_c
                    next_c += 1
                for i in range(n):
                    trial[i] = mapping[trial[i]]
                new_k = count_colors(trial)
                if new_k < current_k:
                    best_coloring = trial
                    current_k = new_k
                    improved = True
                    break  # restart from highest color
        # If no improvement, break

    # Final validation (should always hold)
    if not is_valid(best_coloring):
        # Ultimate fallback: greedy sequential
        best_coloring = greedy_color(list(range(n)))
        # Compact
        used = set(best_coloring)
        mapping = {c: i for i, c in enumerate(sorted(used))]
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

