    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                neighbors[i].add(j)
                bit_adj[i] |= (1 << j)
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)

    # Ensure symmetry
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    best_coloring = None
    best_k = float('inf')
    start_time = time.time()
    time_limit = 0.045  # 45 ms to leave margin

    # 1. DSATUR
    if time.time() - start_time < time_limit:
        uncolored = set(range(n))
        color = [-1] * n
        sat = [0] * n
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([u for u in neighbors[x] if u in uncolored]), x))
            # Compute used colors from neighbors
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] = len({color[w] for w in neighbors[u] if color[w] != -1})
        color = compact_colors(color)
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # 2. RLF (Recursive Largest First)
    if time.time() - start_time < time_limit:
        uncolored = set(range(n))
        color = [-1] * n
        c = 0
        while uncolored and (time.time() - start_time < time_limit):
            # Start with max degree vertex in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            S = {v}
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U = uncolored - {v} - neighbors[v]
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([w for w in neighbors[x] if w in U]), x))
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for w in list(neighbors[u] & U):
                    U.remove(w)
                    W.add(w)
            # Assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        color = compact_colors(color)
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # 3. Smallest-Last (Matula & Beck) ordering
    if time.time() - start_time < time_limit:
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        while remaining:
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    degree[u] -= 1
        # Color in reverse order
        color = greedy_color(order[::-1])
        color = compact_colors(color)
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # If no heuristic succeeded (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_coloring = compact_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal start_time, time_limit
        if time.time() - start_time >= time_limit:
            return coloring
        coloring = coloring[:]
        while True:
            if time.time() - start_time >= time_limit:
                break
            # Find smallest color class
            color_classes = [[] for _ in range(max(coloring) + 1) if coloring]
            for v, c in enumerate(coloring):
                color_classes[c].append(v)
            # Find smallest non-empty class
            k = len(color_classes)
            target_color = -1
            min_size = float('inf')
            for c in range(k):
                if color_classes[c] and len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1 or target_color == 0:
                break  # No color to eliminate or already minimal
            # Try to recolor each vertex in target_color
            removed = False
            for v in color_classes[target_color][:]:
                if time.time() - start_time >= time_limit:
                    break
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                # Try direct reassignment to a smaller color
                for c in range(target_color):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    break
                # Try Kempe chains with each smaller color
                for c in range(target_color):
                    if time.time() - start_time >= time_limit:
                        break
                    if used & (1 << c):
                        continue  # Neighbor has color c, so swapping may not help directly
                    # Find Kempe chain of colors (target_color, c) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for w in neighbors[node]:
                                if w not in visited and (coloring[w] == target_color or coloring[w] == c):
                                    stack.append(w)
                    # Check if any neighbor of v in component has color c (would cause conflict after swap)
                    conflict = False
                    for node in component:
                        for w in neighbors[node]:
                            if w not in component and coloring[w] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            coloring[node] = c if coloring[node] == target_color else target_color
                        removed = True
                        break
                if removed:
                    break
            if not removed:
                break  # Could not eliminate target color
            # Rebuild coloring and compact
            coloring = compact_colors(coloring)
        return coloring

    # Apply Kempe reduction if time permits
    if time.time() - start_time < time_limit and best_coloring is not None:
        best_coloring = kempe_reduce(best_coloring)
        best_coloring = compact_colors(best_coloring)

    # Final validation and compact
    if not is_valid(best_coloring):
        # Last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best_coloring = greedy_color(order)
    best_coloring = compact_colors(best_coloring)

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                val = adj[i][j]
                if val != 0 and val != 1:
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper function to compute number of unique colors in a coloring
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper function to validate a coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR heuristic
    def dsatur():
        color = [-1] * n
        # saturation[v] = set of colors used by colored neighbors
        saturation = [set() for _ in range(n)]
        # degree in the uncolored subgraph (initially full degree)
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if color[i] == -1:
                    sat = len(saturation[i])
                    deg = uncolored_deg[i]
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and random.random() < 0.5):
                        max_sat = sat
                        max_deg = deg
                        v = i
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c

            # Update saturation and uncolored degree for neighbors
            for u in neighbors[v]:
                if color[u] == -1:  # u is uncolored
                    saturation[u].add(c)
                    uncolored_deg[u] -= 1
            uncolored_count -= 1
        return color

    # RLF heuristic
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build maximal independent set for current_color
            # degree in the subgraph induced by uncolored
            deg_in_uncolored = [0] * n
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_in_uncolored[v] += 1

            # Choose v1: vertex in uncolored with max degree in uncolored subgraph
            v1 = max(uncolored, key=lambda x: deg_in_uncolored[x])
            S = {v1}
            # U: vertices in uncolored not adjacent to any in S
            # W: vertices in uncolored adjacent to at least one in S
            U = set()
            W = set()
            for v in uncolored:
                if v == v1:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in neighbors[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.add(v)

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U subgraph
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    # Count neighbors of u that are in W
                    nw = 0
                    for w in neighbors[u]:
                        if w in W:
                            nw += 1
                    # Degree of u in the subgraph induced by U
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or (nw == max_nw and deg_u == min_deg_u and random.random() < 0.5):
                        max_nw = nw
                        min_deg_u = deg_u
                        best_u = u
                if best_u == -1:
                    break  # should not happen if U non-empty
                # Add best_u to S
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign current_color to all vertices in S
            for v in S:
                color[v] = current_color
            # Remove S from uncolored
            uncolored -= S
            current_color += 1
        return color

    # Smallest-Last (Matula-Beck) ordering greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # We'll use a list of buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # Find unremoved vertex with min degree
            v = -1
            min_deg = float('inf')
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse removal order
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        color = coloring[:]
        k = num_colors(color)
        # Try to reduce colors as long as possible
        improved = True
        while improved and k > 1:
            improved = False
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if color[v] == target_color]
            if not target_vertices:
                # This should not happen if k is correct, but safety
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = set()
                for u in neighbors[v]:
                    if color[u] < target_color:  # only colors < target_color matter for direct move
                        used_by_neighbors.add(color[u])
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        # Move v to color c
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart the while loop after any improvement
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # If v already has color c (shouldn't happen as we checked direct reassignment), skip
                    if color[v] == c:
                        continue
                    # Find the Kempe chain component for colors (c, target_color) containing v
                    # We'll do BFS/DFS over vertices with color c or target_color
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        node = queue.popleft()
                        for u in neighbors[node]:
                            if color[u] == c or color[u] == target_color:
                                if u not in comp:
                                    comp.add(u)
                                    queue.append(u)
                    # Check if we can swap: after swap, no neighbor of v will have color c (except possibly via chain, but we check)
                    # Actually, we need to ensure that after swapping, v does not conflict.
                    # Since we are swapping colors c and target_color in the component, v will become c.
                    # We need to check that no neighbor of v has color c after swap.
                    # Neighbors of v that are in the component: if they had color c, they become target_color; if target_color, become c.
                    # So neighbors of v that are in the component and had color c will become target_color (not c).
                    # Neighbors of v that are in the component and had target_color will become c -> conflict if they are adjacent to v.
                    # Therefore, we must check: for any neighbor u of v, if u is in the component and color[u] == target_color, then after swap it becomes c -> conflict.
                    # Also, neighbors not in the component: their color doesn't change, so if they have color c, conflict.
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c:
                            if u not in comp:  # not in component, color stays c -> conflict
                                conflict = True
                                break
                            else:  # u in component and had color c -> after swap becomes target_color, so no conflict
                                pass
                        elif color[u] == target_color:
                            if u in comp:  # u in component and had target_color -> after swap becomes c -> conflict
                                conflict = True
                                break
                            else:  # u not in component, color stays target_color -> no conflict (since v becomes c)
                                pass
                    if not conflict:
                        # Perform the swap
                        for node in comp:
                            if color[node] == c:
                                color[node] = target_color
                            elif color[node] == target_color:
                                color[node] = c
                        improved = True
                        break
                if improved:
                    break
            # If we improved, we may have emptied the target color; recompute k and try again
            if improved:
                # Recompute k as max color + 1
                k = num_colors(color)
                # Compact colors: not strictly necessary for correctness but helps in subsequent steps
                # We'll do a simple compaction: map colors to 0..k-1
                # But note: we are already using colors 0..k-1? Not necessarily if we removed a color.
                # Instead, we can rebuild the color mapping to be consecutive.
                # However, for simplicity, we just note that the max color might have decreased.
                # We'll let the outer loop recompute k from the coloring.
            else:
                # Could not reduce the last color
                break
        # Compact colors to 0..k-1
        # Map existing colors to consecutive integers
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        return color

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (shouldn't happen), fall back to trivial greedy
    if not candidates:
        color = [0] * n
        for i in range(n):
            used = set()
            for j in neighbors[i]:
                if color[j] != 0:  # only check colored neighbors? Actually, we are coloring in order 0..n-1
                    used.add(color[j])
            c = 0
            while c in used:
                c += 1
            color[i] = c
        candidates.append(color)

    # Select the candidate with the fewest colors
    best_coloring = min(candidates, key=num_colors)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid(improved) and num_colors(improved) <= num_colors(best_coloring):
            best_coloring = improved
    except:
        pass

    # Final validation and compacting (ensure colors are 0..k-1)
    if not is_valid(best_coloring):
        # As a last resort, use a simple greedy ordering by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        best_coloring = color

    # Compact colors
    unique_colors = sorted(set(best_coloring))
    if unique_colors:
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]
    else:
        best_coloring = []  # for n=0, but we already handled

    return best_coloring

