    if is_matrix:
        neighbors = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        neighbors = adj

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper functions
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def get_unique_colors(coloring):
        return len(set(coloring)) if coloring else 0

    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        saturated = [0] * n
        uncolored = set(range(n))

        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            colors[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] += 1

        while uncolored:
            # Find vertex with max saturation, break ties by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturated[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)

            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break by degree in uncolored subgraph
                v = max(candidates, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored))

            # Find smallest available color
            neighbor_colors = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] += 1

        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build independent set for current color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored))
            independent_set = {v}
