            U = uncolored - {v}
            W = set()
            for u in U:
                if u in neighbors[v]:
                    W.add(u)
                else:
                    # u remains in U (eligible)
                    pass

            # While there are eligible vertices
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_count = sum(1 for w in neighbors[u] if w in W)
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        best_u = u
                    elif w_count == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = sum(1 for w in neighbors[u] if w in U)
                        deg_best = sum(1 for w in neighbors[best_u] if w in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
