                v = color_classes[c].pop()  # take a vertex
                # Try direct reassignment to a lower color
                for new_c in range(c):
                    conflict = False
                    for nb in neighbors[v]:
                        if color[nb] == new_c:
                            conflict = True
                            break
                    if not conflict:
                        # Assign new color
                        color[v] = new_c
                        color_classes[new_c].append(v)
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chain swaps with each lower color
                for new_c in range(c):
                    swapped = kempe_swap(color, v, c, new_c)
                    if swapped is not None:
                        # Update color and color classes
                        old_c = color[v]
                        color[:] = swapped
                        # Rebuild color classes for efficiency (could be optimized, but n <= 100)
                        color_classes = [[] for _ in range(n)]
                        for u in range(n):
                            cu = color[u]
                            if cu < n:
                                color_classes[cu].append(u)
                        changed = True
                        break
                if not changed:
                    # Could not recolor v, put it back
                    color_classes[c].append(v)
            # If color class c is empty, we can compact colors
            if not color_classes[c]:
                # Shift down all colors > c
                for v in range(n):
                    if color[v] > c:
                        color[v] -= 1
                # Rebuild color classes after shifting
                color_classes = [[] for _ in range(n)]
                for v in range(n):
                    cv = color[v]
                    if cv < n:
