    # Generate initial coloring with DSATUR
    best_color = dsatur()
    best_k = max(best_color) + 1 if n > 0 else 0

    # Try to reduce colors using Kempe chains
    reduced_color = reduce_colors(best_color[:])
    reduced_k = max(reduced_color) + 1 if n > 0 else 0
    if reduced_k < best_k:
        best_color = reduced_color
        best_k = reduced_k

    # Validate and ensure consecutive colors
    # Verify no adjacent same color
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_color[u] == best_color[v]:
                # Fallback: greedy by degree order
