                color = [-1] * n
                for v in order:
                    used = [False] * (n + 1)
                    for nb in neighbors[v]:
                        c = color[nb]
                        if c != -1:
                            used[c] = True
                    c = 0
                    while c <= n and used[c]:
                        c += 1
                    color[v] = c
                best_color = color
                break

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[i] = unique_colors[c]

    return best_color

