def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(colors):
        return len(set(colors)) if colors else 0

    # Helper: convert to consecutive colors starting from 0
    def normalize_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bit masks for fast distinct count
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        # initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            color[v] = 0
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    neighbor_colors[u] |= (1 << 0)
                    sat[u] = neighbor_colors[u].bit_count()

        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([n for n in adj_list[x] if n in uncolored])))
            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] = neighbor_colors[u].bit_count()
        return color

    # Recursive Largest First (RLF)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            S = []
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([n for n in adj_list[x] if n in uncolored]))
            S.append(v)
            # partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in adj_list[u] for w in S):
                    W.add(u)
                    U.remove(u)
            # greedily add to S from U
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                u_star = None
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                for u in U:
                    neighbors_in_W = len([w for w in adj_list[u] if w in W])
                    deg_in_U = len([w for w in adj_list[u] if w in U])
                    if (neighbors_in_W > max_neighbors_in_W or
                        (neighbors_in_W == max_neighbors_in_W and deg_in_U < min_deg_in_U)):
                        max_neighbors_in_W = neighbors_in_W
                        min_deg_in_U = deg_in_U
                        u_star = u
                if u_star is None:
                    break  # should not happen
                S.append(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Smallest-Last (Matula-Beck) ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(buckets):
                buckets[degree[v]].add(v)
        # peel min degree vertex
        for _ in range(n):
            # find non-empty bucket with smallest index
            i = 0
            while i < len(buckets) and not buckets[i]:
                i += 1
            if i >= len(buckets):
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from current degree bucket
                    if degree[u] < len(buckets):
                        buckets[degree[u]].discard(u)
                    degree[u] -= 1
                    if degree[u] < len(buckets):
                        buckets[degree[u]].add(u)
            remaining.remove(v)
        # color in reverse order using first-fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # try to recolor each vertex in this class
            removed = True
            while verts and removed:
                removed = False
                v = verts.pop()
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        neighbor_colors |= (1 << coloring[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    continue
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # if v already has a neighbor of color c, swapping may not help
                    has_neighbor_c = any(coloring[u] == c for u in adj_list[v])
                    if has_neighbor_c:
                        continue
                    # build Kempe chain of colors {c, target_color} containing v
                    # we consider swapping only if v is not adjacent to color c (to avoid immediate conflict)
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (coloring[nb] == c or coloring[nb] == target_color):
                                    stack.append(nb)
                    # check if any neighbor of v in the component has color c? Actually, we want to see if swapping frees color c for v
                    # After swap, v would get color c if it was target_color and in the component.
                    # We need to ensure that no neighbor of v gets color target_color after swap (which would conflict if v becomes c)
                    # But actually, we are going to swap colors in the component: c->target_color, target_color->c.
                    # For v to be recolored to c, it must be in the component and currently target_color.
                    # After swap, its neighbors that are in the component and were color c become target_color.
                    # So if v has a neighbor in the component that is color c, after swap that neighbor becomes target_color, same as v's original color -> no conflict.
                    # The only potential conflict is if v has a neighbor outside the component that is color target_color? 
                    # But if such neighbor existed, it would be in the component (since it's target_color and adjacent to v which is target_color? 
                    # Wait: v is target_color, neighbor is target_color -> edge between same color -> invalid coloring. So cannot happen.
                    # Similarly, neighbor outside component that is color c: after swap, v becomes c, neighbor remains c -> conflict.
                    # So we must check: after swap, does v have any neighbor with color c (outside component)?
                    # Actually, neighbors with color c outside component would remain c, and v becomes c -> conflict.
                    # So we need that v has no neighbor with color c outside the Kempe component.
                    safe = True
                    for nb in adj_list[v]:
                        if coloring[nb] == c and nb not in component:
                            safe = False
                            break
                    if safe:
                        # perform swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        removed = True
                        break
                if removed:
                    # restart the while loop for this target_color since coloring changed
                    verts = [v for v in range(n) if coloring[v] == target_color]
                    break
            # if we eliminated the color class, break and try again from high color
            if not any(coloring[v] == target_color for v in range(n)):
                # compact colors: remap to 0..k-2
                mapping = {}
                new_color = 0
                for col in range(k):
                    if col == target_color:
                        continue
                    mapping[col] = new_color
                    new_color += 1
                for v in range(n):
                    if coloring[v] != -1:
                        coloring[v] = mapping[coloring[v]]
                # restart reduction from scratch with new coloring
                return kempe_reduce(coloring)
        return coloring

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for cand in candidates:
        if not is_valid_coloring(cand):
            # fix by greedy reassign if needed (should not happen)
            # but just in case, apply first-fit in vertex order
            fixed = [-1] * n
            for v in range(n):
                used = 0
                for u in adj_list[v]:
                    if fixed[u] != -1:
                        used |= (1 << fixed[u])
                c = 0
                while used & (1 << c):
                    c += 1
                fixed[v] = c
            cand = fixed
        cand = normalize_colors(cand)
        if not is_valid_coloring(cand):
            continue
        num_colors = count_colors(cand)
        if num_colors < best_colors:
            best_colors = num_colors
            best = cand

    # Apply Kempe reduction to best candidate
    if best is not None:
        best = kempe_reduce(best)
        best = normalize_colors(best)
        # final validation
        if not is_valid_coloring(best):
            # fallback to simple greedy
            best = [-1] * n
            for v in range(n):
                used = 0
                for u in adj_list[v]:
                    if best[u] != -1:
                        used |= (1 << best[u])
                c = 0
                while used & (1 << c):
                    c += 1
                best[v] = c
            best = normalize_colors(best)
    else:
        # all candidates failed, use greedy
        best = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if best[u] != -1:
                    used |= (1 << best[u])
            c = 0
            while used & (1 << c):
                c += 1
            best[v] = c
        best = normalize_colors(best)

    return best

