        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= 1 << j
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= 1 << j
                    neighbors[i].append(j)
    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= 1 << colors[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors
    # Helper: Kempe chain swap for colors a,b from vertex v
    def kempe_swap(colors, a, b, v):
        if colors[v] not in (a, b):
            return colors
        stack = [v]
        visited = [False] * n
        visited[v] = True
        comp = []
        while stack:
            node = stack.pop()
            comp.append(node)
            for nb in neighbors[node]:
                if not visited[nb] and colors[nb] in (a, b):
                    visited[nb] = True
                    stack.append(nb)
        # Check if swapping is safe: no neighbor outside comp has color a or b
        for node in comp:
            for nb in neighbors[node]:
                if not visited[nb] and colors[nb] in (a, b):
                    return colors  # swap would cause conflict
        # Perform swap
        for node in comp:
            if colors[node] == a:
                colors[node] = b
            else:
                colors[node] = a
        return colors
    # Try multiple initial orderings
    best_colors = None
    best_k = float('inf')
    # Order 1: DSATUR
    def dsatur_order():
        colored = [False] * n
        sat = [0] * n  # saturation degree
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        for _ in range(n):
            # select uncolored vertex with max sat, tie-break by degree, then index
            candidates = [-1]
            max_sat = -1
            for v in range(n):
                if not colored[v]:
                    if sat[v] > max_sat:
                        max_sat = sat[v]
                        candidates = [v]
                    elif sat[v] == max_sat:
                        candidates.append(v)
            # tie-break by degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    # count uncolored neighbors
                    d = 0
                    for nb in neighbors[v]:
                        if not colored[nb]:
                            d += 1
                    if d > max_deg:
                        max_deg = d
                        best_v = v
                    elif d == max_deg and v < best_v:
                        best_v = v
                v = best_v
            else:
                v = candidates[0]
            order.append(v)
            colored[v] = True
            # update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if not colored[nb]:
                    sat[nb] += 1
