    def rlf_order():
        uncolored = set(range(n))
        order = []
        while uncolored:
            # pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in neighbors[x] if nb in uncolored))
            # build independent set S with color c
            S = []
            # eligible: not adjacent to any in S
            U = {u for u in uncolored if u != v and all(nb not in S for nb in neighbors[u])}
            # ineligible: adjacent to S
            W = {u for u in uncolored if u != v and any(nb in S for nb in neighbors[u])}
            S.append(v)
            uncolored.remove(v)
            while U:
                # select u in U with max neighbors in W
                u = max(U, key=lambda x: sum(1 for nb in neighbors[x] if nb in W))
                # tie-break: min degree in U
                min_deg = float('inf')
                for uu in U:
                    deg_uu = sum(1 for nb in neighbors[uu] if nb in U)
                    if deg_uu < min_deg:
                        min_deg = deg_uu
                        u = uu
                S.append(u)
                uncolored.remove(u)
                # update U and W: move u from U, and move its neighbors in U to W
                U.remove(u)
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            order.extend(S)
        return order
    # Order 3: Smallest-Last (degeneracy ordering)
    def sl_order():
        # copy degrees
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        for _ in range(n):
            # find vertex with minimum degree among unremoved
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            order.append(v)
            removed[v] = True
            # decrease degree of neighbors
            for nb in neighbors[v]:
                if not removed[nb]:
                    deg[nb] -= 1
        return order[::-1]  # reverse for coloring
    # Order 4: Welsh-Powell (degree descending)
    def wp_order():
        return sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    # Order 5: Random shuffle (a few times)
    orders = [dsatur_order(), rlf_order(), sl_order(), wp_order()]
    for _ in range(2):
        rand_order = list(range(n))
        random.shuffle(rand_order)
        orders.append(rand_order)
    for order in orders:
