    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Precompute neighbor bitmasks for fast operations
    neighbor_mask = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= (1 << v)
        neighbor_mask[u] = mask

