    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count number of colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0..k-1
        used = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in coloring]

    # DSATUR with bitmask optimization
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph (for tie-breaking)
        uncolored_deg = [len(graph[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colors[v] != -1:
                    continue
                sat = saturation[v].bit_count()
                deg = uncolored_deg[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v

            # Find smallest available color (not in saturation mask)
            used_colors = saturation[v]
            c = 0
            while used_colors & (1 << c):
                c += 1
            colors[v] = c

            # Update neighbors
            for u in graph[v]:
                if colors[u] == -1:  # if neighbor uncolored
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
            uncolored_count -= 1

        return normalize(colors)

    # RLF (Recursive Largest First) with bitmask
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build independent set for this color
            independent_set = []
            # Candidates: vertices not adjacent to any in independent_set
            # We'll maintain eligible set U and ineligible set W
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex in uncolored with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set.append(v)
            # U: vertices in uncolored not adjacent to v
            # W: vertices in uncolored adjacent to v
            U = uncolored - {v} - set(graph[v])
            W = set(graph[v]) & uncolored

            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = -1  # degree in U for tie-break
                for u in U:
                    # Count neighbors of u in W
                    w_neighbors = 0
                    for y in graph[u]:
                        if y in W:
                            w_neighbors += 1
                    # Degree in U
                    u_deg = 0
                    for y in graph[u]:
                        if y in U:
                            u_deg += 1
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or \
                       (w_neighbors == best_w_neighbors and u_deg == best_u_deg and (best_u == -1 or random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                independent_set.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in graph[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
