                        node = queue.popleft()
                        component.append(node)
                        for nb in graph[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any node in component has a neighbor with color c (outside component) that would cause conflict if swapped
                    # Actually, after swap, nodes originally color c become target_color and vice versa.
                    # Conflict would occur if a node in component (originally c) has a neighbor outside component that is target_color,
                    # or a node in component (originally target_color) has a neighbor outside component that is c.
