        sorted_verts = sorted(vertices, key=lambda v: len([u for u in complement[v] if u in vertices]), reverse=True)
        clique = []
        for v in sorted_verts:
            # Check if v is adjacent to all in clique (in complement graph)
            if all(u in complement[v] for u in clique):
                clique.append(v)
        return clique

    # Main coloring loop: each iteration finds a maximal clique in complement (i.e., independent set in original)
    uncolored = set(range(n))
    color = 0
    result = [-1] * n

    while uncolored:
        clique = greedy_clique(list(uncolored))
        for v in clique:
            result[v] = color
            uncolored.remove(v)
        color += 1

    return result

