def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert adjacency to bitmask representation for efficiency
    bit_adj = [0] * n
    for i in range(n):
        if isinstance(adj[i], list):
            if len(adj[i]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[i]):
                # Treat as adjacency matrix row
                for j in range(n):
                    if adj[i][j]:
                        bit_adj[i] |= 1 << j
            else:
                # Treat as adjacency list
                for j in adj[i]:
                    if 0 <= j < n:
                        bit_adj[i] |= 1 << j
        else:
            # Fallback: treat as list of neighbors
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= 1 << j

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if coloring[u] == coloring[v]:
                        return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and colors[v] != -1:
                    used |= 1 << colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Helper: DSATUR with tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                deg = 0
                for u in uncolored:
                    if u != v and ((bit_adj[v] >> u) & 1):
                        deg += 1
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v < best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation and neighbor colors for uncolored neighbors
            for u in range(n):
                if u != v and ((bit_adj[v] >> u) & 1) and colors[u] == -1:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= 1 << c
                        saturation[u] += 1
        return colors

    # Helper: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in uncolored if y != x and ((bit_adj[x] >> y) & 1)))
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            U = {u for u in uncolored if u != v and not ((bit_adj[v] >> u) & 1)}
            # W: vertices adjacent to at least one in independent_set (ineligible)
            W = {u for u in uncolored if u != v and ((bit_adj[v] >> u) & 1)}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in W if ((bit_adj[u] >> w) & 1))
                    u_deg = sum(1 for x in U if x != u and ((bit_adj[u] >> x) & 1))
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or (w_neighbors == best_w_neighbors and u_deg == best_u_deg and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if ((bit_adj[u] >> w) & 1):
                        U.remove(w)
                        W.add(w)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color
            uncolored -= to_remove
            color += 1
        return colors

    # Helper: smallest-last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [0] * n
        for i in range(n):
