            v = min(remaining, key=lambda x: sum(1 for y in remaining if y != x and ((bit_adj[x] >> y) & 1)))
            order.append(v)
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []

    # Run DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass

    # Run RLF
    try:
        c2 = rlf()
        if is_valid(c2):
