    except:
        pass

    # Run smallest-last greedy
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # Run multiple random greedy orders
    for _ in range(20):
        order = list(range(n))
        random.shuffle(order)
        c = greedy_color(order)
        if is_valid(c):
            candidates.append(c)

    # If no candidates, fallback to simple greedy
    if not candidates:
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Local search: 1-opt and Kempe-like reduction
    improved = True
    while improved and best_k > 1:
        improved = False
        # Try to eliminate the last color (best_k - 1)
        target_color = best_k - 1
        vertices = [v for v in range(n) if best[v] == target_color]
        random.shuffle(vertices)
        for v in vertices:
            # Try to recolor v to a lower color if possible
            neighbor_colors = set()
            for u in range(n):
