                    neighbor_colors.add(best[u])
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Direct reassignment possible
                    best[v] = c
                    improved = True
                    break
            if improved:
                # After reassignment, check if target color is still used
                if target_color not in best:
                    best_k -= 1
                    # Compact colors: remap to 0..best_k-1
                    mapping = {}
                    next_c = 0
                    for i in range(n):
                        if best[i] not in mapping:
                            mapping[best[i]] = next_c
                            next_c += 1
                    for i in range(n):
                        best[i] = mapping[best[i]]
                    break
                else:
                    # Still need to try other vertices
                    continue
        # If no direct reassignment, try Kempe chain swaps (simplified)
        if not improved:
