                        # Check if any neighbor of v with color c is NOT in this component
                        # If so, we can swap colors in the component to free color c for v
                        has_external = False
                        for y in range(n):
                            if y != v and ((bit_adj[v] >> y) & 1) and best[y] == c and not visited[y]:
                                has_external = True
                                break
                        if has_external:
                            # Swap colors c and target_color in component
                            for x in component:
                                if best[x] == c:
                                    best[x] = target_color
                                elif best[x] == target_color:
                                    best[x] = c
                            improved = True
                            # After swap, v now has color c (since it was target_color and swapped)
                            # Check if target_color is still used
                            if target_color not in best:
                                best_k -= 1
                                mapping = {}
                                next_c = 0
                                for i in range(n):
                                    if best[i] not in mapping:
                                        mapping[best[i]] = next_c
                                        next_c += 1
                                for i in range(n):
                                    best[i] = mapping[best[i]]
