    # Compact colors
    mapping = {}
    next_c = 0
    for i in range(n):
        if best[i] not in mapping:
            mapping[best[i]] = next_c
            next_c += 1
    for i in range(n):
        best[i] = mapping[best[i]]

    return best

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
