                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute bitmask representation
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

