    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_colors(colors):
        if not colors:
            return colors
        # Map used colors to 0..k-1
        used = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in colors]

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur():
        colors = [-1] * n
        # Track saturation: for each vertex, bitmask of colors used by neighbors
        neighbor_colors = [0] * n  # bitmask: bit i set if color i is used by a neighbor

        # Precompute neighbor lists for quick access
        # We'll use neighbor_mask for bit operations

        # Order of coloring
        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            # Saturation degree = number of distinct colors in neighbors = bit_count(neighbor_colors[v])
            max_sat = -1
            candidates = []
            for v in range(n):
                if colors[v] == -1:
                    sat = neighbor_colors[v].bit_count()
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)

            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                selected = candidates[0]
                for v in candidates:
                    # Count uncolored neighbors
                    deg_uncolored = 0
                    for u in adj_list[v]:
                        if colors[u] == -1:
                            deg_uncolored += 1
                    if deg_uncolored > max_deg:
                        max_deg = deg_uncolored
                        selected = v
                v = selected
            else:
                v = candidates[0]

            # Find smallest available color (MEX)
            used_by_neighbors = neighbor_colors[v]
            c = 0
            while used_by_neighbors & (1 << c):
                c += 1
            colors[v] = c

            # Update neighbor_colors for all neighbors of v
            for u in adj_list[v]:
                if colors[u] == -1:  # only update uncolored neighbors
                    neighbor_colors[u] |= (1 << c)

        return normalize_colors(colors)

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color_idx = 0
        # Set of uncolored vertices
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for current color
            # Step 1: pick vertex with max degree in G[uncolored]
            max_deg = -1
            v0 = None
            for v in uncolored:
                # degree in induced subgraph
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            if v0 is None:  # should not happen
                break

            independent_set = {v0}
            # Partition remaining uncolored into U (not adj to any in S) and W (adj to at least one in S)
            U = set()
            W = set()
            for v in uncolored:
                if v == v0:
                    continue
                adj_to_S = False
                for u in independent_set:
                    if v in adj_list[u]:
                        adj_to_S = True
                        break
                if adj_to_S:
                    W.add(v)
                else:
                    U.add(v)

            # While U not empty, add vertices to independent set
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_common = -1
                for u in U:
                    # Count neighbors in W
                    common = 0
                    for w in adj_list[u]:
                        if w in W:
                            common += 1
                    if common > max_common:
                        max_common = common
                        best_u = u
                    elif common == max_common:
