                        if best_u is None:
                            best_u = u
                        else:
                            deg_u = sum(1 for x in adj_list[u] if x in U)
                            deg_best = sum(1 for x in adj_list[best_u] if x in U)
                            if deg_u < deg_best:
                                best_u = u
                if best_u is None:
                    break  # safety

                # Add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                to_move = []
                for u in U:
                    if best_u in adj_list[u]:
                        to_move.append(u)
                for u in to_move:
                    U.remove(u)
                    W.add(u)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
            color_idx += 1
            # Next round: uncolored becomes W
            uncolored = W

        return normalize_colors(colors)

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        # We'll work on a copy of degrees
        deg = degrees[:]
        removed = [False] * n
        order = []  # will store removal order

        # For efficiency, we use buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
            else:
                # extend buckets if needed (shouldn't happen with proper deg)
                while len(buckets) <= deg[v]:
                    buckets.append([])
                buckets[deg[v]].append(v)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
