                        v = buckets[i].pop()
                        found = True
                        break
                if not found:
                    break
            removed[v] = True
            order.append(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    # Remove u from its current bucket
                    old_deg = deg[u]
                    if old_deg < len(buckets) and u in buckets[old_deg]:
                        buckets[old_deg].remove(u)
