                    best_deg = deg
                    best_v = v
            v = best_v

            # Find smallest available color
            neighbor_colors = 0
            nb = adj_list[v]
            for u in nb:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color

            # Update uncolored set and degrees
            uncolored.remove(v)
            for u in nb:
                if u in uncolored:
                    uncolored_deg[u] -= 1
                    # Update saturation if v is now colored
                    if coloring[v] != -1:
                        # Check if this color is new in u's neighborhood
                        mask = 1 << coloring[v]
                        if (colored_neighbors[u] & mask) == 0:
                            colored_neighbors[u] |= mask
                            saturation[u] += 1

        return normalize(coloring)

    # RLF implementation
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # Degree in U subgraph
                    u_deg = 0
                    for w in adj_list[u]:
                        if w in U:
                            u_deg += 1
                    if w_count > best_w_neighbors or \
                       (w_count == best_w_neighbors and u_deg < best_u_deg) or \
                       (w_count == best_w_neighbors and u_deg == best_u_deg and (best_u == -1 or u < best_u)):
                        best_w_neighbors = w_count
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            # Remove S from uncolored
            uncolored -= S
            color += 1

        return normalize(coloring)

    # Smallest-Last (Matula-Beck) greedy
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use a list of sets for buckets, but n<=100 so we can scan
        for _ in range(n):
            # Find unremoved vertex with min degree
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not removed[u]:
                    deg[u] -= 1

        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color

        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring  # should not happen if we start valid

        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest down
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already empty, compact and continue
                k -= 1
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] < target_color:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Direct move possible
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # We'll try to swap in the (c, target_color) Kempe chain containing v
                    # Only if v is not already in a chain that would cause conflict
                    # Build the Kempe chain: connected component of v in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)

                    # Check if swapping colors in this component is safe:
                    # For any node in component, after swap, its new color should not conflict with neighbors
                    safe = True
                    for node in component:
                        new_color = c if coloring[node] == target_color else target_color
                        for nb in adj_list[node]:
                            if coloring[nb] == new_color:
                                safe = False
                                break
                        if not safe:
                            break

                    if safe:
                        # Perform the swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:  # must be target_color
                                coloring[node] = c
                        improved = True
                        break
                if improved:
                    break

            # If we improved, check if target color class is now empty
            if improved:
                # Re-check if target color is used
                if target_color not in coloring:
                    # Compact colors: remap so that we use 0..k-2
                    # Create mapping: all colors < target_color stay, colors > target_color shift down
                    # But since we only removed target_color, and we process from high, we can rebuild
                    # Instead, we'll normalize at the end of kempe_reduce, but for now just continue
                    k = num_colors(coloring)
                    # We'll let the outer loop handle by checking k
                else:
                    # Target color still used, but we made a move; continue trying
                    pass
            # If no improvement, break

        # Normalize at the end to ensure consecutive colors
        return normalize(coloring)

    # Run all heuristics with time budgeting
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # List of heuristic functions
    heuristics = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last)
    ]

    for name, heuristic in heuristics:
        # Check time
        if time.time() - start_time > 0.04:  # leave time for Kempe
            break
        try:
            coloring = heuristic()
            if not is_valid_coloring(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]
        except Exception:
            continue

    # If no heuristic produced a valid coloring, fall back to greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color
        best_coloring = normalize(coloring)
        best_k = num_colors(best_coloring)

    # Apply Kempe chain reduction if time permits
    if time.time() - start_time < 0.045:
        try:
            reduced = kempe_reduce(best_coloring[:])
            if is_valid_coloring(reduced):
                k_red = num_colors(reduced)
                if k_red < best_k:
                    best_coloring = reduced
                    best_k = k_red
        except Exception:
            pass

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Emergency fallback: greedy coloring
        order = list(range(n))
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color
        best_coloring = normalize(coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                neighbors[i].append(j)
                bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def popcount(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring: list[int]) -> bool:
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring: list[int]) -> int:
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: renumber colors to 0..k-1 consecutively
    def renumber_colors(coloring: list[int]) -> list[int]:
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        coloring = [-1] * n
        colored = [False] * n
        saturation = [0] * n
        degree = [len(neighbors[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    if saturation[i] > max_sat or (saturation[i] == max_sat and degree[i] > max_deg):
                        max_sat = saturation[i]
                        max_deg = degree[i]
                        v = i
            if v == -1:
                break  # Should not happen

            # Find smallest available color
            neighbor_colors = 0
            for u in neighbors[v]:
                if colored[u]:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u] += 1
        return renumber_colors(coloring)

    # Recursive Largest First (RLF)
    def rlf() -> list[int]:
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S.append(v)
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = None
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = len([w for w in neighbors[u] if w in W])
                    deg_u = len([w for w in neighbors[u] if w in U])
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                if u_star is None:
                    break
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return renumber_colors(coloring)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last() -> list[int]:
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll simulate removal by updating degrees
        deg_copy = degree[:]
        for _ in range(n):
            # Find vertex of minimum degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg_copy[u] < min_deg:
                    min_deg = deg_copy[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    deg_copy[u] -= 1
        # Color in reverse order using First-Fit
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return renumber_colors(coloring)

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring: list[int], a: int, b: int, v: int) -> bool:
        # Returns True if swap was performed, False otherwise
        # We only swap if the component of v in (a,b) does not contain any vertex of color a that we don't want to move?
        # Standard: swap the component containing v
        from collections import deque
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            u = queue.popleft()
            component.append(u)
            for w in neighbors[u]:
                if not visited[w] and (coloring[w] == a or coloring[w] == b):
                    visited[w] = True
                    queue.append(w)
        # Perform swap: a<->b in component
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            elif coloring[u] == b:
                coloring[u] = a
        return True

    # Try to eliminate the last color using Kempe chains or direct reassignment
    def reduce_colors(coloring: list[int]) -> list[int]:
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        vertices = [i for i in range(n) if coloring[i] == target_color]
        # Try direct reassignment first
        for v in vertices:
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != target_color:  # only consider colors < target_color for moving down
                    neighbor_colors |= (1 << coloring[u])
            # Find smallest color < target_color not used by neighbors
            for c in range(target_color):
                if not (neighbor_colors & (1 << c)):
                    coloring[v] = c
                    break
            else:
                continue  # could not reassign directly
            # Successfully reassigned, remove v from vertices
            vertices.remove(v)
        if not vertices:
            # All vertices of target_color reassigned, compact colors
            new_coloring = [-1] * n
            for i in range(n):
                if coloring[i] < target_color:
                    new_coloring[i] = coloring[i]
                elif coloring[i] > target_color:
                    new_coloring[i] = coloring[i] - 1
            return renumber_colors(new_coloring)
        # Try Kempe chains for each remaining vertex in target_color
        made_progress = False
        for v in vertices[:]:  # iterate over copy
            for c in range(target_color):
                # Check if v has a neighbor of color c (necessary for Kempe chain to be useful)
                has_neighbor_c = any(coloring[u] == c for u in neighbors[v])
                if not has_neighbor_c:
                    continue
                # Try to swap along Kempe chain (v, target_color) <-> c
                # Make a copy to test
                test_coloring = coloring[:]
                if kempe_swap(test_coloring, target_color, c, v):
                    # After swap, check if v is no longer target_color
                    if test_coloring[v] != target_color:
                        # Accept the swap
                        coloring = test_coloring
                        made_progress = True
                        break  # break color loop, go to next vertex
            if made_progress:
                made_progress = False
                # Re-assign vertices list after change
                vertices = [i for i in range(n) if coloring[i] == target_color]
                if not vertices:
                    break
        if not vertices:
            new_coloring = [-1] * n
            for i in range(n):
                if coloring[i] < target_color:
                    new_coloring[i] = coloring[i]
                elif coloring[i] > target_color:
                    new_coloring[i] = coloring[i] - 1
            return renumber_colors(new_coloring)
        return coloring

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select the candidate with fewest colors
    best = min(candidates, key=num_colors)
    best_colors = num_colors(best)

    # Try to reduce colors iteratively (up to a limit to stay within time)
    current = best[:]
    for _ in range(10):  # limit iterations
        reduced = reduce_colors(current)
        if num_colors(reduced) < num_colors(current):
            current = reduced
        else:
            break

    # Final validation and renumber
    if not is_valid_coloring(current):
        # Fallback to DSATUR if something went wrong
        current = dsatur()
    current = renumber_colors(current)
    return current

