    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
