            while U:
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    u_deg = len([w for w in neighbors[u] if w in U])
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or (w_neighbors == best_w_neighbors and u_deg == best_u_deg and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
