def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list if needed
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        # Ensure it's a list of lists
        adj_list = [list(neighbors) for neighbors in adj]

    # Precompute degrees
    degrees = [len(adj_list[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1 consecutive
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor_colors[v] = bitmask of colors used by neighbors
        neighbor_colors = [0] * n
        colored = [False] * n

        # Helper to update saturation when a vertex is colored
        def update_saturation(v, color):
            for u in adj_list[v]:
                if not colored[u]:
                    # If this color is new in u's neighbor colors
                    if not (neighbor_colors[u] & (1 << color)):
                        neighbor_colors[u] |= (1 << color)
                        saturation[u] += 1

        for _ in range(n):
            # Select uncolored vertex with max saturation, break ties by degree, then random
            candidates = []
            max_sat = -1
            for v in range(n):
                if not colored[v]:
                    if saturation[v] > max_sat:
                        max_sat = saturation[v]
                        candidates = [v]
                    elif saturation[v] == max_sat:
                        candidates.append(v)
            if not candidates:
                break  # should not happen
            # Tie-break by degree (uncolored degree)
            max_deg = -1
            best_candidates = []
            for v in candidates:
                # degree in uncolored subgraph
                deg = 0
                for u in adj_list[v]:
                    if not colored[u]:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    best_candidates = [v]
                elif deg == max_deg:
                    best_candidates.append(v)
            if not best_candidates:
                v = random.choice(candidates)
            else:
                v = random.choice(best_candidates)

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True
            update_saturation(v, c)

        return normalize(coloring)

    # RLF algorithm (Largest First Independent Set)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        colored = [False] * n
        color = 0

        # Helper: degree in uncolored subgraph
        def uncolored_degree(v):
            d = 0
            for u in adj_list[v]:
                if not colored[u]:
                    d += 1
            return d

        while True:
            # Find uncolored vertices
            uncolored = [v for v in range(n) if not colored[v]]
            if not uncolored:
                break
            # Start new independent set with max degree vertex in uncolored subgraph
            S = []
            # Choose v with max degree in G[uncolored]
            max_deg = -1
            v0 = -1
            for v in uncolored:
                deg = uncolored_degree(v)
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            if v0 == -1:
                break
            S.append(v0)
            colored[v0] = True
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = []
            W = set()
            for v in uncolored:
                if v == v0:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.append(v)
            # While U not empty, add vertex from U with max neighbors in W
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_count += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:  # note: U is list, but we check membership; could be slow, but n<=100
                            deg_in_U += 1
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                    elif w_count == max_w_neighbors:
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                if best_u == -1:
                    break
                # Add best_u to S
                S.append(best_u)
                colored[best_u] = True
                # Remove best_u from U
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1

        return normalize(coloring)

    # Smallest-Last (Matula-Beck) greedy ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        degree = [degrees[i] for i in range(n)]  # current degree in remaining graph
        order = []  # will be removal order
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for nb in adj_list[v_min]:
                if nb in remaining:
                    degree[nb] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            used = [False] * (n + 1)  # safe upper bound
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # Should not happen, but skip
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = set()
                for nb in adj_list[v]:
                    if current[nb] < target_color:
                        used_by_neighbors.add(current[nb])
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        # Can recolor v to c
                        current[v] = c
                        changed = True
                        break
                if changed:
                    # After recoloring, we may have emptied target_color; break to restart
                    break
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Check if v can be swapped with color c via Kempe chain
                    # We consider the subgraph induced by colors {c, target_color}
                    # Find the Kempe chain component containing v in this subgraph
                    # If the component does not contain any vertex of color c that is adjacent to a vertex of color target_color outside the component? 
                    # Actually, we want to swap the component if it doesn't cause conflict.
                    # Standard: if the Kempe chain of v in colors {c, target_color} does not contain a neighbor of v with color c, then we can swap.
                    # But simpler: we can try to swap the component and see if it's valid.
                    # Instead, we do: if there is no path from v to any vertex of color c using only colors {c, target_color} that would cause a conflict? 
                    # Actually, the condition is: if in the Kempe chain component of v (for colors c and target_color), there is no vertex of color c that is adjacent to a vertex of color target_color that is not in the component? 
                    # This is complex.
                    # Simpler heuristic: attempt to swap the component and check validity.
                    # Build the component: all vertices reachable from v via alternating colors c and target_color.
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    # We'll collect the component and then try swapping
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (current[nb] == c or current[nb] == target_color):
                                visited.add(nb)
                                queue.append(nb)
                    # Now, create a swapped coloring: swap c and target_color in component
                    swapped = current[:]
                    for node in component:
                        if swapped[node] == c:
                            swapped[node] = target_color
                        elif swapped[node] == target_color:
                            swapped[node] = c
                    # Check if swapped is valid
                    if is_valid_coloring(swapped):
                        # If valid, and after swap, the target_color class might be reduced
                        # We accept the swap
                        current = swapped
                        changed = True
                        break
                if changed:
                    break
            # After processing all target vertices (or breaking early), if we changed, we continue loop to possibly reduce further
            # If we didn't change and target_color class is not empty, we cannot reduce
            if not changed:
                # Check if target_color class is still non-empty
                if any(current[v] == target_color for v in range(n)):
                    break
                else:
                    changed = True  # to trigger another iteration to try to reduce further
        # Normalize to ensure consecutive colors
        return normalize(current)

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            coloring = func()
            if not is_valid_coloring(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            continue

    # If no heuristic produced a valid coloring (should not happen), fall back to greedy
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        coloring = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_coloring = improved
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))
    best_coloring = normalize(best_coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build neighbor bitmasks and adjacency list
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= 1 << v
                    neighbors[u].append(v)
    else:
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= 1 << v
                neighbors[u].append(v)

    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and bin(bit_adj[u] & sum(1 << w for w in uncolored)).count('1') > max_deg):
                    max_sat = sat[u]
                    max_deg = bin(bit_adj[u] & sum(1 << w for w in uncolored)).count('1')
                    v = u
            if v == -1:
                v = next(iter(uncolored))
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] = bin(bit_adj[u] & sum(1 << w for w in range(n) if color[w] != -1)).count('1')
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: bin(bit_adj[u] & sum(1 << w for w in uncolored)).count('1'))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = uncolored - {v} - {w for w in neighbors[v] if w in uncolored}
            W = {w for w in neighbors[v] if w in uncolored}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = None
                max_w_neighbors = -1
                min_u_degree = float('inf')
                for u in U:
                    w_neighbors = bin(bit_adj[u] & sum(1 << w for w in W)).count('1')
                    u_degree = bin(bit_adj[u] & sum(1 << w for w in U)).count('1')
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and u_degree < min_u_degree):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        u_star = u
                if u_star is None:
                    u_star = next(iter(U))
                independent_set.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[u]) for u in range(n)]
        # Bucket sort by degree
        buckets = [[] for _ in range(n)]
        for u in range(n):
            if deg[u] < n:
                buckets[deg[u]].append(u)
        min_deg = 0
        for _ in range(n):
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            u = buckets[min_deg].pop()
            order.append(u)
            remaining.remove(u)
            for v in neighbors[u]:
                if v in remaining:
                    d = deg[v]
                    deg[v] -= 1
                    if deg[v] < n:
                        buckets[deg[v]].append(v)
                    if deg[v] < min_deg:
                        min_deg = deg[v]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except:
            continue

    # Also try Welsh-Powell (degree descending)
    wp_order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
    col_wp = greedy_color(wp_order)
    if is_valid(col_wp):
        candidates.append(col_wp)

    # If no candidate, fallback to greedy on natural order
    if not candidates:
        col_natural = greedy_color(list(range(n)))
        if is_valid(col_natural):
            candidates.append(col_natural)

    # Select best candidate
    for col in candidates:
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to lower colors
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True, coloring  # already empty
        # Try direct reassignment first
        new_coloring = coloring[:]
        for v in vertices:
            used = 0
            for u in neighbors[v]:
                c = new_coloring[u]
                if c != -1:
                    used |= 1 << c
            # Find smallest color < target_color not used
            for c in range(target_color):
                if not (used & (1 << c)):
                    new_coloring[v] = c
                    break
            else:
                # Cannot directly assign, try Kempe chains
                recolored = False
                for c in range(target_color):
                    # Check if v can be swapped via (c, target_color) Kempe chain
                    # Build component of v in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v has color c (would cause conflict if swapped)
                    conflict = False
                    for x in component:
                        for y in neighbors[x]:
                            if y not in component and coloring[y] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors c and target_color in component
                        for x in component:
                            if new_coloring[x] == c:
                                new_coloring[x] = target_color
                            elif new_coloring[x] == target_color:
                                new_coloring[x] = c
                        recolored = True
                        break
                if not recolored:
                    return False, coloring  # cannot eliminate
        # Recolor succeeded, now compact colors if target_color was highest
        max_color = max(new_coloring)
        if target_color == max_color:
            # Shift down colors > target_color? Actually we removed target_color, so remap
            mapping = {}
            new_color = 0
            for orig in range(max_color + 1):
                if orig == target_color:
                    continue
                mapping[orig] = new_color
                new_color += 1
            for v in range(n):
                new_coloring[v] = mapping[new_coloring[v]]
        return True, new_coloring

    # Iteratively try to reduce colors
    current = best_coloring[:]
    changed = True
    while changed and current:
        changed = False
        k = count_colors(current)
        # Try to eliminate highest color class first (most likely to succeed)
        for target_color in range(k-1, -1, -1):
            success, new_coloring = eliminate_color_class(current, target_color)
            if success:
                current = new_coloring
                changed = True
                break  # restart from new coloring
        if not changed:
            break

    # Final validation and consecution
    if not is_valid(current):
        # Fallback to best candidate if Kempe broke validity
        current = best_coloring

    # Ensure colors are consecutive starting from 0
    if current:
        unique_colors = sorted(set(current))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        current = [mapping[c] for c in current]

    return current

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    deg = [len(adj_list[i]) for i in range(n)]

    # Helper: greedy coloring given an ordering
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return len(set(coloring))

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    color_dsatur = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))
    for _ in range(n):
        if not uncolored:
            break
        # Select vertex with max saturation, tie-break by degree in uncolored subgraph
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(saturated[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)
        if max_sat == -1:
            # All have saturation 0, pick max degree in uncolored
            max_deg = -1
            for v in uncolored:
                d = sum(1 for u in adj_list[v] if u in uncolored)
                if d > max_deg:
                    max_deg = d
                    candidates = [v]
                elif d == max_deg:
                    candidates.append(v)
        v = random.choice(candidates) if candidates else next(iter(uncolored))
        # Assign smallest available color
        used = [False] * n
        for u in adj_list[v]:
            if color_dsatur[u] != -1:
                used[color_dsatur[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color_dsatur[v] = c
        uncolored.remove(v)
        # Update saturation of uncolored neighbors
        for u in adj_list[v]:
            if u in uncolored:
                saturated[u].add(c)
    k_dsatur = count_colors(color_dsatur)
    if k_dsatur < best_k and is_valid(color_dsatur):
        best_k = k_dsatur
        best_coloring = color_dsatur[:]

    # 2. RLF (Recursive Largest First)
    color_rlf = [-1] * n
    uncolored_rlf = set(range(n))
    c = 0
    while uncolored_rlf:
        # Find vertex with max degree in uncolored subgraph
        max_deg = -1
        v1 = -1
        for v in uncolored_rlf:
            d = sum(1 for u in adj_list[v] if u in uncolored_rlf)
            if d > max_deg:
                max_deg = d
                v1 = v
        if v1 == -1:
            break
        S = {v1}
        U = set(uncolored_rlf - {v1})
        W = set()
        # Initial partition: U = not adjacent to S, W = adjacent to S
        for v in U.copy():
            if any(u in S for u in adj_list[v]):
                U.remove(v)
                W.add(v)
        # Grow independent set S
        while U:
            # Select u in U with max |N(u) ∩ W|
            best_u = -1
            best_score = -1
            for u in U:
                score = sum(1 for w in adj_list[u] if w in W)
                if score > best_score:
                    best_score = score
                    best_u = u
                elif score == best_score:
                    # Tie-break: min degree in G[U]
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    deg_best = sum(1 for w in adj_list[best_u] if w in U) if best_u != -1 else float('inf')
                    if deg_u < deg_best:
                        best_u = u
            if best_u == -1:
                break
            S.add(best_u)
            U.remove(best_u)
            # Move neighbors of best_u from U to W
            for w in adj_list[best_u]:
                if w in U:
                    U.remove(w)
                    W.add(w)
        # Assign color c to all in S
        for v in S:
            color_rlf[v] = c
        uncolored_rlf -= S
        c += 1
    k_rlf = count_colors(color_rlf)
    if k_rlf < best_k and is_valid(color_rlf):
        best_k = k_rlf
        best_coloring = color_rlf[:]

    # 3. Smallest-Last (Matula-Beck) ordering
    # Compute degeneracy ordering
    remaining = set(range(n))
    degree = deg[:]
    order = []
    # Bucket sort by degree
    max_deg = max(degree) if n > 0 else 0
    buckets = [[] for _ in range(max_deg + 1)]
    for v in range(n):
        d = degree[v]
        if d < len(buckets):
            buckets[d].append(v)
    # Pointer to current non-empty bucket
    ptr = 0
    while remaining:
        # Find next non-empty bucket
        while ptr < len(buckets) and not buckets[ptr]:
            ptr += 1
        if ptr >= len(buckets):
            break
        # Get a vertex from bucket[ptr]
        while buckets[ptr] and buckets[ptr][-1] not in remaining:
            buckets[ptr].pop()
        if not buckets[ptr]:
            ptr += 1
            continue
        v = buckets[ptr].pop()
        if v not in remaining:
            continue
        order.append(v)
        remaining.remove(v)
        # Update degrees of neighbors
        for u in adj_list[v]:
            if u in remaining:
                d_u = degree[u]
                degree[u] -= 1
                if d_u < len(buckets):
                    buckets[d_u].append(u)
                if degree[u] < ptr:
                    ptr = degree[u]
    # Reverse for coloring order
    order_sl = order[::-1]
    color_sl = greedy_color(order_sl)
    k_sl = count_colors(color_sl)
    if k_sl < best_k and is_valid(color_sl):
        best_k = k_sl
        best_coloring = color_sl[:]

    # If no valid coloring found (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        changed = True
        while changed and best_k > 0:
            changed = False
            # Identify color classes
            classes = [[] for _ in range(best_k)]
            for v in range(n):
                c = coloring[v]
                if c < best_k:
                    classes[c].append(v)
            # Target smallest color class (highest index)
            target_color = best_k - 1
            while target_color >= 0 and not classes[target_color]:
                target_color -= 1
            if target_color < 0:
                break
            # Try to recolor each vertex in target class
            for v in classes[target_color][:]:
                # Try direct reassignment to a lower color
                used = [False] * best_k
                for u in adj_list[v]:
                    cu = coloring[u]
                    if cu < best_k:
                        used[cu] = True
                for c in range(target_color):
                    if not used[c]:
                        coloring[v] = c
                        classes[target_color].remove(v)
                        classes[c].append(v)
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Build (target_color, c)-Kempe chain containing v
                    stack = [v]
                    visited = set([v])
                    component = set()
                    while stack:
                        node = stack.pop()
                        component.add(node)
                        for u in adj_list[node]:
                            col_u = coloring[u]
                            if col_u == target_color or col_u == c:
                                if u not in visited:
                                    visited.add(u)
                                    stack.append(u)
                    # Check if inverting this component frees color c for v
                    # After inversion, v would become color c (since it was target_color)
                    # So we need that no neighbor of v has color c after inversion
                    # Neighbors of v that are in component and were color c become target_color
                    # Neighbors of v that are in component and were target_color become c
                    # Neighbors not in component keep their color
                    conflict = False
                    for u in adj_list[v]:
                        col_u = coloring[u]
                        if u in component:
                            # After swap: if was c -> becomes target_color; if was target_color -> becomes c
                            if col_u == c:
                                # becomes target_color, not c
                                pass
                            elif col_u == target_color:
                                # becomes c -> conflict
                                conflict = True
                                break
                        else:
                            if col_u == c:
                                conflict = True
                                break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        # Update classes
                        for node in component:
                            old_col = target_color if coloring[node] == c else c
                            new_col = coloring[node]
                            if old_col < best_k:
                                if node in classes[old_col]:
                                    classes[old_col].remove(node)
                            if new_col < best_k:
                                classes[new_col].append(node)
                        # Check if target color class is now empty
                        if not classes[target_color]:
                            changed = True
                            break
                    if changed:
                        break
            # If target color class is empty, compact colors
            if not classes[target_color]:
                # Reindex colors: shift down all colors > target_color
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                best_k -= 1
                changed = True
        return coloring

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)
    best_k = count_colors(best_coloring)

    # Final validation and ensure consecutive colors
    if not is_valid(best_coloring):
        # Fallback to greedy
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)
    # Relabel colors to be consecutive starting from 0
    color_map = {}
    next_color = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best_coloring[v] = color_map[c]

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    # Convert input to adjacency list and handle edge cases
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary entries (0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Convert adjacency list to bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in graph[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bit masks for fast saturation update
        neighbor_colors = [0] * n

        # order: list of uncolored vertices
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > best_sat:
                    best_sat = sat_v
                    best_deg = bit_count(bit_adj[v] & sum((1 << u) for u in uncolored))
                    best_v = v
                elif sat_v == best_sat:
                    deg_v = bit_count(bit_adj[v] & sum((1 << u) for u in uncolored))
                    if deg_v > best_deg:
                        best_deg = deg_v
                        best_v = v
                    elif deg_v == best_deg:
                        if random.random() < 0.5:  # random tie-break
                            best_v = v
            v = best_v
            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            # update uncolored set
            uncolored.remove(v)
            # update saturation and neighbor_colors for neighbors of v
            for u in graph[v]:
                if u in uncolored:
                    # if color c is new in u's neighbor colors
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return normalize_colors(colors)

    # RLF algorithm
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for color_idx
            # Step 1: pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bit_count(bit_adj[x] & sum((1 << u) for u in uncolored)))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - {u for u in graph[v] if u in uncolored}
            W = {u for u in graph[v] if u in uncolored}

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # neighbors of u in W
                    score = bit_count(bit_adj[u] & sum((1 << w) for w in W))
                    if score > best_score:
                        best_score = score
                        best_deg_U = bit_count(bit_adj[u] & sum((1 << x) for x in U))
                        best_u = u
                    elif score == best_score:
                        deg_U = bit_count(bit_adj[u] & sum((1 << x) for x in U))
                        if deg_U < best_deg_U:
                            best_deg_U = deg_U
                            best_u = u
                        elif deg_U == best_deg_U:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for w in graph[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color_idx to all in independent_set
            for v in independent_set:
                colors[v] = color_idx
            uncolored -= independent_set
            color_idx += 1
        return normalize_colors(colors)

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        degrees = [bit_count(bit_adj[i]) for i in range(n)]
        # We'll simulate removal
        removed = [False] * n
        order = []  # removal order
        # current degrees in remaining graph
        curr_deg = degrees[:]
        # For efficiency, we use bucket sort like approach but n is small
        for _ in range(n):
            # find vertex with min curr_deg among not removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and curr_deg[i] < min_deg:
                    min_deg = curr_deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in graph[v]:
                if not removed[u]:
                    curr_deg[u] -= 1
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in graph[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # target the smallest color class (by size)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[colors[v]].append(v)
            # find smallest non-empty color class
            target_color = -1
            min_size = float('inf')
            for c in range(k):
                if color_classes[c] and len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1:
                break

            # Try to recolor each vertex in target_color
            for v in color_classes[target_color][:]:  # copy list as we may modify
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for u in graph[v]:
                        if colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    # restart the while loop as coloring changed
                    break

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component containing v
                    # only if v is not already c (we know it's target_color)
                    # Build the Kempe chain: connected component of v in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for neighbor in graph[node]:
                            if not visited[neighbor] and (colors[neighbor] == c or colors[neighbor] == target_color):
                                visited[neighbor] = True
                                queue.append(neighbor)
                    # Check if swapping in this component would cause conflict: 
                    # After swap, vertices originally color c become target_color and vice versa.
                    # We need to ensure that no neighbor outside the component has the color that would cause conflict.
                    # Specifically, for any vertex in component that is currently color c, after swap it becomes target_color.
                    # So we must check that no neighbor of such a vertex (outside component) is target_color.
                    # Similarly, for vertices currently target_color (like v), after swap become c, so no neighbor outside should be c.
                    valid_swap = True
                    for node in component:
                        if colors[node] == c:
                            # after swap becomes target_color
                            for neighbor in graph[node]:
                                if not visited[neighbor] and colors[neighbor] == target_color:
                                    valid_swap = False
                                    break
                            if not valid_swap:
                                break
                        else:  # colors[node] == target_color
                            # after swap becomes c
                            for neighbor in graph[node]:
                                if not visited[neighbor] and colors[neighbor] == c:
                                    valid_swap = False
                                    break
                            if not valid_swap:
                                break
                    if valid_swap:
                        # perform swap
                        for node in component:
                            if colors[node] == c:
                                colors[node] = target_color
                            else:  # must be target_color
                                colors[node] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # renumber colors to be consecutive
                colors = normalize_colors(colors)
                k = num_colors(colors)
        return colors

    # Run all heuristics and keep the best
    best_colors = None
    best_k = float('inf')

    # Time budget check: we'll run heuristics but break if time exceeds
    start_time = time.time()
    time_limit = 0.04  # 40ms to leave room for Kempe and overhead

    # DSATUR
    if time.time() - start_time < time_limit:
        c1 = dsatur()
        k1 = num_colors(c1)
        if k1 < best_k and is_valid_coloring(c1):
            best_k = k1
            best_colors = c1

    # RLF
    if time.time() - start_time < time_limit:
        c2 = rlf()
