def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: get neighbors mask
    def neighbors_mask(u):
        return bit_adj[u]

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colorsets as bitmask for fast saturation update
        neighbor_colors = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = bin(neighbors_mask(v) & sum((1 << u) for u in uncolored)).count("1")
                elif sat == best_sat:
                    deg = bin(neighbors_mask(v) & sum((1 << u) for u in uncolored)).count("1")
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
            v = best_v
            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return coloring

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            deg_in_uncolored = {}
            for v in uncolored:
                deg = bin(neighbors_mask(v) & sum((1 << u) for u in uncolored)).count("1")
                deg_in_uncolored[v] = deg
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = uncolored - independent_set - {u for u in uncolored if any((neighbors_mask(w) >> u) & 1 for w in independent_set)}
            W = {u for u in uncolored if u not in independent_set and any((neighbors_mask(w) >> u) & 1 for w in independent_set)}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_in_U = None
                for u in U:
                    score = bin(neighbors_mask(u) & sum((1 << w) for w in W)).count("1")
                    if score > best_score:
                        best_score = score
                        best_u = u
                        # deg in U for tie-break
                        best_deg_in_U = bin(neighbors_mask(u) & sum((1 << w) for w in U)).count("1")
                    elif score == best_score:
                        deg_u = bin(neighbors_mask(u) & sum((1 << w) for w in U)).count("1")
                        if deg_u < best_deg_in_U:
                            best_deg_in_U = deg_u
                            best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                nbrs_u = {w for w in U if (neighbors_mask(u) >> w) & 1}
                U -= nbrs_u
                W |= nbrs_u
            # assign color to independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[v]) for v in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # pointer to current min non-empty bucket
        min_deg = 0
        for _ in range(n):
            # find next non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                    if degree[u] < min_deg:
                        min_deg = degree[u]
        # color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest downward
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already empty, compact
                mapping = {}
                new_color = 0
                for c in range(k):
                    if any(coloring[v] == c for v in range(n)):
                        mapping[c] = new_color
                        new_color += 1
                for v in range(n):
                    if coloring[v] in mapping:
                        coloring[v] = mapping[coloring[v]]
                k = new_color
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if coloring[u] != -1 and coloring[u] < target_color:
                        used |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # can recolor directly
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already recolored, break
                    if coloring[v] != target_color:
                        break
                # Build Kempe chain for (target_color, c) containing v
                # We'll do BFS
                from collections import deque
                visited = [False] * n
                queue = deque()
                if coloring[v] == target_color:
                    queue.append(v)
                    visited[v] = True
                component = []
                while queue:
                    node = queue.popleft()
                    component.append(node)
                    for u in adj_list[node]:
                        if not visited[u] and (coloring[u] == target_color or coloring[u] == c):
                            visited[u] = True
                            queue.append(u)
                # Check if swapping this component is safe: no neighbor outside component has color c
                # Actually, swapping is always safe for Kempe chain, but we want to free color c for v
                # After swap, v will have color c if it was target_color
                # We need to ensure that after swap, no two adjacent have same color (which is guaranteed by Kempe)
                # But we also want to reduce the number of vertices in target_color
                # So we swap if v is in the component (it is) and after swap it becomes c
                # However, we must check that we don't accidentally increase another color class? Not needed.
                # Perform swap: target_color <-> c in component
                for node in component:
                    if coloring[node] == target_color:
                        coloring[node] = c
                    elif coloring[node] == c:
                        coloring[node] = target_color
                # Now v has color c (if it was target_color)
                if coloring[v] == c:
                    improved = True
                    break
            if not improved:
                # cannot reduce further
                break
            # compact colors if target_color class is empty
            if not any(coloring[v] == target_color for v in range(n)):
                mapping = {}
                new_color = 0
                for c in range(k):
                    if any(coloring[v] == c for v in range(n)):
                        mapping[c] = new_color
                        new_color += 1
                for v in range(n):
                    if coloring[v] in mapping:
                        coloring[v] = mapping[coloring[v]]
                k = new_color
        return coloring

    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Choose best (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for coloring in candidates:
        if not is_valid(coloring):
            continue
        k = count_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring
    if best_coloring is None:
        # fallback: greedy by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = coloring

    # Apply Kempe reduction to try to improve
    best_coloring = kempe_reduce(best_coloring)

    # Final validation and compacting
    if not is_valid(best_coloring):
        # last resort: greedy
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = coloring

    # Ensure colors are 0..k-1 consecutive
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors)))
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

