            # Build (target_color, swap_color) Kempe chain containing v
            # We'll do BFS to get the component
            from collections import deque
            visited = [False] * n
            queue = deque([v])
            visited[v] = True
            component = []
            while queue:
                node = queue.popleft()
                component.append(node)
                for nb in adj_list[node]:
                    if not visited[nb] and (color[nb] == target_color or color[nb] == swap_color):
                        visited[nb] = True
                        queue.append(nb)

