        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in remaining:
            buckets[degrees[v]].append(v)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    buckets[old_deg].remove(u)
                    degrees[u] -= 1
                    new_deg = degrees[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    else:
                        # should not happen as degree decreases
                        pass
            if ptr > degrees[v] if v in remaining else 0:
                ptr = min(degrees[u] for u in remaining) if remaining else 0
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = {coloring[u] for u in neighbors[v] if coloring[u] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
