                    #       if u in component and coloring[u]==target_color -> becomes c (conflict!)
                    #       if u not in component: color unchanged
                    # So conflict if exists neighbor u of v such that:
                    #   (u not in component and coloring[u]==c) OR (u in component and coloring[u]==target_color)
                    conflict = False
                    for u in neighbors[v]:
