    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = {coloring[u] for u in neighbors[v] if coloring[u] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        candidates.append(compact_colors(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid(best):
