        coloring = [-1] * n
        for v in range(n):
            used = {coloring[u] for u in neighbors[v] if coloring[u] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best = compact_colors(coloring)
    else:
        best = compact_colors(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            if not all(x in (0, 1) for x in row):
                is_matrix = False
                break

    # Build bitmask adjacency
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            mask = 0
            for v in range(n):
                if adj[u][v]:
                    mask |= (1 << v)
            bit_adj[u] = mask
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                if 0 <= v < n:
                    mask |= (1 << v)
            bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            nbrs = bit_adj[u]
            v = nbrs
            while v:
                lb = v & -v
                idx = (lb.bit_length() - 1)
                if color[idx] != -1:
                    used |= (1 << color[idx])
                v ^= lb
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            c_u = coloring[u]
            nbrs = bit_adj[u]
            v = nbrs
            while v:
                lb = v & -v
                idx = (lb.bit_length() - 1)
                if coloring[idx] == c_u:
                    return False
                v ^= lb
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        saturation = [0] * n
        degree = [bin(bit_adj[i]).count('1') for i in range(n)]
        while uncolored:
            # Find vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for v in uncolored:
                if saturation[v] > max_sat:
                    max_sat = saturation[v]
                    candidates = [v]
                elif saturation[v] == max_sat:
                    candidates.append(v)
            # Tie-break by degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                final_candidates = []
                for v in candidates:
                    deg = bin(bit_adj[v] & sum((1 << u) for u in uncolored)).count('1')
                    if deg > max_deg:
                        max_deg = deg
                        final_candidates = [v]
                    elif deg == max_deg:
                        final_candidates.append(v)
                candidates = final_candidates
            v = random.choice(candidates) if candidates else next(iter(uncolored))
            uncolored.remove(v)
            # Compute used colors from neighbors
            used = 0
            nbrs = bit_adj[v]
            w = nbrs
            while w:
                lb = w & -w
                idx = (lb.bit_length() - 1)
                if color[idx] != -1:
                    used |= (1 << color[idx])
                w ^= lb
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # Update saturation of uncolored neighbors
            nbrs = bit_adj[v]
            w = nbrs
            while w:
                lb = w & -w
                idx = (lb.bit_length() - 1)
                if idx in uncolored:
                    saturation[idx] += 1
                w ^= lb
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            S = []
            # Compute degrees in uncolored subgraph
            deg_uncolored = {}
            for v in uncolored:
                deg = bin(bit_adj[v] & sum((1 << u) for u in uncolored)).count('1')
                deg_uncolored[v] = deg
            v1 = max(uncolored, key=lambda x: deg_uncolored[x])
            S.append(v1)
            # U: vertices not adjacent to any in S
            # W: vertices adjacent to at least one in S
            adj_S = 0
            for u in S:
                adj_S |= bit_adj[u]
            U = uncolored - {v1} - set([i for i in range(n) if (adj_S >> i) & 1])
            W = uncolored - U - {v1}
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_U = math.inf
                for u in U:
                    nbrs_u = bit_adj[u]
                    w_count = bin(nbrs_u & sum((1 << w) for w in W)).count('1')
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        min_deg_U = bin(nbrs_u & sum((1 << x) for x in U)).count('1')
                        best_u = u
                    elif w_count == max_w_neighbors:
                        deg_u = bin(nbrs_u & sum((1 << x) for x in U)).count('1')
                        if deg_u < min_deg_U:
                            min_deg_U = deg_u
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                nbrs_best = bit_adj[best_u]
                w = nbrs_best
                while w:
                    lb = w & -w
                    idx = (lb.bit_length() - 1)
                    if idx in U:
                        U.remove(idx)
                        W.add(idx)
                    w ^= lb
            # Assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        # We'll simulate removal
        current_degrees = degrees[:]
        removed = [False] * n
        for _ in range(n):
            # Find vertex with minimum current degree
            min_deg = math.inf
            min_v = -1
            for v in remaining:
                if current_degrees[v] < min_deg:
                    min_deg = current_degrees[v]
                    min_v = v
            if min_v == -1:
                break
            order.append(min_v)
            removed[min_v] = True
            remaining.remove(min_v)
            # Update degrees of neighbors
            nbrs = bit_adj[min_v]
            w = nbrs
            while w:
                lb = w & -w
                idx = (lb.bit_length() - 1)
                if not removed[idx]:
                    current_degrees[idx] -= 1
                w ^= lb
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if starting from valid
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already empty, compact
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                k -= 1
                changed = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                nbrs = bit_adj[v]
                w = nbrs
                while w:
                    lb = w & -w
                    idx = (lb.bit_length() - 1)
                    if coloring[idx] != -1:
                        used |= (1 << coloring[idx])
                    w ^= lb
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Direct move possible
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    # After moving one vertex, check if target color class is empty
                    target_vertices = [v for v in range(n) if coloring[v] == target_color]
                    if not target_vertices:
                        for v in range(n):
                            if coloring[v] > target_color:
                                coloring[v] -= 1
                        k -= 1
                    break  # restart outer while loop
            if changed:
                continue
            # Try Kempe chains for each target vertex
            for v in target_vertices:
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (v, target_color) <-> (some u, c)
                    # Only if there is no path from v to any vertex of color c using only colors target_color and c
                    # We do BFS on the subgraph induced by colors {target_color, c}
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    found_c = False
                    while queue:
                        u = queue.popleft()
                        if coloring[u] == c:
                            found_c = True
                            break
                        # Explore neighbors with color target_color or c
                        nbrs = bit_adj[u]
                        w = nbrs
                        while w:
                            lb = w & -w
                            idx = (lb.bit_length() - 1)
                            col_idx = coloring[idx]
                            if col_idx == target_color or col_idx == c:
                                if idx not in visited:
                                    visited.add(idx)
                                    queue.append(idx)
                            w ^= lb
                    if not found_c:
                        # Swap colors target_color and c in the component containing v
                        for u in visited:
                            if coloring[u] == target_color:
                                coloring[u] = c
                            elif coloring[u] == c:
                                coloring[u] = target_color
                        changed = True
                        break
                if changed:
                    # After swap, check if target color class is empty
                    target_vertices = [v for v in range(n) if coloring[v] == target_color]
                    if not target_vertices:
                        for v in range(n):
                            if coloring[v] > target_color:
                                coloring[v] -= 1
                        k -= 1
                    break  # restart outer while
        return coloring

    # Generate candidates
    candidates = []

    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass

    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass

    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass

    # If no candidate, fallback to simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        col_greedy = greedy_color(order)
        if is_valid(col_greedy):
            candidates.append(col_greedy)
        else:
            # Ultimate fallback: assign distinct colors
            candidates.append(list(range(n)))

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best_coloring = kempe_reduce(best_coloring[:])  # work on a copy
    # Final validation and compacting
    if not is_valid(best_coloring):
        # Should not happen, but fallback
        best_coloring = list(range(n))
    # Ensure colors are consecutive starting from 0
    # Map colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]
    return best_coloring

