    def smallest_last():
        # compute removal order (smallest degree last)
        deg = [len(neighbors[u]) for u in range(n)]
        alive = [True] * n
        order = []
        for _ in range(n):
            # pick vertex with min degree
            u = -1
            min_deg = float('inf')
            for i in range(n):
                if alive[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    u = i
            order.append(u)
            alive[u] = False
            for v in neighbors[u]:
                if alive[v]:
                    deg[v] -= 1
        # color in reverse order
        return greedy_color(list(reversed(order)))

    # Heuristic 4: k-core decomposition ordering (outer to inner core)
    def core_order():
        core = core_numbers()
        # order by increasing core number (outer to inner)
        order = sorted(range(n), key=lambda u: core[u])
        return greedy_color(order)

    # Run all heuristics and pick best
    candidates = [
        dsatur(),
        rlf(),
        smallest_last(),
        core_order()
    ]
    # Also try Welsh-Powell (degree descending)
    wp_order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
    candidates.append(greedy_color(wp_order))

    best_color = None
    best_k = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            k = max(col) + 1 if n > 0 else 0
            if k < best_k:
                best_k = k
                best_color = col[:]

    # Fallback: if none valid (should not happen), use greedy on natural order
    if best_color is None:
        best_color = greedy_color(list(range(n)))

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    compacted = [0] * n
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        compacted[i] = unique_colors[c]
    return compacted

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets as bitmasks and list of neighbor indices
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    bit_adj[u] |= (1 << v)
                    neighbors[u].append(v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= (1 << v)
                    neighbors[u].append(v)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with degree tie-breaking
    start = time.time()
    def dsatur():
        color = [-1] * n
        # saturation degree: bitmask of colors used by colored neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[u]) for u in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and random.random() < 0.5):
                    max_sat = s
                    max_deg = d
                    v = u
            # assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and uncolored degree of neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color
    if time.time() - start < 0.04:  # time budget check
        c = dsatur()
        if is_valid(c):
            k = count_colors(c)
            if k < best_k:
                best_k = k
                best_coloring = c[:]

    # Strategy 2: Recursive Largest First (RLF) independent set extraction
    start = time.time()
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            deg_uncolored = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in neighbors[u]:
                    if v in uncolored:
                        deg_uncolored[u] += 1
            v = max(uncolored, key=lambda u: (deg_uncolored[u], random.random()))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = {u for u in uncolored if u != v and v not in neighbors[u]}
            W = {u for u in uncolored if u != v and v in neighbors[u]}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in G[U]
                def score(u):
                    w_count = sum(1 for w in neighbors[u] if w in W)
                    u_deg = sum(1 for w in neighbors[u] if w in U)
                    return (w_count, -u_deg, random.random())
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color
    if time.time() - start < 0.04:
        c = rlf()
        if is_valid(c):
            k = count_colors(c)
            if k < best_k:
                best_k = k
                best_coloring = c[:]

    # Strategy 3: Smallest-Last (Matula-Beck) ordering
    start = time.time()
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(neighbors[u]) for u in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for u in range(n):
            if deg[u] < n:
                buckets[deg[u]].append(u)
        for d in range(n):
            while buckets[d]:
                u = buckets[d].pop()
                if removed[u]:
                    continue
                if deg[u] != d:
                    buckets[deg[u]].append(u)
                    continue
                removed[u] = True
                order.append(u)
                for v in neighbors[u]:
                    if not removed[v]:
                        deg[v] -= 1
                        if deg[v] < n:
                            buckets[deg[v]].append(v)
        # color in reverse order
        return greedy_color(order[::-1])
    if time.time() - start < 0.04:
        c = smallest_last()
        if is_valid(c):
            k = count_colors(c)
            if k < best_k:
                best_k = k
                best_coloring = c[:]

    # If no strategy produced a valid coloring (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction: try to eliminate smallest color classes
    def kempe_reduce(coloring):
        nonlocal best_k, best_coloring
        # Make a copy to work on
        cur = coloring[:]
        changed = True
        while changed and best_k > 0:
            changed = False
            # Find smallest color class (by index, but we try to eliminate highest colors first)
            # We try to reduce the number of colors by eliminating the largest color index present
            max_color = max(cur) if cur else -1
            for target_color in range(max_color, -1, -1):
                # Get vertices with this color
                verts = [v for v in range(n) if cur[v] == target_color]
                if not verts:
                    continue
                # Try to recolor each vertex in this class to a lower color
                for v in verts:
                    used = 0
                    for u in neighbors[v]:
                        c = cur[u]
                        if c != -1:
                            used |= (1 << c)
                    # Try direct reassignment to a lower color
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            cur[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chain swaps with each lower color
                    for c in range(target_color):
                        if used & (1 << c):
                            continue  # color c is used by a neighbor, skip for now
                        # We want to swap colors target_color and c in the component containing v
                        # But only if v is not adjacent to any vertex of color c (already checked by used)
                        # Actually, we need to check if we can pull v into color c via Kempe chain
                        # Standard Kempe: consider subgraph induced by colors target_color and c
                        # Find connected component of v in that subgraph
                        from collections import deque
                        comp = set()
                        q = deque([v])
                        in_comp = [False] * n
                        in_comp[v] = True
                        while q:
                            x = q.popleft()
                            comp.add(x)
                            for y in neighbors[x]:
                                if not in_comp[y] and (cur[y] == target_color or cur[y] == c):
                                    in_comp[y] = True
                                    q.append(y)
                        # Check if any neighbor of v in the component has color c? Actually, by construction,
                        # neighbors of v in comp are only those with color target_color or c.
                        # But we already know v has no neighbor of color c (from used), so safe to swap?
                        # However, swapping might cause conflict if a neighbor of v in comp has color c after swap?
                        # Actually, after swap, vertices in comp that were target_color become c, and vice versa.
                        # Since v is target_color and has no neighbor of color c, after swap it becomes c and still no neighbor of c.
                        # For any other vertex u in comp:
                        #   If u was target_color, after swap it becomes c. Its neighbors: 
                        #       - outside comp: unchanged, so if they were c, now conflict? 
                        #       - inside comp: if neighbor was c, becomes target_color -> no conflict.
                        #   If u was c, after swap becomes target_color. Its neighbors:
                        #       - outside comp: if they were target_color, now conflict? 
                        # So we need to ensure that no vertex outside the component is colored c and adjacent to a vertex in the component that was target_color (which will become c).
                        # Similarly, no vertex outside the component colored target_color adjacent to a vertex in the component that was c (which will become target_color).
                        # This is equivalent to: the component is isolated with respect to colors c and target_color from the rest of the graph.
                        # Actually, the standard condition is that the component does not contain any vertex adjacent to a vertex of the opposite color outside the component.
                        # We can check: for any vertex u in comp, if it has a neighbor w not in comp with color c (if u was target_color) or color target_color (if u was c), then swap would cause conflict.
                        safe = True
                        for u in comp:
                            for w in neighbors[u]:
                                if not in_comp[w]:
                                    if cur[u] == target_color and cur[w] == c:
                                        safe = False
                                        break
                                    if cur[u] == c and cur[w] == target_color:
                                        safe = False
                                        break
                            if not safe:
                                break
                        if safe:
                            # perform swap
                            for u in comp:
                                if cur[u] == target_color:
                                    cur[u] = c
                                else:
                                    cur[u] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    # compact colors: remap to 0..k-1
                    # but we break to restart the while loop to re-evaluate color classes
                    break
            if changed:
                # compact color indices
                mapping = {}
                next_color = 0
                for v in range(n):
                    c = cur[v]
                    if c not in mapping:
                        mapping[c] = next_color
                        next_color += 1
                    cur[v] = mapping[c]
                # update best if better
                k = next_color
                if k < best_k and is_valid(cur):
                    best_k = k
                    best_coloring = cur[:]
        return best_coloring

    # Apply Kempe reduction if time permits
    if time.time() - start < 0.045:  # leave some margin
        best_coloring = kempe_reduce(best_coloring)

    # Final validation and compacting
    if not is_valid(best_coloring):
        # last resort: greedy by degree order
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        best_coloring = greedy_color(order)
    # Ensure colors are compact
    mapping = {}
    next_color = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        best_coloring[v] = mapping[c]

    return best_coloring

import math
