import time
from collections import deque

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Graph coloring algorithm with bipartite subgraph extraction and Kempe chain refinement.
    Designed to minimize chromatic number within strict time constraints.
    """
    if not adj:
        return []

    n = len(adj)

    # Convert to adjacency list if needed
    if isinstance(adj[0], list) and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]):
        # Adjacency matrix
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # Adjacency list
        graph = adj[:]
        # Ensure symmetric
        for u in range(n):
            for v in graph[u]:
                if u not in graph[v]:
                    graph[v].append(u)

    # Handle trivial cases
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Check if edgeless
    if all(len(graph[i]) == 0 for i in range(n)):
        return [0] * n

    # Check if complete graph
    is_complete = all(len(graph[i]) == n - 1 for i in range(n))
    if is_complete:
        return list(range(n))

    # Start time for budget enforcement
    start_time = time.time()
    time_limit = 0.045  # 45ms to leave margin

    def time_up():
        return time.time() - start_time > time_limit

    # Helper: Check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in graph[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: Get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: Normalize colors to 0..k-1
    def normalize_colors(colors):
        if not colors:
            return colors
        unique_colors = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in colors]

    # Strategy 1: Bipartite extraction + greedy refinement
    def bipartite_based_coloring():
        if time_up():
            return None

        colors = [-1] * n
        # Try to 2-color using BFS (bipartite check)
        is_bipartite = True
        for i in range(n):
            if colors[i] == -1:
                queue = deque([i])
                colors[i] = 0
                while queue and not time_up():
                    u = queue.popleft()
                    for v in graph[u]:
                        if colors[v] == -1:
                            colors[v] = 1 - colors[u]
                            queue.append(v)
                        elif colors[v] == colors[u]:
                            is_bipartite = False
                            break
                    if not is_bipartite:
                        break
                if not is_bipartite:
                    break

        if is_bipartite and not time_up():
            return normalize_colors(colors)

        # Not bipartite, need more colors
        # Use DSATUR on the remaining conflicts
        return dsatur_coloring()

    # Strategy 2: DSATUR with bitmask optimization
    def dsatur_coloring():
        if time_up():
            return None

        # Build bitmask adjacency
        bit_adj = [0] * n
        for u in range(n):
            for v in graph[u]:
                bit_adj[u] |= (1 << v)

        colors = [-1] * n
        # Saturation sets: track which colors appear in neighbors
        neighbor_colors = [set() for _ in range(n)]
        # Degree in uncolored subgraph
        uncolored_deg = [len(graph[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            if time_up():
                break

            # Select vertex with max saturation degree, tie-break by degree
            best_v = -1
            max_sat = -1
            max_deg = -1

            for v in uncolored:
                sat = len(neighbor_colors[v])
                deg = uncolored_deg[v]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or \
                   (sat == max_sat and deg == max_deg and v > best_v):
                    max_sat = sat
                    max_deg = deg
                    best_v = v

            if best_v == -1:
                break

            # Find smallest available color
            used = neighbor_colors[best_v]
            c = 0
            while c in used:
                c += 1
            colors[best_v] = c
            uncolored.remove(best_v)

            # Update neighbors
            for u in graph[best_v]:
                if u in uncolored:
                    neighbor_colors[u].add(c)
                    uncolored_deg[u] -= 1

        return normalize_colors(colors) if not time_up() else None

    # Strategy 3: Recursive Largest First (RLF)
    def rlf_coloring():
        if time_up():
            return None

        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored and not time_up():
            # Build maximal independent set for this color
            if not uncolored:
                break

            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to independent_set (ineligible)
            U = {u for u in uncolored if u != v and all(u not in graph[w] for w in independent_set)}
            W = {u for u in uncolored if u != v and u not in U}

            while U and not time_up():
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_u_degree = float('inf')

                for u in U:
                    w_neighbors = sum(1 for w in graph[u] if w in W)
                    u_degree = sum(1 for nb in graph[u] if nb in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and u_degree < min_u_degree) or \
                       (w_neighbors == max_w_neighbors and u_degree == min_u_degree and u > best_u):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        best_u = u

                if best_u == -1:
                    break

                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in graph[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
                uncolored.remove(v)

            color_idx += 1

        return normalize_colors(colors) if not time_up() else None

    # Strategy 4: Smallest-Last ordering
    def smallest_last_coloring():
        if time_up():
            return None

        # Peel vertices in order of increasing degree
        remaining = set(range(n))
        order = []
        degrees = [len(graph[u]) for u in range(n)]

        while remaining and not time_up():
            # Find vertex with minimum degree in remaining subgraph
            v = min(remaining, key=lambda x: sum(1 for y in graph[x] if y in remaining))
            order.append(v)
            remaining.remove(v)

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in graph[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

        return normalize_colors(colors) if not time_up() else None

    # Kempe chain elimination to reduce colors
    def kempe_reduce(colors):
        if time_up() or not colors:
            return colors

        # Normalize first
        colors = normalize_colors(colors)
        k = num_colors(colors)

        # Try to eliminate color classes from highest downward
        for target_color in range(k-1, 0, -1):
            if time_up():
                break

            # Get vertices with target color
            target_vertices = [i for i in range(n) if colors[i] == target_color]
            if not target_vertices:
                continue

            # Try to recolor each target vertex
            eliminated = True
            for v in target_vertices:
                if time_up():
                    break

                # Check direct recoloring to lower colors
                neighbor_colors = set()
                for u in graph[v]:
                    if colors[u] != -1:
                        neighbor_colors.add(colors[u])

                found = False
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        found = True
                        break

                if found:
                    continue

                # Try Kempe chain swaps
                for c in range(target_color):
                    if time_up():
                        break

                    # Build (c, target_color) Kempe chain containing v
                    # Only if v is not color c (it isn't, since it's target_color)
                    visited = set()
                    stack = [v]
                    component = set()
                    can_swap = True

                    while stack and not time_up():
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)

                        # Only traverse vertices of color c or target_color
                        if colors[u] not in (c, target_color):
                            can_swap = False
                            break

                        component.add(u)
                        for w in graph[u]:
                            if w not in visited and colors[w] in (c, target_color):
                                stack.append(w)

                    if not can_swap or time_up():
                        continue

                    # Check if swapping is safe: no neighbor of component has color c
                    # (would cause conflict after swap)
                    safe = True
                    for u in component:
                        for w in graph[u]:
                            if w not in component and colors[w] == c:
                                safe = False
                                break
                        if not safe:
                            break

                    if safe:
                        # Perform swap: c <-> target_color in component
                        for u in component:
                            if colors[u] == c:
                                colors[u] = target_color
                            else:  # must be target_color
                                colors[u] = c
                        # After swap, v should now be color c
                        found = True
                        break

                if not found:
                    eliminated = False
                    break

            if eliminated and not time_up():
                # Successfully eliminated target_color, rebuild and try again
                colors = normalize_colors(colors)
                # Restart reduction from current max color
                return kempe_reduce(colors)

        return colors

    # Run all strategies within time budget
    best_colors = None
    best_k = float('inf')

    strategies = [
        ("Bipartite-based", bipartite_based_coloring),
        ("DSATUR", dsatur_coloring),
        ("RLF", rlf_coloring),
        ("Smallest-Last", smallest_last_coloring)
    ]

    for name, strategy in strategies:
        if time_up():
            break
        try:
            colors = strategy()
            if colors is not None and is_valid_coloring(colors):
                k = num_colors(colors)
                if k < best_k:
                    best_k = k
                    best_colors = colors[:]
        except Exception:
            continue

    # Fallback: greedy by degree
    if best_colors is None or time_up():
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = set()
            for u in graph[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
