    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask
    # Helper: degree in uncolored subgraph
    def degree_in_uncolored(u, colored_mask):
        return (bit_adj[u] & ~colored_mask).bit_count()
    # Helper: saturation degree
    def saturation_degree(u, color_of):
        neighbor_colors = 0
        nbrs = bit_adj[u]
        while nbrs:
            v = (nbrs & -nbrs).bit_length() - 1
            nbrs &= nbrs - 1
            if color_of[v] != -1:
                neighbor_colors |= (1 << color_of[v])
        return neighbor_colors.bit_count()
