            neighbor_colors = 0
            nbrs = bit_adj[best_v]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                nbrs &= nbrs - 1
                if color_of[v] != -1:
                    neighbor_colors |= (1 << color_of[v])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color_of[best_v] = c
            colored_mask |= (1 << best_v)
