            S_mask = 0
            # Choose first vertex: max degree in uncolored subgraph
            best_v = -1
            best_deg = -1
            u = uncolored_mask
            while u:
                v = (u & -u).bit_length() - 1
                u &= u - 1
                deg = degree_in_uncolored(v, uncolored_mask)
                if deg > best_deg:
                    best_deg = deg
                    best_v = v
            if best_v == -1:
                break
            S_mask |= (1 << best_v)
            # Partition U and W
