                best_u = -1
                best_score = -1
                best_deg_u = -1
                uu = U_mask
                while uu:
                    u_candidate = (uu & -uu).bit_length() - 1
                    uu &= uu - 1
                    # score: number of neighbors in W
                    nbrs_in_W = (bit_adj[u_candidate] & W_mask).bit_count()
                    deg_u = degree_in_uncolored(u_candidate, U_mask)  # degree in current U
                    if nbrs_in_W > best_score or (nbrs_in_W == best_score and deg_u < best_deg_u):
                        best_score = nbrs_in_W
                        best_deg_u = deg_u
                        best_u = u_candidate
                if best_u == -1:
                    break
                S_mask |= (1 << best_u)
                # move best_u from U to W
                U_mask &= ~(1 << best_u)
                # move neighbors of best_u that are in U to W
