                break
            S.append(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                for s in S:
                    if u in neighbors[s]:
                        W.add(u)
                        U.remove(u)
                        break
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
