                if sat_u > best_sat or (sat_u == best_sat and deg_u > best_deg) or \
                   (sat_u == best_sat and deg_u == best_deg and u > best):
                    best = u
                    best_sat = sat_u
                    best_deg = deg_u
            if best == -1:
                break  # should not happen

            u = best
            # Assign smallest available color
            used = set()
            for v in neighbors[u]:
                if color[v] != -1:
                    used.add(color[v])
            c = 0
            while c in used:
                c += 1
            color[u] = c
            uncolored.remove(u)

            # Update saturation of uncolored neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    # Recompute saturation: count distinct colors in neighborhood
                    neighbor_colors = set()
                    for w in neighbors[v]:
                        if color[w] != -1:
                            neighbor_colors.add(color[w])
                    saturation[v] = len(neighbor_colors)
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
                S.add(v)
                uncolored.remove(v)

            # U: vertices not adjacent to S (eligible), W: vertices adjacent to S (ineligible)
            U = uncolored - set().union(*(neighbors[u] for u in S)) if S else uncolored.copy()
            W = set().union(*(neighbors[u] for u in S)) & uncolored

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                best = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    score = len(neighbors[u] & W)
                    deg_u = len(neighbors[u] & U)  # degree in U subgraph
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or \
                       (score == best_score and deg_u == best_deg_u and u < best):
                        best = u
                        best_score = score
                        best_deg_u = deg_u
                if best == -1:
                    break  # should not happen

                u = best
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                W.update(nbrs_u)
                U -= nbrs_u

            # Assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
        return color

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Core decomposition to get removal order
        remaining = set(range(n))
        degree = [len(neighbors[u]) for u in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            # Get a vertex from bucket[ptr]
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    degree[u] -= 1
                    if degree[u] < len(buckets):
                        buckets[degree[u]].append(u)
                    # Ensure ptr is not ahead
                    if degree[u] < ptr:
                        ptr = degree[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except:
        pass

    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except:
        pass

    # Smallest-Last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except:
        pass

    # Welsh-Powell (degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: (-degrees[x], x))
        col_wp = greedy_color(order_wp)
        candidates.append(col_wp)
    except:
        pass

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        if col is None:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = col[:]

    if best_coloring is None:
        # Fallback: trivial coloring
        best_coloring = list(range(n))
        best_k = n

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        changed = True
        while changed and best_k > 1:
            changed = False
            # Find smallest color class (by index, but we target highest color first for reduction)
            # We try to eliminate color classes from highest downward
            for target_color in range(best_k - 1, -1, -1):
                # Get vertices with this color
                vertices = [u for u in range(n) if coloring[u] == target_color]
                if not vertices:
                    continue  # already empty, should not happen if we maintain compact colors

                # Try to recolor each vertex in this class
                made_progress = False
                for u in vertices:
                    # Try direct reassignment to a lower color
                    used = set()
                    for v in neighbors[u]:
                        if coloring[v] != -1:
                            used.add(coloring[v])
                    for c in range(target_color):  # only try colors < target_color
                        if c not in used:
                            coloring[u] = c
                            made_progress = True
                            changed = True
                            break
                    if made_progress:
                        break

                if made_progress:
                    # Recompact colors if necessary (but we break to restart scan)
                    break

                # Try Kempe chains with each lower color
                for u in vertices:
                    for c in range(target_color):
                        if c in {coloring[v] for v in neighbors[u]}:
                            continue  # adjacent to color c, swap would conflict
                        # Check if u is not connected to any vertex of color c via a Kempe chain
                        # We do BFS on the subgraph of colors {target_color, c}
                        from collections import deque
                        visited = set()
                        queue = deque([u])
                        visited.add(u)
                        found_c = False
                        while queue:
                            x = queue.popleft()
                            if coloring[x] == c:
                                found_c = True
                                break
                            for y in neighbors[x]:
                                if y not in visited and coloring[y] in (target_color, c):
                                    visited.add(y)
                                    queue.append(y)
                        if not found_c:
                            # Swap colors in the component
                            for x in visited:
                                if coloring[x] == target_color:
                                    coloring[x] = c
                                elif coloring[x] == c:
                                    coloring[x] = target_color
                            made_progress = True
                            changed = True
                            break
                    if made_progress:
                        break
                if made_progress:
                    break

            # After attempting to eliminate a color, compact if the highest color is unused
            if best_k > 0:
                if not any(coloring[u] == best_k - 1 for u in range(n)):
                    # Shift down all colors >= best_k-1 (none, since we check)
                    # Actually, reindex colors to be consecutive
                    color_map = {}
                    next_color = 0
                    for u in range(n):
                        if coloring[u] not in color_map:
                            color_map[coloring[u]] = next_color
                            next_color += 1
                    for u in range(n):
                        coloring[u] = color_map[coloring[u]]
                    best_k = next_color

        return coloring

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
    except:
        pass  # fallback to current best

    # Final validation and compacting
    # Ensure valid coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Conflict: fix by assigning a new color (should not happen if algorithms are correct)
                # Recolor u with a new color
                used = set(best_coloring[w] for w in neighbors[u])
                c = 0
                while c in used:
                    c += 1
                best_coloring[u] = c

    # Compact colors to 0..k-1
    color_map = {}
    next_color = 0
    for u in range(n):
        if best_coloring[u] not in color_map:
            color_map[best_coloring[u]] = next_color
            next_color += 1
    for u in range(n):
        best_coloring[u] = color_map[best_coloring[u]]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format and build bitmask adjacency
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= 1 << j
    else:
        bit_adj = [0] * n
        for i in range(n):
            for nb in adj[i]:
                bit_adj[i] |= 1 << nb

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        used = [0] * n  # bitmask of colors used by neighbors
        for v in order:
            c = 0
            while used[v] & (1 << c):
                c += 1
            color[v] = c
            mask = 1 << c
            for u in range(n):
                if bit_adj[v] & (1 << u):
                    used[u] |= mask
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1 and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [bin(bit_adj[i]).count("1") for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max degree, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = bin(saturation[u]).count("1")
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and u < v):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # assign smallest available color
            c = 0
            while saturation[v] & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            mask = 1 << c
            for u in range(n):
                if bit_adj[v] & (1 << u):
                    if u in uncolored:
                        saturation[u] |= mask
                        uncolored_deg[u] -= 1
        return compact_colors(color)

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set S for color c
            S = set()
            # vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: bin(bit_adj[u] & sum(1 << w for w in uncolored)).count("1"))
            S.add(v)
            uncolored.remove(v)
            # U: vertices not adjacent to S, W: adjacent to S
            U = {u for u in uncolored if not (bit_adj[v] & (1 << u))}
            W = uncolored - U
            while U:
                # select u in U with max neighbors in W, then min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = bin(bit_adj[u] & sum(1 << w for w in W)).count("1")
                    deg_u = bin(bit_adj[u] & sum(1 << w for w in U)).count("1")
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or \
                       (nw == max_nw and deg_u == min_deg_u and u < u_star):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                nbrs = bit_adj[u_star]
                to_move = {u for u in U if nbrs & (1 << u)}
                U -= to_move
                W |= to_move
            # assign color c to S
            for v in S:
                color[v] = c
            c += 1
        return compact_colors(color)

    # Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        deg = [bin(bit_adj[i]).count("1") for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = deg[v]
        # peel min degree vertex
        for _ in range(n):
            # find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            nbrs = bit_adj[v]
            u = 0
            while nbrs:
                if nbrs & 1:
                    if u in remaining:
                        d_u = pos[u]
                        buckets[d_u].remove(u)
                        d_u -= 1
                        pos[u] = d_u
                        buckets[d_u].append(u)
                nbrs >>= 1
                u += 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # try to recolor each vertex in this class
            changed = True
            while changed and verts:
                changed = False
                v = verts.pop()
                # try direct reassignment to a lower color
                neighbor_colors = set()
                nbrs = bit_adj[v]
                u = 0
                while nbrs:
                    if nbrs & 1:
                        neighbor_colors.add(coloring[u])
                    nbrs >>= 1
                    u += 1
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # try Kempe chains with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # find (target_color, c) Kempe chain containing v
                    stack = [v]
                    visited = set()
                    comp_color = {target_color, c}
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        coloring[node] = c if coloring[node] == target_color else target_color
                        nbrs = bit_adj[node]
                        w = 0
                        while nbrs:
                            if nbrs & 1:
                                if coloring[w] in comp_color and w not in visited:
                                    stack.append(w)
                            nbrs >>= 1
                            w += 1
                    # check if target_color class is now empty for this component
                    if not any(coloring[x] == target_color for x in verts):
                        changed = True
                        break
                    # revert swap if not helpful
                    stack = [v]
                    visited = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        coloring[node] = target_color if coloring[node] == c else c
                        nbrs = bit_adj[node]
                        w = 0
                        while nbrs:
                            if nbrs & 1:
                                if coloring[w] in comp_color and w not in visited:
                                    stack.append(w)
                            nbrs >>= 1
                            w += 1
            # rebuild list of remaining vertices in target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                # compact colors above target_color
                mapping = {}
                next_c = 0
                for col in range(k):
                    if col == target_color:
                        continue
                    mapping[col] = next_c
                    next_c += 1
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] = mapping[coloring[v]]
                    elif coloring[v] == target_color:
                        # should not happen
                        pass
                break
        return compact_colors(coloring)

    # Generate candidates
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best = col
    if best is None:
        # fallback to greedy on natural order
        best = greedy_color(list(range(n)))
        best = compact_colors(best)

    # Apply Kempe reduction
    best = kempe_reduce(best)
    return best

