            mask = 0
            for v in range(n):
                if adj[u][v]:
                    mask |= (1 << v)
            bit_adj[u] = mask
            deg[u] = bin(mask).count("1")
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                mask |= (1 << v)
            bit_adj[u] = mask
            deg[u] = len(adj[u])

