            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # compute mex
            c = 0
            neigh_mask = bit_adj[v]
            while neigh_mask:
                if neigh_mask & 1:
                    u = (neigh_mask.bit_length() - 1) if neigh_mask & (~(neigh_mask - 1)) else 0
                    if color[u] != -1:
                        c = max(c, color[u] + 1)
                neigh_mask &= neigh_mask - 1
            # simpler mex
            used = 0
            neigh_mask = bit_adj[v]
            while neigh_mask:
                if neigh_mask & 1:
                    u = (neigh_mask.bit_length() - 1) if neigh_mask & (~(neigh_mask - 1)) else 0
                    if color[u] != -1:
                        used |= (1 << color[u])
                neigh_mask &= neigh_mask - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            neigh_mask = bit_adj[v]
            while neigh_mask:
                if neigh_mask & 1:
                    u = (neigh_mask.bit_length() - 1) if neigh_mask & (~(neigh_mask - 1)) else 0
                    if color[u] == -1:
                        sat[u] += 1
                neigh_mask &= neigh_mask - 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in uncolored subgraph
            deg_un = {u: ((bit_adj[u] & sum((1 << v) for v in uncolored))).bit_count() for u in uncolored}
            # start with max degree vertex
            v = max(uncolored, key=lambda x: deg_un[x])
            S = {v}
            uncolored.remove(v)
            # W: neighbors of S in uncolored
            W = set()
            for u in S:
                W.update({w for w in uncolored if (bit_adj[u] >> w) & 1})
            # U: uncolored not in W
            U = uncolored - W
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    w_mask = bit_adj[u] & sum((1 << w) for w in W)
                    score = w_mask.bit_count()
                    if score > best_score or (score == best_score and ((bit_adj[u] & sum((1 << x) for x in U)).bit_count() < (bit_adj[best_u] & sum((1 << x) for x in U)).bit_count() if best_u is not None else True)):
                        best_score = score
                        best_u = u
                if best_u is None:
                    break
                S.add(best_u)
                uncolored.remove(best_u)
                # move neighbors of best_u from U to W
                nbrs = {w for w in uncolored if (bit_adj[best_u] >> w) & 1}
                W.update(nbrs)
                U = uncolored - W
            for u in S:
                color[u] = c
            c += 1
        return color

    # Smallest-Last ordering
    def smallest_last():
        order = []
        remaining = set(range(n))
        deg_copy = [deg[u] for u in range(n)]
        adj_list = [ [v for v in range(n) if (bit_adj[u] >> v) & 1] for u in range(n) ]
        for _ in range(n):
            v = min(remaining, key=lambda x: deg_copy[x])
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    deg_copy[u] -= 1
        order.reverse()
        return greedy_color(order)

    # Kempe chain swap for (a,b) component containing v
    def kempe_swap(color, a, b, v):
        n = len(color)
        stack = [v]
        visited = set()
        comp = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if color[u] == a or color[u] == b:
                comp.add(u)
                for w in range(n):
                    if (bit_adj[u] >> w) & 1 and color[w] in (a, b) and w not in visited:
                        stack.append(w)
        # swap colors in comp
        for u in comp:
            if color[u] == a:
                color[u] = b
            elif color[u] == b:
                color[u] = a
        return color

    # Try to eliminate a color via Kempe or reassignment
    def reduce_colors(color):
        # map color to list of vertices
        color_classes = {}
        for v, c in enumerate(color):
            color_classes.setdefault(c, []).append(v)
        if not color_classes:
            return color
        max_color = max(color_classes.keys())
        # try from highest color down
        for c in range(max_color, -1, -1):
            if c not in color_classes:
                continue
            verts = color_classes[c]
            # try to recolor each vertex in this class
            for v in verts:
                neighbor_colors = set()
                mask = bit_adj[v]
                while mask:
                    w = (mask & -mask).bit_length() - 1
                    neighbor_colors.add(color[w])
                    mask &= mask - 1
                # try direct reassignment to a lower color
                for target in range(c):
                    if target not in neighbor_colors:
                        color[v] = target
                        break
                else:
                    # try Kempe chains with each lower color
                    for target in range(c):
                        # if v not adjacent to any target-colored vertex, we could have taken it above
                        # but check Kempe chain (c, target) starting at v
                        # if the component does not contain any vertex of color target that is adjacent to v? 
                        # Actually, we swap and see if v can become target
                        # Make a copy to test
                        test_color = color[:]
                        test_color = kempe_swap(test_color, c, target, v)
                        # check if v now has color target (it should if swapped)
                        if test_color[v] == target:
                            # verify validity
                            valid = True
                            for u in range(n):
                                if (bit_adj[v] >> u) & 1 and test_color[v] == test_color[u]:
                                    valid = False
                                    break
                            if valid:
                                color = test_color
                                break
                    else:
                        continue
                    break
                else:
                    continue
                break
            else:
                continue
            # if we reassigned at least one vertex, rebuild classes and try again
            return reduce_colors(color)
        # compact colors
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in color]

    # Run all heuristics
    best_color = None
    best_k = float('inf')
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            # validate
            valid = True
            for u in range(n):
                if color[u] == -1:
                    valid = False
                    break
                mask = bit_adj[u]
                while mask:
                    v = (mask & -mask).bit_length() - 1
                    if col[u] == col[v]:
                        valid = False
                        break
                    mask &= mask - 1
                if not valid:
                    break
            if valid:
                k = len(set(col))
                if k < best_k:
                    best_k = k
                    best_color = col
        except:
