    if best_color is None:
        # fallback to greedy by degree order
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        best_color = greedy_color(order)

    # Apply color reduction
    best_color = reduce_colors(best_color)

    # Ensure consecutive colors
    unique = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique)}
    best_color = [mapping[c] for c in best_color]

    return best_color

