    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
        if is_matrix:
            for i in range(n):
                for j in range(n):
                    if adj[i][j] not in (0, 1):
                        is_matrix = False
                        break
                if not is_matrix:
                    break

