    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])

