    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

