            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation and degree for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Update saturation: if color c is new to u's neighbors
                    # We can't easily track distinct colors without a set, so we recalc saturation for u?
                    # Instead, we maintain for each uncolored vertex a bitmask of neighbor colors
                    # But to keep simple, we recalc saturation for u by checking its colored neighbors
                    # Since n <= 100, we can do it.
                    # Recalculate saturation for u
                    sat_u = 0
                    seen = 0
                    for w in adj_list[u]:
                        if coloring[w] != -1:
                            seen |= (1 << coloring[w])
                    # Count bits in seen
                    sat_u = seen.bit_count()
