                if v == v1:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.add(v)

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # Count neighbors in W
                    score = 0
                    for w in adj_list[u]:
