    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # We'll compute the ordering by repeatedly removing min degree vertex
        # Work on a copy of degrees and adjacency
        deg = [len(adj_list[i]) for i in range(n)]
