        # Use adjacency list and a removed flag
        removed = [False] * n
        order = []  # will append removed vertices, so reverse order is coloring order
        # We'll maintain current degrees in the remaining graph
        current_deg = deg[:]  # copy

        for _ in range(n):
            # Find vertex with minimum current_deg among not removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and current_deg[i] < min_deg:
                    min_deg = current_deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    current_deg[u] -= 1
