            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                # Already normalized, so this should not happen unless gap
                # Renormalize and continue
                col = normalize(col)
                k = num_colors(col)
                target_color = k - 1
                target_vertices = [v for v in range(n) if col[v] == target_color]
                if not target_vertices:
                    break
            # Try to recolor each target vertex to a lower color
            # We'll attempt to move each vertex to a color < target_color if possible
            # Use Kempe chains
            success = [False] * len(target_vertices)
            # For each target vertex, try to find a color c < target_color that we can assign
            # either directly or via Kempe swap
            for idx, v in enumerate(target_vertices):
                # Try direct reassignment first
                neighbor_colors = 0
                for u in adj_list[v]:
                    if col[u] != -1:
                        neighbor_colors |= (1 << col[u])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (neighbor_colors & (1 << c)):
                        # Directly assign color c to v
                        col[v] = c
                        success[idx] = True
                        break
                if success[idx]:
                    continue
                # Try Kempe chains for each color c < target_color
                for c in range(target_color):
                    # We consider swapping colors c and target_color in the component of v
                    # in the subgraph induced by vertices with color c or target_color
                    # If we can swap such that v becomes color c and no vertex becomes target_color (or we don't care as long as we can remove target_color later)
                    # Actually, we want to eliminate target_color: after swap, v should not be target_color, and we hope that no other vertex remains target_color? 
                    # But we are processing one vertex at a time. We will do the swap and then later try to remove the color class.
                    # Standard approach: if the Kempe chain of v for colors (c, target_color) does not contain any vertex of color c that is adjacent to a vertex of color target_color? 
                    # Simpler: we try to swap the component containing v in the (c, target_color) subgraph. After swap, v will have color c.
                    # We then check if this creates any conflict? It shouldn't because swapping colors in a Kempe chain preserves validity.
                    # So we can safely swap.
                    # However, we want to avoid increasing the number of vertices in target_color? Actually, after swap, some vertices that were c become target_color and vice versa.
                    # The number of target_color vertices may change. We want to reduce the count of target_color.
                    # We will do the swap and then later attempt to remove the color class again.
                    # For now, we just try to recolor v to c via Kempe chain, and if we can, we do it and break.
                    # Find the Kempe chain component of v in the subgraph of vertices with color c or target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (col[nb] == c or col[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping is safe: it always is, but we want to know if after swap, v will not be target_color.
                    # After swap, v will become c (if it was target_color) or target_color (if it was c). Since v is target_color, it becomes c.
                    # So we can perform the swap.
                    # Perform swap: for each node in component, if col[node]==c set to target_color, else if col[node]==target_color set to c.
                    for node in component:
                        if col[node] == c:
                            col[node] = target_color
                        elif col[node] == target_color:
                            col[node] = c
                    # Now v has color c (since it was target_color and in component)
                    success[idx] = True
                    break  # break from color c loop
                if success[idx]:
                    break  # break from vertex loop, we will restart the while changed loop
            # If we succeeded in recoloring at least one target vertex, we set changed=True and will try to reduce again
            if any(success):
                changed = True
                # Renormalize to fill gaps
                col = normalize(col)
        return col

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_coloring = c1
    except Exception:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_coloring = c2
    except Exception:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_coloring = c3
    except Exception:
        pass

    # If none worked (should not happen), use greedy as fallback
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_coloring = improved
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))
    best_coloring = normalize(best_coloring)

    return best_coloring

