                        best = u
            v = best
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and uncolored degrees for neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1:
                    if color[u] == -1:  # u is uncolored
                        saturation[u] |= (1 << c)
                        uncolored_deg[u] -= 1
                    # if u is colored, no need to update saturation (already accounted)
