    if is_matrix:
        neighbors = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        neighbors = [list(lst) for lst in adj]  # copy
        bit_adj = [0] * n
        for i in range(n):
            for j in neighbors[i]:
                bit_adj[i] |= (1 << j)

    # Helper: compute number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            cu = colors[u]
            for v in neighbors[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # Precompute degrees
        degrees = [len(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                # saturation: distinct colors in neighbors
                sat = 0
                neighbor_colors = 0
                for u in neighbors[v]:
                    if colored[u]:
                        neighbor_colors |= (1 << colors[u])
                sat = neighbor_colors.bit_count()
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Find smallest available color
            used = 0
            for u in neighbors[v]:
                if colored[u]:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
        return compact_colors(colors)

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            S = []
            # Subgraph induced by uncolored
            # Find vertex with max degree in G[uncolored]
            max_deg = -1
            v0 = -1
            for v in uncolored:
                deg = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            if v0 == -1:  # should not happen
                break
            S.append(v0)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored) - {v0}
            W = set()
            for u in neighbors[v0]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_in_U = None
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_in_U += 1
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
            # Remove S from uncolored
            uncolored -= set(S)
        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees in current graph
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # Find vertex with minimum degree among non-removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse removal order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain based color reduction
    def kempe_reduce(colors):
        if not is_valid(colors):
            return colors  # should not happen if input is valid
        k = num_colors(colors)
        # Try to reduce from k down
        while k > 0:
            target_color = k - 1
            # Vertices with target color
            verts_target = [v for v in range(n) if colors[v] == target_color]
            if not verts_target:
                k -= 1
                continue
            # Try to recolor each vertex in target color
            made_progress = False
            for v in verts_target:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    cu = colors[u]
                    if cu < target_color:  # only lower colors matter for elimination
                        used_by_neighbors |= (1 << cu)
                # Find smallest color < target_color not used by neighbors
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Direct move possible
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be swapped via (target_color, c) Kempe chain
                    # We'll do BFS/DFS for the component containing v in the subgraph of colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    # We only traverse vertices with color target_color or c
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (colors[y] == target_color or colors[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of the component has color c (would cause conflict if we swap)
                    has_conflict = False
                    for x in component:
                        for y in neighbors[x]:
                            if colors[y] == c and y not in component:  # neighbor outside component with color c
                                has_conflict = True
                                break
                        if has_conflict:
                            break
                    if not has_conflict:
                        # Perform swap: target_color <-> c in component
                        for x in component:
                            if colors[x] == target_color:
                                colors[x] = c
                            else:  # must be c
                                colors[x] = target_color
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # Cannot eliminate this color class
                break
            # Compact colors after potential elimination
            colors = compact_colors(colors)
            k = num_colors(colors)
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_colors = c1
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_colors = c2
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_colors = c3
    except:
        pass

    # If none worked (should not happen), fallback to greedy
    if best_colors is None:
        # Simple greedy in vertex order
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe chain reduction to improve
    try:
        improved = kempe_reduce(best_colors[:])  # work on a copy
        if is_valid(improved):
            k_improved = num_colors(improved)
            if k_improved < num_colors(best_colors):
                best_colors = improved
    except:
        pass

    # Final validation and compact
    if not is_valid(best_colors):
        # Last resort: greedy
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    return best_colors

