        # Validate binary entries
        for i in range(n):
            if len(adj[i]) != n:
                raise ValueError("Adjacency matrix must be square")
            for val in adj[i]:
                if val not in (0, 1):
                    raise ValueError("Adjacency matrix entries must be 0 or 1")
        # Build adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Treat as adjacency list
        adj_list = adj
        # Validate indices
        for i in range(n):
            for v in adj_list[i]:
                if not (0 <= v < n):
                    raise ValueError(f"Invalid vertex index {v} in adjacency list of vertex {i}")

    if n == 0:
        return []
    if n == 1:
        return [0]

    # Precompute degrees and bitmasks for fast operations
    deg = [len(adj_list[i]) for i in range(n)]
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for nb in adj_list[i]:
            mask |= (1 << nb)
        bit_adj[i] = mask

    best_coloring = None
    best_k = float('inf')

    # Helper: validate coloring and compute number of colors
    def validate_and_count(coloring):
        k = 0
        seen = [False] * n  # upper bound on colors
        for c in coloring:
            if c < 0:
                return False, 0
            if c >= n:
                return False, 0
            seen[c] = True
            if c + 1 > k:
                k = c + 1
        # Check adjacency constraints
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False, 0
        # Ensure colors are consecutive from 0
        for i in range(k):
            if not seen[i]:
                return False, 0
        return True, k

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                if sat_u > max_sat:
                    max_sat = sat_u
                    max_deg = sum(1 for nb in adj_list[u] if nb in uncolored)
                    v = u
                elif sat_u == max_sat:
                    deg_u = sum(1 for nb in adj_list[u] if nb in uncolored)
                    if deg_u > max_deg:
                        max_deg = deg_u
                        v = u
                    elif deg_u == max_deg:
                        if random.random() < 0.5:
                            v = u
            # assign smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and neighbor masks for uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    # if this color is new to nb's neighborhood
                    if not (neighbor_color_mask[nb] & (1 << c)):
                        neighbor_color_mask[nb] |= (1 << c)
                        saturation[nb] += 1
        return coloring

    # RLF (Recursive Largest First) - maximal independent set extraction
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
