        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            independent_set = {v}
            # partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            # greedily add vertices from U
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u = None
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for cand in U:
                    w_neighbors = sum(1 for nb in adj_list[cand] if nb in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_u = sum(1 for nb in adj_list[cand] if nb in U)
                        u = cand
                    elif w_neighbors == max_w_neighbors:
                        deg_u = sum(1 for nb in adj_list[cand] if nb in U)
                        if deg_u < min_deg_u:
                            min_deg_u = deg_u
                            u = cand
                        elif deg_u == min_deg_u:
                            if random.random() < 0.5:
                                u = cand
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to independent set
            for vertex in independent_set:
                coloring[vertex] = color
                uncolored.remove(vertex)
            color += 1
        return coloring

    # Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = deg[:]  # current degree in remaining subgraph
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d = degree[nb]
                    if d > 0:
                        buckets[d].remove(nb)
                        degree[nb] -= 1
                        buckets[degree[nb]].append(nb)
                        if degree[nb] < ptr:
                            ptr = degree[nb]
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Generate initial colorings
    for coloring_func in [dsatur, rlf, smallest_last]:
        try:
            coloring = coloring_func()
            valid, k = validate_and_count(coloring)
            if valid and k < best_k:
                best_k = k
                best_coloring = coloring[:]
        except Exception:
            continue

    # Fallback: if no valid coloring found (should not happen), use greedy by index
    if best_coloring is None:
        coloring = [-1] * n
        for v in range(n):
            used = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        valid, k = validate_and_count(coloring)
        if valid:
            best_k = k
            best_coloring = coloring
        else:
            # last resort: assign distinct colors
            best_coloring = list(range(n))
            best_k = n

    # Kempe chain color reduction
    def eliminate_color_class(coloring, k):
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # collect vertices with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each target vertex
            made_change = False
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for nb in adj_list[v]:
                    if coloring[nb] != -1:
                        used |= (1 << coloring[nb])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # BFS to get component
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for nb in adj_list[x]:
                            if nb not in comp and (coloring[nb] == target_color or coloring[nb] == c):
                                comp.add(nb)
                                queue.append(nb)
                    # Check if swapping colors in component is valid: no neighbor outside component has color c or target_color after swap?
                    # Actually, swapping preserves validity as long as we only swap within the component.
                    # But we want to free color target_color for v, i.e., after swap, v should have color c.
                    # This happens if v is in the component and we swap.
                    # However, we need to ensure that after swap, no vertex in the component gets a color that conflicts with its neighbors outside.
                    # Since the component only contains colors target_color and c, and we swap them, it remains valid.
                    # But we must check that no neighbor of a vertex in the component that is outside the component has the color that it will become after swap.
                    # For a vertex x in component:
                    #   if coloring[x] == target_color, after swap it becomes c.
                    #   if coloring[x] == c, after swap it becomes target_color.
                    # So we need to check:
                    #   For any x in component with coloring[x] == target_color, all neighbors y not in component must have coloring[y] != c.
                    #   For any x in component with coloring[x] == c, all neighbors y not in component must have coloring[y] != target_color.
                    valid_swap = True
                    for x in comp:
                        cx = coloring[x]
                        for nb in adj_list[x]:
                            if nb not in comp:
                                if cx == target_color and coloring[nb] == c:
                                    valid_swap = False
                                    break
                                if cx == c and coloring[nb] == target_color:
                                    valid_swap = False
                                    break
                        if not valid_swap:
                            break
                    if valid_swap:
                        # perform swap
                        for x in comp:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:  # must be c
                                coloring[x] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if not made_change:
                # cannot eliminate this color class, try next lower
                continue
            else:
                # we made a change, need to compact colors and restart from highest
                # but first, check if target_color class is now empty
                if target_color not in set(coloring):
                    # compact colors: remap to 0..k-2
                    mapping = {}
                    new_color = 0
                    for old_color in range(k):
                        if old_color in set(coloring):
                            mapping[old_color] = new_color
                            new_color += 1
                    for v in range(n):
                        coloring[v] = mapping[coloring[v]]
                    return True, k-1
                else:
                    # still have the color, but we made a change, try again from same target? 
                    # For simplicity, break and let outer loop handle
                    break
        return False, k

    # Apply Kempe reduction iteratively
    current_coloring = best_coloring[:]
    current_k = best_k
    improved = True
    # Limit iterations to avoid timeout
    for _ in range(10):  # max 10 reduction attempts
        if current_k <= 1:
            break
        changed, new_k = eliminate_color_class(current_coloring, current_k)
        if changed:
            current_k = new_k
            # validate after reduction
            valid, k_val = validate_and_count(current_coloring)
            if valid and k_val < best_k:
                best_k = k_val
                best_coloring = current_coloring[:]
        else:
            break

    # Final validation and return
    valid, k = validate_and_count(best_coloring)
    if not valid:
        # fallback to greedy
        coloring = [-1] * n
        for v in range(n):
            used = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        # ensure consecutive
        mapping = {}
        new_color = 0
        for old_color in sorted(set(coloring)):
            mapping[old_color] = new_color
            new_color += 1
        for v in range(n):
            coloring[v] = mapping[coloring[v]]
        return coloring
    return best_coloring

