        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v]
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = sum(1 for u in neighbors[v] if u in uncolored)
                elif sat == best_sat:
