            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_in_U = -1
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_in_U = sum(1 for w in neighbors[u] if w in U)
                    elif score == best_score:
                        deg_in_U = sum(1 for w in neighbors[u] if w in U)
                        if deg_in_U < best_deg_in_U:
                            best_deg_in_U = deg_in_U
                            best_u = u
                        elif deg_in_U == best_deg_in_U:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
