    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering via min-degree peeling
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # Use buckets for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d <= max_deg:
                buckets[d].append(v)
