            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    # Remove u from bucket[d]
                    if d <= max_deg and u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    if d_new <= max_deg:
                        buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new
