                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has color c (shouldn't), skip
                    if coloring[v] == c:
                        continue
                    # Check if v can be swapped via Kempe chain (target_color, c)
                    # We'll try to find the Kempe chain component containing v in colors {target_color, c}
                    # and see if we can swap without pulling in other target_color vertices
                    from collections import deque
