    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if coloring[j] != -1:
                    used |= (1 << coloring[j])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: get_color_count(x))
    best = kempe_reduce(best)
    best = compact_colors(best)
    # Final validation (should be valid)
    if not is_valid_coloring(best):
