        coloring = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if coloring[j] != -1:
                    used |= (1 << coloring[j])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        return coloring
    return best

