        for u in uncolored:
            if sat[u] > max_sat:
                max_sat = sat[u]
                max_deg = len([w for w in adj_list[u] if w in uncolored])
                v = u
            elif sat[u] == max_sat:
                deg_u = len([w for w in adj_list[u] if w in uncolored])
                if deg_u > max_deg:
                    max_deg = deg_u
                    v = u
                elif deg_u == max_deg:
                    if random.random() < 0.5:
                        v = u
        # Assign smallest available color
        used = 0
        for u in adj_list[v]:
            c = color[u]
            if c != -1:
                used |= (1 << c)
        c = 0
        while used & (1 << c):
            c += 1
        color[v] = c
        uncolored.remove(v)
        # Update saturation of uncolored neighbors
        for u in adj_list[v]:
            if u in uncolored:
                sat[u] = len({color[w] for w in adj_list[u] if color[w] != -1})
    k_dsatur = num_colors(color)
    if k_dsatur < best_k:
        best_k = k_dsatur
        best_coloring = color[:]

    # 2. RLF (Recursive Largest First)
    uncolored = set(range(n))
    color = [-1] * n
    c = 0
    while uncolored:
        # Build maximal independent set for color c
        # Start with vertex of max degree in uncolored subgraph
        v = max(uncolored, key=lambda x: len([w for w in adj_list[x] if w in uncolored]))
        S = {v}
        # U: vertices not adjacent to any in S (eligible)
        # W: vertices adjacent to at least one in S (ineligible)
        U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in S)}
        W = {u for u in uncolored if u != v and any(u in adj_list[w] for w in S)}
        while U:
            # Select u in U with max neighbors in W, tie-break by min degree in G[U]
            u = -1
            max_nw = -1
            min_deg_u = float('inf')
            for candidate in U:
                nw = len([w for w in adj_list[candidate] if w in W])
                deg_u = len([w for w in adj_list[candidate] if w in U])
                if nw > max_nw:
                    max_nw = nw
                    min_deg_u = deg_u
                    u = candidate
                elif nw == max_nw:
                    if deg_u < min_deg_u:
                        min_deg_u = deg_u
                        u = candidate
                    elif deg_u == min_deg_u and random.random() < 0.5:
                        u = candidate
            S.add(u)
            U.remove(u)
            # Move neighbors of u from U to W
            for w in adj_list[u]:
                if w in U:
                    U.remove(w)
                    W.add(w)
        # Assign color c to all in S
        for v in S:
            color[v] = c
        uncolored -= S
        c += 1
    k_rlf = num_colors(color)
    if k_rlf < best_k:
        best_k = k_rlf
        best_coloring = color[:]

    # 3. Smallest-Last ordering (Matula & Beck)
    # Compute degeneracy ordering by repeatedly removing min degree vertex
    remaining = set(range(n))
    order = []
    degrees = [len(adj_list[i]) for i in range(n)]
    # Current degree in remaining subgraph
    curr_deg = degrees[:]
    while remaining:
        # Find vertex with minimum current degree
        v = min(remaining, key=lambda x: curr_deg[x])
        order.append(v)
        remaining.remove(v)
        for u in adj_list[v]:
            if u in remaining:
                curr_deg[u] -= 1
    # Color in reverse order
    order.reverse()
    color = greedy_color(order)
    k_sl = num_colors(color)
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = color[:]

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        n_local = len(coloring)
        # Map color to list of vertices
        color_classes = {}
        for v, c in enumerate(coloring):
            color_classes.setdefault(c, []).append(v)
        # Sort colors by class size (smallest first)
        colors_sorted = sorted(color_classes.keys(), key=lambda c: len(color_classes[c]))
        # Try to eliminate each color class from smallest to largest
        for target_color in colors_sorted:
            if target_color >= len(color_classes):
                continue
            if not color_classes[target_color]:
                continue
            # Try to recolor each vertex in target_color
            changed = True
            while changed and color_classes.get(target_color, []):
                changed = False
                v = color_classes[target_color][0]  # Take first vertex
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):  # Only try colors < target_color
                    if not (used & (1 << c)):
                        # Recolor v to c
                        old_color = coloring[v]
                        coloring[v] = c
                        # Update color classes
                        color_classes[old_color].remove(v)
                        if not color_classes[old_color]:
                            del color_classes[old_color]
                        color_classes.setdefault(c, []).append(v)
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # BFS to get component
                    from collections import deque
                    comp = []
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    while queue:
                        x = queue.popleft()
                        comp.append(x)
                        for y in adj_list[x]:
                            if y not in visited and coloring[y] in (target_color, c):
                                visited.add(y)
                                queue.append(y)
                    # Check if swapping colors in comp would cause conflict
                    # After swap, vertices in comp that were target_color become c, and vice versa
                    # We need to ensure no neighbor outside comp has color c (for those becoming c) or target_color (for those becoming target_color)
                    # But since we are only targeting to remove target_color, we focus on vertices becoming c
                    # For each vertex in comp that is currently target_color, after swap it becomes c.
                    # Check if any neighbor of such vertex (outside comp) has color c -> conflict
                    safe = True
                    for x in comp:
                        if coloring[x] == target_color:  # will become c
                            for y in adj_list[x]:
                                if y not in comp and coloring[y] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        # Perform swap
                        for x in comp:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:  # must be c
                                coloring[x] = target_color
                        # Update color classes
                        # Rebuild color_classes for simplicity (since n <= 100)
                        color_classes = {}
                        for i, col in enumerate(coloring):
                            color_classes.setdefault(col, []).append(i)
                        changed = True
                        break
            # After attempting to recolor all vertices in target_color, if the class is empty, we can compact colors
            if target_color not in color_classes or not color_classes[target_color]:
                # Compact colors: remap so that colors are 0..k-1 without gaps
                # But we do this at the end
                pass
        # Compact color indices
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        for i in range(n_local):
            coloring[i] = mapping[coloring[i]]
        return coloring

    # Apply Kempe reduction to the best coloring found
    best_coloring = kempe_reduce(best_coloring[:])

    # Final validation (optional, but safe)
    # Ensure proper coloring
    for u in range(n):
        for v in adj_list[u]:
            if best_coloring[u] == best_coloring[v]:
                # Fallback: greedy on random order if invalid (should not happen)
                order = list(range(n))
                random.shuffle(order)
                best_coloring = greedy_color(order)
                break
        else:
            continue
        break

    # Ensure colors are consecutive starting from 0
    unique_colors = sorted(set(best_coloring))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    for i in range(n):
        best_coloring[i] = mapping[best_coloring[i]]

    return best_coloring

