            W = set().union(*[neighbors[s] for s in S]) & uncolored
            # Greedily add to S from U
            while U:
                # Select u in U maximizing |N(u) ∩ W|
                u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([w for w in neighbors[x] if w in U]), x))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                W.update(nbrs_u)
