            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= 1 << coloring[u]
            # Try direct reassignment to a lower color
            for c in range(target_color):
                if not (used & (1 << c)):
                    coloring[v] = c
                    break
            else:
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build (c, target_color) Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == c or coloring[u] == target_color):
                                    stack.append(u)
                    # Check if any neighbor of v in component has color c (would cause conflict if swapped)
                    conflict = False
                    for node in component:
                        for u in neighbors[node]:
                            if u in component and coloring[u] == c and coloring[node] == target_color:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors c and target_color in component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        coloring[v] = c  # Now v has color c
                        break
        # Re-check if target_color is still used
        if any(coloring[v] == target_color for v in range(n)):
            return coloring, False
        # Compact colors: shift down all colors > target_color
        for v in range(n):
            if coloring[v] > target_color:
                coloring[v] -= 1
        return coloring, True

    # Iteratively try to reduce color count
    current = best[:]
    changed = True
    while changed and max(current) + 1 > 1:
        changed = False
        target = max(current)  # highest color index
        # Try to eliminate the highest color class first (often easier)
        new_col, eliminated = eliminate_color_class(current[:], target)
        if eliminated:
            current = new_col
            changed = True
        else:
            # Try eliminating color classes from high to low
            for c in range(max(current), -1, -1):
                new_col, eliminated = eliminate_color_class(current[:], c)
                if eliminated:
                    current = new_col
                    changed = True
                    break

    # Final validation and compaction to zero-based
    if not is_valid_coloring(current):
        # Fallback to greedy on best ordering
        current = greedy_coloring(list(range(n)))
    # Ensure colors are consecutive starting from 0
    unique_colors = {}
    next_color = 0
    for i in range(n):
        if current[i] not in unique_colors:
            unique_colors[current[i]] = next_color
            next_color += 1
        current[i] = unique_colors[current[i]]
    return current

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = (len(adj[0]) == n) and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in adj_list[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring: list[int]) -> bool:
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring: list[int]) -> int:
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring: list[int]) -> list[int]:
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR algorithm
    def dsatur() -> list[int]:
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor masks for fast saturation update
        colored_masks = [0] * n
        # degree in uncolored subgraph (initially full degree)
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            candidates = []
            max_sat = -1
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            # Tie-break by uncolored degree
            if len(candidates) > 1:
                max_deg = -1
                new_candidates = []
                for v in candidates:
                    d = uncolored_deg[v]
                    if d > max_deg:
                        max_deg = d
                        new_candidates = [v]
                    elif d == max_deg:
                        new_candidates.append(v)
                candidates = new_candidates
            # Final tie-break randomly
            v = random.choice(candidates) if candidates else 0

            # Compute forbidden colors from neighbors
            forbidden = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    forbidden |= (1 << coloring[u])
            # Find smallest available color (mex)
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            # Update saturation and uncolored degree for neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Update saturation: if this color is new in u's neighborhood
                    if not (colored_masks[u] & (1 << c)):
                        sat[u] += 1
                        colored_masks[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return normalize(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf() -> list[int]:
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            # Degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1

            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to independent_set (ineligible)
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                best_u = None
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # Degree in U-induced subgraph
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_u < min_deg_u):
                        max_w_neighbors = w_count
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
            uncolored -= independent_set
            color += 1
        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # Buckets for degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket with min degree
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break  # should not happen
            v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = deg[u]
                    if d < len(buckets):
                        buckets[d].remove(u)
                    deg[u] -= 1
                    if deg[u] < len(buckets):
                        buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        # Color in reverse removal order
        coloring = [-1] * n
        for v in reversed(order):
            forbidden = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    forbidden |= (1 << coloring[u])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring: list[int]) -> list[int]:
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid
        k = num_colors(coloring)
        # Try to reduce colors from k-1 down to 0
        while k > 0:
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                k -= 1
                continue
            # Try to recolor each target vertex
            removed = False
            for v in target_vertices:
                # Try direct reassignment to a lower color
                forbidden = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        forbidden |= (1 << coloring[u])
                for c in range(target_color):  # only try colors < target_color
                    if not (forbidden & (1 << c)):
                        # Move v to color c
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    break
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component containing v in colors (target_color, c)
                    # BFS to get component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping colors in component would free color c for v
                    # After swap, v would get color c (since it was target_color)
                    # We need to ensure no neighbor of v gets color c from the swap
                    conflict = False
                    for nb in adj_list[v]:
                        if coloring[nb] == c and nb not in component:
                            # This neighbor would keep color c (not in component) -> conflict
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: target_color <-> c in component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        removed = True
                        break
                if removed:
                    break
            if not removed:
                # Cannot eliminate this color class
                break
            # Recolor target vertices that were moved; rebuild target_vertices
            # Actually, we break after first success, so we need to restart the color reduction
            # Compact colors and try again from current k
            coloring = normalize(coloring)
            k = num_colors(coloring)
        return normalize(coloring)

    # Run all heuristics and pick best
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_coloring = c1
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_coloring = c2
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_coloring = c3
    except:
        pass

    # Fallback: greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            forbidden = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    forbidden |= (1 << coloring[u])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Apply Kempe chain reduction to improve
    try:
        improved = kempe_reduce(best_coloring[:])
        if is_valid(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_coloring = improved
    except:
        pass

    # Final validation and normalization
    if not is_valid(best_coloring):
        # Last resort: greedy coloring
        coloring = [-1] * n
        for v in range(n):
            forbidden = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    forbidden |= (1 << coloring[u])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    return best_coloring

