        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = uncolored_deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and (best == -1 or random.random() < 0.5)):
                    best_sat = s
                    best_deg = d
                    best = v
            u = best
            # assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            uncolored.remove(u)
            # update neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    sat[v] |= (1 << c)
                    uncolored_deg[v] -= 1
        return color

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
