def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        neighbors = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        neighbors = adj

    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    def deg(v, colored_mask):
        return (bit_adj[v] & ~colored_mask).bit_count()

    def sat(v, color_mask):
        mask = bit_adj[v] & color_mask
        s = 0
        while mask:
            low = mask & -mask
            c = (low.bit_length() - 1)
            s |= (1 << c)
            mask -= low
        return s.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        colored_mask = 0
        color_mask = 0
        for _ in range(n):
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if color[v] != -1:
                    continue
                s = sat(v, color_mask)
                d = deg(v, colored_mask)
                if s > best_sat or (s == best_sat and d > best_deg):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            neighbor_colors = 0
            mask = bit_adj[v] & color_mask
            while mask:
                low = mask & -mask
                c = (low.bit_length() - 1)
                neighbor_colors |= (1 << c)
                mask -= low
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[v] = c
            colored_mask |= (1 << v)
            color_mask |= (1 << c)
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored_mask = (1 << n) - 1
        c = 0
        while uncolored_mask:
            # Build independent set S for color c
            S_mask = 0
            # Choose vertex with max degree in uncolored subgraph
            best_v = -1
            best_deg = -1
            temp = uncolored_mask
            while temp:
                low = temp & -temp
                v = low.bit_length() - 1
                d = deg(v, uncolored_mask)
                if d > best_deg:
                    best_deg = d
                    best_v = v
                temp -= low
            if best_v == -1:
                break  # should not happen
            S_mask |= (1 << best_v)
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            adj_S_mask = 0
            temp = S_mask
            while temp:
                low = temp & -temp
                v = low.bit_length() - 1
                adj_S_mask |= bit_adj[v]
                temp -= low
            U_mask = uncolored_mask & ~adj_S_mask
            W_mask = uncolored_mask & adj_S_mask
            # While U not empty
            while U_mask:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_u = -1
                temp = U_mask
                while temp:
                    low = temp & -temp
                    u = low.bit_length() - 1
                    score = (bit_adj[u] & W_mask).bit_count()
                    deg_u = deg(u, U_mask)  # degree in current U
                    if score > best_score or (score == best_score and deg_u < best_deg_u):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                    temp -= low
                if best_u == -1:
                    break
                # Add best_u to S
                S_mask |= (1 << best_u)
                # Remove from U, add its neighbors in U to W
                U_mask &= ~(1 << best_u)
                neighbors_U = bit_adj[best_u] & U_mask
                W_mask |= neighbors_U
                U_mask &= ~neighbors_U
            # Assign color c to all in S
            temp = S_mask
            while temp:
                low = temp & -temp
                v = low.bit_length() - 1
                color[v] = c
                temp -= low
            uncolored_mask &= ~S_mask
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degs = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            d = degs[v]
            if d < n:
                buckets[d].append(v)
        # Pointer to current min degree
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break
            v = buckets[ptr].pop()
            if removed[v]:
                # Find another
                while buckets[ptr] and removed[buckets[ptr][-1]]:
                    buckets[ptr].pop()
                if not buckets[ptr]:
                    ptr += 1
                    while ptr < n and not buckets[ptr]:
                        ptr += 1
                    if ptr >= n:
                        break
                    v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d_u = degs[u]
                    # remove u from bucket d_u
                    if u in buckets[d_u]:
                        buckets[d_u].remove(u)
                    degs[u] -= 1
                    buckets[degs[u]].append(u)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain swap for (a,b)
    def kempe_swap(color, a, b, v):
        n_local = len(color)
        if color[v] not in (a, b):
            return False
        target = b if color[v] == a else a
        stack = [v]
        visited = [False] * n_local
        visited[v] = True
        component = []
        while stack:
            node = stack.pop()
            component.append(node)
            for u in neighbors[node]:
                if not visited[u] and color[u] in (a, b):
                    visited[u] = True
                    stack.append(u)
        # Check if any neighbor of component has color target
        for node in component:
            for u in neighbors[node]:
                if not visited[u] and color[u] == target:
                    return False  # swap would cause conflict
        # Perform swap
        for node in component:
            if color[node] == a:
                color[node] = b
            else:
                color[node] = a
        return True

    # Try to eliminate a color class using Kempe chains
    def reduce_colors(color):
        # Map color to list of vertices
        color_classes = {}
        for v, c in enumerate(color):
            color_classes.setdefault(c, []).append(v)
        if not color_classes:
            return color
        max_color = max(color_classes.keys())
        # Try from highest color down
        for c in range(max_color, -1, -1):
            if c not in color_classes:
                continue
            vertices = color_classes[c][:]
            # Try to recolor each vertex in this class
            changed = False
            for v in vertices:
                if color[v] != c:  # might have been recolored
                    continue
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors[v]:
                    if color[u] != -1:
                        neighbor_colors |= (1 << color[u])
                for c_new in range(c):  # only try lower colors
                    if not (neighbor_colors & (1 << c_new)):
                        color[v] = c_new
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c_new in range(c):
                    if kempe_swap(color, c, c_new, v):
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # Rebuild color classes and try again from start (since max color may have changed)
                return reduce_colors(color)
        # If no changes, return as is
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Apply Kempe reduction to each candidate
    reduced = []
    for col in candidates:
        reduced.append(reduce_colors(col[:]))

    # Select the coloring with the smallest number of colors
    best_coloring = None
    best_num_colors = float('inf')
    for col in reduced:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if u < v and color[u] == color[v]:
