                    break
            if not valid:
                break
        if not valid:
            continue
        num_colors = max(col) + 1 if col else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = col

    # Fallback: if no valid candidate (should not happen), use DSATUR
    if best_coloring is None:
        best_coloring = dsatur()

    # Compact colors to 0..k-1
    mapping = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        best_coloring[i] = mapping[c]

