                for target in range(c):
                    if target not in neighbor_colors:
                        # Recolor v to target
                        classes[c].remove(v)
                        if not classes[c]:
                            del classes[c]
                        classes.setdefault(target, []).append(v)
                        color[v] = target
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe swap with each lower color
                for target in range(c):
                    if target in neighbor_colors:
                        continue
                    # Find Kempe chain of (c, target) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if color[node] == c or color[node] == target:
                            component.add(node)
                            for u in neighbors[node]:
                                if color[u] == c or color[u] == target:
                                    if u not in visited:
                                        stack.append(u)
                    # Check if any neighbor of v in target color is NOT in this component
                    has_external = False
                    for u in neighbors[v]:
                        if color[u] == target and u not in component:
                            has_external = True
                            break
                    if not has_external:
                        # Swap colors in component
                        for node in component:
                            if color[node] == c:
                                color[node] = target
                                classes[target].append(node)
                                if c in classes:
                                    classes[c].remove(node)
                                    if not classes[c]:
                                        del classes[c]
                            else:  # color[node] == target
                                color[node] = c
                                classes.setdefault(c, []).append(node)
                                classes[target].remove(node)
                                if not classes[target]:
                                    del classes[target]
                        changed = True
                        break
            # If class c is eliminated, break to restart from highest
            if c not in classes or not classes[c]:
                break
        # Compact colors again
        mapping = {}
        next_color = 0
        for v in range(n):
            c = color[v]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            color[v] = mapping[c]
        return color

    best_color = kempe_reduce(best_color[:])
    # Final validation (optional, but ensures correctness)
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_color[u] == best_color[v]:
                # Fallback to DSATUR if validation fails (should not happen)
                return dsatur_fallback(neighbors, n)
    return best_color

def dsatur_fallback(neighbors, n):
    # Simple DSATUR implementation as fallback
    color = [-1] * n
    # saturation: number of distinct colors in neighbors
    sat = [0] * n
    # neighbor colorsets for saturation update
    neighbor_colors = [set() for _ in range(n)]
    uncolored = set(range(n))
    # initial vertex: highest degree
    if n == 0:
        return []
    v = max(uncolored, key=lambda x: len(neighbors[x]))
    color[v] = 0
    uncolored.remove(v)
    for u in neighbors[v]:
        neighbor_colors[u].add(0)
        sat[u] = len(neighbor_colors[u])
    while uncolored:
        # select vertex with max sat, tie-break by degree
        v = max(uncolored, key=lambda x: (sat[x], len(neighbors[x]), -x))
        # find smallest available color
        used = [False] * n
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c
        uncolored.remove(v)
        # update saturation for uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    sat[u] = len(neighbor_colors[u])
    # compact colors
    mapping = {}
    next_color = 0
    for c in color:
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
    return [mapping[c] for c in color]

