            sat = sat_mask.bit_count()
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)

        if not candidates:
            break  # Should not happen

        # Tie-break: max sum of degrees of uncolored neighbors
        best_v = candidates[0]
        best_score = -1
