            if score > best_score:
                best_score = score
                best_v = v
            elif score == best_score:
                if v < best_v:  # deterministic tie-break by index
                    best_v = v
                    best_score = score

        v = best_v
        # Find smallest available color
        used_mask = 0
        for u in neighbors[v]:
            if color[u] != -1:
