def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
        if is_matrix:
            for i in range(n):
                for j in range(n):
                    if adj[i][j] not in (0, 1):
                        is_matrix = False
                        break
                if not is_matrix:
                    break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        normalized = [0] * n
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            normalized[i] = unique_colors[c]
        return normalized

    # Strategy 1: BFS-based bipartite extraction + conflict resolution
    def bfs_bipartite_plus():
        color = [-1] * n
        from collections import deque
        q = deque()

        # Process each connected component
        for start in range(n):
            if color[start] != -1:
                continue
            color[start] = 0
            q.append(start)
            while q:
                u = q.popleft()
                for v in neighbors[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        q.append(v)
                    elif color[v] == color[u]:
                        # Conflict: edge within same layer -> odd cycle detected
                        # We'll handle this later by trying to recolor
                        pass

        # Now try to resolve conflicts by introducing third color where needed
        # We'll use a simple greedy approach on conflicting vertices
        # First, identify vertices involved in conflicts
        conflict = [False] * n
        for u in range(n):
            for v in neighbors[u]:
                if u < v and color[u] == color[v]:
                    conflict[u] = True
                    conflict[v] = True

        # Try to recolor conflicted vertices with color 2 if possible
        # Process in random order to avoid bias
        order = [i for i in range(n) if conflict[i]]
        random.shuffle(order)
        for u in order:
            used = set()
            for v in neighbors[u]:
                if color[v] != -1:
                    used.add(color[v])
            # Find smallest color not in used
            c = 0
            while c in used:
                c += 1
            color[u] = c

        # Ensure validity by final greedy pass if needed
        if not is_valid(color):
            # Fallback to greedy with ordering by degree
            order = list(range(n))
            order.sort(key=lambda x: len(neighbors[x]), reverse=True)
            color = [-1] * n
            for u in order:
                used = set()
                for v in neighbors[u]:
                    if color[v] != -1:
                        used.add(color[v])
                c = 0
                while c in used:
                    c += 1
                color[u] = c

        return normalize(color)

    # Strategy 2: DSATUR with bitmask optimization
    def dsatur():
        if n == 0:
            return []
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor masks for each vertex
        colored_mask = [0] * n
        degree = [len(neighbors[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if color[u] == -1:
                    sat_u = saturation[u]
                    deg_u = degree[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            used = colored_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Update neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    # Add color c to u's saturation if not already present
                    if not (saturation[u] & (1 << c)):
                        saturation[u] |= (1 << c)
                    colored_mask[u] |= (1 << c)

        return normalize(color)

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        color = [-1] * n
        current_color = 0
        # uncolored set as bitmask
        uncolored = (1 << n) - 1

        while uncolored:
            # Build independent set for current color
            independent_set = 0
            # Choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            # Iterate over uncolored vertices
            temp = uncolored
            while temp:
                u = (temp & -temp).bit_length() - 1
                temp &= temp - 1
                # Degree in uncolored subgraph: neighbors[u] & uncolored
                deg_u = (bit_adj[u] & uncolored).bit_count()
                if deg_u > max_deg:
                    max_deg = deg_u
                    v = u
            if v == -1:
                break

            independent_set |= (1 << v)
            # Partition uncolored: U = not adjacent to S, W = adjacent to S
            S_mask = independent_set
            W_mask = 0
            # U initially: uncolored minus v and its neighbors
            U_mask = uncolored & ~(S_mask | bit_adj[v])

            while U_mask:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = n+1
                temp = U_mask
                while temp:
                    u = (temp & -temp).bit_length() - 1
                    temp &= temp - 1
                    # |N(u) ∩ W|
                    w_neighbors = (bit_adj[u] & W_mask).bit_count()
                    # degree in U: |N(u) ∩ U|
                    deg_in_U = (bit_adj[u] & U_mask).bit_count()
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                # Add best_u to S
                independent_set |= (1 << best_u)
                # Move best_u from U to W
                U_mask &= ~(1 << best_u)
                W_mask |= (1 << best_u)
                # Remove neighbors of best_u from U (they become ineligible)
                U_mask &= ~bit_adj[best_u]

            # Assign color to independent_set
            temp = independent_set
            while temp:
                u = (temp & -temp).bit_length() - 1
                temp &= temp - 1
                color[u] = current_color
            current_color += 1
            # Remove independent_set from uncolored
            uncolored &= ~independent_set

        return normalize(color)

    # Strategy 4: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll use bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # Remove u from its current bucket
                    old_deg = degree[u]
                    buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    buckets[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg

        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

        return normalize(color)

    # Run all strategies and pick the best (fewest colors)
    strategies = [
        ("bfs_bipartite_plus", bfs_bipartite_plus),
        ("dsatur", dsatur),
        ("rlf", rlf),
        ("smallest_last", smallest_last)
    ]

    best_coloring = None
    best_num_colors = float('inf')

    for name, strategy in strategies:
        try:
            coloring = strategy()
            if is_valid(coloring):
                nc = num_colors(coloring)
                if nc < best_num_colors:
                    best_num_colors = nc
                    best_coloring = coloring
        except Exception:
            # In case of error, skip this strategy
            continue

    # Fallback: if no strategy worked, use simple greedy
    if best_coloring is None or not is_valid(best_coloring):
        order = list(range(n))
        order.sort(key=lambda x: len(neighbors[x]), reverse=True)
        color = [-1] * n
        for u in order:
            used = set()
            for v in neighbors[u]:
                if color[v] != -1:
                    used.add(color[v])
            c = 0
            while c in used:
                c += 1
            color[u] = c
        best_coloring = normalize(color)

    return best_coloring

