        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = [False] * k
                for u in adj_list[v]:
                    c = coloring[u]
                    if c < k:  # only consider colors in range
                        used_by_neighbors[c] = True

                for c in range(k - 1):  # try colors 0 to k-2
                    if not used_by_neighbors[c]:
                        # Try to move v to color c
                        coloring[v] = c
                        if is_valid(coloring):
                            improved = True
                            break
                        else:
                            coloring[v] = target_color  # revert
                if improved:
                    break

                # Try Kempe chains with each lower color
                for c in range(k - 1):
                    # Build (c, target_color) Kempe chain containing v
                    # We'll do BFS to find the component
                    from collections import deque
                    queue = deque([v])
                    visited = set([v])
                    component = set()
                    # Only traverse vertices colored c or target_color
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in adj_list[x]:
                            if y not in visited and (coloring[y] == c or coloring[y] == target_color):
                                visited.add(y)
                                queue.append(y)

                    # Try swapping colors in the component
                    # Create new coloring by swapping c and target_color in component
                    new_coloring = coloring[:]
                    for x in component:
                        if new_coloring[x] == c:
                            new_coloring[x] = target_color
                        elif new_coloring[x] == target_color:
                            new_coloring[x] = c

                    # Check if this move reduces the number of vertices in target_color
                    # and doesn't increase conflicts
                    if is_valid(new_coloring):
                        # Count how many vertices would be in target_color after swap
                        count_target = sum(1 for x in component if new_coloring[x] == target_color)
                        if count_target < len([x for x in component if coloring[x] == target_color]):
                            # This swap reduces the target color count in this component
                            coloring = new_coloring
                            improved = True
                            break
                if improved:
                    break

            # If we improved, try to renormalize and reduce k
            if improved:
                coloring = normalize(coloring)
                k = num_colors(coloring)

        return coloring

    # Run all heuristics with time budgeting
    start_time = time.time()
    time_limit = 0.045  # 45ms to leave room for overhead

    # DSATUR
    if time.time() - start_time < time_limit:
        c1 = dsatur()
        if is_valid(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_coloring = c1

    # RLF
    if time.time() - start_time < time_limit:
        c2 = rlf()
        if is_valid(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_coloring = c2

    # Smallest-Last
    if time.time() - start_time < time_limit:
        c3 = smallest_last()
        if is_valid(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_coloring = c3

    # Apply Kempe reduction to the best found so far
    if best_coloring is not None and time.time() - start_time < time_limit:
        c4 = kempe_reduce(best_coloring[:])
        if is_valid(c4):
            k4 = num_colors(c4)
            if k4 < best_k:
                best_k = k4
                best_coloring = c4

    # Fallback: if nothing worked, use greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: (-degrees[x], x))
        coloring = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            color = 0
            while used[color]:
                color += 1
            coloring[v] = color
        best_coloring = normalize(coloring)

    return best_coloring

