    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Helper: count triangles for each vertex
    def count_triangles():
        tri_count = [0] * n
        for u in range(n):
            neighbors = adj_list[u]
            ln = len(neighbors)
            for i in range(ln):
                for j in range(i+1, ln):
                    v = neighbors[i]
                    w = neighbors[j]
                    # Check if v and w are adjacent
                    if (bit_adj[v] >> w) & 1:
                        tri_count[u] += 1
                        tri_count[v] += 1
                        tri_count[w] += 1
        # Each triangle counted 3 times (once per vertex), so divide by 3? 
        # Actually we want per-vertex triangle count, so we leave as is (each vertex's count is correct)
        return tri_count

    # DSATUR with triangle count tie-breaking
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colorsets as bitmask for fast saturation update
        neighbor_colors = [0] * n  # bitmask of colors used by neighbors

        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]
        # Triangle counts for tie-breaking
        tri_counts = count_triangles()

        # Select first vertex: max degree, then max triangle count
        uncolored = set(range(n))
        if uncolored:
            v = max(uncolored, key=lambda x: (degrees[x], tri_counts[x], x))
            coloring[v] = 0
            uncolored.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:  # uncolored
                    neighbor_colors[u] |= (1 << 0)
                    saturation[u] = neighbor_colors[u].bit_count()

        # Color remaining vertices
        while uncolored:
            # Find vertex with max saturation
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat = saturation[v]
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)

            # Tie-break: degree in uncolored subgraph, then triangle count, then index
            def uncolored_degree(v):
                count = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        count += 1
                return count

            v = max(candidates, key=lambda x: (uncolored_degree(x), tri_counts[x], x))

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            # Update neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:  # uncolored
                    neighbor_colors[u] |= (1 << c)
                    saturation[u] = neighbor_colors[u].bit_count()

        return normalize(coloring)

    # RLF (Recursive Largest First) with triangle count
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        # Precompute triangle counts for tie-breaking
        tri_counts = count_triangles()

        while uncolored:
            # Build independent set for this color
            independent_set = []
            # Candidates: vertices not adjacent to any in independent_set
            # ineligible: vertices adjacent to independent_set
            ineligible = set()

            # Start with vertex of max degree in uncolored subgraph
            def degree_in_uncolored(v):
                return sum(1 for u in adj_list[v] if u in uncolored)

            v = max(uncolored, key=lambda x: (degree_in_uncolored(x), tri_counts[x], x))
            independent_set.append(v)
            # Mark neighbors as ineligible
            for u in adj_list[v]:
                if u in uncolored:
                    ineligible.add(u)

            # Update uncolored: remove v
            uncolored.remove(v)

            # Eligible vertices: uncolored and not ineligible
            eligible = uncolored - ineligible

            while eligible:
                # Select vertex with max neighbors in ineligible
                def num_ineligible_neighbors(v):
                    return sum(1 for u in adj_list[v] if u in ineligible)

                # Tie-break: min degree in eligible subgraph
                def degree_in_eligible(v):
                    return sum(1 for u in adj_list[v] if u in eligible)

                v = max(eligible, key=lambda x: (num_ineligible_neighbors(x), -degree_in_eligible(x), tri_counts[x], x))

                independent_set.append(v)
                # Move v from eligible to independent_set
                eligible.remove(v)
                # Add neighbors of v that are in eligible to ineligible
                for u in adj_list[v]:
                    if u in eligible:
                        ineligible.add(u)
                        eligible.remove(u)

                # Recompute eligible: uncolored - ineligible
                eligible = uncolored - ineligible

            # Assign color to independent_set
            for v in independent_set:
                coloring[v] = color
            color += 1

        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        # Set of unremoved vertices
        remaining = set(range(n))
        order = []  # removal order

        while remaining:
            # Find vertex with minimum degree in remaining subgraph
            min_deg = float('inf')
            min_v = -1
            for v in remaining:
                # Compute current degree in remaining subgraph
                deg = 0
                for u in adj_list[v]:
                    if u in remaining:
                        deg += 1
                if deg < min_deg:
                    min_deg = deg
                    min_v = v
            # Remove min_v
            remaining.remove(min_v)
            order.append(min_v)
            # Update degrees of neighbors (optional, but we recompute each time)

        # Color in reverse removal order using First-Fit
        coloring = [-1] * n
        for v in reversed(order):
            # Find colors used by colored neighbors
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            # Find smallest available color
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        improved = True

        while improved:
            improved = False
            k = num_colors(current)
            if k <= 1:
                break

            # Target the smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if current[v] == target_color]

            if not target_vertices:
                # Should not happen, but safety
                break

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    if current[u] != -1:
