                    # We'll try to swap colors c and target_color in the component containing v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap would cause conflict)
                    has_c_neighbor = False
                    for u in adj_list[v]:
                        if current[u] == c:
                            has_c_neighbor = True
                            break
                    if has_c_neighbor:
                        continue  # swap would create conflict with c-colored neighbor

                    # Build the Kempe chain component for colors (c, target_color) containing v
                    # Using BFS
                    from collections import deque
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    while q:
                        node = q.popleft()
                        for u in adj_list[node]:
                            if current[u] == c or current[u] == target_color:
                                if u not in comp:
                                    comp.add(u)
                                    q.append(u)

                    # Check if swapping is safe: no vertex in comp has a neighbor outside comp with the target color
                    # Actually, swapping is always safe for Kempe chain as it preserves validity
                    # Perform swap: c <-> target_color in comp
                    for node in comp:
                        if current[node] == c:
                            current[node] = target_color
                        elif current[node] == target_color:
                            current[node] = c
                    improved = True
                    break  # break from color loop
                if improved:
                    break  # break from vertex loop

            # If we improved, try to eliminate empty color classes
            if improved:
                # Compact colors: remove gaps
                # First, normalize to 0..k-1
                current = normalize(current)
                # Recompute k
                k = num_colors(current)
                # If the highest color class is empty, we can reduce
                # But normalize already ensures no gaps, so we just continue

        return normalize(current)

    # Generate candidate colorings
    candidates = []

    # Run DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass

    # Run RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass

    # Run Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), use greedy
    if not candidates:
        # Simple greedy by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(normalize(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_colors = num_colors(best)

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best[:])
        if is_valid_coloring(improved):
            improved_colors = num_colors(improved)
            if improved_colors < best_colors:
                best = improved
    except:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()

    return normalize(best)

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neigh) for neigh in adj]
    deg = [len(adj_list[i]) for i in range(n)]

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree then random
            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # Assign smallest available color
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to S (eligible), W: adjacent to S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in adj_list[w] for w in S)}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = max(U, key=lambda x: (sum(1 for y in adj_list[x] if y in W), -sum(1 for y in adj_list[x] if y in U), random.random()))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for y in adj_list[u_star]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg_copy = deg[:]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg_copy[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = deg_copy[u]
                    if d > 0:
                        deg_copy[u] -= 1
                        buckets[d].remove(u)
                        buckets[d-1].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal k
        improved = True
        while improved and k > 1:
            improved = False
            # Find smallest color class (highest index)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[coloring[v]].append(v)
            # Try to eliminate color k-1
            target_color = k - 1
            if not color_classes[target_color]:
                k -= 1
                continue
            # Try to recolor each vertex in target color
            for v in color_classes[target_color][:]:
                # Try direct reassignment to a lower color
                used = [False] * k
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used[coloring[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        # Check if moving v to c is safe (no conflict)
                        conflict = False
                        for u in adj_list[v]:
                            if coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            coloring[v] = c
                            improved = True
                            break
                if improved:
                    # Rebuild color classes and restart
                    color_classes = [[] for _ in range(k)]
                    for u in range(n):
                        color_classes[coloring[u]].append(u)
                    if not color_classes[target_color]:
                        k -= 1
                        improved = True
                        break
                    else:
                        # Reset for next vertex
                        continue
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Skip if v already has a neighbor of color c (direct move blocked)
                    if any(coloring[u] == c for u in adj_list[v]):
                        continue
                    # Build (c, target_color) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if swapping colors in component is safe
                    # Specifically, ensure no vertex in component gets a color that conflicts with its neighbors
                    valid_swap = True
                    for x in component:
                        new_color = c if coloring[x] == target_color else target_color
                        for y in adj_list[x]:
                            if coloring[y] == new_color and y not in component:
                                valid_swap = False
                                break
                        if not valid_swap:
                            break
                    if valid_swap:
                        # Perform swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            else:
                                coloring[x] = c
                        improved = True
                        # Rebuild and check if target color is eliminated
                        color_classes = [[] for _ in range(k)]
                        for u in range(n):
                            color_classes[coloring[u]].append(u)
                        if not color_classes[target_color]:
                            k -= 1
                            improved = True
                            break
                if improved:
                    break
            # If no improvement in this pass, try to reduce k by compacting colors
            if not improved:
                # Compact color indices: map used colors to 0..k'-1
                used_colors = set(coloring)
                if len(used_colors) < k:
                    mapping = {old: new for new, old in enumerate(sorted(used_colors))]
                    coloring = [mapping[c] for c in coloring]
                    k = len(used_colors)
                    improved = True
        return coloring

    best_coloring = kempe_reduce(best_coloring[:])
    # Final validation and compacting
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors)))
        best_coloring = [mapping[c] for c in best_coloring]
    # Verify correctness
    for u in range(n):
        for v in adj_list[u]:
            if best_coloring[u] == best_coloring[v]:
                # Fallback to greedy if invalid (should not happen)
                return greedy_color(list(range(n)))
    return best_coloring

