    # Degree ascending
    orderings.append(sorted(vertices, key=lambda x: (degrees[x], x)))
    # Random shuffles
    for _ in range(20):
        if time.time() - start_time > timeout:
            break
        order = vertices[:]
        random.shuffle(order)
        orderings.append(order)
    # Perturbed degree orderings
    for _ in range(10):
        if time.time() - start_time > timeout:
            break
        order = sorted(vertices, key=lambda x: (-degrees[x], random.random()))
        orderings.append(order)

    for order in orderings:
        if time.time() - start_time > timeout:
