        k = count_colors(coloring)
        if k >= best_k:
            continue
        # Apply 1-opt local search: try to reduce color of each vertex
        improved = True
        while improved and k > 1:
            improved = False
            # Process vertices in random order to avoid cycles
            order_v = vertices[:]
            random.shuffle(order_v)
            for v in order_v:
