    # Fallback: if no valid coloring found (should not happen), use greedy on degree order
    if best_coloring is None or not is_valid(best_coloring):
        coloring = greedy_color(sorted(vertices, key=lambda x: (-degrees[x], x)))
        if is_valid(coloring):
