            best_k = count_colors(coloring)
        else:
            # Last resort: assign each vertex a unique color
            best_coloring = list(range(n))
            best_k = n

    # Compact colors to 0..k-1
    if best_coloring:
        unique_colors = {}
        next_color = 0
        compacted = []
        for c in best_coloring:
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            compacted.append(unique_colors[c])
        best_coloring = compacted

    return best_coloring

