    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # Treat as adjacency list
        graph = [list(neighbors) for neighbors in adj]

    # Precompute neighbor sets for fast lookup
    neighbor_sets = [set(neighbors) for neighbors in graph]

    # Compute Jaccard similarity for non-adjacent vertex pairs
    jaccard = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if j not in neighbor_sets[i]:
                set_i = neighbor_sets[i]
                set_j = neighbor_sets[j]
                intersection = len(set_i & set_j)
                union = len(set_i | set_j)
                if union > 0:
                    jaccard[i][j] = jaccard[j][i] = intersection / union
                else:
                    jaccard[i][j] = jaccard[j][i] = 0.0

    # Initialize coloring: -1 means uncolored
    color = [-1] * n
    current_color = 0

    # Greedy coloring using Jaccard-based heuristic
    while -1 in color:
        # Find the uncolored vertex with the highest degree (break ties by index)
        uncolored = [v for v in range(n) if color[v] == -1]
        if not uncolored:
            break
        v = max(uncolored, key=lambda x: (len(graph[x]), -x))

        # Determine forbidden colors from colored neighbors
        forbidden = set()
        for u in graph[v]:
            if color[u] != -1:
                forbidden.add(color[u])

        # Try to assign the smallest available color
        c = 0
        while c in forbidden:
            c += 1
        color[v] = c

        # Try to extend the color class with non-adjacent vertices having high Jaccard similarity
        candidates = []
        for u in uncolored:
            if u == v or color[u] != -1:
                continue
            if u not in neighbor_sets[v]:  # Ensure non-adjacency
                sim = jaccard[v][u]
                if sim > 0.5:  # Threshold for high similarity
                    candidates.append((sim, u))

        # Sort candidates by similarity descending, then by vertex index for tie-breaking
        candidates.sort(key=lambda x: (-x[0], x[1]))

        for sim, u in candidates:
            # Check if u can safely take color c (no conflict with already colored neighbors)
            conflict = False
            for w in graph[u]:
                if color[w] == c:
                    conflict = True
                    break
            if not conflict:
                color[u] = c

    # Compact color indices to ensure they are consecutive starting from 0
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

