        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # 1. Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    col_wp = greedy_color(order_wp)
    k_wp = num_colors(col_wp)
    if k_wp < best_k:
        best_k = k_wp
        best_coloring = col_wp[:]

    # 2. Smallest-Last ordering (degeneracy)
    remaining = set(range(n))
    order_sl = []
    deg = [len(neighbors[u]) for u in range(n)]
    for _ in range(n):
        # find vertex with min degree in remaining
        v = min(remaining, key=lambda x: deg[x])
        order_sl.append(v)
        remaining.remove(v)
        for w in neighbors[v]:
            if w in remaining:
                deg[w] -= 1
    order_sl.reverse()
    col_sl = greedy_color(order_sl)
    k_sl = num_colors(col_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = col_sl[:]

    # 3. DSATUR with bitmask optimization
    color = [-1] * n
    sat = [0] * n  # saturation degree as bitmask of colors used in neighbors
    uncolored = set(range(n))
    for _ in range(n):
        if not uncolored:
            break
        # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
        v = max(uncolored, key=lambda x: (sat[x].bit_count(),
                                           sum(1 for y in neighbors[x] if y in uncolored),
                                           random.random()))
        # compute used colors from neighbors
        used = 0
        for y in neighbors[v]:
            c = color[y]
            if c != -1:
                used |= (1 << c)
