        c = 0
        while used & (1 << c):
            c += 1
        color[v] = c
        uncolored.remove(v)
        # update saturation of uncolored neighbors
        for y in neighbors[v]:
            if y in uncolored:
                sat[y] |= (1 << c)
    col_ds = color[:]
    k_ds = num_colors(col_ds)
    if k_ds < best_k:
        best_k = k_ds
        best_coloring = col_ds[:]

    # Kempe chain elimination to reduce colors
    def eliminate_color(col):
        nonlocal best_k, best_coloring
        k = num_colors(col)
        if k <= 1:
            return col
        # try to eliminate highest color class
        target = k - 1
        verts_target = [i for i in range(n) if col[i] == target]
        if not verts_target:
            # compact colors
            mapping = {}
            next_c = 0
            for i in range(n):
                c = col[i]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[i] = mapping[c]
            return eliminate_color(col)
        moved = False
        for v in verts_target:
            # try direct reassignment to a lower color
            used = 0
            for y in neighbors[v]:
                c = col[y]
                if c != -1:
                    used |= (1 << c)
            for c in range(target):
                if not (used & (1 << c)):
                    col[v] = c
                    moved = True
                    break
            if moved:
                break
            # try Kempe chain swap with each lower color
            for c in range(target):
                # BFS to find Kempe chain component of v in colors {c, target}
                from collections import deque
                comp = []
                seen = set()
                dq = deque([v])
                seen.add(v)
                while dq:
                    node = dq.popleft()
                    comp.append(node)
                    for nb in neighbors[node]:
                        if nb not in seen and col[nb] in (c, target):
                            seen.add(nb)
                            dq.append(nb)
                # check if any neighbor of component has color c (would cause conflict if swapped)
                conflict = False
                for node in comp:
                    for nb in neighbors[node]:
                        if col[nb] == c and nb not in comp:
                            conflict = True
                            break
                    if conflict:
                        break
                if not conflict:
                    # perform swap
                    for node in comp:
                        col[node] = c if col[node] == target else target
                    moved = True
                    break
            if moved:
                break
        if moved:
            # compact and recurse
            mapping = {}
            next_c = 0
            for i in range(n):
                c = col[i]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[i] = mapping[c]
            return eliminate_color(col)
        else:
            return col

    # Apply Kempe elimination on best coloring found
    final_col = eliminate_color(best_coloring[:])
    final_k = num_colors(final_col)
    if final_k < best_k:
        best_k = final_k
        best_coloring = final_col

    # Validate coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Fallback to Welsh-Powell if invalid (should not happen)
                col_wp = greedy_color(order_wp)
                return col_wp

    return best_coloring

