    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    for u in range(n):
        if is_matrix:
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
        else:
            for v in adj[u]:
                adj_list[u].append(v)
                bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and len([w for w in adj_list[u] if w in uncolored]) > max_deg):
                    max_sat = sat[u]
                    max_deg = len([w for w in adj_list[u] if w in uncolored])
                    v = u
            # Assign smallest available color
            used = 0
            for w in adj_list[v]:
                if color[w] != -1:
                    used |= (1 << color[w])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for w in adj_list[v]:
                if w in uncolored:
                    sat[w] += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: len([w for w in adj_list[u] if w in uncolored]))
            S.append(v)
            # Partition U and W
            U = uncolored - {v}
            W = set(w for w in adj_list[v] if w in uncolored)
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = len([w for w in adj_list[u] if w in W])
                    deg_u = len([w for w in adj_list[u] if w in U])
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        degrees = [len(adj_list[u]) for u in range(n)]
        order = []
        remaining = set(range(n))
        temp_adj = [set(adj_list[u]) for u in range(n)]
        for _ in range(n):
            # Find vertex of min degree in remaining
            v = min(remaining, key=lambda u: degrees[u])
            order.append(v)
            remaining.remove(v)
            for u in temp_adj[v]:
                if u in remaining:
                    degrees[u] -= 1
            temp_adj[v].clear()
        # Reverse order and greedy color
        order.reverse()
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = min(candidates, key=lambda col: max(col) + 1 if col else 0)
    k = max(best_color) + 1 if best_color else 0

    # Try to reduce colors via Kempe chain swaps
    def kempe_reduce(coloring, target_k):
        # Try to eliminate color target_k-1
        target_color = target_k - 1
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return coloring, target_k - 1

        # Try direct reassignment
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != target_color:  # only consider colors < target_color
                    used |= (1 << coloring[u])
            for c in range(target_color):
                if not (used & (1 << c)):
                    coloring[v] = c
                    vertices.remove(v)
                    break
        if not vertices:
            # Successfully eliminated target_color
            # Remap colors to be consecutive
            mapping = {}
            next_c = 0
            for v in range(n):
                if coloring[v] not in mapping:
                    mapping[coloring[v]] = next_c
                    next_c += 1
                coloring[v] = mapping[coloring[v]]
            return coloring, next_c

        # Try Kempe chains for remaining vertices in target_color
        for v in vertices[:]:  # iterate over copy
            for c in range(target_color):
                # Build (c, target_color)-Kempe chain containing v
                if coloring[v] != target_color:
                    continue
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if coloring[node] == c or coloring[node] == target_color:
                        component.add(node)
                        for u in adj_list[node]:
                            if u not in visited and (coloring[u] == c or coloring[u] == target_color):
                                stack.append(u)
                # Check if we can swap: no vertex in component colored c would get conflict after swap
                valid = True
                for node in component:
                    if coloring[node] == c:
                        for u in adj_list[node]:
                            if coloring[u] == target_color and u not in component:
                                valid = False
                                break
                    if not valid:
                        break
                if valid:
                    # Perform swap
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = target_color
                        else:
                            coloring[node] = c
                    vertices.remove(v)
                    break
            if not vertices:
                break

        if vertices:
            # Could not eliminate, return original
            return coloring, target_k
        else:
            # Remap colors
            mapping = {}
            next_c = 0
            for v in range(n):
                if coloring[v] not in mapping:
                    mapping[coloring[v]] = next_c
                    next_c += 1
                coloring[v] = mapping[coloring[v]]
            return coloring, next_c

    # Kempe reduction loop
    current_color = best_color[:]
    current_k = k
    improved = True
    while improved and current_k > 1:
        improved = False
        new_color, new_k = kempe_reduce(current_color[:], current_k)
        if new_k < current_k:
            current_color = new_color
            current_k = new_k
            improved = True

    # Final validation (optional, but safe)
    for u in range(n):
        for v in adj_list[u]:
            if u < v and current_color[u] == current_color[v]:
                # Fallback to best candidate if invalid (should not happen)
                return best_color

    return current_color

