            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
        else:
            for v in adj[u]:
                adj_list[u].append(v)
                bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

