        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([y for y in adj_list[x] if y in uncolored])))
            # Compute used colors from neighbors
            used = 0
            for y in adj_list[v]:
                if color[y] != -1:
                    used |= (1 << color[y])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for y in adj_list[v]:
                if y in uncolored:
                    sat[y] += 1
        return color

    # Helper: RLF
    def rlf():
