        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U = {y for y in uncolored if y not in S and not any(z in S for z in adj_list[y])}
            W = {y for y in uncolored if y not in S and y not in U}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([z for z in adj_list[x] if z in W]), -len([z for z in adj_list[x] if z in U])))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: smallest-last ordering
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        for _ in range(n):
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for y in adj_list[v]:
                if y in remaining:
