                for c in range(target):
                    # Build (target, c)-Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target or coloring[node] == c:
                            component.add(node)
                            for u in adj_list[node]:
                                if u not in visited and (coloring[u] == target or coloring[u] == c):
                                    stack.append(u)
                    # Check if swapping this component would not pull any vertex into target color
                    # Actually, swapping will change target->c and c->target in component
                    # We want that after swap, no vertex in component becomes target (unless it was c and we don't mind)
                    # But we are trying to free v from target, so we need that after swap, v is not target.
                    # Since v is target, after swap it becomes c, so good.
                    # However, we must ensure we don't pull other target-colored vertices into target? 
                    # Swapping target<->c: target becomes c, c becomes target.
                    # So vertices that were target become c (good), vertices that were c become target (bad if they were not target originally).
                    # We only want to do the swap if it does not increase the number of target-colored vertices.
                    # Currently, component has some number of target and c vertices.
                    # After swap, target-colored vertices in component become c, and c-colored become target.
                    # So the number of target-colored vertices in component becomes the number that were c.
