                    # But we are trying to eliminate target color, so we want to reduce total target count.
                    # Let t = number of target in component, c_count = number of c in component.
                    # After swap, target count in component becomes c_count.
                    # Change in target count = c_count - t.
                    # We want this to be negative (so total target count decreases).
                    t_count = sum(1 for node in component if coloring[node] == target)
                    c_count = sum(1 for node in component if coloring[node] == c)
                    if c_count < t_count:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target:
                                coloring[node] = c
                            else:
                                coloring[node] = target
                        changed = True
                        break
                if changed:
                    break
            if not changed:
