            classes = [[] for _ in range(k)]
            for v in range(n):
                classes[coloring[v]].append(v)
            if not classes[target]:
                # Recolor: map colors > target down by 1
                for v in range(n):
                    if coloring[v] > target:
                        coloring[v] -= 1
                k -= 1
