                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + flat[base + m]
            # Build backward matrix q ((k+1) x M)
            q = [[0] * M for _ in range(k+1)]
            # q[k][m] = 0 already
            for r in range(k-1, -1, -1):
                base = pi[r] * M
                q[r][M-1] = q[r+1][M-1] + flat[base + M-1]
                for m in range(M-2, -1, -1):
