                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + flat[base + m]
            # Find best insertion position
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                f = [0] * M
