    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for NEH and Palmer
    total_time = [sum(job) for job in times]
    slope = [sum((2 * j - m + 1) * times[i][j] for j in range(m)) for i in range(n)]

    # Helper: compute makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for k in range(1, m):
                t[k] = max(t[k], t[k-1]) + job_time[k]
        return t[-1]

    # Helper: compute forward completion matrix e for a prefix of length k
    def compute_forward(perm, k):
        if k == 0:
            return [[0] * m]
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job = perm[r]
            job_time = times[job]
            if r == 0:
                e[0][0] = job_time[0]
                for mc in range(1, m):
                    e[0][mc] = e[0][mc-1] + job_time[mc]
            else:
                e[r][0] = e[r-1][0] + job_time[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + job_time[mc]
        return e

    # Helper: compute backward tail matrix q for a prefix of length k
    def compute_backward(perm, k):
        if k == 0:
            return [[0] * m for _ in range(k+1)]
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            job_time = times[job]
            q[r][m-1] = q[r+1][m-1] + job_time[m-1]
            for mc in range(m-2, -1, -1):
                q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + job_time[mc]
        return q

    # NEH construction with Taillard acceleration
    def construct_neh(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) == 1:
            return seq
        # Evaluate first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Greedy insertion
        for idx in range(2, len(order)):
            job = order[idx]
            k = len(seq)
            e = compute_forward(seq, k)
            q = compute_backward(seq, k)
            best_pos = 0
            best_mk = float('inf')
            for pos in range(k+1):
                # Compute forward vector f for inserting job at position pos
                f = [0] * m
                if pos == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[pos-1]
                f[0] = prev_e[0] + times[job][0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], prev_e[mc]) + times[job][mc]
                # Compute makespan candidate
                mk = 0
                for mc in range(m):
                    val = f[mc] + q[pos][mc]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Initial solution: try NEH with total time and Palmer order
    order_total = sorted(range(n), key=lambda i: (-total_time[i], i))
    order_palmer = sorted(range(n), key=lambda i: (-slope[i], i))
    best_seq = construct_neh(order_total)
    best_mk = makespan(best_seq)
    seq2 = construct_neh(order_palmer)
    mk2 = makespan(seq2)
    if mk2 < best_mk:
        best_seq = seq2
