    if n > 80:
        max_iter = 30
    elif n > 40:
        max_iter = 40

    current_seq = best_seq[:]
    current_mk = best_mk

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= n:
            destroyed = []
            removed = current_seq[:]
        else:
            indices = random.sample(range(n), d)
            indices_set = set(indices)
            destroyed = [current_seq[i] for i in indices]
            removed = [current_seq[i] for i in range(n) if i not in indices_set]
        # Reconstruction: reinsert removed jobs one by one using NEH insertion with Taillard
        for job in removed:
            k = len(destroyed)
            e = compute_forward(destroyed, k)
            q = compute_backward(destroyed, k)
            best_pos = 0
            best_mk_ins = float('inf')
            for pos in range(k+1):
                if pos == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[pos-1]
                f = [0] * m
                f[0] = prev_e[0] + times[job][0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], prev_e[mc]) + times[job][mc]
                mk_ins = 0
                for mc in range(m):
