def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    N = len(times)
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    p = [row[:] for row in times]

    # Compute total processing times for NEH priority
    total = [sum(job) for job in p]
    order = sorted(range(N), key=lambda i: total[i], reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    # Helper: compute makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Helper: evaluate insertion makespan using Taillard's O(k*M) scheme
    def evaluate_insertion(partial, job_idx, k):
        # Compute forward matrix e for partial schedule of length k
        if k == 0:
            for m in range(M):
                e[0][m] = p[partial[0]][m] if partial else 0
        else:
            for m in range(M):
                e[0][m] = p[partial[0]][m]
            for r in range(1, k):
                e[r][0] = e[r-1][0] + p[partial[r]][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[partial[r]][m]
        # Compute backward tail matrix q for partial schedule
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        # Evaluate each insertion position
        best_val = float('inf')
        best_pos = 0
        for i in range(k+1):
            # Compute forward vector f for job_idx up to each machine
            if i == 0:
                f0 = p[job_idx][0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[-1], 0) + p[job_idx][m])
            else:
                f0 = e[i-1][0] + p[job_idx][0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[-1], e[i-1][m]) + p[job_idx][m])
            # Compute makespan candidate
            val = 0
            for m in range(M):
                cand = f[m] + q[i][m]
                if cand > val:
                    val = cand
            if val < best_val:
                best_val = val
                best_pos = i
        return best_pos, best_val

    # NEH construction with Taillard acceleration
    perm = [order[0]]
    for k in range(1, N):
        job_idx = order[k]
        pos, _ = evaluate_insertion(perm, job_idx, k)
        perm.insert(pos, job_idx)

    best_perm = perm[:]
    best_makespan = makespan(perm)

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        # Destruction: remove d jobs at random positions
        if N <= d:
            destroyed = perm[:]
            remaining = []
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            destroyed = []
            remaining = perm[:]
            for pos in positions:
                destroyed.append(remaining.pop(pos))
        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        current = remaining[:]
        for job_idx in destroyed:
            k = len(current)
            pos, _ = evaluate_insertion(current, job_idx, k)
            current.insert(pos, job_idx)
        # Acceptance criterion
        current_makespan = makespan(current)
        if current_makespan < makespan(perm):
            perm = current[:]
            if current_makespan < best_makespan:
                best_perm = current[:]
                best_makespan = current_makespan
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = current_makespan - makespan(perm)
            if delta < 0 or random.random() < math.exp(-delta / T):
                perm = current[:]
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= no_improve_limit:
            break

    return best_perm

