def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    lower_bound = 0
    for m in range(M):
        min_before = min(times[i][:m] for i in range(N)) if m > 0 else [0] * N
        min_after = min(times[i][m+1:] for i in range(N)) if m < M-1 else [0] * N
        lb_m = min(sum(b) for b in min_before) + sum(times[i][m] for i in range(N)) + min(sum(a) for a in min_after)
        if lb_m > lower_bound:
            lower_bound = lb_m

    P = [sum(job) for job in times]
    S = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]
    order_by_P = sorted(range(N), key=lambda i: (-P[i], i))
    order_by_S = sorted(range(N), key=lambda i: (-S[i], i))

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
        return e

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    def insertion_cost(perm, job, e, q, i):
        k = len(perm)
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev = e[i-1][m] if i-1 >= 0 else 0
                f[m] = prev + times[job][m]
            else:
                f[m] = max(f[m-1], e[i-1][m] if i-1 >= 0 else 0) + times[job][m]
        cost = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > cost:
                cost = val
        return cost

    def neh_insertion(order):
        if not order:
            return []
        perm = [order[0]]
        if len(order) > 1:
            job1, job2 = order[0], order[1]
            cost1 = makespan([job1, job2])
            cost2 = makespan([job2, job1])
            perm = [job1, job2] if cost1 <= cost2 else [job2, job1]
            start_idx = 2
        else:
            start_idx = 1
        for idx in range(start_idx, len(order)):
            job = order[idx]
            e = compute_forward(perm)
            q = compute_backward(perm)
            best_cost = float('inf')
            best_pos = 0
            for i in range(len(perm) + 1):
                cost = insertion_cost(perm, job, e, q, i)
                if cost < best_cost or (cost == best_cost and i < best_pos):
                    best_cost = cost
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    def ig_iteration(current_perm, T):
        d = 3 if N <= 30 else 4
        if d > N:
            d = N
        indices = random.sample(range(N), d)
        extracted = [current_perm[i] for i in indices]
        remaining = [current_perm[i] for i in range(N) if i not in indices]
        random.shuffle(extracted)
        perm_D = remaining[:]
        for job in extracted:
            e = compute_forward(perm_D)
            q = compute_backward(perm_D)
            best_cost = float('inf')
            best_pos = 0
            for i in range(len(perm_D) + 1):
                cost = insertion_cost(perm_D, job, e, q, i)
                if cost < best_cost or (cost == best_cost and i < best_pos):
                    best_cost = cost
                    best_pos = i
            perm_D.insert(best_pos, job)
        new_cost = makespan(perm_D)
        curr_cost = makespan(current_perm)
        if new_cost < curr_cost or random.random() < math.exp(-(new_cost - curr_cost) / T):
            return perm_D
        else:
            return current_perm

    best_perm = neh_insertion(order_by_P)
    best_cost = makespan(best_perm)
    if best_cost == lower_bound:
        return best_perm
    current_perm = best_perm[:]
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    for _ in range(max_iter):
        current_perm = ig_iteration(current_perm, T)
        curr_cost = makespan(current_perm)
        if curr_cost < best_cost:
            best_cost = curr_cost
            best_perm = current_perm[:]
            if best_cost == lower_bound:
                break
    return best_perm

