                perm.insert(best_pos, job)
            current_cost = makespan(perm)
            if current_cost < best_cost:
                best_cost = current_cost
                best_perm = perm[:]
            if current_cost < makespan(perm):
                perm = perm[:]
            elif current_cost > makespan(perm):
                if random.random() < math.exp(-(current_cost - makespan(perm)) / T):
                    perm = perm[:]
                else:
                    perm = best_perm[:]
        return best_perm

    initial_perm = neh_construct()
    improved_perm = ig_improve(initial_perm)
    return improved_perm

