def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_p = p[job]
            t[0] += job_p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_p[m]
        return t[M-1]

    # Taillard-accelerated insertion evaluation
    def evaluate_insertion(partial, job, e, q, k):
        best_pos = 0
        best_cmax = float('inf')
        job_p = p[job]
        for i in range(k + 1):
            if i == 0:
                f0 = job_p[0]
            else:
                f0 = e[i-1][0] + job_p[0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + job_p[m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    # NEH construction with Taillard acceleration
    def neh_construction():
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N == 0:
            return []
        partial = [order[0]]
        if N == 1:
            return partial
        # Evaluate first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            partial = seq1
        else:
            partial = seq2
        # Build forward and tail matrices for current partial
        k = len(partial)
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job_r = p[partial[r]]
            if r == 0:
                e[0][0] = job_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_r[m]
            else:
                e[r][0] = e[r-1][0] + job_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = p[partial[r]]
            q[r][M-1] = q[r+1][M-1] + job_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        # Insert remaining jobs
        for idx in range(2, N):
            job = order[idx]
            pos, _ = evaluate_insertion(partial, job, e, q, k)
            partial.insert(pos, job)
            k += 1
            # Recompute e and q for new partial
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                job_r = p[partial[r]]
                if r == 0:
                    e[0][0] = job_r[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r[m]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
            q = [[0]*M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = p[partial[r]]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        return partial

    # Iterated Greedy refinement
    def iterated_greedy(initial_seq):
        current = initial_seq[:]
        current_cmax = makespan(current)
        best_seq = current[:]
        best_cmax = current_cmax
        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3
        max_iter = 60
        for _ in range(max_iter):
            # Destruction: remove d jobs at random
            if N <= d:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(N), d)
                positions.sort(reverse=True)
                destroyed = [current.pop(pos) for pos in positions]
                remaining = current
            # Reconstruction: reinsert jobs one by one using NEH insertion
            for job in destroyed:
                k = len(remaining)
                if k == 0:
                    remaining = [job]
                    continue
                # Build e and q for current remaining sequence
                e = [[0]*M for _ in range(k)]
                for r in range(k):
                    job_r = p[remaining[r]]
                    if r == 0:
                        e[0][0] = job_r[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + job_r[m]
                    else:
                        e[r][0] = e[r-1][0] + job_r[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
                q = [[0]*M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = p[remaining[r]]
                    q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
                # Find best insertion position
                best_pos, _ = evaluate_insertion(remaining, job, e, q, k)
                remaining.insert(best_pos, job)
            # Form new sequence
            new_seq = remaining
            new_cmax = makespan(new_seq)
            # Acceptance criterion
            if new_cmax < current_cmax or random.random() < math.exp(-(new_cmax - current_cmax) / T):
                current = new_seq
                current_cmax = new_cmax
                if current_cmax < best_cmax:
                    best_seq = current[:]
                    best_cmax = current_cmax
        return best_seq

    # Execute pipeline
    initial_seq = neh_construction()
    refined_seq = iterated_greedy(initial_seq)
    return refined_seq

