def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Flatten processing times for faster access
    p = [times[i][:] for i in range(n)]

    # Makespan calculation for a given sequence
    def makespan(seq):
        t = [0] * m
        for job in seq:
            t[0] += p[job][0]
            for j in range(1, m):
                t[j] = max(t[j], t[j-1]) + p[job][j]
        return t[-1]

    # NEH with Taillard acceleration and idle time tie-breaking
    def neh_construct():
        # Job priorities: total processing time descending
        total_p = [sum(p[i]) for i in range(n)]
        order = sorted(range(n), key=lambda i: (-total_p[i], i))

        # Start with first two jobs
        seq = [order[0], order[1]]
        best_makespan = makespan([order[0], order[1]])
        if makespan([order[1], order[0]]) < best_makespan:
            seq = [order[1], order[0]]
            best_makespan = makespan(seq)

        # Greedy insertion with Taillard acceleration
        for k in range(2, n):
            job = order[k]
            best_pos = 0
            best_ms = float('inf')
            best_idle = float('inf')

            # Current sequence length
            L = len(seq)

            # Precompute forward matrix e: completion times of current seq
            e = [[0] * m for _ in range(L)]
            for r in range(L):
                for mc in range(m):
                    if mc == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][mc] = prev + p[seq[r]][mc]
                    else:
                        left = e[r][mc-1]
                        up = e[r-1][mc] if r > 0 else 0
                        e[r][mc] = max(left, up) + p[seq[r]][mc]

            # Precompute backward tail matrix q: from job r to end
            q = [[0] * m for _ in range(L+1)]  # q[L][:] = 0
            for r in range(L-1, -1, -1):
                for mc in range(m-1, -1, -1):
                    if mc == m-1:
                        q[r][mc] = q[r+1][mc] + p[seq[r]][mc]
                    else:
                        right = q[r][mc+1]
                        down = q[r+1][mc]
                        q[r][mc] = max(right, down) + p[seq[r]][mc]

            # Try inserting job at each position i in [0, L]
            for i in range(L+1):
                # Compute forward vector f for job at position i
                f = [0] * m
                if i == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[i-1]
                for mc in range(m):
                    if mc == 0:
                        f[mc] = prev_e[0] + p[job][mc]
                    else:
                        f[mc] = max(f[mc-1], prev_e[mc]) + p[job][mc]

                # Compute makespan if job inserted at i
                ms = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > ms:
                        ms = val

                # Tie-breaking: if same makespan, minimize idle time on last machine
                if ms < best_ms:
                    best_ms = ms
                    best_pos = i
                    # Compute idle time on last machine for tie-breaking
                    if i == 0:
                        prev_last = 0
                    else:
                        prev_last = e[i-1][m-1] if i-1 < L else 0
                    start_last = max(prev_last, f[m-1])
                    end_last = start_last + p[job][m-1]
                    if i == L:
                        next_first = 0
                    else:
                        next_first = q[i][m-1]
                    idle_last = max(0, next_first - end_last)
                    best_idle = idle_last
                elif ms == best_ms:
                    # Compute idle time on last machine for this position
                    if i == 0:
                        prev_last = 0
                    else:
                        prev_last = e[i-1][m-1] if i-1 < L else 0
                    start_last = max(prev_last, f[m-1])
                    end_last = start_last + p[job][m-1]
                    if i == L:
                        next_first = 0
                    else:
                        next_first = q[i][m-1]
                    idle_last = max(0, next_first - end_last)
                    if idle_last < best_idle:
                        best_pos = i
                        best_idle = idle_last

            # Insert job at best_pos
            seq.insert(best_pos, job)

        return seq

    # Iterated Greedy (IG) with Taillard-accelerated reinsertion
    def ig_refine(init_seq, max_iters=60):
        current = init_seq[:]
        best = init_seq[:]
        best_ms = makespan(best)
        total_processing = sum(sum(p[i]) for i in range(n))
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6

        for _ in range(max_iters):
            # Destruction: remove d=3 jobs at random positions
            d = 3
            if n <= d:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(n), d)
                positions.sort(reverse=True)
                destroyed = [current.pop(pos) for pos in positions]
                remaining = current[:]

            # Reconstruction: reinsert each destroyed job using NEH-like insertion
            for job in destroyed:
                L = len(remaining)
                if L == 0:
                    remaining.append(job)
                    continue

                # Precompute forward matrix e for remaining
                e = [[0] * m for _ in range(L)]
                for r in range(L):
                    for mc in range(m):
                        if mc == 0:
                            prev = e[r-1][0] if r > 0 else 0
                            e[r][mc] = prev + p[remaining[r]][mc]
                        else:
                            left = e[r][mc-1]
                            up = e[r-1][mc] if r > 0 else 0
                            e[r][mc] = max(left, up) + p[remaining[r]][mc]

                # Precompute backward tail matrix q
                q = [[0] * m for _ in range(L+1)]
                for r in range(L-1, -1, -1):
                    for mc in range(m-1, -1, -1):
                        if mc == m-1:
                            q[r][mc] = q[r+1][mc] + p[remaining[r]][mc]
                        else:
                            right = q[r][mc+1]
                            down = q[r+1][mc]
                            q[r][mc] = max(right, down) + p[remaining[r]][mc]

                # Find best insertion position for job
                best_pos = 0
                best_ms_local = float('inf')
                best_idle_local = float('inf')
                for i in range(L+1):
                    # Forward vector f for job at position i
                    f = [0] * m
                    if i == 0:
                        prev_e = [0] * m
                    else:
                        prev_e = e[i-1]
                    for mc in range(m):
                        if mc == 0:
                            f[mc] = prev_e[0] + p[job][mc]
                        else:
                            f[mc] = max(f[mc-1], prev_e[mc]) + p[job][mc]

                    # Compute makespan
                    ms = 0
                    for mc in range(m):
                        val = f[mc] + q[i][mc]
                        if val > ms:
                            ms = val

                    # Tie-breaking by idle time on last machine
                    if ms < best_ms_local:
                        best_ms_local = ms
                        best_pos = i
                        if i == 0:
                            prev_last = 0
                        else:
                            prev_last = e[i-1][m-1] if i-1 < L else 0
                        start_last = max(prev_last, f[m-1])
                        end_last = start_last + p[job][m-1]
                        if i == L:
                            next_first = 0
                        else:
                            next_first = q[i][m-1]
                        idle_last = max(0, next_first - end_last)
                        best_idle_local = idle_last
                    elif ms == best_ms_local:
                        if i == 0:
                            prev_last = 0
                        else:
                            prev_last = e[i-1][m-1] if i-1 < L else 0
                        start_last = max(prev_last, f[m-1])
                        end_last = start_last + p[job][m-1]
                        if i == L:
                            next_first = 0
                        else:
                            next_first = q[i][m-1]
                        idle_last = max(0, next_first - end_last)
                        if idle_last < best_idle_local:
                            best_pos = i
                            best_idle_local = idle_last

                remaining.insert(best_pos, job)

            current = remaining[:]
            current_ms = makespan(current)
            if current_ms < best_ms:
                best_ms = current_ms
                best = current[:]
            elif current_ms < makespan(best):  # Accept if better than current
                # Metropolis acceptance
                delta = current_ms - makespan(best)
                if random.random() < math.exp(-delta / T):
                    best = current[:]

        return best

    # Build initial solution with NEH
    init_seq = neh_construct()
    # Refine with IG
    final_seq = ig_refine(init_seq, max_iters=50)
    return final_seq

