def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    P = [sum(row) for row in p]

    # Slope index for U-shaped workloads: prioritize jobs with high load on first and last machines
    S = [0] * N
    for i in range(N):
        total = 0
        for j in range(M):
            total += (2 * j - M + 1) * p[i][j]
        S[i] = total

    # Combine criteria: primary by slope (descending), secondary by total time (descending)
    order = sorted(range(N), key=lambda i: (S[i], P[i]), reverse=True)

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job, k):
        # k is current length of partial sequence
        if k == 0:
            f = [p[job][m] for m in range(M)]
            return max(f)

        # Forward matrix e for partial sequence
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            if r == 0:
                e[0][0] = p[job_r][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[job_r][m]
            else:
                e[r][0] = e[r-1][0] + p[job_r][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]

        # Backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]

        # Evaluate each insertion position
        best_val = float('inf')
        best_pos = 0
        for i in range(k+1):
            # Compute forward vector f for job at position i
            if i == 0:
                f0 = p[job][0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + p[job][m])
            else:
                prev = e[i-1]
                f0 = prev[0] + p[job][0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], prev[m]) + p[job][m])

            # Compute makespan candidate
            cand = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cand:
                    cand = val
            if cand < best_val:
                best_val = cand
                best_pos = i
        return best_pos, best_val

    # NEH construction with Taillard acceleration
    def neh_construction(job_order):
        if not job_order:
            return []
        seq = [job_order[0]]
        for idx in range(1, len(job_order)):
            job = job_order[idx]
            pos, _ = evaluate_insertion(seq, job, len(seq))
            seq.insert(pos, job)
        return seq

    # Initial solution
    current = neh_construction(order)
    best_seq = current[:]
    best_makespan = makespan(current)

    # Iterated Greedy parameters
    total_processing = sum(P)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 5 else max(1, N // 2)
    max_iter = 60
    iter_count = 0

    # Iterated Greedy loop
    while iter_count < max_iter:
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_indices.sort()
        destroyed = []
        extracted = []
        ri = 0
        for i in range(N):
            if ri < d and i == removed_indices[ri]:
                extracted.append(current[i])
                ri += 1
            else:
                destroyed.append(current[i])

        # Reconstruction: reinsert extracted jobs one by one in random order
        random.shuffle(extracted)
        for job in extracted:
            pos, _ = evaluate_insertion(destroyed, job, len(destroyed))
            destroyed.insert(pos, job)

        candidate = destroyed
        cand_makespan = makespan(candidate)

        # Acceptance criterion
        if cand_makespan < makespan(current):
            current = candidate
            if cand_makespan < best_makespan:
                best_seq = candidate[:]
                best_makespan = cand_makespan
        else:
            delta = cand_makespan - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = candidate

        iter_count += 1

    return best_seq

