    def neh_construction():
        order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)
        if N == 1:
            return order
        # Initial pair
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        # Greedy insertion with Taillard acceleration
        for k in range(2, N):
            job = order[k]
