                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward matrix q for current seq (length k)
            q = [[0] * M for _ in range(k+1)]
            # q[k][m] = 0 already
            for r in range(k-1, -1, -1):
                pj = job_data[seq[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Find best insertion position
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Forward vector f for job at position i
                f = [0] * M
                if i == 0:
                    f[0] = job_data[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job_data[job][m]
