                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                # Compute makespan if inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

