            removed = [current_seq[i] for i in indices]
            # Build partial sequence without removed indices
            marker = [False] * N
            for idx in indices:
                marker[idx] = True
            partial_seq = [current_seq[i] for i in range(N) if not marker[i]]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                # Rebuild forward matrix e for current partial_seq
                k = len(partial_seq)
                if k == 0:
                    e = []
                else:
                    e = [[0] * M for _ in range(k)]
                    for r in range(k):
                        pj = job_data[partial_seq[r]]
                        if r == 0:
                            e[0][0] = pj[0]
                            for m in range(1, M):
                                e[0][m] = e[0][m-1] + pj[m]
                        else:
                            e[r][0] = e[r-1][0] + pj[0]
                            for m in range(1, M):
                                e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                # Rebuild backward matrix q for current partial_seq
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    pj = job_data[partial_seq[r]]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Find best insertion position for job
                best_pos = 0
                best_mk = float('inf')
                for i in range(k+1):
                    # Forward vector f for job at position i
                    f = [0] * M
                    if i == 0:
                        f[0] = job_data[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + job_data[job][m]
                    else:
                        f[0] = e[i-1][0] + job_data[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                    # Compute makespan if inserted at i
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = i
                partial_seq.insert(best_pos, job)
            new_seq = partial_seq
            new_mk = makespan(new_seq)
            # Acceptance criterion
            if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
                current_seq = new_seq
                current_mk = new_mk
                if new_mk < best_mk:
                    best_seq = new_seq[:]
                    best_mk = new_mk
        return best_seq

    # Run the pipeline
    initial_seq = neh_construction()
    final_seq = iterated_greedy(initial_seq)
    return final_seq

