def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data as flat lists for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Taillard acceleration: forward and backward matrices
    def compute_forward_backward(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        if k > 0:
            e[0][0] = p[seq[0]][0]
            for m in range(1, M):
                e[0][m] = e[0][m-1] + p[seq[0]][m]
            for r in range(1, k):
                e[r][0] = e[r-1][0] + p[seq[r]][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[seq[r]][m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            q[r][M-1] = q[r+1][M-1] + p[seq[r]][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[seq[r]][m]
        return e, q

    # Makespan of a sequence
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for idx in seq:
            t[0] += p[idx][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[idx][m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construction(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for k in range(2, len(order)):
            job = order[k]
            e, q = compute_forward_backward(seq)
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                f = [0] * M
                if i == 0:
                    f[0] = p[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + p[job][m]
                else:
                    f[0] = e[i-1][0] + p[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + p[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reinsertion
    def iterated_greedy(init_seq, max_iters=60):
        current = init_seq[:]
        best = init_seq[:]
        best_mk = makespan(best)
        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        for _ in range(max_iters):
            # Destruction: remove d random jobs
            positions = random.sample(range(N), d)
            removed = [current[pos] for pos in sorted(positions, reverse=True)]
            for pos in sorted(positions, reverse=True):
                del current[pos]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                e, q = compute_forward_backward(current)
                best_pos = 0
                best_mk_local = float('inf')
                for i in range(len(current)+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = p[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + p[job][m]
                    else:
                        f[0] = e[i-1][0] + p[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + p[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_local:
                        best_mk_local = mk
                        best_pos = i
                current.insert(best_pos, job)
            # Acceptance
            curr_mk = makespan(current)
            if curr_mk < best_mk:
                best_mk = curr_mk
                best = current[:]
            if curr_mk < makespan(init_seq):  # always accept if better than current start of iteration
                pass  # current is already updated
            else:
                if random.random() < math.exp(-(curr_mk - makespan(init_seq)) / T):
                    pass  # accept worse
                else:
                    current = init_seq[:]  # revert to initial solution for this iteration
        return best

    # Try multiple orderings and pick the best
    orders = []
    # NEH order: total processing time descending
    order_neh = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    orders.append(order_neh)
    # Palmer's slope descending
    order_slope = sorted(range(N), key=lambda i: slope[i], reverse=True)
    orders.append(order_slope)
    # Random orders for diversity
    for _ in range(2):
        order_rand = list(range(N))
        random.shuffle(order_rand)
        orders.append(order_rand)

    best_overall = None
    best_overall_mk = float('inf')
    for order in orders:
        init_seq = neh_construction(order)
        refined_seq = iterated_greedy(init_seq, max_iters=40)
        mk = makespan(refined_seq)
        if mk < best_overall_mk:
            best_overall_mk = mk
            best_overall = refined_seq
            if best_overall_mk == 0:  # optimal if zero processing time
                break

    return best_overall

