def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 0

    # Precompute job processing times as flat lists for faster access
    p = [row[:] for row in times]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            tj = p[job]
            t[0] += tj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + tj[m]
        return t[-1]

    def taillard_forward_backward(partial):
        k = len(partial)
        if k == 0:
            return [0] * M, [[0] * M for _ in range(1)]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            tj = p[job]
            if r == 0:
                e[0][0] = tj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + tj[m]
            else:
                e[r][0] = e[r-1][0] + tj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + tj[m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            tj = p[job]
            q[r][M-1] = q[r+1][M-1] + tj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + tj[m]
        return e, q

    def insert_job_taillard(partial, job, e, q):
        k = len(partial)
        best_pos = 0
        best_mk = float('inf')
        tj = p[job]
        for i in range(k+1):
            if i == 0:
                f0 = tj[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + tj[m])
            else:
                prev_e = e[i-1]
                f0 = prev_e[0] + tj[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], prev_e[m]) + tj[m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos

    def neh_taillard():
        job_sums = [sum(job) for job in p]
        order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        if N < 2:
            return order[:]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for idx in range(2, N):
            job = order[idx]
            e, q = taillard_forward_backward(seq)
            pos = insert_job_taillard(seq, job, e, q)
            seq.insert(pos, job)
        return seq

    current = neh_taillard()
    best = current[:]
    best_mk = makespan(best)

    # Lower bound check (Taillard)
    lb = 0
    for m in range(M):
        min_pre = min(sum(p[i][:m]) for i in range(N)) if m > 0 else 0
        min_suf = min(sum(p[i][m+1:]) for i in range(N)) if m < M-1 else 0
        machine_sum = sum(p[i][m] for i in range(N))
        lb_m = min_pre + machine_sum + min_suf
        if lb_m > lb:
            lb = lb_m
    if best_mk == lb:
        return best

    # Iterated Greedy
    max_iter = 60
    d = 3 if N > 20 else 4
    for _ in range(max_iter):
        # Destruction
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        indices_set = set(indices)
        partial = [current[i] for i in range(N) if i not in indices_set]
        # Reconstruction
        for job in removed:
            e, q = taillard_forward_backward(partial)
            pos = insert_job_taillard(partial, job, e, q)
            partial.insert(pos, job)
        # Acceptance
        new_mk = makespan(partial)
        if new_mk < makespan(current):
            current = partial[:]
            if new_mk < best_mk:
                best = current[:]
                best_mk = new_mk
                if best_mk == lb:
                    break
        else:
            if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                current = partial[:]
    return best

