            job_r = partial[r]
            pt = times[job_r]
            q[r][M-1] = q[r+1][M-1] + pt[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pt[m]

        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            # Forward pass for job
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + times[job][m]
            else:
                prev = e[i-1]
                f[0] = prev[0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev[m]) + times[job][m]
            # Compute makespan
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    # NEH construction with Taillard acceleration
    curr_seq = [order[0], order[1]]
    if makespan([order[1], order[0]]) < makespan(curr_seq):
        curr_seq = [order[1], order[0]]
    for idx in range(2, N):
        job = order[idx]
        pos, _ = evaluate_insertion(curr_seq, job)
        curr_seq.insert(pos, job)
    best_seq = curr_seq[:]
    best_cmax = makespan(best_seq)

    # Iterated Greedy refinement
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 50

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [curr_seq[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del curr_seq[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            pos, _ = evaluate_insertion(curr_seq, job)
            curr_seq.insert(pos, job)
        # Acceptance
        curr_cmax = makespan(curr_seq)
        if curr_cmax < best_cmax:
            best_cmax = curr_cmax
            best_seq = curr_seq[:]
        if curr_cmax < makespan(best_seq):  # current is better than best? redundant but safe
            best_seq = curr_seq[:]
            best_cmax = curr_cmax
        elif random.random() < math.exp(-(curr_cmax - makespan(best_seq)) / T):
            # accept worse solution
            pass
        else:
            # reject, restore to previous? In standard IG, we keep the new solution for next iteration
            # but here we keep the current sequence as is (already updated)
            pass

    return best_seq
